@typia/interface/src/http/IHttpLlmApplic:
import { OpenApi } from "../openapi/OpenApi";
import { ILlmSchema } from "../schema/ILlmSchema";
import { IHttpLlmFunction } from "./IHttpLlmFunction";
import { IHttpMigrateRoute } from "./IHttpMigrateRoute";

/**
 * LLM function calling application from OpenAPI document.
 *
 * `IHttpLlmApplication` is a collection of {@link IHttpLlmFunction} schemas
 * converted from {@link OpenApi.IDocument} by `HttpLlm.application()`. Each
 * eligible OpenAPI operation becomes an LLM-callable function. Operations
 * marked with `x-samchon-human: true` are omitted from both result lists.
 * Eligibility first follows the migration-supported methods `head`, `get`,
 * `post`, `put`, `patch`, `delete`, and `query`; other method entries are
 * omitted.
 *
 * Successful conversions go to {@link functions}, failed ones to {@link errors}
 * with detailed error messages. Common failure causes:
 *
 * - Unsupported schema features (tuples, `oneOf` with incompatible types)
 * - Missing required fields in OpenAPI document
 * - HEAD operations or multipart request/response bodies
 *
 * Configure behavior via {@link IHttpLlmApplication.IConfig}:
 *
 * - {@link IHttpLlmApplication.IConfig.maxLength}: Function name length limit
 * - {@link ILlmSchema.IConfig.strict}: OpenAI structured output mode
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @evidence contracts/common.md#principled-implementation The two lists distinguish successful conversions from reported failures among eligible operations. The composer filters human-only operations from both migration routes and errors; the config records the composition settings and the optional version records the source info.version when present.
 * @evidence contracts/common.md#clear-and-simple-design Two required lists, a configuration record and an optional version keep conversion results and their context together; config and error types are namespaced.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Conversion failures are represented as data for eligible operations; the documented human-only filter intentionally omits those endpoints rather than fabricating callable tools.
 * @evidence contracts/common.md#meaningful-documentation The comment explains the success and error split, common failure causes and the configuration options with links.
 */
export interface IHttpLlmApplication {
  /** Successfully converted LLM function schemas. */
  functions: IHttpLlmFunction[];

  /** Operations that failed conversion. */
  errors: IHttpLlmApplication.IError[];

  /** Configuration used for composition. */
  config: IHttpLlmApplication.IConfig;

  /**
   * Version of the API, taken from the OpenAPI document's `info.version`.
   *
   * `undefined` when the source document carries no version info.
   */
  version?: string | undefined;
}
export namespace IHttpLlmApplication {
  /**
   * Configuration for HTTP LLM application composition.
   *
   * @evidence contracts/common.md#principled-implementation Config extends the LLM schema configuration and adds a name length limit and a strictness flag for superfluous properties. The documented shortening rule is the one implemented by the composer's shorten and abbreviate functions, which choose deterministic unique names that fit the limit and do not start with a digit, and throw when every hashed name is taken.
   * @evidence contracts/common.md#clear-and-simple-design Two added fields on an existing configuration interface rather than a separate options object.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The shortening rule is a documented contract of the composer; it is not a consumer-specific name table.
   * @evidence contracts/common.md#meaningful-documentation The comment gives defaults and describes the shortening procedure including its failure condition.
   */
  export interface IConfig extends ILlmSchema.IConfig {
    /**
     * Maximum function name length.
     *
     * A longer name becomes its longest non-empty accessor suffix of at most
     * `maxLength - 8` characters that is free, as is or with a counter prefix.
     * When no suffix is free, the name keeps as much of its last segment as
     * fits beside a hash of the full name, none of it below 9. Every name is
     * deterministic, unique, at most `maxLength`, and does not start with a
     * digit. Composition throws when a name must be shortened and every such
     * hashed name is taken, as all are below 2.
     *
     * @default 64
     */
    maxLength: number;

    /**
     * Whether to disallow superfluous properties.
     *
     * @default false
     */
    equals: boolean;
  }

  /**
   * Composition error for an operation.
   *
   * @evidence contracts/common.md#principled-implementation An error holds the method, path and messages that identify the failed operation plus accessors to the source operation and route, whose route is possibly undefined because failures can occur before routes exist.
   * @evidence contracts/common.md#clear-and-simple-design Two accessor functions in place of copies keep the source data in one place.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A plain record; messages are produced elsewhere and no failure is hidden by this type.
   * @evidence contracts/common.md#meaningful-documentation The comment says it is a composition error for an operation, and each field and accessor is documented.
   */
  export interface IError {
    /** HTTP method of the failed operation. */
    method: "head" | "get" | "post" | "put" | "patch" | "delete" | "query";

    /** Path of the failed operation. */
    path: string;

    /** Error messages describing the failure. */
    messages: string[];

    /**
     * Returns source {@link OpenApi.IOperation}.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the source operation, so the error record does not duplicate or retain a second copy of the document structure.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued property that matches the sibling route accessor.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns the existing source object; no clone or patch is involved.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment says what it returns.
     */
    operation: () => OpenApi.IOperation;

    /**
     * Returns source route. Undefined if error occurred at migration level.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the migration route or undefined, undefined being the case where migration itself failed, so a route value is never fabricated for an operation that could not be migrated.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued property returning an optional route.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It does not synthesize a route for failed migration.
     * @evidence contracts/common.md#meaningful-documentation The comment states the undefined case.
     */
    route: () => IHttpMigrateRoute | undefined;
  }
}

@typia/interface/src/http/IHttpLlmContro:
import { IHttpConnection } from "./IHttpConnection";
import { IHttpLlmApplication } from "./IHttpLlmApplication";
import { IHttpLlmFunction } from "./IHttpLlmFunction";
import { IHttpResponse } from "./IHttpResponse";

/**
 * Controller of HTTP LLM function calling.
 *
 * `IHttpLlmController` is a controller for registering OpenAPI operations as
 * LLM function calling tools. It contains {@link IHttpLlmApplication} with
 * {@link IHttpLlmFunction function calling schemas}, {@link name identifier}, and
 * {@link connection} to the API server.
 *
 * You can create this controller with {@link HttpLlm.controller} function, and
 * feed it to an LLM framework adapter such as `@typia/langchain` or
 * `@typia/vercel`:
 *
 * ```typescript
 * import { HttpLlm } from "@typia/utils";
 * import { toVercelTools } from "@typia/vercel";
 *
 * const controller = HttpLlm.controller({
 *   name: "shopping",
 *   document: await fetch(
 *     "https://shopping-be.wrtn.io/editor/swagger.json",
 *   ).then((r) => r.json()),
 *   connection: {
 *     host: "https://shopping-be.wrtn.io",
 *     headers: { Authorization: "Bearer ********" },
 *   },
 * });
 * const tools = toVercelTools({ controllers: [controller] });
 * ```
 *
 * For TypeScript class-based controller, use {@link ILlmController} instead.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @evidence contracts/common.md#principled-implementation The `protocol: "http"` literal discriminates it from class-based controllers, and the record holds the application, a name and a connection, plus an optional executor whose argument object bundles the connection, application, function and arguments the default executor needs. The optional executor is the supported override point.
 * @evidence contracts/common.md#clear-and-simple-design One flat controller interface with its executor argument inline, because only this member uses that argument shape.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Overriding execution goes through the executor member and not through patching HttpLlm.
 * @evidence contracts/common.md#meaningful-documentation The comment shows creation and use with framework adapters, links the alternative class-based controller and documents how arguments are keyed.
 */
export interface IHttpLlmController {
  /** Protocol discriminator. */
  protocol: "http";

  /** Identifier name of the controller. */
  name: string;

  /** Application schema of function calling. */
  application: IHttpLlmApplication;

  /**
   * Connection to the server.
   *
   * Connection to the API server including the URL and headers.
   */
  connection: IHttpConnection;

  /**
   * Executor of the API function.
   *
   * Default executor is {@link HttpLlm.execute} function, and you can override
   * it with your own function.
   *
   * @param props Properties of the API function call
   *
   * @returns HTTP response of the API function call
   */
  execute?:
    | undefined
    | ((props: {
        /** Connection to the server. */
        connection: IHttpConnection;

        /** Application schema. */
        application: IHttpLlmApplication;

        /** Function schema. */
        function: IHttpLlmFunction;

        /**
         * Arguments of the function calling.
         *
         * It is an object of key-value pairs of the API function's parameters.
         * The property keys are composed by below rules:
         *
         * - Path parameter names
         * - Header parameter group if it exists
         * - Cookie parameter group if it exists
         * - Query parameter group if it exists
         * - Body parameter if it exists
         */
        arguments: object;
      }) => Promise<IHttpResponse>);
}

@typia/interface/src/http/IHttpLlmFuncti:
import { OpenApi } from "../openapi/OpenApi";
import { ILlmFunction } from "../schema/ILlmFunction";
import { IHttpMigrateRoute } from "./IHttpMigrateRoute";

/**
 * LLM function calling schema from OpenAPI operation.
 *
 * Extends {@link ILlmFunction} with HTTP-specific properties. Generated from
 * {@link OpenApi.IOperation} as part of {@link IHttpLlmApplication}.
 *
 * - {@link method}, {@link path}: HTTP endpoint info
 * - {@link operation}: Source OpenAPI operation
 * - {@link route}: Source migration route
 *
 * Inherits {@link parse} and {@link validate} from {@link ILlmFunction}.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @evidence contracts/common.md#principled-implementation It extends the neutral LLM function with the HTTP method union, path, optional tags and accessors to the source operation and route, so one record carries what both the model and the executor need.
 * @evidence contracts/common.md#clear-and-simple-design Interface inheritance is used because every field of ILlmFunction applies unchanged.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Accessors return existing objects and nothing is cloned or patched.
 * @evidence contracts/common.md#meaningful-documentation The comment lists the added properties and which members are inherited.
 */
export interface IHttpLlmFunction extends ILlmFunction {
  /** HTTP method of the endpoint. */
  method: "head" | "get" | "post" | "put" | "patch" | "delete" | "query";

  /** Path of the endpoint. */
  path: string;

  /** Category tags from {@link OpenApi.IOperation.tags}. */
  tags?: string[];

  /**
   * Returns the source {@link OpenApi.IOperation}.
   *
   * @evidence contracts/common.md#principled-implementation A thunk returns the source OpenAPI operation instead of copying it into each function.
   * @evidence contracts/common.md#clear-and-simple-design A function-valued property matching route.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns existing data and has no side effects.
   * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
   */
  operation: () => OpenApi.IOperation;

  /**
   * Returns the source {@link IHttpMigrateRoute}.
   *
   * @evidence contracts/common.md#principled-implementation A thunk returns the migration route that this function was derived from, always defined for a successfully composed function.
   * @evidence contracts/common.md#clear-and-simple-design A function-valued property, matching operation.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns an existing route and creates none.
   * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
   */
  route: () => IHttpMigrateRoute;
}

@typia/interface/src/http/IHttpMigrateAp:
import { OpenApi } from "../openapi/OpenApi";
import { IHttpMigrateRoute } from "./IHttpMigrateRoute";

/**
 * Migrated application from OpenAPI document.
 *
 * `IHttpMigrateApplication` converts OpenAPI operations into callable HTTP
 * routes via `HttpMigration.application()`. Unlike {@link IHttpLlmApplication}
 * which targets LLM function calling, this focuses on SDK/client code
 * generation for the migration-supported HTTP operations.
 *
 * Migration considers `head`, `get`, `post`, `put`, `patch`, `delete`, and
 * `query`. Other method entries, including `options`, `trace`, and
 * `additionalOperations`, do not appear in either result list.
 *
 * Each {@link IHttpMigrateRoute} represents a single API endpoint with:
 *
 * - Resolved path parameters (`:id` format)
 * - Combined query/header schemas as objects
 * - Request/response body with content type
 * - Accessor path for RPC-style function naming
 *
 * Failed operations go to {@link errors} with detailed messages.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @evidence contracts/common.md#principled-implementation The composer considers its seven supported methods: head, get, post, put, patch, delete and query. Their successful conversions become routes and failed attempts become errors; other method entries are outside these lists. The accessor returns the normalized source document.
 * @evidence contracts/common.md#clear-and-simple-design Two lists and an accessor, with the error record in the namespace.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Supported-method conversion failures are retained as data; the documented method boundary does not claim to report unsupported method entries as errors.
 * @evidence contracts/common.md#meaningful-documentation The comment contrasts it with the LLM application, lists what each route carries and mentions failures.
 */
export interface IHttpMigrateApplication {
  /** Successfully migrated routes. */
  routes: IHttpMigrateRoute[];

  /** Operations that failed migration. */
  errors: IHttpMigrateApplication.IError[];

  /**
   * Returns source OpenAPI document.
   *
   * @evidence contracts/common.md#principled-implementation A thunk returns the source OpenAPI document so the application does not embed a second copy of it.
   * @evidence contracts/common.md#clear-and-simple-design A function-valued property.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns the existing document; nothing is cloned.
   * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
   */
  document: () => OpenApi.IDocument;
}
export namespace IHttpMigrateApplication {
  /**
   * Migration error for an operation.
   *
   * @evidence contracts/common.md#principled-implementation A failed operation is identified by method, path and messages, with an accessor to the source operation.
   * @evidence contracts/common.md#clear-and-simple-design Four fields and no behavior.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A plain record that reports the failure instead of hiding it.
   * @evidence contracts/common.md#meaningful-documentation The comment and member comments name the operation, method, path and messages.
   */
  export interface IError {
    /**
     * Returns source operation.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the source operation of the failed migration.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued property that mirrors the route-level accessors.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns existing data only.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
     */
    operation: () => OpenApi.IOperation;

    /** HTTP method. */
    method: "head" | "get" | "post" | "put" | "patch" | "delete" | "query";

    /** Operation path. */
    path: string;

    /** Error messages. */
    messages: string[];
  }
}

@typia/interface/src/http/IHttpMigrateRo:
import { OpenApi } from "../openapi/OpenApi";

/**
 * HTTP route converted from OpenAPI operation.
 *
 * `IHttpMigrateRoute` represents a single API endpoint with all
 * request/response schemas resolved and ready for code generation. Contains
 * {@link parameters} for URL path variables, {@link query} for query strings,
 * {@link headers}, {@link cookies}, {@link body} for request payload, and
 * {@link success}/{@link exceptions} for responses.
 *
 * @author Jeongho Nam - https://github.com/samchon
 *
 * @evidence contracts/common.md#principled-implementation A route keeps the original and emended path, an accessor name array, path parameters, nullable combined headers, cookies, query and body, one representative success and exceptions keyed by status, with accessors to the comment and source operation. Combined groups are single objects because the migrated function takes them as one argument.
 * @evidence contracts/common.md#clear-and-simple-design Nested records for each group live in the namespace, and accessors replace copies of the source data.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It is plain data produced by the composer and does not itself resolve or default anything.
 * @evidence contracts/common.md#meaningful-documentation The comment and member comments explain emended paths, accessor naming, nullability and the reserved-word rename of delete.
 */
export interface IHttpMigrateRoute {
  /** HTTP method. */
  method: "head" | "get" | "post" | "put" | "patch" | "delete" | "query";

  /** Original path from OpenAPI document. */
  path: string;

  /** Emended path with `:param` format, always starts with `/`. */
  emendedPath: string;

  /**
   * Accessor path for generated RPC function.
   *
   * Namespaces from static path segments, function name from method +
   * parameters. `delete` becomes `erase` to avoid reserved keyword.
   */
  accessor: string[];

  /** Path parameters only. */
  parameters: IHttpMigrateRoute.IParameter[];

  /** Combined headers as single object. Null if none. */
  headers: IHttpMigrateRoute.IHeaders | null;

  /** Combined cookies as single object. Null if none. */
  cookies?: IHttpMigrateRoute.ICookies | null;

  /** Combined query parameters as single object. Null if none. */
  query: IHttpMigrateRoute.IQuery | null;

  /** Request body metadata. Null if none. */
  body: IHttpMigrateRoute.IBody | null;

  /** Representative success response for the declared 2xx class. */
  success: IHttpMigrateRoute.ISuccess | null;

  /** Exception responses keyed by status code. */
  exceptions: Record<string, IHttpMigrateRoute.IException>;

  /**
   * Returns description comment for the RPC function.
   *
   * @evidence contracts/common.md#principled-implementation A thunk renders the description comment on demand instead of storing a pre-built string.
   * @evidence contracts/common.md#clear-and-simple-design A function-valued property.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts It computes from the operation and does not carry fixed text.
   * @evidence contracts/common.md#meaningful-documentation A one-line comment says what it returns.
   */
  comment: () => string;

  /**
   * Returns source {@link OpenApi.IOperation}.
   *
   * @evidence contracts/common.md#principled-implementation A thunk returns the source operation of the route.
   * @evidence contracts/common.md#clear-and-simple-design A function-valued property that matches the other accessors.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns existing data only.
   * @evidence contracts/common.md#meaningful-documentation A one-line comment states that it returns the source operation.
   */
  operation: () => OpenApi.IOperation;
}
export namespace IHttpMigrateRoute {
  /**
   * Path parameter metadata.
   *
   * @evidence contracts/common.md#principled-implementation A path parameter has its template name and variable key, the schema and optional style and explode, whose defaults are simple and false, with an accessor to the source parameter. Style is limited to the three path styles that OpenAPI permits for path parameters.
   * @evidence contracts/common.md#clear-and-simple-design Distinct from the grouped parameters because path parameters stay individual.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Defaults are documented, not applied by the type.
   * @evidence contracts/common.md#meaningful-documentation Each field says what it holds and states defaults.
   */
  export interface IParameter {
    /** Parameter name in path template. */
    name: string;

    /** Parameter variable key. */
    key: string;

    /** Parameter type schema. */
    schema: OpenApi.IJsonSchema;

    /** Effective serialization style. Defaults to `simple`. */
    style?: "matrix" | "label" | "simple";

    /** Effective explode behavior. Defaults to `false`. */
    explode?: boolean;

    /**
     * Returns source parameter definition.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the source parameter definition.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued property.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns existing data only.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
     */
    parameter: () => OpenApi.IOperation.IParameter;
  }

  /**
   * Headers metadata.
   *
   * @evidence contracts/common.md#principled-implementation Header parameters are combined into one object with a name, key and schema, an optional required flag, the original parameter serialization records and accessors for title, description and examples, so a client can both type the group and serialize each source parameter.
   * @evidence contracts/common.md#clear-and-simple-design Four accessors share a shape across IHeaders and IQuery and are separate members because each returns documentation that may be absent.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A record only; there is no schema merging in the type.
   * @evidence contracts/common.md#meaningful-documentation The comment names the group and each member says what it returns.
   */
  export interface IHeaders {
    /** Combined headers parameter name. */
    name: string;

    /** Headers variable key. */
    key: string;

    /** Combined headers schema. */
    schema: OpenApi.IJsonSchema;

    /** Whether the combined headers argument is required. */
    required?: boolean;

    /** Source parameter serialization metadata. */
    parameters?: IHttpMigrateRoute.ISerialization[];

    /**
     * Returns title.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the title or undefined when the source declares none.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member that avoids storing derived text.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns data from the source.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    title: () => string | undefined;

    /**
     * Returns description.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the description or undefined.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member with the same shape as title.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns data from the source.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    description: () => string | undefined;

    /**
     * Returns example value.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns a single example value or undefined; the `any` return reflects that examples are arbitrary JSON.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns source data.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    example: () => any | undefined;

    /**
     * Returns named examples.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns named examples or undefined.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns source data.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    examples: () => Record<string, any> | undefined;
  }

  /**
   * Query parameters metadata.
   *
   * @evidence contracts/common.md#principled-implementation Query parameters are combined into one object like headers, with an optional whole-query media record for the OpenAPI 3.2 querystring parameter, which replaces per-parameter serialization when present.
   * @evidence contracts/common.md#clear-and-simple-design It repeats the group fields of IHeaders and adds one optional querystring member.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A record only; serialization is decided by the fetcher.
   * @evidence contracts/common.md#meaningful-documentation The comment and member comments describe the combined query and the querystring option.
   */
  export interface IQuery {
    /** Combined query parameter name. */
    name: string;

    /** Query variable key. */
    key: string;

    /** Combined query schema. */
    schema: OpenApi.IJsonSchema;

    /** Whether the combined query argument is required. */
    required?: boolean;

    /** Source parameter serialization metadata. */
    parameters?: IHttpMigrateRoute.ISerialization[];

    /** Whole-query media metadata for OpenAPI 3.2 `querystring`. */
    querystring?: IHttpMigrateRoute.IQuerystring;

    /**
     * Returns title.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the title or undefined.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member mirroring IHeaders.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns source data.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    title: () => string | undefined;

    /**
     * Returns description.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns the description or undefined.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member mirroring IHeaders.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns source data.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    description: () => string | undefined;

    /**
     * Returns example value.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns one example or undefined.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member mirroring IHeaders.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns source data.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    example: () => any | undefined;

    /**
     * Returns named examples.
     *
     * @evidence contracts/common.md#principled-implementation A thunk returns named examples or undefined.
     * @evidence contracts/common.md#clear-and-simple-design A function-valued member mirroring IHeaders.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts It returns source data.
     * @evidence contracts/common.md#meaningful-documentation A one-line comment states the return.
     */
    examples: () => Record<string, any> | undefined;
  }

  /**
   * Whole-query media metadata.
