    (collection: IComponentsCollection) =>
    (
      input: OpenApi.IOperation.IRequestBody,
    ): OpenApiV3_1.IOperation.IRequestBody => ({
      ...input,
      content: input.content
        ? downgradeContent(collection)(input.content)
        : undefined,
    });

  const downgradeResponse =
    (collection: IComponentsCollection) =>
    (
      input: OpenApi.IOperation.IResponse,
    ): OpenApiV3_1.IOperation.IResponse => ({
      ...input,
      content: input.content
        ? downgradeContent(collection)(input.content)
        : undefined,
      headers: input.headers
        ? Object.fromEntries(
            Object.entries(input.headers)
              .filter(([_, v]) => v !== undefined)
              .map(([key, value]) => {
                const { name: _name, in: _in, style, ...rest } = value;
                return [
                  key,
                  {
                    ...rest,
                    style: style === "cookie" ? "form" : style,
                    schema: downgradeSchema(collection)(value.schema),
                  },
                ];
              }),
          )
        : undefined,
    });

  const downgradeContent =
    (collection: IComponentsCollection) =>
    (
      record: OpenApi.IOperation.IContent,
    ): Record<string, OpenApiV3_1.IOperation.IMediaType> =>
      Object.fromEntries(
        Object.entries(record)
          .filter(([_, v]) => v !== undefined)
          .map(
            ([key, value]) =>
              [
                key,
                {
                  ...value,
                  schema: value?.schema
                    ? downgradeSchema(collection)(value.schema)
                    : undefined,
                  // itemSchema is v3.2-only, remove it
                  itemSchema: undefined,
                },
              ] as const,
          ),
      );

  /* -----------------------------------------------------------
    DEFINITIONS
  ----------------------------------------------------------- */
  /**
   * Downgrade every component schema and security scheme.
   *
   * @param input Emended components
   *
   * @returns Collection holding the original and the downgraded components
   *
   * @evidence contracts/common.md#principled-implementation Each schema is downgraded into a new store under the same name and security schemes are rewritten for 3.1.
   * @evidence contracts/common.md#clear-and-simple-design One function.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts No hidden state.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const downgradeComponents = (
    input: OpenApi.IComponents,
  ): IComponentsCollection => {
    const collection: IComponentsCollection = {
      original: input,
      downgraded: {
        securitySchemes: input.securitySchemes
          ? downgradeSecuritySchemes(input.securitySchemes)
          : undefined,
      },
    };
    if (input.schemas) {
      collection.downgraded.schemas = {};
      for (const [key, value] of Object.entries(input.schemas))
        if (value !== undefined)
          ObjectDictionary.set(
            collection.downgraded.schemas,
            key,
            downgradeSchema(collection)(value),
          );
    }
    return collection;
  };

  /**
   * Downgrade one emended schema to 3.1.
   *
   * @param collection Original and downgraded components
   *
   * @returns Function that converts an emended schema to a 3.1 schema
   *
   * @evidence contracts/common.md#principled-implementation Members of a `oneOf` are flattened into one union, null and constants are written in their 3.1 forms, strings get their base64 encoding, and tuples and objects recurse, with a discriminator kept only while the union kept one member per branch.
   * @evidence contracts/common.md#clear-and-simple-design One recursive function with a small examples helper.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Rewrites follow the 3.1 dialect and no keyword is invented.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const downgradeSchema =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IJsonSchema): OpenApiV3_1.IJsonSchema => {
      const union: OpenApiV3_1.IJsonSchema[] = [];
      const discriminator:
        | OpenApiV3_1.IJsonSchema.IOneOf.IDiscriminator
        | undefined =
        OpenApiTypeChecker.isOneOf(input) && input.discriminator !== undefined
          ? OpenApiDiscriminatorConverter.clone(input.discriminator)
          : undefined;
      let preserveDiscriminator: boolean = discriminator !== undefined;
      const attribute: OpenApiV3_1.IJsonSchema.__IAttribute = {
        title: input.title,
        description: input.description,
        deprecated: input.deprecated,
        readOnly: input.readOnly,
        writeOnly: input.writeOnly,
        example: input.example,
        examples: downgradeSchemaExamples(input.examples),
        ...Object.fromEntries(
          Object.entries(input).filter(
            ([key, value]) => key.startsWith("x-") && value !== undefined,
          ),
        ),
      };
      const visit = (schema: OpenApi.IJsonSchema): void => {
        if (OpenApiTypeChecker.isNull(schema)) union.push({ type: "null" });
        else if (OpenApiTypeChecker.isConstant(schema))
          union.push({ const: schema.const });
        else if (OpenApiTypeChecker.isString(schema)) {
          const { contentEncoding, format, ...rest } = schema;
          const base64: boolean =
            format === "byte" &&
            (contentEncoding === undefined || contentEncoding === "base64");
          union.push({
            ...rest,
            format: base64 ? undefined : format,
            contentEncoding: base64 ? "base64" : contentEncoding,
            examples: downgradeSchemaExamples(schema.examples),
          });
        } else if (
          OpenApiTypeChecker.isBoolean(schema) ||
          OpenApiTypeChecker.isInteger(schema) ||
          OpenApiTypeChecker.isNumber(schema) ||
          OpenApiTypeChecker.isReference(schema)
        )
          union.push({
            ...schema,
            examples: downgradeSchemaExamples(schema.examples),
          });
        else if (OpenApiTypeChecker.isArray(schema))
          union.push({
            ...schema,
            examples: downgradeSchemaExamples(schema.examples),
            items: downgradeSchema(collection)(schema.items),
          });
        else if (OpenApiTypeChecker.isTuple(schema))
          union.push({
            ...schema,
            examples: downgradeSchemaExamples(schema.examples),
            prefixItems: schema.prefixItems.length
              ? schema.prefixItems.map(downgradeSchema(collection))
              : undefined,
            minItems: schema.minItems ?? schema.prefixItems.length,
            items:
              typeof schema.additionalItems === "object"
                ? downgradeSchema(collection)(schema.additionalItems)
                : (schema.additionalItems ?? false),
            additionalItems: undefined,
          });
        else if (OpenApiTypeChecker.isObject(schema))
          union.push({
            ...schema,
            examples: downgradeSchemaExamples(schema.examples),
            properties:
              schema.properties === undefined
                ? undefined
                : Object.fromEntries(
                    Object.entries(schema.properties)
                      .filter(([_, v]) => v !== undefined)
                      .map(([key, value]) => [
                        key,
                        downgradeSchema(collection)(value),
                      ]),
                  ),
            additionalProperties:
              schema.additionalProperties === undefined
                ? undefined
                : typeof schema.additionalProperties === "object"
                  ? downgradeSchema(collection)(schema.additionalProperties)
                  : schema.additionalProperties,
            required: schema.required,
          });
        else if (OpenApiTypeChecker.isOneOf(schema)) {
          const tracked: boolean =
            schema === input && discriminator !== undefined;
          for (const branch of schema.oneOf) {
            const previous: number = union.length;
            visit(branch);
            if (tracked && union.length !== previous + 1)
              preserveDiscriminator = false;
          }
        }
      };
      visit(input);
      return {
        ...(union.length === 0
          ? { type: undefined }
          : union.length === 1
            ? { ...union[0] }
            : {
                oneOf: union,
                ...(preserveDiscriminator && discriminator !== undefined
                  ? { discriminator }
                  : {}),
              }),
        ...attribute,
      };
    };

  const downgradeSchemaExamples = (
    examples: OpenApi.IJsonSchema["examples"],
  ): any[] | undefined =>
    examples === undefined ? undefined : Object.values(examples);

  const downgradeSecuritySchemes = (
    input: Record<string, OpenApi.ISecurityScheme>,
  ): Record<string, OpenApiV3_1.ISecurityScheme> =>
    Object.fromEntries(
      Object.entries(input)
        .filter(([_, v]) => v !== undefined)
        .map(([key, value]) => [key, downgradeSecurityScheme(value)]),
    );

  const downgradeSecurityScheme = (
    input: OpenApi.ISecurityScheme,
  ): OpenApiV3_1.ISecurityScheme => {
    if (input.type === "oauth2") {
      const { deviceAuthorization: _, ...flows } = input.flows;
      return {
        type: "oauth2",
        flows,
        description: input.description,
      };
    }
    return { ...input } as OpenApiV3_1.ISecurityScheme;
  };
}

import { IJsonSchemaAttribute, OpenApi, OpenApiV3_1 } from "@typia/interface";

import { OpenApiReferenceKey } from "../../utils/internal/OpenApiReferenceKey";
import { OpenApiTypeChecker } from "../../validators/OpenApiTypeChecker";
import { OpenApiV3_1TypeChecker } from "../../validators/OpenApiV3_1TypeChecker";
import { OpenApiDiscriminatorConverter } from "./OpenApiDiscriminatorConverter";
import { OpenApiExclusiveEmender } from "./OpenApiExclusiveEmender";

/**
 * Upgrades an OpenAPI 3.1 document to the emended OpenAPI 3.2 form.
 *
 * Besides the work shared with the 3.0 upgrader, it resolves webhook and
 * component references, turns `type` arrays and tuple spellings into the
 * emended union and tuple forms, and reads `contentEncoding: base64` as the
 * `byte` format. The 3.2 upgrader reuses its schema conversion.
 *
 * @evidence contracts/common.md#principled-implementation A 3.1 document is brought to the emended form with the 3.0 rewrites plus webhooks and path-item references, `type` arrays, `const`, both tuple spellings and base64 content encoding, with schema references rewritten to the components path.
 * @evidence contracts/common.md#clear-and-simple-design Private helpers per object kind; the schema conversion is exported because the 3.2 upgrader reuses it, and the document-level helpers duplicate the 3.0 ones, which is a limitation.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The declared dialect decides every rewrite; no example document is special-cased.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment lists the rewrites and the reuse by 3.2.
 */
export namespace OpenApiV3_1Upgrader {
  /**
   * Upgrade a whole 3.1 document; a document that is already emended is
   * returned as it is.
   *
   * @param input OpenAPI 3.1 document
   *
   * @returns Emended document marked with `x-typia-emended-v12`
   *
   * @evidence contracts/common.md#principled-implementation An emended input is returned unchanged, otherwise the version and marker are set and components, paths and webhooks are converted.
   * @evidence contracts/common.md#clear-and-simple-design One function.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The marker is the contract marker.
   * @evidence contracts/common.md#meaningful-documentation The doc states the pass-through of an emended document.
   */
  export const convert = (input: OpenApiV3_1.IDocument): OpenApi.IDocument => {
    if ((input as unknown as OpenApi.IDocument)["x-typia-emended-v12"] === true)
      return input as unknown as OpenApi.IDocument;
    return {
      ...input,
      openapi: "3.2.0",
      components: convertComponents(input.components ?? {}),
      paths: input.paths
        ? Object.fromEntries(
            Object.entries(input.paths)
              .filter(([_, v]) => v !== undefined)
              .map(
                ([key, value]) => [key, convertPathItem(input)(value)] as const,
              ),
          )
        : undefined,
      webhooks: input.webhooks
        ? Object.fromEntries(
            Object.entries(input.webhooks)
              .filter(([_, v]) => v !== undefined)
              .map(
                ([key, value]) =>
                  [key, convertWebhooks(input)(value)!] as const,
              )
              .filter(([_, value]) => value !== undefined),
          )
        : undefined,
      "x-typia-emended-v12": true,
    };
  };

  /* -----------------------------------------------------------
    OPERATORS
  ----------------------------------------------------------- */
  const convertWebhooks =
    (doc: OpenApiV3_1.IDocument) =>
    (
      webhook:
        | OpenApiV3_1.IPath
        | OpenApiV3_1.IJsonSchema.IReference<`#/components/pathItems/${string}`>,
    ): OpenApi.IPath | undefined => {
      if (!OpenApiV3_1TypeChecker.isReference(webhook))
        return convertPathItem(doc)(webhook);
      const found: OpenApiV3_1.IPath | undefined = OpenApiReferenceKey.get(
        doc.components?.pathItems,
        webhook.$ref,
      );
      return found ? convertPathItem(doc)(found) : undefined;
    };

  const convertPathItem =
    (doc: OpenApiV3_1.IDocument) =>
    (pathItem: OpenApiV3_1.IPath): OpenApi.IPath => {
      // Convert x-additionalOperations to additionalOperations
      // Promote "query" to standard method (it's a v3.2 standard method)
      const xAdditional = pathItem["x-additionalOperations"];
      const queryOp = xAdditional?.["query"];
      const additionalOperations = xAdditional
        ? Object.fromEntries(
            Object.entries(xAdditional)
              .filter(([key, v]) => key !== "query" && v !== undefined)
              .map(([key, value]) => [
                key,
                convertOperation(doc)(pathItem)(value),
              ]),
          )
        : undefined;
      const { parameters: _parameters, ...rest } = pathItem as any;

      return {
        ...rest,
        ...(pathItem.get
          ? { get: convertOperation(doc)(pathItem)(pathItem.get) }
          : undefined),
        ...(pathItem.put
          ? { put: convertOperation(doc)(pathItem)(pathItem.put) }
          : undefined),
        ...(pathItem.post
          ? { post: convertOperation(doc)(pathItem)(pathItem.post) }
          : undefined),
        ...(pathItem.delete
          ? { delete: convertOperation(doc)(pathItem)(pathItem.delete) }
          : undefined),
        ...(pathItem.options
          ? { options: convertOperation(doc)(pathItem)(pathItem.options) }
          : undefined),
        ...(pathItem.head
          ? { head: convertOperation(doc)(pathItem)(pathItem.head) }
          : undefined),
        ...(pathItem.patch
          ? { patch: convertOperation(doc)(pathItem)(pathItem.patch) }
          : undefined),
        ...(pathItem.trace
          ? { trace: convertOperation(doc)(pathItem)(pathItem.trace) }
          : undefined),
        ...(queryOp
          ? { query: convertOperation(doc)(pathItem)(queryOp) }
          : undefined),
        ...(additionalOperations && Object.keys(additionalOperations).length > 0
          ? { additionalOperations }
          : undefined),
        "x-additionalOperations": undefined,
      };
    };

  const convertOperation =
    (doc: OpenApiV3_1.IDocument) =>
    (pathItem: OpenApiV3_1.IPath) =>
    (input: OpenApiV3_1.IOperation): OpenApi.IOperation => {
      const components: OpenApiV3_1.IComponents = doc.components ?? {};
      const pathParameters: OpenApiV3_1.IOperation.IParameter[] = (
        pathItem.parameters ?? []
      )
        .map(resolveParameter(components))
        .filter((p): p is OpenApiV3_1.IOperation.IParameter => p !== undefined);
      const operationParameters: OpenApiV3_1.IOperation.IParameter[] = (
        input.parameters ?? []
      )
        .map(resolveParameter(components))
        .filter((p): p is OpenApiV3_1.IOperation.IParameter => p !== undefined);
      return {
        ...input,
        parameters:
          pathItem.parameters !== undefined || input.parameters !== undefined
            ? mergeParameters(pathParameters, operationParameters).map(
                convertParameter(components),
              )
            : undefined,
        requestBody: input.requestBody
          ? convertRequestBody(doc)(input.requestBody)
          : undefined,
        responses: input.responses
          ? Object.fromEntries(
              Object.entries(input.responses)
                .filter(([_, v]) => v !== undefined)
                .map(
                  ([key, value]) =>
                    [key, convertResponse(doc)(value)!] as const,
                )
                .filter(([_, value]) => value !== undefined),
            )
          : undefined,
      };
    };

  const resolveParameter =
    (components: OpenApiV3_1.IComponents) =>
    (
      input:
        | OpenApiV3_1.IOperation.IParameter
        | OpenApiV3_1.IJsonSchema.IReference<`#/components/headers/${string}`>
        | OpenApiV3_1.IJsonSchema.IReference<`#/components/parameters/${string}`>,
    ): OpenApiV3_1.IOperation.IParameter | undefined => {
      if (!("$ref" in input)) return input;
      const key: string | undefined = OpenApiReferenceKey.read(input.$ref);
      if (key === undefined) return undefined;
      if (input.$ref.startsWith("#/components/headers/")) {
        const header:
          | Omit<OpenApiV3_1.IOperation.IParameter, "in">
          | undefined = OpenApiReferenceKey.get(components.headers, input.$ref);
        if (header === undefined) return undefined;
        const { name, ...rest } = header;
        return { ...rest, name: name ?? key, in: "header" };
      }
      return OpenApiReferenceKey.get(components.parameters, input.$ref);
    };

  const mergeParameters = (
    pathParameters: OpenApiV3_1.IOperation.IParameter[],
    operationParameters: OpenApiV3_1.IOperation.IParameter[],
  ): OpenApiV3_1.IOperation.IParameter[] => {
    const map: Map<string, OpenApiV3_1.IOperation.IParameter> = new Map();
    const duplicates = (
      parameters: OpenApiV3_1.IOperation.IParameter[],
    ): OpenApiV3_1.IOperation.IParameter[] => {
      const seen: Set<string> = new Set();
      return parameters.filter((parameter) => {
        const key: string = `${parameter.in}:${parameter.name}`;
        if (seen.has(key)) return true;
        seen.add(key);
        return false;
      });
    };
    const emplace = (parameter: OpenApiV3_1.IOperation.IParameter): void => {
      map.set(`${parameter.in}:${parameter.name}`, parameter);
    };
    pathParameters.forEach(emplace);
    operationParameters.forEach(emplace);
    return [
      ...map.values(),
      ...duplicates(pathParameters),
      ...duplicates(operationParameters),
    ];
  };

  const convertParameter =
    (components: OpenApiV3_1.IComponents) =>
    (
      input: OpenApiV3_1.IOperation.IParameter,
    ): OpenApi.IOperation.IParameter => {
      const { required: inputRequired, ...rest } = input;
      const required: boolean | undefined =
        input.in === "path" ? true : inputRequired;
      return {
        ...rest,
        ...(required !== undefined ? { required } : {}),
        schema: convertSchema(components)(input.schema),
        examples: input.examples
          ? Object.fromEntries(
              Object.entries(input.examples)
                .map(([key, value]) => [
                  key,
                  OpenApiV3_1TypeChecker.isReference(value)
                    ? OpenApiReferenceKey.get(components.examples, value.$ref)
                    : value,
                ])
                .filter(([_, v]) => v !== undefined),
            )
          : undefined,
      };
    };

  const convertRequestBody =
    (doc: OpenApiV3_1.IDocument) =>
    (
      input:
        | OpenApiV3_1.IOperation.IRequestBody
        | OpenApiV3_1.IJsonSchema.IReference<`#/components/requestBodies/${string}`>,
    ): OpenApi.IOperation.IRequestBody | undefined => {
      if ("$ref" in input) {
        const found: OpenApiV3_1.IOperation.IRequestBody | undefined =
          OpenApiReferenceKey.get(doc.components?.requestBodies, input.$ref);
        if (found === undefined) return undefined;
        input = found;
      }
      return {
        ...input,
        content: input.content
          ? convertContent(doc.components ?? {})(input.content)
          : undefined,
      };
    };

  const convertResponse =
    (doc: OpenApiV3_1.IDocument) =>
    (
      input:
        | OpenApiV3_1.IOperation.IResponse
        | OpenApiV3_1.IJsonSchema.IReference<`#/components/responses/${string}`>,
    ): OpenApi.IOperation.IResponse | undefined => {
      if ("$ref" in input) {
        const found: OpenApiV3_1.IOperation.IResponse | undefined =
          OpenApiReferenceKey.get(doc.components?.responses, input.$ref);
        if (found === undefined) return undefined;
        input = found;
      }
      return {
        ...input,
        content: input.content
          ? convertContent(doc.components ?? {})(input.content)
          : undefined,
        headers: input.headers
          ? Object.fromEntries(
              Object.entries(input.headers)
                .filter(([_, v]) => v !== undefined)
                .map(([key, value]) => [
                  key,
                  convertHeader(doc.components ?? {})(key, value),
                ])
                .filter(([_, v]) => v !== undefined),
            )
          : undefined,
      };
    };

  const convertHeader =
    (components: OpenApiV3_1.IComponents) =>
    (
      key: string,
      input:
        | Omit<OpenApiV3_1.IOperation.IParameter, "in">
        | OpenApiV3_1.IJsonSchema.IReference<`#/components/headers/${string}`>,
    ): OpenApi.IOperation.IParameter | undefined => {
      if ("$ref" in input) {
        const found: Omit<OpenApiV3_1.IOperation.IParameter, "in"> | undefined =
          input.$ref.startsWith("#/components/headers/")
            ? OpenApiReferenceKey.get(components.headers, input.$ref)
            : undefined;
        if (found === undefined) return undefined;
        input = found;
      }
      const { name: _name, ...rest } = input;
      return convertParameter(components)({
        ...rest,
        name: key,
        in: "header",
      });
    };

  const convertContent =
    (components: OpenApiV3_1.IComponents) =>
    (
      record: Record<string, OpenApiV3_1.IOperation.IMediaType>,
    ): Record<string, OpenApi.IOperation.IMediaType> =>
      Object.fromEntries(
        Object.entries(record)
          .filter(([_, v]) => v !== undefined)
          .map(
            ([key, value]) =>
              [
                key,
                {
                  ...value,
                  schema: value.schema
                    ? convertSchema(components)(value.schema)
                    : undefined,
                  examples: value.examples
                    ? Object.fromEntries(
                        Object.entries(value.examples)
                          .map(([key, value]) => [
                            key,
                            OpenApiV3_1TypeChecker.isReference(value)
                              ? OpenApiReferenceKey.get(
                                  components.examples,
                                  value.$ref,
                                )
                              : value,
                          ])
                          .filter(([_, v]) => v !== undefined),
                      )
                    : undefined,
                },
              ] as const,
          ),
      );

  /* -----------------------------------------------------------
    DEFINITIONS
  ----------------------------------------------------------- */
  /**
   * Upgrade the components of a 3.1 or 3.2 document; only schemas and security
   * schemes are kept.
   *
   * @param input OpenAPI 3.1 components
   *
   * @returns Emended components
   *
   * @evidence contracts/common.md#principled-implementation Component schemas are converted and security schemes kept; other component kinds are not needed once references are inlined.
   * @evidence contracts/common.md#clear-and-simple-design One function, also used for 3.2 and for the component entry of OpenApiConverter.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Supported schema and security-scheme stores are retained without reachability pruning; other component kinds are consumed while converting operations.
   * @evidence contracts/common.md#meaningful-documentation The doc states what is kept.
   */
  export const convertComponents = (
    input: OpenApiV3_1.IComponents,
  ): OpenApi.IComponents => ({
    schemas: Object.fromEntries(
      Object.entries(input.schemas ?? {})
        .filter(([_, v]) => v !== undefined)
        .map(([key, value]) => [key, convertSchema(input)(value)] as const),
    ),
    securitySchemes: input.securitySchemes,
  });

  /**
   * Upgrade one 3.1 schema, as the 3.2 upgrader does too.
   *
   * A `type` array becomes a union restricted by its `enum`, including the
   * empty enum. Null requires both assertions to allow it. An empty primitive
   * intersection becomes a string with contradictory length bounds, a valid
   * schema with no possible instance. This preserves rejection through schema
   * validation and downversion conversion; strict LLM conversion still shifts
   * bounds into descriptions, and type coverage remains conservative across
   * different atomic types. A tuple becomes `prefixItems` with its rest schema.
   * Boolean `items: false` without a prefix becomes an empty closed tuple; true
   * or omitted items leave array elements unconstrained.
   *
   * @param components Components used to resolve references
   *
   * @returns Function that converts a 3.1 schema to the emended schema
   *
   * @evidence contracts/common.md#principled-implementation Mixed primitive enum members satisfy both listed type and enum membership; integer uses Number.isInteger and null must be explicitly listed. If no member survives, minLength 1 and maxLength 0 define an empty valid-instance set using supported string assertions instead of invalid empty oneOf or unknown. The outer annotation record remains on the result. This is not a universal never variant: strict LLM conversion and cross-type covers keep their documented limitations, and existing container enum support is not expanded.
   * @evidence contracts/common.md#clear-and-simple-design One recursive function with a mixed-type branch that reuses the single-type branches.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The enum restriction follows JSON Schema's simultaneous type and enum constraint, and the condition is the general form and not a patch for one input.
   * @evidence contracts/common.md#meaningful-documentation The doc states the type array, enum and tuple rules.
   */
  export const convertSchema =
    (components: OpenApiV3_1.IComponents) =>
    (input: OpenApiV3_1.IJsonSchema): OpenApi.IJsonSchema => {
      const union: OpenApi.IJsonSchema[] = [];
      const discriminator:
        | OpenApi.IJsonSchema.IOneOf.IDiscriminator
        | undefined =
        OpenApiV3_1TypeChecker.isMixed(input) === false &&
        OpenApiV3_1TypeChecker.isOneOf(input) &&
        input.discriminator !== undefined
          ? OpenApiDiscriminatorConverter.clone(input.discriminator)
          : undefined;
      let preserveDiscriminator: boolean = discriminator !== undefined;
      const attribute: IJsonSchemaAttribute = {
        title: input.title,
        description: input.description,
        deprecated: input.deprecated,
        readOnly: input.readOnly,
        writeOnly: input.writeOnly,
        example: input.example,
        examples: Array.isArray(input.examples)
          ? Object.fromEntries(input.examples.map((v, i) => [`v${i}`, v]))
          : input.examples,
        ...Object.fromEntries(
          Object.entries(input).filter(
            ([key, value]) => key.startsWith("x-") && value !== undefined,
          ),
        ),
      };
      const nullable: { value: boolean; default?: null } = {
        value: false,
        default: undefined,
      };

      const visit = (schema: OpenApiV3_1.IJsonSchema): void => {
        // NULLABLE PROPERTY
        if (
          !OpenApiV3_1TypeChecker.isMixed(schema) &&
          (schema as OpenApiV3_1.IJsonSchema.INumber).nullable === true
        ) {
          nullable.value ||= true;
          if ((schema as OpenApiV3_1.IJsonSchema.INumber).default === null)
            nullable.default = null;
        }
        if (
          !OpenApiV3_1TypeChecker.isMixed(schema) &&
          Array.isArray((schema as OpenApiV3_1.IJsonSchema.INumber).enum) &&
          (schema as OpenApiV3_1.IJsonSchema.INumber).enum?.length &&
          (schema as OpenApiV3_1.IJsonSchema.INumber).enum?.some(
            (e) => e === null,
          )
        )
          nullable.value ||= true;

        // MIXED TYPE CASE
        if (OpenApiV3_1TypeChecker.isMixed(schema)) {
          const previous: number = union.length;
          const previousNullable: boolean = nullable.value;
          if (schema.const !== undefined)
            visit({
              ...schema,
              ...{
                type: undefined,
                oneOf: undefined,
                anyOf: undefined,
                allOf: undefined,
                $ref: undefined,
              },
            });
          if (schema.oneOf !== undefined)
            visit({
              ...schema,
              ...{
                type: undefined,
                anyOf: undefined,
                allOf: undefined,
                $ref: undefined,
              },
            });
          if (schema.anyOf !== undefined)
            visit({
              ...schema,
              ...{
                type: undefined,
                oneOf: undefined,
                allOf: undefined,
                $ref: undefined,
              },
            });
          if (schema.allOf !== undefined)
            visit({
              ...schema,
              ...{
                type: undefined,
                oneOf: undefined,
                anyOf: undefined,
                $ref: undefined,
              },
            });
          // Both assertions apply: even an empty enum admits no value, and
          // null is admitted only by a listed null type and a matching enum.
          const enumerated: boolean = schema.enum !== undefined;
          for (const type of schema.type) {
            const values: unknown[] | undefined = !enumerated
              ? undefined
              : type === "boolean" || type === "number" || type === "string"
                ? schema.enum!.filter((x) => typeof x === type)
                : type === "integer"
                  ? schema.enum!.filter(
                      (x) => typeof x === "number" && Number.isInteger(x),
                    )
                  : type === "null"
                    ? schema.enum!.filter((x) => x === null)
                    : undefined;
            if (values !== undefined && values.length === 0) continue;
            visit({
              ...schema,
              nullable: undefined,
              ...(type === "null"
                ? { enum: undefined }
                : type === "boolean" ||
                    type === "number" ||
                    type === "string" ||
                    type === "integer"
                  ? { enum: values as any }
                  : {}),
              type: type as any,
            });
          }
          if (union.length === previous && nullable.value === previousNullable)
            // This supported string schema has no possible instance. Unlike
            // an empty oneOf, it is valid JSON Schema and retains rejection
            // through the existing OpenAPI downgrader and validator paths.
            union.push({ type: "string", minLength: 1, maxLength: 0 });
        }
        // UNION TYPE CASE
        else if (OpenApiV3_1TypeChecker.isOneOf(schema)) {
          const tracked: boolean =
            schema === input && discriminator !== undefined;
          if (tracked && nullable.value) preserveDiscriminator = false;
          for (const branch of schema.oneOf) {
            const previous: number = union.length;
            const previousNullable: boolean = nullable.value;
            visit(branch);
            if (
              tracked &&
              (union.length !== previous + 1 ||
                nullable.value !== previousNullable)
            )
              preserveDiscriminator = false;
          }
        } else if (OpenApiV3_1TypeChecker.isAnyOf(schema))
          schema.anyOf.forEach(visit);
        else if (OpenApiV3_1TypeChecker.isAllOf(schema))
          if (schema.allOf.length === 1) visit(schema.allOf[0]!);
          else union.push(convertAllOfSchema(components)(schema));
        // ATOMIC TYPE CASE (CONSIDER ENUM VALUES)
        else if (OpenApiV3_1TypeChecker.isBoolean(schema))
          if (
            schema.enum?.length &&
            schema.enum.filter((e) => e !== null).length
          )
            for (const value of schema.enum.filter((e) => e !== null))
              union.push({
                const: value,
                ...({
                  ...schema,
                  type: undefined as any,
                  enum: undefined,
                  default: undefined,
                } satisfies OpenApiV3_1.IJsonSchema.IBoolean as any),
              } satisfies OpenApi.IJsonSchema.IConstant);
          else
            union.push({
              ...schema,
              default: schema.default ?? undefined,
              ...{
                enum: undefined,
              },
            });
        else if (
          OpenApiV3_1TypeChecker.isInteger(schema) ||
          OpenApiV3_1TypeChecker.isNumber(schema)
        )
          if (schema.enum?.length && schema.enum.filter((e) => e !== null))
            for (const value of schema.enum.filter((e) => e !== null))
              union.push({
                const: value,
                ...({
                  ...schema,
                  type: undefined as any,
                  enum: undefined,
                  default: undefined,
                  minimum: undefined,
                  maximum: undefined,
                  exclusiveMinimum: undefined,
                  exclusiveMaximum: undefined,
                  multipleOf: undefined,
                } satisfies OpenApiV3_1.IJsonSchema.IInteger as any),
              } satisfies OpenApi.IJsonSchema.IConstant);
          else
            union.push(
              OpenApiExclusiveEmender.emend({
                ...schema,
                default: schema.default ?? undefined,
                ...{
                  enum: undefined,
                },
                exclusiveMinimum:
                  typeof schema.exclusiveMinimum === "boolean"
                    ? schema.exclusiveMinimum === true
                      ? schema.minimum
                      : undefined
                    : schema.exclusiveMinimum,
                exclusiveMaximum:
                  typeof schema.exclusiveMaximum === "boolean"
                    ? schema.exclusiveMaximum === true
                      ? schema.maximum
                      : undefined
                    : schema.exclusiveMaximum,
                minimum:
                  schema.exclusiveMinimum === true ? undefined : schema.minimum,
                maximum:
                  schema.exclusiveMaximum === true ? undefined : schema.maximum,
              }),
            );
        else if (OpenApiV3_1TypeChecker.isString(schema)) {
          const normalized: OpenApiV3_1.IJsonSchema.IString =
            normalizeStringSchema(schema);
          if (
            normalized.enum?.length &&
            normalized.enum.filter((e) => e !== null).length
          )
            for (const value of normalized.enum.filter((e) => e !== null))
              union.push({
                const: value,
                ...({
                  ...normalized,
                  type: undefined as any,
                  enum: undefined,
                  default: undefined,
                } satisfies OpenApiV3_1.IJsonSchema.IString as any),
              } satisfies OpenApi.IJsonSchema.IConstant);
          else
            union.push({
              ...normalized,
              default: normalized.default ?? undefined,
              ...{
                enum: undefined,
              },
            });
        }
        // ARRAY TYPE CASE (CONSIDER TUPLE)
        else if (OpenApiV3_1TypeChecker.isArray(schema)) {
          if (Array.isArray(schema.items))
            union.push({
              ...schema,
              ...{
                items: undefined!,
                prefixItems: schema.items.map(convertSchema(components)),
                additionalItems:
                  typeof schema.additionalItems === "object" &&
                  schema.additionalItems !== null
                    ? convertSchema(components)(schema.additionalItems)
                    : schema.additionalItems,
              },
            } satisfies OpenApi.IJsonSchema.ITuple);
          else if (Array.isArray(schema.prefixItems))
            union.push({
              ...schema,
              ...{
                items: undefined!,
                prefixItems: schema.prefixItems.map(convertSchema(components)),
                minItems: schema.minItems ?? 0,
                additionalItems:
                  typeof schema.items === "object" && schema.items !== null
                    ? convertSchema(components)(schema.items)
                    : (schema.items ?? true),
              },
            });
          else if (schema.items === false)
            union.push({
              ...schema,
              ...{
                items: undefined!,
                prefixItems: [],
                minItems: schema.minItems ?? 0,
                additionalItems: false,
              },
            } satisfies OpenApi.IJsonSchema.ITuple);
          else if (schema.items === undefined || schema.items === true)
            // OMITTED OR TRUE `items` LEAVES EVERY ARRAY ELEMENT UNCONSTRAINED.
            union.push({
              ...schema,
              ...{
                items: {},
                prefixItems: undefined,
                additionalItems: undefined,
              },
            });
          else
            union.push({
              ...schema,
              ...{
                items: convertSchema(components)(schema.items),
                prefixItems: undefined,
                additionalItems: undefined,
              },
            });
        }
        // OBJECT TYPE CASE
        else if (OpenApiV3_1TypeChecker.isObject(schema)) {
          union.push({
            ...schema,
            properties:
              schema.properties === undefined
                ? undefined
                : Object.fromEntries(
                    Object.entries(schema.properties)
                      .filter(([_, v]) => v !== undefined)
                      .map(
                        ([key, value]) =>
                          [key, convertSchema(components)(value)] as const,
                      ),
                  ),
            additionalProperties:
              schema.additionalProperties === undefined
                ? undefined
                : typeof schema.additionalProperties === "object" &&
                    schema.additionalProperties !== null
                  ? convertSchema(components)(schema.additionalProperties)
                  : schema.additionalProperties,
            required: schema.required,
          });
        } else if (OpenApiV3_1TypeChecker.isReference(schema))
          union.push({
            ...schema,
            ...{
              $ref: `#/components/schemas/${schema.$ref.split("/").pop()}`,
            },
          });
        else if (OpenApiV3_1TypeChecker.isRecursiveReference(schema))
          union.push({
            ...schema,
            ...{
              $ref: `#/components/schemas/${schema.$recursiveRef.split("/").pop()}`,
              $recursiveRef: undefined,
            },
          });
        // THE OTHERS
        else union.push(schema);
      };

      visit(input);
      if (
        nullable.value === true &&
        !union.some((e) => (e as OpenApi.IJsonSchema.INull).type === "null")
      )
        union.push({
          type: "null",
          default: nullable.default,
        });
      if (
        union.length === 2 &&
        union.filter((x) => OpenApiTypeChecker.isNull(x)).length === 1
      ) {
        const type: OpenApi.IJsonSchema = union.filter(
          (x) => OpenApiTypeChecker.isNull(x) === false,
        )[0]!;
        for (const key of [
          "title",
          "description",
          "deprecated",
          "readOnly",
          "writeOnly",
          "example",
          "examples",
        ] as const)
          if (type[key] !== undefined) delete type[key];
      }
      return {
        ...(union.length === 0
          ? {
              type: undefined,
            }
          : union.length === 1
            ? {
                ...union[0],
              }
            : {
                oneOf: union.map((u) => ({
                  ...u,
                  nullable: undefined,
                  $defs: undefined,
                })),
                ...(preserveDiscriminator && discriminator !== undefined
                  ? { discriminator }
                  : {}),
              }),
        ...attribute,
        ...{
          nullable: undefined,
          $defs: undefined,
        },
      };
    };

  const convertAllOfSchema =
    (components: OpenApiV3_1.IComponents) =>
    (input: OpenApiV3_1.IJsonSchema.IAllOf): OpenApi.IJsonSchema => {
      const objects: Array<OpenApiV3_1.IJsonSchema.IObject | null> =
        input.allOf.map((schema) => retrieveObject(components)(schema));
      if (objects.some((obj) => obj === null))
        return {
          type: undefined,
          ...{
            allOf: undefined,
          },
        };
      return {
        ...input,
        type: "object" as const,
        properties: Object.fromEntries(
          objects
            .map((o) => Object.entries(o?.properties ?? {}))
            .flat()
            .map(
              ([key, value]) =>
                [key, convertSchema(components)(value)] as const,
            ),
        ),
        additionalProperties: objects.every(
          (o) => o?.additionalProperties === false,
        )
          ? false
          : undefined,
        ...{
          allOf: undefined,
          required: [...new Set(objects.map((o) => o?.required ?? []).flat())],
        },
      };
    };

  const retrieveObject =
    (components: OpenApiV3_1.IComponents) =>
    (
      input: OpenApiV3_1.IJsonSchema,
      visited: Set<OpenApiV3_1.IJsonSchema> = new Set(),
    ): OpenApiV3_1.IJsonSchema.IObject | null => {
      if (OpenApiV3_1TypeChecker.isObject(input))
        return input.properties !== undefined && !input.additionalProperties
          ? input
          : null;
      else if (visited.has(input)) return null;
      else visited.add(input);

      if (OpenApiV3_1TypeChecker.isReference(input))
        return retrieveObject(components)(
          OpenApiReferenceKey.get(components.schemas, input.$ref) ?? {},
          visited,
        );
      else if (OpenApiV3_1TypeChecker.isRecursiveReference(input))
        return retrieveObject(components)(
          OpenApiReferenceKey.get(components.schemas, input.$recursiveRef) ??
            {},
          visited,
        );
      return null;
    };

  const normalizeStringSchema = (
    schema: OpenApiV3_1.IJsonSchema.IString,
  ): OpenApiV3_1.IJsonSchema.IString => {
    if (
      schema.contentEncoding !== "base64" ||
      (schema.format !== undefined && schema.format !== "byte")
    )
      return schema;
    const { contentEncoding: _contentEncoding, ...rest } = schema;
    return {
      ...rest,
      format: "byte",
    };
  };
}

import { OpenApi, OpenApiV3_2 } from "@typia/interface";

import { OpenApiReferenceKey } from "../../utils/internal/OpenApiReferenceKey";
import { OpenApiV3_1TypeChecker } from "../../validators/OpenApiV3_1TypeChecker";
import { OpenApiV3_1Upgrader } from "./OpenApiV3_1Upgrader";

/**
 * OpenAPI v3.2 to emended OpenApi converter.
 *
 * Reuses JSON Schema conversion logic from OpenApiV3_1Upgrader since the schema
 * format is identical between v3.1 and v3.2.
 *
 * @evidence contracts/common.md#principled-implementation A 3.2 document differs from 3.1 in tags, additional operations, `querystring` parameters, item schemas and OAuth2 additions, so only those parts are converted here and every schema goes through the 3.1 conversion because the dialect is identical.
 * @evidence contracts/common.md#clear-and-simple-design A small number of helpers around reuse of the 3.1 schema conversion.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Reuse is by calling the 3.1 converter and not by copying its logic; the 3.2-only fields are copied by name from the interface.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment explains the reuse of the 3.1 schema conversion.
 */
export namespace OpenApiV3_2Upgrader {
  /**
   * Upgrade a whole 3.2 document; a document that is already emended is
   * returned as it is.
   *
   * @param input OpenAPI 3.2 document
   *
   * @returns Emended document marked with `x-typia-emended-v12`
   *
   * @evidence contracts/common.md#principled-implementation An emended input is returned as is, otherwise tags, paths and webhooks are converted and the emended marker is set.
   * @evidence contracts/common.md#clear-and-simple-design One function.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The marker is the contract marker.
   * @evidence contracts/common.md#meaningful-documentation The doc states the pass-through.
   */
  export const convert = (input: OpenApiV3_2.IDocument): OpenApi.IDocument => {
    if ((input as OpenApi.IDocument)["x-typia-emended-v12"] === true)
      return input as OpenApi.IDocument;
    return {
      ...input,
      openapi: "3.2.0",
      components: convertComponents(input.components ?? {}),
      tags: input.tags?.map(convertTag),
      paths: input.paths
        ? Object.fromEntries(
            Object.entries(input.paths)
              .filter(([_, v]) => v !== undefined)
              .map(
                ([key, value]) => [key, convertPathItem(input)(value)] as const,
              ),
          )
        : undefined,
      webhooks: input.webhooks
        ? Object.fromEntries(
            Object.entries(input.webhooks)
              .filter(([_, v]) => v !== undefined)
              .map(
                ([key, value]) =>
                  [key, convertWebhooks(input)(value)!] as const,
              )
              .filter(([_, value]) => value !== undefined),
          )
        : undefined,
      "x-typia-emended-v12": true,
    };
  };

  /* -----------------------------------------------------------
    TAGS
  ----------------------------------------------------------- */
  const convertTag = (
    tag: OpenApiV3_2.IDocument.ITag,
  ): OpenApi.IDocument.ITag => ({
    name: tag.name,
    summary: tag.summary,
    description: tag.description,
    parent: tag.parent,
    kind: tag.kind,
  });

  /* -----------------------------------------------------------
    OPERATORS
  ----------------------------------------------------------- */
  const convertWebhooks =
    (doc: OpenApiV3_2.IDocument) =>
    (
      webhook:
        | OpenApiV3_2.IPath
        | OpenApiV3_2.IJsonSchema.IReference<`#/components/pathItems/${string}`>,
    ): OpenApi.IPath | undefined => {
      if (!OpenApiV3_1TypeChecker.isReference(webhook))
        return convertPathItem(doc)(webhook);
      const found: OpenApiV3_2.IPath | undefined = OpenApiReferenceKey.get(
        doc.components?.pathItems,
        webhook.$ref,
      );
      return found ? convertPathItem(doc)(found) : undefined;
    };

  const convertPathItem =
    (doc: OpenApiV3_2.IDocument) =>
    (pathItem: OpenApiV3_2.IPath): OpenApi.IPath => {
      const { parameters: _parameters, ...rest } = pathItem as any;
      return {
        ...rest,
        ...(pathItem.get
          ? { get: convertOperation(doc)(pathItem)(pathItem.get) }
          : undefined),
        ...(pathItem.put
          ? { put: convertOperation(doc)(pathItem)(pathItem.put) }
          : undefined),
        ...(pathItem.post
          ? { post: convertOperation(doc)(pathItem)(pathItem.post) }
          : undefined),
        ...(pathItem.delete
          ? { delete: convertOperation(doc)(pathItem)(pathItem.delete) }
          : undefined),
        ...(pathItem.options
          ? { options: convertOperation(doc)(pathItem)(pathItem.options) }
          : undefined),
        ...(pathItem.head
          ? { head: convertOperation(doc)(pathItem)(pathItem.head) }
          : undefined),
        ...(pathItem.patch
          ? { patch: convertOperation(doc)(pathItem)(pathItem.patch) }
          : undefined),
        ...(pathItem.trace
          ? { trace: convertOperation(doc)(pathItem)(pathItem.trace) }
          : undefined),
        ...(pathItem.query
          ? { query: convertOperation(doc)(pathItem)(pathItem.query) }
          : undefined),
        ...(pathItem.additionalOperations
          ? {
              additionalOperations: Object.fromEntries(
                Object.entries(pathItem.additionalOperations)
                  .filter(([_, v]) => v !== undefined)
                  .map(
                    ([key, value]) =>
                      [key, convertOperation(doc)(pathItem)(value)] as const,
                  ),
              ),
            }
          : undefined),
      };
    };

  const convertOperation =
    (doc: OpenApiV3_2.IDocument) =>
    (pathItem: OpenApiV3_2.IPath) =>
    (input: OpenApiV3_2.IOperation): OpenApi.IOperation => {
      const components: OpenApiV3_2.IComponents = doc.components ?? {};
      const pathParameters: OpenApiV3_2.IOperation.IParameter[] = (
        pathItem.parameters ?? []
      )
        .map(resolveParameter(components))
        .filter((p): p is OpenApiV3_2.IOperation.IParameter => p !== undefined);
      const operationParameters: OpenApiV3_2.IOperation.IParameter[] = (
        input.parameters ?? []
      )
        .map(resolveParameter(components))
        .filter((p): p is OpenApiV3_2.IOperation.IParameter => p !== undefined);
      return {
        ...input,
        parameters:
          pathItem.parameters !== undefined || input.parameters !== undefined
            ? mergeParameters(pathParameters, operationParameters).map(
                convertParameter(components),
              )
            : undefined,
        requestBody: input.requestBody
          ? convertRequestBody(doc)(input.requestBody)
          : undefined,
        responses: input.responses
          ? Object.fromEntries(
              Object.entries(input.responses)
                .filter(([_, v]) => v !== undefined)
                .map(
                  ([key, value]) =>
                    [key, convertResponse(doc)(value)!] as const,
                )
                .filter(([_, value]) => value !== undefined),
            )
          : undefined,
      };
    };

  const resolveParameter =
    (components: OpenApiV3_2.IComponents) =>
    (
      input:
        | OpenApiV3_2.IOperation.IParameter
        | OpenApiV3_2.IJsonSchema.IReference<`#/components/headers/${string}`>
        | OpenApiV3_2.IJsonSchema.IReference<`#/components/parameters/${string}`>,
    ): OpenApiV3_2.IOperation.IParameter | undefined => {
      if (!("$ref" in input)) return input;
      const key: string | undefined = OpenApiReferenceKey.read(input.$ref);
      if (key === undefined) return undefined;
      if (input.$ref.startsWith("#/components/headers/")) {
        const header:
          | Omit<OpenApiV3_2.IOperation.IParameter, "in">
          | undefined = OpenApiReferenceKey.get(components.headers, input.$ref);
        if (header === undefined) return undefined;
        const { name, ...rest } = header;
        return { ...rest, name: name ?? key, in: "header" };
      }
      return OpenApiReferenceKey.get(components.parameters, input.$ref);
    };

  const mergeParameters = (
    pathParameters: OpenApiV3_2.IOperation.IParameter[],
    operationParameters: OpenApiV3_2.IOperation.IParameter[],
  ): OpenApiV3_2.IOperation.IParameter[] => {
    const map: Map<string, OpenApiV3_2.IOperation.IParameter> = new Map();
    const duplicates = (
      parameters: OpenApiV3_2.IOperation.IParameter[],
    ): OpenApiV3_2.IOperation.IParameter[] => {
      const seen: Set<string> = new Set();
      return parameters.filter((parameter) => {
        const key: string = `${parameter.in}:${parameter.name}`;
        if (seen.has(key)) return true;
        seen.add(key);
        return false;
      });
    };
    const emplace = (parameter: OpenApiV3_2.IOperation.IParameter): void => {
      map.set(`${parameter.in}:${parameter.name}`, parameter);
    };
    pathParameters.forEach(emplace);
    operationParameters.forEach(emplace);
    return [
      ...map.values(),
      ...duplicates(pathParameters),
      ...duplicates(operationParameters),
    ];
  };

  const convertParameter =
    (components: OpenApiV3_2.IComponents) =>
    (
      input: OpenApiV3_2.IOperation.IParameter,
    ): OpenApi.IOperation.IParameter => {
      const { required: inputRequired, ...rest } = input;
      const required: boolean | undefined =
        input.in === "path" ? true : inputRequired;
      const content: OpenApi.IOperation.IContent | undefined = input.content
        ? convertContent(components)(input.content)
        : undefined;
      return {
        ...rest,
        ...(required !== undefined ? { required } : {}),
        schema:
          input.schema !== undefined
            ? convertSchema(components)(input.schema)
            : (Object.values(content ?? {})[0]?.schema ?? {}),
        content,
        examples: input.examples
          ? Object.fromEntries(
              Object.entries(input.examples)
                .map(([key, value]) => [
                  key,
                  OpenApiV3_1TypeChecker.isReference(value)
                    ? OpenApiReferenceKey.get(components.examples, value.$ref)
                    : value,
                ])
                .filter(([_, v]) => v !== undefined),
            )
          : undefined,
      };
    };

  const convertRequestBody =
    (doc: OpenApiV3_2.IDocument) =>
    (
      input:
        | OpenApiV3_2.IOperation.IRequestBody
        | OpenApiV3_2.IJsonSchema.IReference<`#/components/requestBodies/${string}`>,
    ): OpenApi.IOperation.IRequestBody | undefined => {
      if ("$ref" in input) {
        const found: OpenApiV3_2.IOperation.IRequestBody | undefined =
          OpenApiReferenceKey.get(doc.components?.requestBodies, input.$ref);
        if (found === undefined) return undefined;
        input = found;
      }
      return {
        ...input,
        content: input.content
          ? convertContent(doc.components ?? {})(input.content)
          : undefined,
      };
    };

  const convertResponse =
    (doc: OpenApiV3_2.IDocument) =>
    (
      input:
        | OpenApiV3_2.IOperation.IResponse
        | OpenApiV3_2.IJsonSchema.IReference<`#/components/responses/${string}`>,
    ): OpenApi.IOperation.IResponse | undefined => {
      if ("$ref" in input) {
        const found: OpenApiV3_2.IOperation.IResponse | undefined =
          OpenApiReferenceKey.get(doc.components?.responses, input.$ref);
        if (found === undefined) return undefined;
        input = found;
      }
      return {
        ...input,
        content: input.content
          ? convertContent(doc.components ?? {})(input.content)
          : undefined,
        headers: input.headers
          ? Object.fromEntries(
              Object.entries(input.headers)
                .filter(([_, v]) => v !== undefined)
                .map(([key, value]) => [
                  key,
                  convertHeader(doc.components ?? {})(key, value),
                ])
                .filter(([_, v]) => v !== undefined),
            )
          : undefined,
      };
    };

  const convertHeader =
    (components: OpenApiV3_2.IComponents) =>
    (
      key: string,
      input:
        | Omit<OpenApiV3_2.IOperation.IParameter, "in">
        | OpenApiV3_2.IJsonSchema.IReference<`#/components/headers/${string}`>,
    ): OpenApi.IOperation.IParameter | undefined => {
      if ("$ref" in input) {
        const found: Omit<OpenApiV3_2.IOperation.IParameter, "in"> | undefined =
          input.$ref.startsWith("#/components/headers/")
            ? OpenApiReferenceKey.get(components.headers, input.$ref)
            : undefined;
        if (found === undefined) return undefined;
        input = found;
      }
      const { name: _name, ...rest } = input;
      return convertParameter(components)({
        ...rest,
        name: key,
        in: "header",
      });
    };

  const convertContent =
    (components: OpenApiV3_2.IComponents) =>
    (
      record: Record<string, OpenApiV3_2.IOperation.IMediaType>,
    ): Record<string, OpenApi.IOperation.IMediaType> =>
      Object.fromEntries(
        Object.entries(record)
          .filter(([_, v]) => v !== undefined)
          .map(
            ([key, value]) =>
              [
                key,
                {
                  ...value,
                  schema: value.schema
                    ? convertSchema(components)(value.schema)
                    : undefined,
                  itemSchema: value.itemSchema
                    ? convertSchema(components)(value.itemSchema)
                    : undefined,
                  examples: value.examples
                    ? Object.fromEntries(
                        Object.entries(value.examples)
                          .map(([key, value]) => [
                            key,
                            OpenApiV3_1TypeChecker.isReference(value)
                              ? OpenApiReferenceKey.get(
                                  components.examples,
                                  value.$ref,
                                )
                              : value,
                          ])
                          .filter(([_, v]) => v !== undefined),
                      )
                    : undefined,
                },
              ] as const,
          ),
      );

  /* -----------------------------------------------------------
    DEFINITIONS
  ----------------------------------------------------------- */
  /**
   * Upgrade the components of a 3.2 document.
   *
   * @param input OpenAPI 3.2 components
   *
   * @returns Emended components
   *
   * @evidence contracts/common.md#principled-implementation Component schemas are converted through the 3.1 schema conversion and security schemes kept.
   * @evidence contracts/common.md#clear-and-simple-design One function.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Supported schema and security-scheme stores are retained without reachability pruning; other component kinds are consumed while converting operations.
   * @evidence contracts/common.md#meaningful-documentation The doc states what is kept.
   */
  export const convertComponents = (
    input: OpenApiV3_2.IComponents,
  ): OpenApi.IComponents => ({
    schemas: Object.fromEntries(
      Object.entries(input.schemas ?? {})
        .filter(([_, v]) => v !== undefined)
        .map(([key, value]) => [key, convertSchema(input)(value)] as const),
    ),
    securitySchemes: input.securitySchemes
      ? Object.fromEntries(
          Object.entries(input.securitySchemes)
            .filter(([_, v]) => v !== undefined)
            .map(
              ([key, value]) => [key, convertSecurityScheme(value)] as const,
            ),
        )
      : undefined,
  });

  const convertSecurityScheme = (
    input: OpenApiV3_2.ISecurityScheme,
  ): OpenApi.ISecurityScheme => {
    if (input.type === "oauth2") {
      return {
        ...input,
        flows: {
          ...input.flows,
          deviceAuthorization: input.flows.deviceAuthorization,
        },
        oauth2MetadataUrl: input.oauth2MetadataUrl,
      };
    }
    return input;
  };

  /**
   * Reuse schema conversion from OpenApiV3_1Upgrader. OpenAPI v3.2 uses the
   * same JSON Schema (2020-12) as v3.1.
   *
   * @evidence contracts/common.md#principled-implementation The call forwards to the 3.1 schema conversion, whose input shape is the same dialect, so the 3.2 schema rules are one implementation.
   * @evidence contracts/common.md#clear-and-simple-design One delegation with casts for the shared structural type.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The casts reflect the identical dialect; a future 3.2 schema difference would have to be handled here and is not handled today.
   * @evidence contracts/common.md#meaningful-documentation The existing doc says it reuses the 3.1 conversion because the dialects match.
   */
  export const convertSchema =
    (components: OpenApiV3_2.IComponents) =>
    (input: OpenApiV3_2.IJsonSchema): OpenApi.IJsonSchema =>
      OpenApiV3_1Upgrader.convertSchema(components as any)(input as any);
}

import { OpenApi, OpenApiV3 } from "@typia/interface";

import { ObjectDictionary } from "../../utils/internal/ObjectDictionary";
import { OpenApiReferenceKey } from "../../utils/internal/OpenApiReferenceKey";
import { OpenApiTypeChecker } from "../../validators/OpenApiTypeChecker";
import { OpenApiDiscriminatorConverter } from "./OpenApiDiscriminatorConverter";

/**
 * Downgrades the emended OpenAPI document to OpenAPI 3.0.
 *
 * Numeric exclusive bounds become the boolean 3.0 form, `null` members become
 * `nullable` on the other members, tuples become bounded arrays of the union of
 * their elements, constants become enums and `examples` are dropped, because
 * 3.0 does not define them. A nullable reference gets a generated `.Nullable`
 * component. Tuple conversion loses positional restrictions and uses the prefix
 * length for its bounds. An existing `.Nullable` component is reused, so
 * callers must reserve that generated suffix for this conversion.
 *
 * @evidence contracts/common.md#principled-implementation The emended document is rewritten to 3.0 by turning numeric exclusive bounds into the draft-04 boolean form, `null` members into `nullable`, constants into enums, tuples into bounded arrays and by dropping `examples`; a nullable reference gets a generated `.Nullable` component so `nullable` can be expressed on a reference.
 * @evidence contracts/common.md#clear-and-simple-design Per-object helpers in one namespace; the rewrites that only 3.0 needs are private to it.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The generated .Nullable suffix is a convention and an existing target is reused without schema comparison, so callers must reserve that suffix. Tuple approximation is an explicit dialect limitation rather than exact positional preservation.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment lists the rewrites.
 */
export namespace OpenApiV3Downgrader {
  /**
   * Pair of the original emended components and the 3.0 components being built.
   *
   * @evidence contracts/common.md#principled-implementation A pair of the original and downgraded components lets nullable references consult the source schemas while the target is being built.
   * @evidence contracts/common.md#clear-and-simple-design Two fields.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A data record.
   * @evidence contracts/common.md#meaningful-documentation A one-line comment states the role.
   */
  export interface IComponentsCollection {
    /** Emended schemas used to resolve the source references. */
    original: OpenApi.IComponents;

    /** Target component store receiving converted schemas. */
    downgraded: OpenApiV3.IComponents;
  }

  /**
   * Downgrade a whole emended document to 3.0.
   *
   * @param input Emended document
   *
   * @returns OpenAPI 3.0 document
   *
   * @evidence contracts/common.md#principled-implementation The components are downgraded first and then paths are rewritten against the collection; `query` and additional operations have no 3.0 form and are carried to `x-additionalOperations`, while webhooks, which 3.0 has no place for, are not carried and are lost.
   * @evidence contracts/common.md#clear-and-simple-design One function over the shared helpers.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Extension fields are documented ones.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const downgrade = (input: OpenApi.IDocument): OpenApiV3.IDocument => {
    const collection: IComponentsCollection = downgradeComponents(
      input.components,
    );
    return {
      openapi: "3.0.0",
      servers: input.servers,
      info: input.info,
      components: collection.downgraded,
      paths: input.paths
        ? Object.fromEntries(
            Object.entries(input.paths)
              .filter(([_, v]) => v !== undefined)
              .map(
                ([key, value]) =>
                  [key, downgradePathItem(collection)(value)] as const,
              ),
          )
        : undefined,
      security: input.security,
      tags: input.tags,
    };
  };

  /* -----------------------------------------------------------
    OPERATORS
  ----------------------------------------------------------- */
  const downgradePathItem =
    (collection: IComponentsCollection) =>
    (pathItem: OpenApi.IPath): OpenApiV3.IPath => {
      // Collect non-standard operations for x-additionalOperations
      const xAdditionalOperations: Record<string, OpenApiV3.IOperation> = {};

      // query method goes to x-additionalOperations
      if (pathItem.query) {
        xAdditionalOperations["query"] = downgradeOperation(collection)(
          pathItem.query,
        );
      }

      // additionalOperations also go to x-additionalOperations
      if (pathItem.additionalOperations) {
        for (const [key, value] of Object.entries(
          pathItem.additionalOperations,
        )) {
          if (value !== undefined) {
            xAdditionalOperations[key] = downgradeOperation(collection)(value);
          }
        }
      }

      return {
        ...(pathItem as any),
        ...(pathItem.get
          ? { get: downgradeOperation(collection)(pathItem.get) }
          : undefined),
        ...(pathItem.put
          ? { put: downgradeOperation(collection)(pathItem.put) }
          : undefined),
        ...(pathItem.post
          ? { post: downgradeOperation(collection)(pathItem.post) }
          : undefined),
        ...(pathItem.delete
          ? { delete: downgradeOperation(collection)(pathItem.delete) }
          : undefined),
        ...(pathItem.options
          ? { options: downgradeOperation(collection)(pathItem.options) }
          : undefined),
        ...(pathItem.head
          ? { head: downgradeOperation(collection)(pathItem.head) }
          : undefined),
        ...(pathItem.patch
          ? { patch: downgradeOperation(collection)(pathItem.patch) }
          : undefined),
        ...(pathItem.trace
          ? { trace: downgradeOperation(collection)(pathItem.trace) }
          : undefined),
        ...(Object.keys(xAdditionalOperations).length > 0
          ? { "x-additionalOperations": xAdditionalOperations }
          : undefined),
        // Remove v3.2-only properties from spread
        query: undefined,
        additionalOperations: undefined,
      };
    };

  const downgradeOperation =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IOperation): OpenApiV3.IOperation => ({
      ...input,
      parameters: input.parameters
        ? input.parameters.map(downgradeParameter(collection))
        : undefined,
      requestBody: input.requestBody
        ? downgradeRequestBody(collection)(input.requestBody)
        : undefined,
      responses: input.responses
        ? Object.fromEntries(
            Object.entries(input.responses)
              .filter(([_, v]) => v !== undefined)
              .map(([key, value]) => [
                key,
                downgradeResponse(collection)(value),
              ]),
          )
        : undefined,
    });

  const downgradeParameter =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IOperation.IParameter): OpenApiV3.IOperation.IParameter => {
      const { style, content: _content, ...rest } = input;
      return {
        ...rest,
        in: input.in === "querystring" ? "query" : input.in,
        style: style === "cookie" ? "form" : style,
        schema: downgradeSchema(collection)(input.schema),
      };
    };

  const downgradeRequestBody =
    (collection: IComponentsCollection) =>
    (
      input: OpenApi.IOperation.IRequestBody,
    ): OpenApiV3.IOperation.IRequestBody => ({
      ...input,
      content: input.content
        ? downgradeContent(collection)(input.content)
        : undefined,
    });

  const downgradeResponse =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IOperation.IResponse): OpenApiV3.IOperation.IResponse => ({
      ...input,
      content: input.content
        ? downgradeContent(collection)(input.content)
        : undefined,
      headers: input.headers
        ? Object.fromEntries(
            Object.entries(input.headers)
              .filter(([_, v]) => v !== undefined)
              .map(([key, value]) => {
                const { name: _name, in: _in, style, ...rest } = value;
                return [
                  key,
                  {
                    ...rest,
                    style: style === "cookie" ? "form" : style,
                    schema: downgradeSchema(collection)(value.schema),
                  },
                ];
              }),
          )
        : undefined,
    });

  const downgradeContent =
    (collection: IComponentsCollection) =>
    (
      record: OpenApi.IOperation.IContent,
    ): Record<string, OpenApiV3.IOperation.IMediaType> =>
      Object.fromEntries(
        Object.entries(record)
          .filter(([_, v]) => v !== undefined)
          .map(
            ([key, value]) =>
              [
                key,
                {
                  ...value,
                  schema: value?.schema
                    ? downgradeSchema(collection)(value.schema)
                    : undefined,
                },
              ] as const,
          ),
      );

  /* -----------------------------------------------------------
    DEFINITIONS
  ----------------------------------------------------------- */
  /**
   * Downgrade every component schema and carry the security schemes over.
   *
   * @param input Emended components
   *
   * @returns Collection holding the original and the downgraded components
   *
   * @evidence contracts/common.md#principled-implementation Every schema is downgraded into a new store keyed by the same names, while the security schemes are carried over unchanged.
   * @evidence contracts/common.md#clear-and-simple-design One function.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A data transformation with no hidden state.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const downgradeComponents = (
    input: OpenApi.IComponents,
  ): IComponentsCollection => {
    const collection: IComponentsCollection = {
      original: input,
      downgraded: {
        securitySchemes: input.securitySchemes,
      },
    };
    if (input.schemas) {
      collection.downgraded.schemas = {};
      for (const [key, value] of Object.entries(input.schemas))
        if (value !== undefined)
          ObjectDictionary.set(
            collection.downgraded.schemas,
            key,
            downgradeSchema(collection)(value),
          );
    }
    return collection;
  };

  /**
   * Downgrade one emended schema to 3.0.
   *
   * @param collection Original and downgraded components
   *
   * @returns Function that converts an emended schema to a 3.0 schema
   *
   * @evidence contracts/common.md#principled-implementation A nullable schema, found by following oneOf and references, gets nullable on each member, constants merge into enums per type and exclusive bounds are rewritten. Tuples approximate positional schemas as one item union, set the minimum to the prefix length and close the maximum at that length when no rest is present; this loses positional and optional-prefix constraints. Existing generated .Nullable targets are reused without schema equivalence checking.
   * @evidence contracts/common.md#clear-and-simple-design One recursive function with helpers for nullable references, example removal and bounds.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Rewrites follow the 3.0 dialect and the bound rewrite cites its issue.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result; helpers have comments.
   */
  export const downgradeSchema =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IJsonSchema): OpenApiV3.IJsonSchema => {
      const nullable: boolean = isNullable(new Set())(collection.original)(
        input,
      );
      const union: OpenApiV3.IJsonSchema[] = [];
      const discriminator:
        | OpenApiV3.IJsonSchema.IOneOf.IDiscriminator
        | undefined =
        OpenApiTypeChecker.isOneOf(input) && input.discriminator !== undefined
          ? OpenApiDiscriminatorConverter.clone(input.discriminator)
          : undefined;
      let preserveDiscriminator: boolean =
        discriminator !== undefined && nullable === false;
      const attribute: OpenApiV3.IJsonSchema.__IAttribute = {
        title: input.title,
        description: input.description,
        deprecated: input.deprecated,
        readOnly: input.readOnly,
        writeOnly: input.writeOnly,
        example: input.example,
        ...Object.fromEntries(
          Object.entries(input).filter(
            ([key, value]) => key.startsWith("x-") && value !== undefined,
          ),
        ),
      };
      const visit = (schema: OpenApi.IJsonSchema): void => {
        if (OpenApiTypeChecker.isString(schema)) {
          const {
            contentEncoding,
            contentMediaType: _contentMediaType,
            ...rest
          } = schema;
          union.push(
            omitSchemaExamples({
              ...rest,
              format:
                rest.format ??
                (contentEncoding === "base64" ? "byte" : undefined),
            }),
          );
        } else if (
          // A boolean carries its declared keywords (at minimum `default`,
          // plus every attribute OpenApiV3.IJsonSchema.IBoolean allows) through
          // the downgrade like the other primitives. Rebuilding it as a bare
          // `{ type: "boolean" }` dropped them; `omitSchemaExamples` keeps the
          // legal 3.0 keys and strips only `examples`, which 3.0 does not define.
          OpenApiTypeChecker.isBoolean(schema) ||
          OpenApiTypeChecker.isInteger(schema) ||
          OpenApiTypeChecker.isNumber(schema) ||
          OpenApiTypeChecker.isReference(schema)
        )
          union.push(omitSchemaExamples(schema));
        else if (OpenApiTypeChecker.isArray(schema)) {
          const next = omitSchemaExamples(schema);
          union.push({
            ...next,
            items: downgradeSchema(collection)(schema.items),
          });
        } else if (OpenApiTypeChecker.isTuple(schema)) {
          const next = omitSchemaExamples(schema);
          union.push({
            ...next,
            items: ((): OpenApiV3.IJsonSchema => {
              if (schema.additionalItems === true) return {};
              const elements = [
                ...schema.prefixItems,
                ...(typeof schema.additionalItems === "object"
                  ? [downgradeSchema(collection)(schema.additionalItems)]
                  : []),
              ];
              if (elements.length === 0) return {};
              return {
                oneOf: elements.map(downgradeSchema(collection) as any),
              };
            })(),
            minItems: schema.prefixItems.length,
            maxItems:
              !!schema.additionalItems === true
                ? undefined
                : schema.prefixItems.length,
            ...{
              prefixItems: undefined,
              additionalItems: undefined,
            },
          });
        } else if (OpenApiTypeChecker.isObject(schema)) {
          const next = omitSchemaExamples(schema);
          union.push({
            ...next,
            properties:
              schema.properties === undefined
                ? undefined
                : Object.fromEntries(
                    Object.entries(schema.properties)
                      .filter(([_, v]) => v !== undefined)
                      .map(([key, value]) => [
                        key,
                        downgradeSchema(collection)(value),
                      ]),
                  ),
            additionalProperties:
              schema.additionalProperties === undefined
                ? undefined
                : typeof schema.additionalProperties === "object"
                  ? downgradeSchema(collection)(schema.additionalProperties)
                  : schema.additionalProperties,
            required: schema.required,
          });
        } else if (OpenApiTypeChecker.isOneOf(schema)) {
          const tracked: boolean =
            schema === input && discriminator !== undefined;
          for (const branch of schema.oneOf) {
            const previous: number = union.length;
            visit(branch);
            if (tracked && union.length !== previous + 1)
              preserveDiscriminator = false;
          }
        }
      };
      const visitConstant = (schema: OpenApi.IJsonSchema): void => {
        const insert = (value: any): void => {
          const matched: OpenApiV3.IJsonSchema.INumber | undefined = union.find(
            (u) => (u as OpenApiV3.IJsonSchema.INumber).type === typeof value,
          ) as OpenApiV3.IJsonSchema.INumber | undefined;
          if (matched !== undefined) {
            matched.enum ??= [];
            matched.enum.push(value);
          } else union.push({ type: typeof value as "number", enum: [value] });
        };
        if (OpenApiTypeChecker.isConstant(schema)) insert(schema.const);
        else if (OpenApiTypeChecker.isOneOf(schema))
          for (const u of schema.oneOf)
            if (OpenApiTypeChecker.isConstant(u)) insert(u.const);
      };

      visit(input);
      visitConstant(input);
      if (nullable === true)
        for (const u of union)
          if (OpenApiTypeChecker.isReference(u as any))
            downgradeNullableReference(new Set())(collection)(u as any);
          else (u as OpenApiV3.IJsonSchema.IArray).nullable = true;
      if (nullable === true && union.length === 0)
        return { type: "null", ...attribute };
      return {
        ...(union.length === 0
          ? { type: undefined }
          : union.length === 1
            ? { ...union[0] }
            : {
                oneOf: union,
                ...(preserveDiscriminator && discriminator !== undefined
                  ? { discriminator }
                  : {}),
              }),
        ...attribute,
      };
    };

  const downgradeNullableReference =
    (visited: Set<string>) =>
    (collection: IComponentsCollection) =>
    (schema: OpenApiV3.IJsonSchema.IReference): void => {
      if (OpenApiReferenceKey.read(schema.$ref)?.endsWith(".Nullable")) return;

      const entry = OpenApiReferenceKey.find(
        collection.original.schemas,
        schema.$ref,
      );
      if (entry === undefined) return;
      const { key, value: found } = entry;
      if (isNullable(visited)(collection.original)(found) === true) return;
      else if (
        ObjectDictionary.get(
          collection.downgraded.schemas,
          `${key}.Nullable`,
        ) === undefined
      ) {
        collection.downgraded.schemas ??= {};
        ObjectDictionary.set(
          collection.downgraded.schemas,
          `${key}.Nullable`,
          {},
        );
        ObjectDictionary.set(
          collection.downgraded.schemas,
          `${key}.Nullable`,
          downgradeSchema(collection)(
            OpenApiTypeChecker.isOneOf(found)
              ? {
                  ...found,
                  oneOf: [...found.oneOf, { type: "null" }],
                }
              : {
                  oneOf: [found, { type: "null" }],
                  title: found.title,
                  description: found.description,
                  example: found.example,
                  examples: found.examples,
                  ...Object.fromEntries(
                    Object.entries(found).filter(
                      ([key, value]) =>
                        key.startsWith("x-") && value !== undefined,
                    ),
                  ),
                },
          ),
        );
      }
      schema.$ref += ".Nullable";
    };

  const omitSchemaExamples = <Schema extends OpenApi.IJsonSchema>(
    schema: Schema,
  ): Omit<Schema, "examples"> => {
    const { examples: _examples, ...rest } = schema;
    return exclusiveBounds(rest);
  };

  /**
   * Rewrites an exclusive numeric bound into the form the 3.0 dialect defines.
   *
   * 3.0's Schema Object descends from JSON Schema draft-04, where
   * `exclusiveMinimum` and `exclusiveMaximum` are booleans qualifying `minimum`
   * and `maximum`; the numeric spelling belongs to 3.1. Carrying the number
   * through left a document that declares itself 3.0 with a 3.1 keyword, and a
   * 3.0 reader taking the value as the boolean its dialect declares finds no
   * `minimum` beside it and drops the bound entirely (#2300).
   *
   * {@link OpenApiV3Upgrader} already performs the inverse, so this makes the
   * pair a round trip.
   */
  const exclusiveBounds = <Schema extends object>(schema: Schema): Schema => {
    const target = schema as Record<string, unknown>;
    for (const [exclusive, inclusive] of [
      ["exclusiveMinimum", "minimum"],
      ["exclusiveMaximum", "maximum"],
    ] as const) {
      const value: unknown = target[exclusive];
      if (typeof value !== "number") continue;
      target[inclusive] = value;
      target[exclusive] = true;
    }
    return schema;
  };

  const isNullable =
    (visited: Set<string>) =>
    (components: OpenApi.IComponents) =>
    (schema: OpenApi.IJsonSchema): boolean => {
      if (OpenApiTypeChecker.isNull(schema)) return true;
      else if (OpenApiTypeChecker.isReference(schema)) {
        if (visited.has(schema.$ref)) return false;
        visited.add(schema.$ref);
        const next: OpenApi.IJsonSchema | undefined = OpenApiReferenceKey.get(
          components.schemas,
          schema.$ref,
        );
        return next ? isNullable(visited)(components)(next) : false;
      }
      return (
        OpenApiTypeChecker.isOneOf(schema) &&
        schema.oneOf.some(isNullable(visited)(components))
      );
    };
}

import { IJsonSchemaAttribute, OpenApi, OpenApiV3 } from "@typia/interface";

import { OpenApiReferenceKey } from "../../utils/internal/OpenApiReferenceKey";
import { OpenApiTypeChecker } from "../../validators/OpenApiTypeChecker";
import { OpenApiV3TypeChecker } from "../../validators/OpenApiV3TypeChecker";
import { OpenApiDiscriminatorConverter } from "./OpenApiDiscriminatorConverter";
import { OpenApiExclusiveEmender } from "./OpenApiExclusiveEmender";

/**
 * Upgrades an OpenAPI 3.0 document to the emended OpenAPI 3.2 form.
 *
 * Referenced parameters, request bodies, responses and examples are inlined,
 * `nullable` becomes a `null` member of a `oneOf`, `allOf` of plain objects is
 * merged, boolean exclusive bounds become numeric ones and path-level
 * parameters are merged into each operation.
 *
 * @evidence contracts/common.md#principled-implementation A 3.0 document is brought to the emended form by inlining parameter, header, body, response and example references, merging path-level parameters into operations, expressing `nullable` as a `null` member, rewriting boolean exclusive bounds as numbers and merging an `allOf` of closed objects; schema references stay references.
 * @evidence contracts/common.md#clear-and-simple-design Path, operation, parameter and content conversion are private helpers of this namespace, and the path-item, parameter-merging and media conversion have the same shape in the 3.1, 3.2 and Swagger upgraders, which is a duplication limitation.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Conversion follows the 3.0 object model and no document is special-cased; an unreadable reference is dropped, not guessed.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment lists the rewrites; the exported functions carry their own docs.
 */
export namespace OpenApiV3Upgrader {
  /**
   * Upgrade a whole 3.0 document.
   *
   * @param input OpenAPI 3.0 document
   *
   * @returns Emended document marked with `x-typia-emended-v12`
   *
   * @evidence contracts/common.md#principled-implementation The document is spread to preserve unknown fields, its components and path items are converted and the version and emended marker are set.
   * @evidence contracts/common.md#clear-and-simple-design One function that delegates to the component and path-item converters.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The marker is the contract marker and no input is modified.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const convert = (input: OpenApiV3.IDocument): OpenApi.IDocument => ({
    ...input,
    components: convertComponents(input.components ?? {}),
    paths: input.paths
      ? Object.fromEntries(
          Object.entries(input.paths)
            .filter(([_, v]) => v !== undefined)
            .map(
              ([key, value]) => [key, convertPathItem(input)(value)] as const,
            ),
        )
      : undefined,
    openapi: "3.2.0",
    "x-typia-emended-v12": true,
  });

  /* -----------------------------------------------------------
    OPERATORS
  ----------------------------------------------------------- */
  const convertPathItem =
    (doc: OpenApiV3.IDocument) =>
    (pathItem: OpenApiV3.IPath): OpenApi.IPath => {
      // Convert x-additionalOperations to additionalOperations
      // Promote "query" to standard method (it's a v3.2 standard method)
      const xAdditional = pathItem["x-additionalOperations"];
      const queryOp = xAdditional?.["query"];
      const additionalOperations = xAdditional
        ? Object.fromEntries(
            Object.entries(xAdditional)
              .filter(([key, v]) => key !== "query" && v !== undefined)
              .map(([key, value]) => [
                key,
                convertOperation(doc)(pathItem)(value),
              ]),
          )
        : undefined;
      const { parameters: _parameters, ...rest } = pathItem as any;

      return {
        ...rest,
        ...(pathItem.get
          ? { get: convertOperation(doc)(pathItem)(pathItem.get) }
          : undefined),
        ...(pathItem.put
          ? { put: convertOperation(doc)(pathItem)(pathItem.put) }
          : undefined),
        ...(pathItem.post
          ? { post: convertOperation(doc)(pathItem)(pathItem.post) }
          : undefined),
        ...(pathItem.delete
          ? { delete: convertOperation(doc)(pathItem)(pathItem.delete) }
          : undefined),
        ...(pathItem.options
          ? { options: convertOperation(doc)(pathItem)(pathItem.options) }
          : undefined),
        ...(pathItem.head
          ? { head: convertOperation(doc)(pathItem)(pathItem.head) }
          : undefined),
        ...(pathItem.patch
          ? { patch: convertOperation(doc)(pathItem)(pathItem.patch) }
          : undefined),
        ...(pathItem.trace
          ? { trace: convertOperation(doc)(pathItem)(pathItem.trace) }
          : undefined),
        ...(queryOp
          ? { query: convertOperation(doc)(pathItem)(queryOp) }
          : undefined),
        ...(additionalOperations && Object.keys(additionalOperations).length > 0
          ? { additionalOperations }
          : undefined),
        "x-additionalOperations": undefined,
      };
    };

  const convertOperation =
    (doc: OpenApiV3.IDocument) =>
    (pathItem: OpenApiV3.IPath) =>
    (input: OpenApiV3.IOperation): OpenApi.IOperation => {
      const components: OpenApiV3.IComponents = doc.components ?? {};
      const pathParameters: OpenApiV3.IOperation.IParameter[] = (
        pathItem.parameters ?? []
      )
        .map(resolveParameter(components))
        .filter((p): p is OpenApiV3.IOperation.IParameter => p !== undefined);
      const operationParameters: OpenApiV3.IOperation.IParameter[] = (
        input.parameters ?? []
      )
        .map(resolveParameter(components))
        .filter((p): p is OpenApiV3.IOperation.IParameter => p !== undefined);
      return {
        ...input,
        parameters:
          pathItem.parameters !== undefined || input.parameters !== undefined
            ? mergeParameters(pathParameters, operationParameters).map(
                convertParameter(components),
              )
            : undefined,
        requestBody: input.requestBody
          ? convertRequestBody(doc)(input.requestBody)
          : undefined,
        responses: input.responses
          ? Object.fromEntries(
              Object.entries(input.responses)
                .filter(([_, v]) => v !== undefined)
                .map(
                  ([key, value]) =>
                    [key, convertResponse(doc)(value)!] as const,
                )
                .filter(([_, v]) => v !== undefined),
            )
          : undefined,
      };
    };

  const resolveParameter =
    (components: OpenApiV3.IComponents) =>
    (
      input:
        | OpenApiV3.IOperation.IParameter
        | OpenApiV3.IJsonSchema.IReference<`#/components/headers/${string}`>
        | OpenApiV3.IJsonSchema.IReference<`#/components/parameters/${string}`>,
    ): OpenApiV3.IOperation.IParameter | undefined => {
      if (!("$ref" in input)) return input;
      const key: string | undefined = OpenApiReferenceKey.read(input.$ref);
      if (key === undefined) return undefined;
      if (input.$ref.startsWith("#/components/headers/")) {
        const header: Omit<OpenApiV3.IOperation.IParameter, "in"> | undefined =
          OpenApiReferenceKey.get(components.headers, input.$ref);
        if (header === undefined) return undefined;
        const { name, ...rest } = header;
        return { ...rest, name: name ?? key, in: "header" };
