  const downgradeRequestBody =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IOperation.IRequestBody): IDowngradedRequestBody => {
      const media: IDowngradedMedia = downgradeMedia(
        input.content,
        "request body",
      );
      if (Object.keys(media.examples ?? {}).length > 0)
        throw new TypeError(
          "SwaggerV2Downgrader: request body examples are not representable.",
        );
      if (input["x-nestia-encrypted"] !== undefined)
        throw new TypeError(
          "SwaggerV2Downgrader: encrypted request bodies are not representable.",
        );
      const types: string[] | undefined = media.types;
      if (!types?.length)
        throw new TypeError(
          "SwaggerV2Downgrader: request bodies require at least one media type.",
        );
      if (media.schema === undefined)
        throw new TypeError(
          "SwaggerV2Downgrader: request media types require a shared schema.",
        );
      const formTypes: string[] = types.filter(isFormMediaType);
      if (formTypes.length > 0 && formTypes.length !== types.length)
        throw new TypeError(
          "SwaggerV2Downgrader: form and non-form request media types cannot coexist.",
        );
      if (formTypes.length > 0 && input.description !== undefined)
        throw new TypeError(
          "SwaggerV2Downgrader: form request body descriptions are not representable.",
        );
      return {
        consumes: media.types,
        parameters:
          formTypes.length > 0
            ? downgradeFormData(collection)(media.schema, input.required)
            : [
                {
                  name: "body",
                  in: "body",
                  description: input.description,
                  ...(input.required !== undefined
                    ? { required: input.required }
                    : {}),
                  schema: downgradeSchema(collection)(media.schema),
                },
              ],
      };
    };

  const downgradeFormData =
    (collection: IComponentsCollection) =>
    (
      schema: OpenApi.IJsonSchema | undefined,
      requestRequired: boolean | undefined,
    ): SwaggerV2.IOperation.IGeneralParameter[] => {
      const resolved: OpenApi.IJsonSchema | undefined =
        resolveSchema(collection)(schema);
      if (
        resolved === undefined ||
        OpenApiTypeChecker.isObject(resolved) === false
      )
        throw new TypeError(
          "SwaggerV2Downgrader: form request schemas must be objects.",
        );
      const object: OpenApi.IJsonSchema.IObject = resolved;
      const unsupported: string[] = Object.entries(object)
        .filter(
          ([key, value]) =>
            value !== undefined &&
            key !== "type" &&
            key !== "properties" &&
            key !== "additionalProperties" &&
            key !== "required",
        )
        .map(([key]) => key);
      if (unsupported.length > 0)
        throw new TypeError(
          `SwaggerV2Downgrader: form request object attributes are not representable: ${unsupported.join(", ")}.`,
        );
      if (object.additionalProperties !== undefined)
        throw new TypeError(
          "SwaggerV2Downgrader: form request additionalProperties constraints are not representable.",
        );
      const properties: [string, OpenApi.IJsonSchema][] = Object.entries(
        object.properties ?? {},
      ).filter(
        (entry): entry is [string, OpenApi.IJsonSchema] =>
          entry[1] !== undefined,
      );
      if (properties.length === 0)
        throw new TypeError(
          "SwaggerV2Downgrader: form request schemas require at least one defined property.",
        );
      const propertyNames: Set<string> = new Set(
        properties.map(([name]) => name),
      );
      const required: string[] = object.required ?? [];
      if (required.some((name) => propertyNames.has(name) === false))
        throw new TypeError(
          "SwaggerV2Downgrader: form required fields must exist as properties.",
        );
      if ((requestRequired === true) !== required.length > 0)
        throw new TypeError(
          "SwaggerV2Downgrader: form request body and field requiredness must agree.",
        );
      return properties.map(([name, property]) => ({
        ...downgradeFormDataSchema(collection)(property),
        name,
        in: "formData",
        required: required.includes(name) || undefined,
      }));
    };

  const downgradeFormDataSchema =
    (collection: IComponentsCollection) =>
    (
      input: OpenApi.IJsonSchema,
    ):
      | SwaggerV2.IJsonSchema.IBoolean
      | SwaggerV2.IJsonSchema.IInteger
      | SwaggerV2.IJsonSchema.INumber
      | SwaggerV2.IJsonSchema.IString
      | SwaggerV2.IJsonSchema.IArray
      | SwaggerV2.IJsonSchema.IOneOf
      | SwaggerV2.IOperation.IGeneralParameter.IFile => {
      const schema: OpenApi.IJsonSchema | undefined =
        resolveSchema(collection)(input);
      if (schema === undefined)
        throw new TypeError(
          "SwaggerV2Downgrader: form property references must resolve.",
        );
      if (OpenApiTypeChecker.isString(schema) && schema.format === "binary") {
        const { format: _format, ...rest } = downgradeSchema(collection)(
          schema,
        ) as SwaggerV2.IJsonSchema.IString;
        return { ...rest, type: "file" };
      }
      // A nullable reference downgrades to a `.Nullable` definition reference,
      // which a form field cannot hold, so it is inlined like a parameter's,
      // and so is one in the items of an array field.
      // The simple-schema gate reads the field before `typeEnumeration` adds a
      // `type`, which would otherwise let a malformed union through as a string.
      // One visited set spans the items chain, so an array whose items refer
      // back to itself is a cycle, not an endless descent.
      const visited: Set<string> = new Set();
      const inline = (next: SwaggerV2.IJsonSchema): SwaggerV2.IJsonSchema => {
        const inlined: SwaggerV2.IJsonSchema = inlineReference(
          collection,
          visited,
        )(next);
        return SwaggerV2TypeChecker.isArray(inlined)
          ? { ...inlined, items: inline(inlined.items) }
          : inlined;
      };
      const downgraded: SwaggerV2.IJsonSchema = inline(
        downgradeSchema(collection)(schema),
      );
      if (isFormDataSchema(downgraded) === false)
        throw new TypeError(
          "SwaggerV2Downgrader: form properties must use simple schemas.",
        );
      return typeEnumeration(downgraded) as typeof downgraded;
    };

  /**
   * Inline the definition a non-body parameter's schema refers to.
   *
   * A non-body parameter spreads its schema into itself, and a `$ref` item in a
   * 2.0 `parameters` list names a parameter, not a schema. A spread schema
   * reference therefore read back as a dangling parameter reference, and the
   * upgrader dropped the parameter (#2441). The downgraded definition,
   * including a synthesized `.Nullable` one, is inlined with the reference's
   * sibling annotations over it. A reference that does not resolve, or resolves
   * only through a cycle, is not representable.
   */
  const inlineReference =
    (collection: IComponentsCollection, visited: Set<string> = new Set()) =>
    (schema: SwaggerV2.IJsonSchema): SwaggerV2.IJsonSchema => {
      let current: SwaggerV2.IJsonSchema = schema;
      while (SwaggerV2TypeChecker.isReference(current)) {
        const { $ref, ...siblings } = current;
        if (visited.has($ref))
          throw new TypeError(
            "SwaggerV2Downgrader: non-body parameter references must not form a cycle.",
          );
        visited.add($ref);
        const found: SwaggerV2.IJsonSchema | undefined =
          OpenApiReferenceKey.get(
            collection.downgraded,
            $ref,
            "#/definitions/",
          );
        if (found === undefined)
          throw new TypeError(
            "SwaggerV2Downgrader: non-body parameter references must resolve.",
          );
        current = {
          ...found,
          ...Object.fromEntries(
            Object.entries(siblings).filter(
              ([_, value]) => value !== undefined,
            ),
          ),
        } as SwaggerV2.IJsonSchema;
      }
      return current;
    };

  /**
   * State a documented enumeration as a typed `enum` in a non-body location.
   *
   * Annotated constants downgrade to an `x-oneOf` of one-value enums, which
   * keeps each annotation and reads back losslessly but carries no `type`, so a
   * 2.0 consumer other than typia sees an untyped parameter, form field, or
   * header (#2441). When every non-null branch is a constant of one type, the
   * union is also stated as that `type` with every value in `enum`, and a
   * `null` member as `x-nullable`. The upgrader reads `x-oneOf` first, so the
   * round trip is unchanged. Array items are typed the same way.
   */
  const typeEnumeration = (
    schema: SwaggerV2.IJsonSchema,
  ): SwaggerV2.IJsonSchema => {
    if (SwaggerV2TypeChecker.isArray(schema))
      return { ...schema, items: typeEnumeration(schema.items) };
    if (SwaggerV2TypeChecker.isOneOf(schema) === false) return schema;
    const branches = schema["x-oneOf"] as Array<{
      type?: string;
      enum?: unknown[];
    }>;
    const nonNull = branches.filter((branch) => branch.type !== "null");
    const type: string | undefined = nonNull[0]?.type;
    if (
      (type !== "boolean" &&
        type !== "integer" &&
        type !== "number" &&
        type !== "string") ||
      nonNull.some(
        (branch) =>
          branch.type !== type ||
          Array.isArray(branch.enum) === false ||
          branch.enum.length === 0,
      )
    )
      return schema;
    const values: unknown[] = [
      ...new Set(
        nonNull.flatMap((branch) =>
          branch.enum!.filter((value) => value !== null),
        ),
      ),
    ];
    return {
      ...schema,
      type,
      enum: values,
      ...(nonNull.length !== branches.length ? { "x-nullable": true } : {}),
    } as SwaggerV2.IJsonSchema;
  };

  const resolveSchema =
    (collection: IComponentsCollection) =>
    (
      input: OpenApi.IJsonSchema | undefined,
      visited: Set<string> = new Set(),
    ): OpenApi.IJsonSchema | undefined => {
      if (
        input === undefined ||
        OpenApiTypeChecker.isReference(input) === false
      )
        return input;
      if (visited.has(input.$ref)) return undefined;
      visited.add(input.$ref);
      const resolved: OpenApi.IJsonSchema | undefined = resolveSchema(
        collection,
      )(
        OpenApiReferenceKey.get(collection.original.schemas, input.$ref),
        visited,
      );
      if (resolved === undefined) return undefined;
      return {
        ...resolved,
        ...Object.fromEntries(
          Object.entries(input).filter(
            ([property, value]) => property !== "$ref" && value !== undefined,
          ),
        ),
      } as OpenApi.IJsonSchema;
    };

  const isFormDataSchema = (
    input: SwaggerV2.IJsonSchema,
  ): input is
    | SwaggerV2.IJsonSchema.IBoolean
    | SwaggerV2.IJsonSchema.IInteger
    | SwaggerV2.IJsonSchema.INumber
    | SwaggerV2.IJsonSchema.IString
    | SwaggerV2.IJsonSchema.IArray
    | SwaggerV2.IJsonSchema.IOneOf => {
    if (isFormDataScalarSchema(input)) return true;
    if (SwaggerV2TypeChecker.isArray(input) === false) return false;
    const array: SwaggerV2.IJsonSchema.IArray =
      input as SwaggerV2.IJsonSchema.IArray;
    return isFormDataSchema(array.items);
  };

  const isFormDataScalarSchema = (input: SwaggerV2.IJsonSchema): boolean => {
    if (
      SwaggerV2TypeChecker.isBoolean(input) ||
      SwaggerV2TypeChecker.isInteger(input) ||
      SwaggerV2TypeChecker.isNumber(input)
    )
      return true;
    if (SwaggerV2TypeChecker.isString(input)) return input.format !== "binary";
    if (SwaggerV2TypeChecker.isOneOf(input) === false) return false;
    const nonNull: SwaggerV2.IJsonSchema[] = input["x-oneOf"].filter(
      (schema) => (schema as { type?: string }).type !== "null",
    );
    const nullCount: number = input["x-oneOf"].length - nonNull.length;
    if (nullCount > 1 || nonNull.length === 0) return false;
    if (
      input["x-oneOf"].length === 2 &&
      nonNull.length === 1 &&
      isFormDataSchema(nonNull[0]!)
    )
      return true;
    const enumTypes: string[] = nonNull
      .filter(
        (schema) =>
          isFormDataScalarSchema(schema) &&
          Array.isArray((schema as SwaggerV2.IJsonSchema.IString).enum) &&
          (schema as SwaggerV2.IJsonSchema.IString).enum!.some(
            (value) => value !== null,
          ),
      )
      .map((schema) => (schema as { type: string }).type);
    return enumTypes.length === nonNull.length && new Set(enumTypes).size === 1;
  };

  const downgradeResponse =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IOperation.IResponse): IDowngradedResponse => {
      if (input["x-nestia-encrypted"] !== undefined)
        throw new TypeError(
          "SwaggerV2Downgrader: encrypted responses are not representable.",
        );
      const media: IDowngradedMedia = downgradeMedia(input.content, "response");
      if (
        media.types?.length &&
        media.schema === undefined &&
        Object.keys(media.examples ?? {}).length === 0
      )
        throw new TypeError(
          "SwaggerV2Downgrader: response media types require a shared schema or example.",
        );
      return {
        produces: media.types?.length ? media.types : undefined,
        response: {
          description: input.description,
          schema:
            media.schema !== undefined
              ? downgradeSchema(collection)(media.schema)
              : undefined,
          examples: media.examples,
          headers: input.headers
            ? Object.fromEntries(
                Object.entries(input.headers)
                  .filter(([_, v]) => v !== undefined)
                  .map(([key, value]) => {
                    const {
                      name: _name,
                      in: _in,
                      required: _required,
                      style: _style,
                      explode: _explode,
                      example: _example,
                      examples: _examples,
                      schema,
                      ...rest
                    } = value;
                    return [
                      key,
                      {
                        ...rest,
                        ...typeEnumeration(downgradeSchema(collection)(schema)),
                      },
                    ];
                  }),
              )
            : undefined,
        },
      };
    };

  /* -----------------------------------------------------------
    DEFINITIONS
  ----------------------------------------------------------- */
  /**
   * Downgrade every component schema to a definition.
   *
   * @param input Emended components
   *
   * @returns Collection holding the original components and the definitions
   *
   * @evidence contracts/common.md#principled-implementation Each schema is downgraded into a definitions record keyed by the same names.
   * @evidence contracts/common.md#clear-and-simple-design One function.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts No hidden state.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const downgradeComponents = (
    input: OpenApi.IComponents,
  ): IComponentsCollection => {
    const collection: IComponentsCollection = {
      original: input,
      downgraded: {},
    };
    if (input.schemas) {
      for (const [key, value] of Object.entries(input.schemas))
        if (value !== undefined)
          ObjectDictionary.set(
            collection.downgraded,
            key,
            downgradeSchema(collection)(value),
          );
    }
    return collection;
  };

  /**
   * Downgrade one emended schema to Swagger 2.0.
   *
   * @param collection Original components and downgraded definitions
   *
   * @returns Function that converts an emended schema to a Swagger 2.0 schema
   *
   * @evidence contracts/common.md#principled-implementation Nullable and union schemas use vendor extensions, constants become enums and references use definitions. Tuples approximate positional members by an item union and prefix-length bounds, losing positional and optional-prefix constraints. Existing generated nullable definitions are reused without equivalence checking; these mappings are not exact inverses of every source schema.
   * @evidence contracts/common.md#clear-and-simple-design One large recursive function with helpers for nullable references, enumerations and form-data schemas.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Documented extension keys express supported unions and nullability; tuple and generated-name limitations remain explicit rather than being claimed lossless.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result; helpers carry comments.
   */
  export const downgradeSchema =
    (collection: IComponentsCollection) =>
    (input: OpenApi.IJsonSchema): SwaggerV2.IJsonSchema => {
      const nullable: boolean = isNullable(new Set())(collection.original)(
        input,
      );
      const union: SwaggerV2.IJsonSchema[] = [];
      const constantGroups: Map<
        "boolean" | "number" | "string",
        | SwaggerV2.IJsonSchema.IBoolean
        | SwaggerV2.IJsonSchema.INumber
        | SwaggerV2.IJsonSchema.IString
      > = new Map();
      const getAttribute = (
        schema: OpenApi.IJsonSchema,
      ): SwaggerV2.IJsonSchema.__IAttribute =>
        Object.fromEntries(
          Object.entries({
            title: schema.title,
            description: schema.description,
            deprecated: schema.deprecated,
            readOnly: schema.readOnly,
            example: schema.example,
            examples: schema.examples
              ? Object.values(schema.examples)
              : undefined,
            ...Object.fromEntries(
              Object.entries(schema).filter(
                ([key, value]) => key.startsWith("x-") && value !== undefined,
              ),
            ),
          }).filter(([_, value]) => value !== undefined),
        ) as SwaggerV2.IJsonSchema.__IAttribute;
      const attribute: SwaggerV2.IJsonSchema.__IAttribute = getAttribute(input);
      const preserveNullableBranches: { value: boolean } = { value: false };
      const nullableBranches: SwaggerV2.IJsonSchema[] = [];
      const insertConstant = (schema: OpenApi.IJsonSchema.IConstant): void => {
        const value: boolean | number | string = schema.const;
        const type: "boolean" | "number" | "string" =
          typeof value === "boolean"
            ? "boolean"
            : typeof value === "number"
              ? "number"
              : "string";
        const branchAttribute: SwaggerV2.IJsonSchema.__IAttribute =
          getAttribute(schema);
        if (
          schema !== input &&
          Object.values(branchAttribute).some((value) => value !== undefined)
        ) {
          union.push({ type, enum: [value], ...branchAttribute } as
            | SwaggerV2.IJsonSchema.IBoolean
            | SwaggerV2.IJsonSchema.INumber
            | SwaggerV2.IJsonSchema.IString);
          return;
        }
        const old = constantGroups.get(type);
        if (old !== undefined) {
          old.enum ??= [];
          if (old.enum.includes(value as never) === false)
            old.enum.push(value as never);
          return;
        }
        const created = {
          type,
          enum: [value],
        } as
          | SwaggerV2.IJsonSchema.IBoolean
          | SwaggerV2.IJsonSchema.INumber
          | SwaggerV2.IJsonSchema.IString;
        constantGroups.set(type, created);
        union.push(created);
      };
      const visit = (schema: OpenApi.IJsonSchema): void => {
        if (schema !== input && Object.keys(getAttribute(schema)).length > 0)
          preserveNullableBranches.value = true;
        if (OpenApiTypeChecker.isNull(schema))
          nullableBranches.push({
            type: "null",
            default: schema.default,
            ...getAttribute(schema),
          });
        else if (OpenApiTypeChecker.isConstant(schema)) insertConstant(schema);
        else if (
          OpenApiTypeChecker.isBoolean(schema) ||
          OpenApiTypeChecker.isInteger(schema) ||
          OpenApiTypeChecker.isNumber(schema) ||
          OpenApiTypeChecker.isString(schema)
        )
          union.push({
            ...schema,
            examples: schema.examples
              ? Object.values(schema.examples)
              : undefined,
          });
        else if (OpenApiTypeChecker.isReference(schema))
          union.push({
            $ref: `#/definitions/${schema.$ref.split("/").pop()}`,
            ...(schema === input ? {} : getAttribute(schema)),
          });
        else if (OpenApiTypeChecker.isArray(schema))
          union.push({
            ...schema,
            items: downgradeSchema(collection)(schema.items),
            examples: schema.examples
              ? Object.values(schema.examples)
              : undefined,
          });
        else if (OpenApiTypeChecker.isTuple(schema))
          union.push({
            ...schema,
            items: ((): SwaggerV2.IJsonSchema => {
              if (schema.additionalItems === true) return {};
              const elements = [
                ...schema.prefixItems,
                ...(typeof schema.additionalItems === "object"
                  ? [downgradeSchema(collection)(schema.additionalItems)]
                  : []),
              ];
              if (elements.length === 0) return {};
              return {
                "x-oneOf": elements.map(downgradeSchema(collection) as any),
              };
            })(),
            minItems: schema.prefixItems.length,
            maxItems:
              !!schema.additionalItems === true
                ? undefined
                : schema.prefixItems.length,
            ...{
              prefixItems: undefined,
              additionalItems: undefined,
            },
            examples: schema.examples
              ? Object.values(schema.examples)
              : undefined,
          });
        else if (OpenApiTypeChecker.isObject(schema))
          union.push({
            ...schema,
            properties:
              schema.properties === undefined
                ? undefined
                : Object.fromEntries(
                    Object.entries(schema.properties)
                      .filter(([_, v]) => v !== undefined)
                      .map(([key, value]) => [
                        key,
                        downgradeSchema(collection)(value),
                      ]),
                  ),
            additionalProperties:
              schema.additionalProperties === undefined
                ? undefined
                : typeof schema.additionalProperties === "object"
                  ? downgradeSchema(collection)(schema.additionalProperties)
                  : schema.additionalProperties,
            required: schema.required,
            examples:
              schema.examples === undefined
                ? undefined
                : Object.values(schema.examples),
          });
        else if (OpenApiTypeChecker.isOneOf(schema))
          schema.oneOf.forEach(visit);
      };

      visit(input);
      const nullableDefault: boolean = nullableBranches.some(
        (branch) =>
          SwaggerV2TypeChecker.isNullOnly(branch) && branch.default === null,
      );
      const canInlineNullableDefault: boolean =
        union.length === 1 &&
        (SwaggerV2TypeChecker.isBoolean(union[0]!) ||
          SwaggerV2TypeChecker.isInteger(union[0]!) ||
          SwaggerV2TypeChecker.isNumber(union[0]!) ||
          SwaggerV2TypeChecker.isString(union[0]!));
      if (
        nullable === true &&
        (preserveNullableBranches.value === true ||
          (nullableDefault === true && canInlineNullableDefault === false))
      ) {
        const branches: SwaggerV2.IJsonSchema[] = [
          ...union,
          ...(nullableBranches.length > 0
            ? nullableBranches
            : [{ type: "null" } as SwaggerV2.IJsonSchema]),
        ];
        if (branches.length === 1) return { ...branches[0], ...attribute };
        return {
          "x-oneOf": branches,
          ...attribute,
        };
      }
      if (nullable) {
        for (const u of union)
          if (OpenApiTypeChecker.isReference(u as any))
            downgradeNullableReference(new Set())(collection)(u as any);
          else {
            (u as SwaggerV2.IJsonSchema.IArray)["x-nullable"] = true;
            if (nullableDefault === true)
              (
                u as
                  | SwaggerV2.IJsonSchema.IBoolean
                  | SwaggerV2.IJsonSchema.IInteger
                  | SwaggerV2.IJsonSchema.INumber
                  | SwaggerV2.IJsonSchema.IString
              ).default = null;
          }
      }

      if (nullable === true && union.length === 0)
        return { ...(nullableBranches[0] ?? { type: "null" }), ...attribute };
      return {
        ...(union.length === 0
          ? { type: undefined }
          : union.length === 1
            ? { ...union[0] }
            : { "x-oneOf": union }),
        ...attribute,
        ...(union.length > 1 ? { discriminator: undefined } : {}),
      };
    };

  const downgradeNullableReference =
    (visited: Set<string>) =>
    (collection: IComponentsCollection) =>
    (schema: SwaggerV2.IJsonSchema.IReference): void => {
      if (OpenApiReferenceKey.read(schema.$ref)?.endsWith(".Nullable")) return;

      const entry = OpenApiReferenceKey.find(
        collection.original.schemas,
        schema.$ref,
      );
      if (entry === undefined) return;
      const { key, value: found } = entry;
      if (isNullable(visited)(collection.original)(found) === true) return;
      else if (
        ObjectDictionary.get(collection.downgraded, `${key}.Nullable`) ===
        undefined
      ) {
        ObjectDictionary.set(collection.downgraded, `${key}.Nullable`, {});
        ObjectDictionary.set(
          collection.downgraded,
          `${key}.Nullable`,
          downgradeSchema(collection)(
            OpenApiTypeChecker.isOneOf(found)
              ? {
                  ...found,
                  oneOf: [...found.oneOf, { type: "null" }],
                }
              : {
                  title: found.title,
                  description: found.description,
                  example: found.example,
                  examples: found.examples
                    ? Object.values(found.examples)
                    : undefined,
                  ...Object.fromEntries(
                    Object.entries(found).filter(
                      ([key, value]) =>
                        key.startsWith("x-") && value !== undefined,
                    ),
                  ),
                  oneOf: [found, { type: "null" }],
                },
          ),
        );
      }
      schema.$ref += ".Nullable";
    };

  const downgradeSecurityScheme = (
    input: OpenApi.ISecurityScheme,
  ): SwaggerV2.ISecurityDefinition[] => {
    if (input.type === "apiKey") return [input];
    else if (input.type === "http")
      if (input.scheme === "basic")
        return [{ type: "basic", description: input.description }];
      else return [];
    else if (input.type === "oauth2") {
      const output: SwaggerV2.ISecurityDefinition[] = [];
      if (input.flows.implicit)
        output.push({
          type: "oauth2",
          flow: "implicit",
          authorizationUrl: input.flows.implicit.authorizationUrl,
          scopes: input.flows.implicit.scopes,
        });
      if (input.flows.password)
        output.push({
          type: "oauth2",
          flow: "password",
          tokenUrl: input.flows.password.tokenUrl,
          scopes: input.flows.password.scopes,
        });
      if (input.flows.clientCredentials)
        output.push({
          type: "oauth2",
          flow: "application",
          tokenUrl: input.flows.clientCredentials.tokenUrl,
          scopes: input.flows.clientCredentials.scopes,
        });
      if (input.flows.authorizationCode)
        output.push({
          type: "oauth2",
          flow: "accessCode",
          authorizationUrl: input.flows.authorizationCode.authorizationUrl,
          tokenUrl: input.flows.authorizationCode.tokenUrl,
          scopes: input.flows.authorizationCode.scopes,
        });
      return output;
    }
    return [];
  };

  const isNullable =
    (visited: Set<string>) =>
    (components: OpenApi.IComponents) =>
    (schema: OpenApi.IJsonSchema): boolean => {
      if (OpenApiTypeChecker.isNull(schema)) return true;
      else if (OpenApiTypeChecker.isReference(schema)) {
        if (visited.has(schema.$ref)) return false;
        visited.add(schema.$ref);
        const next: OpenApi.IJsonSchema | undefined = OpenApiReferenceKey.get(
          components.schemas,
          schema.$ref,
        );
        return next ? isNullable(visited)(components)(next) : false;
      }
      return (
        OpenApiTypeChecker.isOneOf(schema) &&
        schema.oneOf.some(isNullable(visited)(components))
      );
    };

  interface ISwaggerServer {
    host?: string;
    basePath?: string;
    schemes?: SwaggerV2.Scheme[];
  }

  interface IDowngradedRequestBody {
    consumes?: string[];
    parameters: SwaggerV2.IOperation.IParameter[];
  }

  interface IDowngradedResponse {
    produces?: string[];
    response: SwaggerV2.IOperation.IResponse;
  }

  interface IDowngradedMedia {
    types?: string[];
    schema?: OpenApi.IJsonSchema;
    examples?: Record<string, any>;
  }

  const downgradeServers = (
    servers: OpenApi.IServer[] | undefined,
    scope: string,
  ): ISwaggerServer => {
    if (!servers?.length) return {};
    const parsed: ISwaggerServer[] = servers.map((server) => {
      if (server.description !== undefined)
        throw new TypeError(
          `SwaggerV2Downgrader: ${scope} descriptions are not representable.`,
        );
      if (
        Object.keys(server.variables ?? {}).length > 0 ||
        server.url.includes("{")
      )
        throw new TypeError(
          `SwaggerV2Downgrader: ${scope} contain template variables.`,
        );
      if (/[?#]/.test(server.url))
        throw new TypeError(
          `SwaggerV2Downgrader: ${scope} contain a query or fragment.`,
        );
      const absolute: RegExpMatchArray | null = server.url.match(
        /^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]+)(\/[^?#]*)?$/,
      );
      if (absolute) {
        const scheme: string = absolute[1]!.toLowerCase();
        if (isSwaggerScheme(scheme) === false)
          throw new TypeError(
            `SwaggerV2Downgrader: ${scope} use an unsupported scheme.`,
          );
        if (absolute[2]!.includes("@"))
          throw new TypeError(
            `SwaggerV2Downgrader: ${scope} contain user information.`,
          );
        return {
          schemes: [scheme],
          host: absolute[2]!,
          basePath: normalizeBasePath(absolute[3]),
        };
      }
      const network: RegExpMatchArray | null = server.url.match(
        /^\/\/([^/?#]+)(\/[^?#]*)?$/,
      );
      if (network) {
        if (network[1]!.includes("@"))
          throw new TypeError(
            `SwaggerV2Downgrader: ${scope} contain user information.`,
          );
        return {
          host: network[1]!,
          basePath: normalizeBasePath(network[2]),
        };
      }
      if (server.url.startsWith("/"))
        return { basePath: normalizeBasePath(server.url) };
      throw new TypeError(
        `SwaggerV2Downgrader: ${scope} contain a relative URL Swagger 2 cannot represent.`,
      );
    });
    const first: ISwaggerServer = parsed[0]!;
    if (
      parsed.some(
        (server) =>
          sameAuthority(server.host, first.host) === false ||
          server.basePath !== first.basePath,
      )
    )
      throw new TypeError(
        `SwaggerV2Downgrader: ${scope} must share one host and basePath.`,
      );
    const withoutScheme: boolean = parsed.some(
      (server) => server.schemes === undefined,
    );
    const withScheme: boolean = parsed.some(
      (server) => server.schemes !== undefined,
    );
    if (withoutScheme && withScheme)
      throw new TypeError(
        `SwaggerV2Downgrader: ${scope} mix explicit and scheme-relative URLs.`,
      );
    return {
      host: first.host,
      basePath: first.basePath,
      schemes: withScheme
        ? [...new Set(parsed.flatMap((server) => server.schemes ?? []))]
        : undefined,
    };
  };

  const downgradeOperationSchemes = (
    document: ISwaggerServer,
    servers: OpenApi.IServer[] | undefined,
  ): SwaggerV2.Scheme[] | undefined => {
    if (servers === undefined) return undefined;
    const operation: ISwaggerServer = downgradeServers(
      servers,
      "operation servers",
    );
    if (
      sameAuthority(operation.host, document.host) === false ||
      operation.basePath !== document.basePath
    )
      throw new TypeError(
        "SwaggerV2Downgrader: operation servers cannot override host or basePath.",
      );
    if (sameStrings(operation.schemes, document.schemes)) return undefined;
    if (operation.schemes === undefined)
      throw new TypeError(
        "SwaggerV2Downgrader: an operation cannot remove document schemes.",
      );
    return operation.schemes;
  };

  const downgradeMedia = (
    content: OpenApi.IOperation.IContent | undefined,
    scope: string,
  ): IDowngradedMedia => {
    if (content === undefined) return {};
    const entries: [string, OpenApi.IOperation.IMediaType][] = Object.entries(
      content,
    ).filter(
      (entry): entry is [string, OpenApi.IOperation.IMediaType] =>
        entry[1] !== undefined,
    );
    if (entries.length === 0) return { types: [] };
    const first = entries[0]![1];
    if (first.itemSchema !== undefined)
      throw new TypeError(
        `SwaggerV2Downgrader: ${scope} itemSchema is not representable.`,
      );
    if (Object.keys(first.examples ?? {}).length > 0)
      throw new TypeError(
        `SwaggerV2Downgrader: ${scope} named examples are not representable.`,
      );
    for (const [_, media] of entries.slice(1)) {
      if (media.itemSchema !== undefined)
        throw new TypeError(
          `SwaggerV2Downgrader: ${scope} itemSchema is not representable.`,
        );
      if (Object.keys(media.examples ?? {}).length > 0)
        throw new TypeError(
          `SwaggerV2Downgrader: ${scope} named examples are not representable.`,
        );
      if (!JsonCanonical.equals(media.schema, first.schema))
        throw new TypeError(
          `SwaggerV2Downgrader: ${scope} media types must share one schema.`,
        );
    }
    const examples: Array<[string, any]> = entries
      .filter(([_, media]) => media.example !== undefined)
      .map(([type, media]) => [type, media.example]);
    return {
      types: [...new Set(entries.map(([type]) => type))],
      schema: first.schema,
      examples: examples.length > 0 ? Object.fromEntries(examples) : undefined,
    };
  };

  const normalizeBasePath = (path: string | undefined): string | undefined => {
    if (!path || path === "/") return undefined;
    const prefixed: string = path.startsWith("/") ? path : `/${path}`;
    return prefixed.replace(/\/+$/, "");
  };

  const sameStrings = (
    x: string[] | undefined,
    y: string[] | undefined,
  ): boolean =>
    x === undefined || y === undefined
      ? x === y
      : x.length === y.length && x.every((value, index) => value === y[index]);

  const sameAuthority = (
    x: string | undefined,
    y: string | undefined,
  ): boolean =>
    x === undefined || y === undefined
      ? x === y
      : x.toLowerCase() === y.toLowerCase();

  const sameStringSet = (x: string[], y: string[]): boolean =>
    x.length === y.length && x.every((value) => y.includes(value));

  const isFormMediaType = (type: string): boolean =>
    type === "application/x-www-form-urlencoded" ||
    type === "multipart/form-data";

  const isSwaggerScheme = (input: string): input is SwaggerV2.Scheme =>
    input === "http" || input === "https" || input === "ws" || input === "wss";
}

import { IJsonSchemaAttribute, OpenApi, SwaggerV2 } from "@typia/interface";

import { OpenApiReferenceKey } from "../../utils/internal/OpenApiReferenceKey";
import { OpenApiTypeChecker } from "../../validators/OpenApiTypeChecker";
import { SwaggerV2TypeChecker } from "../../validators/SwaggerV2TypeChecker";
import { OpenApiExclusiveEmender } from "./OpenApiExclusiveEmender";

/**
 * Upgrades a Swagger 2.0 document to the emended OpenAPI 3.2 form.
 *
 * Definitions become component schemas, body and form-data parameters become a
 * request body per consumed media type, responses are keyed by produced media
 * type, host, base path and schemes become servers, and `x-nullable`, `x-anyOf`
 * and `x-oneOf` become the emended unions. A document that cannot be
 * represented, such as a body together with form data, throws a TypeError.
 *
 * @evidence contracts/common.md#principled-implementation A Swagger 2.0 document is converted by turning definitions into component schemas, body and form-data parameters into request bodies per consumed media type, response schemas into content per produced media type, and host, base path and schemes into servers, and by reading `x-nullable`, `x-anyOf` and `x-oneOf`. Constructs that have no 3.x form, such as a body with form data or file parameters outside form data, throw TypeError with a message instead of being converted wrongly.
 * @evidence contracts/common.md#clear-and-simple-design Helpers per object kind in one namespace, and server composition and form-data schema checks are private; the operation and path-item conversion duplicates the other upgraders' shape.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Unsupported combinations are rejected. Media types come from the operation, then the document, with application/json as the existing default when neither declares them; an explicitly empty declaration stays empty and can cause rejection.
 * @evidence contracts/common.md#meaningful-documentation The namespace comment lists the mappings and the rejections.
 */
export namespace SwaggerV2Upgrader {
  /**
   * Upgrade a whole Swagger 2.0 document.
   *
   * @param input Swagger 2.0 document
   *
   * @returns Emended document marked with `x-typia-emended-v12`
   *
   * @evidence contracts/common.md#principled-implementation Info, components, paths, servers, security and tags are converted, and the version and marker are set; Swagger fields that have no counterpart are not copied.
   * @evidence contracts/common.md#clear-and-simple-design One function over the sub-converters.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The marker is the contract marker.
   * @evidence contracts/common.md#meaningful-documentation The doc names the parameter and result.
   */
  export const convert = (input: SwaggerV2.IDocument): OpenApi.IDocument => ({
    openapi: "3.2.0",
    info: input.info,
    components: convertComponents(input),
    paths: input.paths
      ? Object.fromEntries(
          Object.entries(input.paths)
            .filter(([_, v]) => v !== undefined)
            .map(
              ([key, value]) => [key, convertPathItem(input)(value)] as const,
            ),
        )
      : undefined,
    servers: convertServers(input),
    security: input.security,
    tags: input.tags,
    "x-typia-emended-v12": true,
  });

  /* -----------------------------------------------------------
    OPERATORS
  ----------------------------------------------------------- */
  const convertPathItem =
    (doc: SwaggerV2.IDocument) =>
    (pathItem: SwaggerV2.IPath): OpenApi.IPath => {
      // Convert x-additionalOperations to additionalOperations
      // Promote "query" to standard method (it's a v3.2 standard method)
      const xAdditional = pathItem["x-additionalOperations"];
      const queryOp = xAdditional?.["query"];
      const additionalOperations = xAdditional
        ? Object.fromEntries(
            Object.entries(xAdditional)
              .filter(([key, v]) => key !== "query" && v !== undefined)
              .map(([key, value]) => [
                key,
                convertOperation(doc)(pathItem)(value),
              ]),
          )
        : undefined;
      const { parameters: _parameters, ...rest } = pathItem as any;

      return {
        ...rest,
        ...(pathItem.get
          ? { get: convertOperation(doc)(pathItem)(pathItem.get) }
          : undefined),
        ...(pathItem.put
          ? { put: convertOperation(doc)(pathItem)(pathItem.put) }
          : undefined),
        ...(pathItem.post
          ? { post: convertOperation(doc)(pathItem)(pathItem.post) }
          : undefined),
        ...(pathItem.delete
          ? { delete: convertOperation(doc)(pathItem)(pathItem.delete) }
          : undefined),
        ...(pathItem.options
          ? { options: convertOperation(doc)(pathItem)(pathItem.options) }
          : undefined),
        ...(pathItem.head
          ? { head: convertOperation(doc)(pathItem)(pathItem.head) }
          : undefined),
        ...(pathItem.patch
          ? { patch: convertOperation(doc)(pathItem)(pathItem.patch) }
          : undefined),
        ...(pathItem.trace
          ? { trace: convertOperation(doc)(pathItem)(pathItem.trace) }
          : undefined),
        ...(queryOp
          ? { query: convertOperation(doc)(pathItem)(queryOp) }
          : undefined),
        ...(additionalOperations && Object.keys(additionalOperations).length > 0
          ? { additionalOperations }
          : undefined),
        "x-additionalOperations": undefined,
      };
    };

  const convertOperation =
    (doc: SwaggerV2.IDocument) =>
    (pathItem: SwaggerV2.IPath) =>
    (input: SwaggerV2.IOperation): OpenApi.IOperation => {
      const resolve = (
        p: SwaggerV2.IOperation.IParameter | SwaggerV2.IJsonSchema.IReference,
      ): SwaggerV2.IOperation.IParameter | undefined =>
        "$ref" in p ? OpenApiReferenceKey.get(doc.parameters, p.$ref) : p;
      const pathParameters: SwaggerV2.IOperation.IParameter[] = (
        pathItem.parameters ?? []
      )
        .map(resolve)
        .filter((p): p is SwaggerV2.IOperation.IParameter => p !== undefined);
      const operationParameters: SwaggerV2.IOperation.IParameter[] = (
        input.parameters ?? []
      )
        .map((p) =>
          resolve(
            p as
              | SwaggerV2.IOperation.IParameter
              | SwaggerV2.IJsonSchema.IReference,
          ),
        )
        .filter((p): p is SwaggerV2.IOperation.IParameter => p !== undefined);
      const parameters: SwaggerV2.IOperation.IGeneralParameter[] =
        mergeParameters(
          pathParameters.filter(isGeneralParameter),
          operationParameters.filter(isGeneralParameter),
        );
      const formData: SwaggerV2.IOperation.IGeneralParameter[] =
        parameters.filter((parameter) => parameter.in === "formData");
      const body: SwaggerV2.IOperation.IBodyParameter | undefined = [
        ...operationParameters,
        ...pathParameters,
      ].find(isBodyParameter) as
        | SwaggerV2.IOperation.IBodyParameter
        | undefined;
      if (body !== undefined && formData.length > 0)
        throw new TypeError(
          "SwaggerV2Upgrader: body and formData parameters cannot coexist.",
        );
      const consumes: string[] = selectMediaTypes(input.consumes, doc.consumes);
      const produces: string[] = selectMediaTypes(input.produces, doc.produces);
      return {
        ...input,
        parameters:
          pathItem.parameters !== undefined || input.parameters !== undefined
            ? parameters
                .filter((parameter) => parameter.in !== "formData")
                .map(convertParameter(doc.definitions ?? {}))
            : undefined,
        requestBody: body
          ? convertRequestBody(doc.definitions ?? {}, consumes)(body)
          : formData.length > 0
            ? convertFormData(doc.definitions ?? {}, consumes)(formData)
            : undefined,
        responses: input.responses
          ? Object.fromEntries(
              Object.entries(input.responses)
                .filter(([_, v]) => v !== undefined)
                .map(
                  ([key, value]) =>
                    [key, convertResponse(doc, produces)(value)!] as const,
                )
                .filter(([_, v]) => v !== undefined),
            )
          : undefined,
        servers:
          input.schemes !== undefined
            ? convertServers({ ...doc, schemes: input.schemes })
            : undefined,
        ...{
          consumes: undefined,
          produces: undefined,
          schemes: undefined,
        },
      };
    };

  const isBodyParameter = (
    input: SwaggerV2.IOperation.IParameter,
  ): input is SwaggerV2.IOperation.IBodyParameter =>
    input.in === "body" ||
    (input as SwaggerV2.IOperation.IBodyParameter).schema !== undefined;

  const isGeneralParameter = (
    input: SwaggerV2.IOperation.IParameter,
  ): input is SwaggerV2.IOperation.IGeneralParameter =>
    isBodyParameter(input) === false;

  const mergeParameters = (
    pathParameters: SwaggerV2.IOperation.IGeneralParameter[],
    operationParameters: SwaggerV2.IOperation.IGeneralParameter[],
  ): SwaggerV2.IOperation.IGeneralParameter[] => {
    const map: Map<string, SwaggerV2.IOperation.IGeneralParameter> = new Map();
    const emplace = (
      parameter: SwaggerV2.IOperation.IGeneralParameter,
    ): void => {
      map.set(`${parameter.in}:${parameter.name}`, parameter);
    };
    pathParameters.forEach(emplace);
    operationParameters.forEach(emplace);
    return [...map.values()];
  };

  const convertParameter =
    (definitions: Record<string, SwaggerV2.IJsonSchema>) =>
    (
      input: SwaggerV2.IOperation.IGeneralParameter,
    ): OpenApi.IOperation.IParameter => {
      if (isFileParameter(input))
        throw new TypeError(
          "SwaggerV2Upgrader: file parameters must be located in formData.",
        );
      const {
        name,
        in: location,
        required: inputRequired,
        description,
        ...schema
      } = input as SwaggerV2.IOperation.IGeneralParameter & {
        required?: boolean | string[];
      };
      const required: boolean | undefined =
        location === "path"
          ? true
          : typeof inputRequired === "boolean"
            ? inputRequired
            : undefined;
      return {
        name,
        in: location as any,
        description,
        schema: convertSchema(definitions)({
          ...schema,
          ...(Array.isArray(inputRequired)
            ? { required: inputRequired }
            : undefined),
        } as SwaggerV2.IJsonSchema),
        ...(required !== undefined ? { required } : {}),
      };
    };

  const convertFormData =
    (
      definitions: Record<string, SwaggerV2.IJsonSchema>,
      mediaTypes: string[],
    ) =>
    (
      parameters: SwaggerV2.IOperation.IGeneralParameter[],
    ): OpenApi.IOperation.IRequestBody => {
      if (
        mediaTypes.length === 0 ||
        mediaTypes.some((type) => isFormMediaType(type) === false)
      )
        throw new TypeError(
          "SwaggerV2Upgrader: formData parameters require only form media types.",
        );
      const schema: OpenApi.IJsonSchema.IObject = {
        type: "object",
        properties: Object.fromEntries(
          parameters.map((parameter) => [
            parameter.name,
            convertFormDataSchema(definitions)(parameter),
          ]),
        ),
        required: parameters
          .filter((parameter) => isRequiredParameter(parameter))
          .map((parameter) => parameter.name),
      };
      return {
        required: schema.required!.length > 0 ? true : undefined,
        content: Object.fromEntries(
          mediaTypes.map((type) => [type, { schema }]),
        ),
      };
    };

  const convertFormDataSchema =
    (definitions: Record<string, SwaggerV2.IJsonSchema>) =>
    (input: SwaggerV2.IOperation.IGeneralParameter): OpenApi.IJsonSchema => {
      const {
        name: _name,
        in: _in,
        required: _required,
        description,
        ...schema
      } = input as SwaggerV2.IOperation.IGeneralParameter & {
        required?: boolean | string[];
      };
      if ((schema as { type?: string }).type === "file") {
        const {
          type: _type,
          format: _format,
          ...attributes
        } = schema as SwaggerV2.IJsonSchema.IString;
        return {
          ...attributes,
          type: "string",
          format: "binary",
          description,
        } as OpenApi.IJsonSchema;
      }
      const converted: OpenApi.IJsonSchema = convertSchema(definitions)({
        ...schema,
        description:
          (schema as { description?: string }).description ?? description,
      } as SwaggerV2.IJsonSchema);
      if (isFormDataSchema(converted) === false)
        throw new TypeError(
          "SwaggerV2Upgrader: formData parameters must use simple schemas.",
        );
      return converted;
    };
  const convertRequestBody =
    (
      definitions: Record<string, SwaggerV2.IJsonSchema>,
      mediaTypes: string[],
    ) =>
    (
      input: SwaggerV2.IOperation.IBodyParameter,
    ): OpenApi.IOperation.IRequestBody => {
      if (mediaTypes.length === 0)
        throw new TypeError(
          "SwaggerV2Upgrader: body parameters require a consumed media type.",
        );
      return {
        description: input.description,
        ...(input.required !== undefined ? { required: input.required } : {}),
        content: Object.fromEntries(
          mediaTypes.map((type) => [
            type,
            {
              schema: convertSchema(definitions)(input.schema),
            },
          ]),
        ),
      };
    };

  const convertResponse =
    (doc: SwaggerV2.IDocument, mediaTypes: string[]) =>
    (
      input:
        | SwaggerV2.IOperation.IResponse
        | SwaggerV2.IJsonSchema.IReference<`#/definitions/responses/${string}`>,
    ): OpenApi.IOperation.IResponse | undefined => {
      if ("$ref" in input) {
        const found: SwaggerV2.IOperation.IResponse | undefined =
          OpenApiReferenceKey.get(doc.responses, input.$ref)!;
        if (found === undefined) return undefined;
        input = found;
      }
      const exampleTypes: string[] = Object.keys(input.examples ?? {});
      const hasPayload: boolean =
        input.schema !== undefined ||
        exampleTypes.length > 0 ||
        input.example !== undefined;
      if (hasPayload && mediaTypes.length === 0)
        throw new TypeError(
          "SwaggerV2Upgrader: response payloads require a produced media type.",
        );
      if (exampleTypes.some((type) => mediaTypes.includes(type) === false))
        throw new TypeError(
          "SwaggerV2Upgrader: response examples must match produced media types.",
        );
      return {
        description: input.description,
        content:
          input.schema !== undefined ||
          exampleTypes.length > 0 ||
          input.example !== undefined
            ? Object.fromEntries(
                mediaTypes.map((type) => [
                  type,
                  {
                    schema:
                      input.schema !== undefined
                        ? convertSchema(doc.definitions ?? {})(input.schema)
                        : undefined,
                    example: Object.hasOwn(input.examples ?? {}, type)
                      ? input.examples![type]
                      : input.example,
                  },
                ]),
              )
            : undefined,
        headers: input.headers
          ? Object.fromEntries(
              Object.entries(input.headers)
                .filter(([_, v]) => v !== undefined)
                .map(
                  ([key, value]) =>
                    [
                      key,
                      {
                        name: key,
                        in: "header",
                        schema: convertSchema(doc.definitions ?? {})(value),
                      },
                    ] as const,
                ),
            )
          : undefined,
      };
    };

  const selectMediaTypes = (
    operation: string[] | undefined,
    document: string[] | undefined,
  ): string[] => [
    ...new Set(
      operation !== undefined
        ? operation
        : document !== undefined
          ? document
          : ["application/json"],
    ),
  ];

  const convertServers = (
    input: Pick<SwaggerV2.IDocument, "host" | "basePath" | "schemes">,
  ): OpenApi.IServer[] | undefined => {
    if (/[?#]/.test(input.host ?? "") || /[?#]/.test(input.basePath ?? ""))
      throw new TypeError(
        "SwaggerV2Upgrader: host and basePath cannot contain a query or fragment.",
      );
    const basePath: string = normalizeBasePath(input.basePath);
    if (!input.host) {
      if (input.schemes?.length)
        throw new TypeError(
          "SwaggerV2Upgrader: schemes require host to compose server URLs.",
        );
      return basePath ? [{ url: basePath }] : undefined;
    }

    const absolute: RegExpMatchArray | null = input.host.match(
      /^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]+)(\/[^?#]*)?$/,
    );
    const embeddedScheme: string | undefined = absolute?.[1]?.toLowerCase();
    const host: string = absolute?.[2] ?? input.host.replace(/^\/\//, "");
    if (host.includes("@"))
      throw new TypeError(
        "SwaggerV2Upgrader: host cannot contain user information.",
      );
    const hostPath: string = normalizeBasePath(absolute?.[3]);
    const path: string = joinBasePaths(hostPath, basePath);
    const schemes: string[] = [
      ...new Set(
        input.schemes?.length
          ? input.schemes
          : embeddedScheme
            ? [embeddedScheme]
            : [],
      ),
    ];
    if (schemes.some((scheme) => isSwaggerScheme(scheme) === false))
      throw new TypeError(
        "SwaggerV2Upgrader: schemes must be http, https, ws, or wss.",
      );
    return schemes.length
      ? (schemes as SwaggerV2.Scheme[]).map((scheme) => ({
          url: `${scheme}://${host}${path}`,
        }))
      : [{ url: `//${host}${path}` }];
  };

  const normalizeBasePath = (path: string | undefined): string => {
    if (!path || path === "/") return path ?? "";
    const prefixed: string = path.startsWith("/") ? path : `/${path}`;
    return prefixed.replace(/\/+$/, "");
  };

  const joinBasePaths = (x: string, y: string): string =>
