  export const find = <T>(
    dictionary: Record<string, T> | undefined,
    reference: string,
    prefix?: string,
  ): { key: string; value: T } | undefined => {
    const key: string | undefined = read(reference, prefix);
    return key !== undefined && ObjectDictionary.has(dictionary, key)
      ? { key, value: dictionary![key] as T }
      : undefined;
  };

