          ? {
              ...res,
              description: JsonDescriptor.cascade({
                components: props.components,
                schema: props.schema,
                escape: true,
                key,
              }),
            }
          : res;
      } else {
        const res: OpenApi.IJsonSchema | null | undefined = escapeSchema({
          ...props,
          schema: target,
          accessor: `${props.refAccessor}[${JSON.stringify(key)}]`,
          visited: new Map([...props.visited, [key, 1]]),
        });
        return res
          ? {
              ...res,
              description: JsonDescriptor.cascade({
                components: props.components,
                schema: props.schema,
                escape: true,
                key,
              }),
            }
          : res;
