    y: OpenApi.IJsonSchema.IArray | OpenApi.IJsonSchema.ITuple;
  }): boolean => {
    const xRange: IArrayRange = getArrayRange(p.x);
    const yRange: IArrayRange = getArrayRange(p.y);
