    if (ch === '"') {
      pos++;
      while (pos < len) {
        if (input[pos] === "\\") {
          pos += 2; // skip escape sequence
          continue;
        }
        if (input[pos] === '"') {
          pos++;
          break;
        }
        pos++;
      }
      continue;
    }

    pos++;
