    ? camelSnake(`${str.substring(0, index)}_${str.substring(index + 2)}`)
    : `${str
        .substring(0, index)
        .toLowerCase()}${middle.toUpperCase()}${camelSnake(
        str.substring(index + 2),
      )}`;
};

