      ctx.schema.multipleOf !== undefined
        ? _isMultipleOf(ctx.value, ctx.schema.multipleOf) ||
          ctx.report({
            ...ctx,
            expected: `${type} & MultipleOf<${ctx.schema.multipleOf}>`,
