   */
  export function checkPluginsReportTypeScriptDiagnostics(
    plugins: readonly ITtscLoadedNativePlugin[],
  ): boolean {
    return plugins.some(
      (plugin) =>
        plugin.stage === "check" &&
        plugin.reportsTypeScriptDiagnostics === true,
    );
  }

