    plugin: ITtscLoadedNativePlugin,
    args: readonly string[],
    options: TtscBuildOptions,
    execution: ReturnType<typeof resolveExecutionContext>,
    label: string,
    timing: BuildTiming.BuildTiming,
    timingLabel: string,
    tsgoArgs?: string,
  ): TtscBuildResult {
    const startedAt = process.hrtime.bigint();
