function resolveCompilerOptionPath(
  declaringDir: string,
  configDir: string,
  value: string,
): string {
  const normalized = value.replaceAll("\\", "/");
  if (
    normalized.slice(0, CONFIG_DIR_TEMPLATE.length).toLowerCase() !==
    CONFIG_DIR_TEMPLATE.toLowerCase()
