import type { AnySubcommand } from "./AnySubcommand";
import type { FlagKind } from "./FlagKind";
import type { FlagLayer } from "./FlagLayer";
import type { ValueValidator } from "./ValueValidator";

/**
 * One CLI flag's complete contract. Every layer's behaviour is structural —
 * which subcommands accept the flag, where it is consumed, where it is
 * forwarded, whether it is terminal (prints and exits) — so the next layer
 * never silently drops the flag.
 *
 * @evidence contracts/common.md#principled-implementation The record separates token arity, command acceptance, consumer ownership, forwarding and terminal behavior because each controls a distinct parser or pipeline decision. Native capability discriminants prevent sending unsupported bare arguments to older hosts.
 * @evidence contracts/common.md#clear-and-simple-design One schema row owns a flag's identities and routing policy, allowing parser, launcher classifications and generated native allow-lists to derive their views from the same declaration.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Terminal and projectFree distinctions express real tool semantics, and internalShadow records user-visible ownership rather than matching fixture spellings or mutating the native parser.
 * @evidence contracts/common.md#meaningful-documentation Members explain absence defaults, repeated-value ordering, terminal/project-free distinctions and capability ownership. Separate member paragraphs and blank lines follow the documentation skill's association and rationale guidance without property-level checklist tags.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation This type declaration describes a data shape only; it opens no file, builds no path and branches on no platform.
 */
export interface FlagSpec {
  /**
   * Canonical flag name including leading dashes (`"--singleThreaded"`). The
   * generator normalizes canonical names and aliases to dash-free lowercase Go
   * allow-list keys; the docs table retains this spelling in its first column.
   */
  readonly name: string;

  /**
   * Alternative spellings (`"-p"`, `"--project"` for `--tsconfig`). The parsing
   * engine treats every alias as an equivalent of `name`.
   */
  readonly aliases?: readonly string[];

  /** Argument shape: boolean / required value / optional value. */
  readonly kind: FlagKind;

  /**
   * For `value` flags: optional validator. `positiveInt` mirrors the
   * `--checkers minValue:1` constraint tsgo enforces.
   */
  readonly validator?: ValueValidator;

  /** Subcommands that accept this flag. */
  readonly subcommands: readonly AnySubcommand[];

  /**
   * Layers that read the flag into a typed option. Order matters only for
   * documentation; the parsing engine merges across layers.
   */
  readonly consumedBy: readonly FlagLayer[];

  /**
   * Where the flag travels when the consuming layer does not absorb it. Default
   * for any flag a layer does not consume is `"tsgo"` — i.e. the launcher
   * forwards an unknown flag to tsgo via passthrough. Setting this to
   * `undefined` while `consumedBy: ["launcher"]` is set means the flag is
   * intentionally consumed-not-forwarded (e.g. ttsc-internal `--binary`).
   */
  readonly forwardTo?: FlagLayer;

  /**
   * Terminal flags ask the underlying tool to print something and exit
   * (`--help`, `--version`, `--showConfig`, `--listFilesOnly`, `--all`,
   * `--init`). ttsc must not wrap them in a pre-emit pass: the wrapped pass
   * would run the printing command twice.
   */
  readonly terminal?: boolean;

  /**
   * `true` when a `terminal` flag's meaning does not presuppose a resolved
   * project, so ttsc must answer it before project resolution runs (`--init`
   * writes the starter tsconfig, `--all` and `-?` print tsgo's help). Without
   * this split `ttsc --init` would fail with "could not find tsconfig.json …"
   * in the only directory where it is useful.
   *
   * `--showConfig` and `--listFilesOnly` are terminal but deliberately NOT
   * project-free: both describe a project, so failing without one is correct.
   */
  readonly projectFree?: boolean;

  /**
   * `true` when every occurrence of a repeated `value` flag counts rather than
   * the last one winning (`ttsx -r a -r b` preloads both). The engine keeps the
   * last value in `ParseResult.values` for callers that want a single answer
   * and records the complete ordered list in `ParseResult.repeated`.
   */
  readonly repeatable?: boolean;

  /**
   * `true` when ttsc may add this flag to tsgo internally and post-process the
   * output. If the user also forwards the same flag, ttsc keeps the
   * user-visible behaviour (no double-print, no swallowed output). The shadow
   * check is structural rather than `passthrough.includes("…")`.
   *
   * Currently true for `--listEmittedFiles`, `--noEmit`, `--pretty`.
   */
  readonly internalShadow?: boolean;

  /**
   * `true` when pinned tsgo only permits the option in tsconfig, except for
   * command-line `false` or `null`. The launcher forwards the original argv so
   * tsgo remains the diagnostic authority.
   */
  readonly tsconfigOnly?: boolean;

  /**
   * Native sidecar capability that must be declared before ttsc sends this flag
   * as a bare optional compiler-control argument to a check-stage host. This
   * does not describe the host's required subcommand/project/plugin protocol
   * fields. Other forwarded compiler argv uses `TTSC_TSGO_ARGS`; launcher-owned
   * options stay with their JavaScript consumer.
   */
  readonly nativeCapability?: "diagnosticsTiming" | "threadingArgs";

  /** Human description for `--help` and the docs table. */
  readonly description: string;
}

ttsc/src/flags/normalizeCompilerEnumValu:
import { COMPILER_ENUM_WHITESPACE } from "./COMPILER_ENUM_WHITESPACE";
import { COMPILER_OPTION_ASCII_FOLDS } from "./COMPILER_OPTION_ASCII_FOLDS";

/**
 * Normalize an enum discriminant at the boundary that supplied it.
 *
 * Native command-line enum parsing trims IsWhiteSpaceLike before lookup; JSON
 * enum parsing does not trim. Both use Unicode simple lowercase. Generated
 * folds into the pinned compiler's ASCII enum domain preserve the native
 * spelling where JavaScript lowercase expands a character instead. Dashes
 * remain value data, and an empty discriminant represents the native reset.
 * This projection does not validate membership in an option's enum map.
 *
 * @evidence contracts/common.md#principled-implementation CLI-only trimming follows the generated native IsWhiteSpaceLike table; both origins use generated simple folds before lowercase, preserve leading dashes and distinguish an empty reset from a padded JSON value.
 * @evidence contracts/common.md#clear-and-simple-design One pure boundary normalizer separates enum data from option-name normalization and makes CLI versus JSON origin explicit.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Enum membership and invalid-value diagnostics remain native-owned; the adapter does not strip a value's dash or trim JSON to admit an invalid spelling.
 * @evidence contracts/common.md#meaningful-documentation Native prose explains origin-specific trimming, Unicode folding, the reset outcome and the projection's validation boundary.
 * @evidence contracts/performance.md#efficient-algorithms CLI boundary scans, Unicode fold replacement and lowercase conversion are linear in token length, using immutable generated lookup tables instead of scanning declarations. Intermediate slices/replacements and the returned string grow with that token; JSON skips boundary trimming.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Each token belongs to its caller's current option origin; immutable native tables are module-shared, and no invocation or historical value cache is retained.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Only the normalized string is returned; transient string slices and replacements create no resource or retained history.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation This origin-specific Unicode string transformation interprets no filesystem path or process capability; generated native whitespace/fold policy is module data, and callers own any native compiler validation.
 */
export function normalizeCompilerEnumValue(
  value: string,
  origin: "cli" | "json",
): string | null {
  let start = 0;
  let end = value.length;
  if (origin === "cli") {
    while (start < end && COMPILER_ENUM_WHITESPACE.has(value[start]!)) start++;
    while (end > start && COMPILER_ENUM_WHITESPACE.has(value[end - 1]!)) end--;
  }
  const normalized = value
    .slice(start, end)
    .replace(
      /[^\x00-\x7f]/gu,
      (character) => COMPILER_OPTION_ASCII_FOLDS.get(character) ?? character,
    )
    .toLowerCase();
  return normalized === "" ? null : normalized;
}

ttsc/src/flags/readCompilerOptionOccurre:
import { COMPILER_ENUM_WHITESPACE } from "./COMPILER_ENUM_WHITESPACE";
import { COMPILER_OPTIONS } from "./COMPILER_OPTIONS";
import type { CompilerOptionSpec } from "./CompilerOptionSpec";
import { normalizeFlagToken } from "./normalizeFlagToken";

/**
 * Read one unexpanded argv frame using pinned native command-line grammar.
 * Scalars consume dash operands; lists consume only a nonempty parsed list or
 * its diagnostic, and configuration-only options admit explicit resets.
 * Response files remain frame boundaries owned by the caller/native parser.
 *
 * @evidence contracts/common.md#principled-implementation Generated native kind, element and configuration-only metadata drive scalar, boolean and list lookahead; returned width, optional assignment and deletion-boundary marker retain those distinct decisions. List-level Unicode White_Space follows Go TrimSpace, enum-item emptiness uses the separately generated native IsWhiteSpaceLike set, and rejected inline names remain unknown native options.
 * @evidence contracts/common.md#clear-and-simple-design One pure occurrence reader owns consumption and assignment; callers advance their own cursor and attach launcher semantics separately. One local record serves classification, forwarding and removal without retaining an argv cursor.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Grammar and boundary markers come from native declarations without guessing values from source suffixes, spelling exceptions or treating a dash operand as another launcher request.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs state the unexpanded-frame scope and distinctions among scalar, list and config-only rules; the private result prose explains removal fences, unknown metadata and absent boolean assignments, while each member documents its role.
 * @evidence contracts/performance.md#efficient-algorithms Metadata lookup is constant-time after a token-name scan; list lookahead scans its value and components linearly. Temporary component/rune arrays grow with only that value, and callers advance by the returned width.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work This pure lookahead reads current invocation argv; immutable generated tables are already shared by module identity, and no per-argv computation is coordinated or cached here.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The returned occurrence and transient normalized token-name strings, value components and rune arrays belong to this invocation; no argv history, process, handle or persistent invocation state is retained.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation This deterministic argv grammar reads generated metadata and Unicode trimming rules without interpreting operands as filesystem paths, expanding response files or probing a native executable; the spawning/compiler owners supply those OS capabilities.
 */
export function readCompilerOptionOccurrence(
  argv: readonly string[],
  index: number,
): CompilerOptionOccurrence {
  const token = argv[index];
  const option =
    token?.startsWith("-") === true && !token.includes("=")
      ? COMPILER_OPTIONS.get(normalizeFlagToken(token))
      : undefined;
  if (option === undefined) return { width: 1, needsFence: false };
  const next = argv[index + 1];
  if (next === undefined)
    return {
      option,
      width: 1,
      needsFence: false,
      booleanValue:
        option.kind === "boolean" && !option.configOnly ? true : undefined,
    };
  if (next === "null")
    return {
      option,
      width: 2,
      needsFence: false,
      booleanValue: option.kind === "boolean" ? false : undefined,
    };
  if (option.kind === "boolean")
    return {
      option,
      width: next === "true" || next === "false" ? 2 : 1,
      booleanValue:
        option.configOnly && next !== "false" ? undefined : next !== "false",
      needsFence: next.startsWith("-"),
    };
  if (option.configOnly)
    return {
      option,
      width: next !== "" && !next.startsWith("-") ? 2 : 1,
      needsFence: next.startsWith("-"),
    };
  if (option.kind === "list") {
    // Go strings.TrimSpace follows Unicode White_Space, which excludes FEFF
    // and includes U+0085; JavaScript trim uses a different character set.
    let start = 0;
    let end = next.length;
    const whitespace = /\p{White_Space}/u;
    while (start < end && whitespace.test(next[start]!)) start++;
    while (end > start && whitespace.test(next[end - 1]!)) end--;
    const trimmed = next.slice(start, end);
    // Enum members undergo the compiler's IsWhiteSpaceLike trim as well;
    // FEFF and zero-width space can therefore make every member empty.
    const empty =
      trimmed === "" ||
      trimmed.startsWith("-") ||
      trimmed
        .split(",")
        .every((part) =>
          option.element === "string"
            ? part === ""
            : [...part].every((character) =>
                COMPILER_ENUM_WHITESPACE.has(character),
              ),
        );
    return { option, width: empty ? 1 : 2, needsFence: next.startsWith("-") };
  }
  return { option, width: 2, needsFence: false };
}

/**
 * One native argv occurrence and the lookahead boundary it establishes.
 * Undefined metadata denotes a positional token or an unknown option. An
 * undefined boolean value denotes a nonboolean option or a config-only boolean
 * request the native compiler rejects without assigning a value.
 */
interface CompilerOptionOccurrence {
  /** Native declaration, absent for non-options and unknown spellings. */
  readonly option?: CompilerOptionSpec;

  /** Option token plus the next token only when native parsing consumes it. */
  readonly width: 1 | 2;

  /** Native boolean assignment; false also represents an explicit null reset. */
  readonly booleanValue?: boolean;

  /** Whether removing the following option requires an empty lookahead fence. */
  readonly needsFence: boolean;
}

import { normalizeCompilerEnumValue } from "./normalizeCompilerEnumValue";
import { readCompilerOptionOccurrence } from "./readCompilerOptionOccurrence";

/**
 * Project visible compiler arguments in native frame order.
 *
 * Every frame advances by the owned occurrence reader's consumption width,
 * including scalars whose values look like flags or response files. Only an
 * unconsumed response-file token requests native expansion. Known assignments
 * use canonical option names, and a present null reset is distinct from an
 * absent assignment. Rejected configuration-only requests make no assignment.
 * Boolean assignments and enum discriminants are projected for launcher
 * decisions; other operands retain their forwarded representation. Native
 * compilation owns full value validation and list conversion.
 *
 * @evidence contracts/common.md#principled-implementation Native occurrence widths prevent reinterpreting scalar operands, canonical names retain aliases and order, and explicit null or empty enum assignments remain present resets. Config-only requests without a native boolean assignment do not overwrite earlier values.
 * @evidence contracts/common.md#clear-and-simple-design One invocation record carries an assignment map and actual response-file frames; callers use map presence for precedence and leave response expansion with the native owner.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Values remain a launcher projection rather than a fabricated validated configuration; forwarded list operands and unknown native diagnostics are not replaced by guessed schema validation or a response-file parser.
 * @evidence contracts/common.md#meaningful-documentation Native prose explains frame consumption, reset versus absence, assignment admission and validation ownership; the private record's member comments describe the two retained facts.
 * @evidence contracts/performance.md#efficient-algorithms One advancing cursor projects argv once, with map replacement for repeated assignments; option-name normalization, enum normalization and list lookahead also scan their visited text bytes. The result holds at most the schema's distinct assigned keys plus ordered response-frame references; transient normalized strings/components grow with the current token or operand.
 * @evidence contracts/performance.md#reuse-equivalent-work Callers share this invocation record across option queries, while immutable native metadata is shared by module identity. No value from a different argv population is reused.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The returned map and response array transfer to the caller with module-owned canonical keys and current invocation values or normalized enum strings; no process, handle, persistent cache or historical argument population is owned here.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation This argv-frame projection treats operands and response requests as data without resolving filesystem paths or reading response contents; expansion, executable discovery and native validation belong to its callers.
 */
export function readCompilerOptionValues(
  argv: readonly string[] = [],
): CompilerOptionValues {
  const values = new Map<string, unknown>();
  const responseFiles: string[] = [];
  for (let index = 0; index < argv.length; ) {
    const occurrence = readCompilerOptionOccurrence(argv, index);
    const option = occurrence.option;
    const next = argv[index + 1];
    if (argv[index]!.startsWith("@")) responseFiles.push(argv[index]!);
    if (option !== undefined) {
      if (next === "null") values.set(option.name, null);
      else if (option.kind === "boolean") {
        if (occurrence.booleanValue !== undefined) {
          values.set(option.name, occurrence.booleanValue);
        }
      } else if (!option.configOnly) {
        if (option.kind === "list") values.set(option.name, next ?? []);
        else if (occurrence.width === 2) {
          values.set(
            option.name,
            option.kind === "enum"
              ? normalizeCompilerEnumValue(next!, "cli")
              : next,
          );
        }
      }
    }
    index += occurrence.width;
  }
  return { values, responseFiles };
}

/** Invocation-local assignments and the unconsumed response expansion requests. */
interface CompilerOptionValues {
  /**
   * Canonical names with last assigned values; map presence retains a null
   * reset.
   */
  readonly values: ReadonlyMap<string, unknown>;

  /** Response-file tokens found at native argv frame boundaries, in their order. */
  readonly responseFiles: readonly string[];
}

ttsc/src/flags/resolveFlagSpec.ts:
import { FLAG_BY_TOKEN } from "./FLAG_BY_TOKEN";
import type { FlagSpec } from "./FlagSpec";
import { normalizeFlagToken } from "./normalizeFlagToken";

/**
 * Resolve a raw argv token to the flag it names, or `undefined` when the schema
 * claims no such flag.
 *
 * Accepts every spelling the compiler accepts — any casing, one or two leading
 * dashes — plus the inline `--flag=value` form, whose value is not part of the
 * identity. A token without a leading dash is never a flag: bare tokens are
 * input files and flag values, and resolving them here would let a value like
 * the `all` of `--target all` masquerade as `--all`.
 *
 * @evidence contracts/common.md#principled-implementation Requiring a leading dash distinguishes option tokens from values; splitting at the first equals sign and normalizing only the name yields the canonical schema identity while preserving value spelling for its owner.
 * @evidence contracts/common.md#clear-and-simple-design This resolver owns raw-token classification and delegates spelling policy to normalizeFlagToken and lookup storage to FLAG_BY_TOKEN.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The dash guard follows argv grammar rather than compensating with a list of positional names that happen to collide with options.
 * @evidence contracts/common.md#meaningful-documentation The native paragraphs explain undefined results, inline-value separation and why bare values are rejected, applying the documentation skill's failure-state and rationale guidance.
 * @evidence contracts/performance.md#efficient-algorithms A dash guard avoids normalization for positional data; locating the first equals sign and normalizing the name scan token bytes linearly before one lookup in the module-built index. Transient name strings grow with the token, without scanning schema rows per request.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Transient name strings belong to the invocation; the returned schema reference has module-owned lifetime, and this resolver retains no invocation history or handle.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work This invocation-local token interpretation does not coordinate a completed or in-flight producer across requests; callers already share the immutable module-built schema index.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation resolveFlagSpec computes from its arguments only; it opens no file, builds no path and calls no platform or process API.
 */
export function resolveFlagSpec(token: string): FlagSpec | undefined {
  if (!token.startsWith("-")) return undefined;
  const equalsIndex = token.indexOf("=");
  const name = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  return FLAG_BY_TOKEN.get(normalizeFlagToken(name));
}

