import type { ITtscCompilerContext } from "../structures/ITtscCompilerContext";
import type { ITtscProjectPluginConfig } from "../structures/ITtscProjectPluginConfig";

/**
 * Own compiler options while preserving host selectors and JSON plugin input.
 *
 * Construction evaluates each entry's JSON serialization once. Date and custom
 * toJSON behavior is preserved in that captured payload; cycles and BigInt fail
 * at capture rather than during a later plugin launch. Each adapter conversion
 * parses defined captured JSON anew; an undefined payload stays omitted. A
 * parsed result cannot mutate the retained string.
 *
 * Worker transfer sends selectors and serialized payload separately because
 * structured cloning cannot carry the local JSON adapter method.
 *
 * @evidence contracts/common.md#principled-implementation Native plugin and descriptor inputs are JSON, whereas parent-side loading reads raw transform/enabled/configFile selectors; storing both preserves those distinct meanings even when custom toJSON changes the wire representation.
 * @evidence contracts/common.md#clear-and-simple-design One snapshot owner supplies local copying and worker transfer; the extra payload channel is required because structured cloning omits local behavior while the loader still needs the original selectors.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The toJSON method belongs to a newly owned adapter, not a foreign object or global patch; unsupported cyclic/BigInt payloads fail instead of being replaced with invented defaults.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain capture timing, supported JSON conversion, failure timing, private ownership and the worker distinction, following documentation paragraph and tag separation guidance.
 * @evidence contracts/portability.md#os-neutral-implementation Context path strings and environment overrides remain native inputs; own undefined environment overrides are preserved rather than being lost through JSON serialization of the whole context.
 * @evidence contracts/performance.md#efficient-algorithms Local copies traverse context/environment fields and plugin entries, including their key text. First capture also traverses JSON input and invokes its conversion/property behavior, whose work is not bounded by output bytes alone; captured copies share immutable strings and consumers parse only requested payloads. This avoids a custom recursive object copier without asserting constant callback or conversion cost.
 * @evidence contracts/performance.md#reuse-equivalent-work Captured JSON strings reuse the constructor's conversion result independently of later original-input mutation. Host selectors are copied into owned, mutable adapters rather than frozen; internal consumers must preserve them. Caller-visible parsed payloads are newly allocated and do not change retained strings.
 * @evidence contracts/performance.md#bound-retention-and-release-resources WeakMap associations do not strongly retain owned adapters. Payload strings scale with captured plugin bytes and remain reachable through adapter closures or copied transfer channels until their holders release them; no global strong history, forced reclamation deadline or payload-size cap is imposed.
 */
export class CompilerContextSnapshot {
  /**
   * Capture options or copy a captured context without reevaluating conversion.
   *
   * @evidence contracts/common.md#principled-implementation Host selectors are read before first JSON conversion and retained independently; captured entries copy the retained payload rather than executing custom conversion again.
   * @evidence contracts/common.md#clear-and-simple-design Context spreading retains scalar options, environment copying preserves own undefined overrides, and one entry adapter owns the selector/payload distinction.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Only newly owned objects receive adapters; arbitrary plugin payload remains governed by actual JSON serialization, without foreign patches or invented fallback config.
   * @evidence contracts/common.md#meaningful-documentation The method states capture versus copying, while the enclosing native paragraphs explain JSON conversion timing and ownership consequences.
   * @evidence contracts/portability.md#os-neutral-implementation Native path fields remain unchanged and environment entries are copied without JSON omission; downstream native owners interpret their respective bases and name semantics.
   * @evidence contracts/performance.md#efficient-algorithms Copying traverses context/environment own fields and plugin entries with their key text and property reads. An uncaptured entry additionally runs JSON.stringify, including input traversal and user conversion behavior; subsequent captured clones share immutable payload strings rather than repeat conversion.
   * @evidence contracts/performance.md#reuse-equivalent-work Existing adapters reuse their WeakMap-captured payload strings without reevaluating user conversion. Selectors are copied from the supplied adapter at this call, so preserving internal adapter selectors is a consumer premise rather than an enforced freeze.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The returned context initially owns new adapter references; an independently retained adapter or payload channel can extend its string lifetime. Weak associations impose no strong historical retention, and reclamation depends on holders dropping their references rather than a disposal hook here.
   */
  public static clone(context: ITtscCompilerContext): ITtscCompilerContext {
    return {
      ...context,
      env: context.env ? { ...context.env } : undefined,
      plugins: Array.isArray(context.plugins)
        ? context.plugins.map((entry: ITtscProjectPluginConfig) => {
            const selectors = {
              enabled: entry.enabled,
              transform: entry.transform,
              ...(typeof entry.configFile === "string"
                ? { configFile: entry.configFile }
                : {}),
            };
            const payload = payloads.has(entry)
              ? payloads.get(entry)
              : JSON.stringify(entry);
            return ownedPlugin(selectors, payload);
          })
        : context.plugins,
    };
  }

  /**
   * JSON payload channel paired by index with worker context selectors.
   *
   * @evidence contracts/common.md#principled-implementation Index-preserving mapping keeps each captured JSON payload paired with the same entry whose host selectors the worker clones.
   * @evidence contracts/common.md#clear-and-simple-design Only payload strings cross this channel; compiler options remain in the ordinary context channel and local behavior is restored by one owner.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Actual captured JSON is transmitted, without fabricating clone-compatible substitutes for plugin values.
   * @evidence contracts/common.md#meaningful-documentation The native description explains pairing and worker transfer purpose; the enclosing comment documents why structured cloning needs a separate channel.
   *
   * @evidenceExclude contracts/portability.md#os-neutral-implementation This maps captured JSON strings and performs no native path, environment or process interpretation.
   *
   * @evidence contracts/performance.md#efficient-algorithms Mapping captured entries costs O(N) reference operations for N entries. Uncaptured entries run JSON.stringify with input traversal, output bytes and user conversion work; only captured strings avoid that serialization traversal.
   * @evidence contracts/performance.md#reuse-equivalent-work Retained payload strings preserve the constructor's conversion outcome across worker calls; uncaptured direct internal inputs are serialized once for this transfer.
   *
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The returned string array transfers to the caller; this method acquires no independent retained population or native resource.
   */
  public static serializePlugins(
    context: ITtscCompilerContext,
  ): (string | undefined)[] | undefined {
    return Array.isArray(context.plugins)
      ? context.plugins.map((entry: ITtscProjectPluginConfig) =>
          payloads.has(entry) ? payloads.get(entry) : JSON.stringify(entry),
        )
      : undefined;
  }

  /**
   * Restore local adapters after the worker cloned selectors and payloads.
   *
   * @evidence contracts/common.md#principled-implementation Equal-length arrays establish one payload per selector entry; restored adapters expose the captured JSON result without reevaluating user conversion in the worker.
   * @evidence contracts/common.md#clear-and-simple-design Restoration owns only the transfer seam and delegates ordinary uncaptured contexts to clone; malformed pairing fails at that boundary.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Pairing failures throw a protocol error rather than inventing defaults; adapter methods belong solely to newly owned objects.
   * @evidence contracts/common.md#meaningful-documentation Native wording identifies worker restoration and links it to the class's capture and transfer semantics, with prose and tags separated.
   * @evidence contracts/portability.md#os-neutral-implementation Native option spellings and own undefined environment entries survive restoration unchanged; the worker's separate environment adoption remains the native-name owner.
   * @evidence contracts/performance.md#efficient-algorithms With a supplied paired channel, one indexed pass builds N adapters and copies context/environment fields plus their key text; payload bytes are parsed when consumers request JSON. Without a channel, clone may capture uncaptured entries and incur their JSON traversal/conversion work.
   * @evidence contracts/performance.md#reuse-equivalent-work Rehydration reuses the caller's captured conversion rather than recomputing custom behavior in another environment.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Restored contexts and any separately retained adapters hold their configured payload strings while reachable. Weak associations do not globally keep completed contexts alive; this method enforces no request-end reclamation or payload-size bound.
   */
  public static restorePlugins(
    context: ITtscCompilerContext,
    serializedPlugins: readonly (string | undefined)[] | undefined,
  ): ITtscCompilerContext {
    if (serializedPlugins === undefined) return this.clone(context);
    if (
      !Array.isArray(context.plugins) ||
      context.plugins.length !== serializedPlugins.length
    )
      throw new Error(
        "ttsc: compiler plugin snapshot transfer is inconsistent",
      );
    return {
      ...context,
      env: context.env ? { ...context.env } : undefined,
      plugins: context.plugins.map(
        (entry: ITtscProjectPluginConfig, index: number) =>
          ownedPlugin(entry, serializedPlugins[index]),
      ),
    };
  }
}

const payloads = new WeakMap<ITtscProjectPluginConfig, string | undefined>();

/** Parent-side selectors stay separate from plugin-owned JSON representation. */
function ownedPlugin(
  entry: ITtscProjectPluginConfig,
  payload: string | undefined,
): ITtscProjectPluginConfig {
  const owned: ITtscProjectPluginConfig = {
    enabled: entry.enabled,
    transform: entry.transform,
    ...(typeof entry.configFile === "string"
      ? { configFile: entry.configFile }
      : {}),
  };
  Object.defineProperty(owned, "toJSON", {
    value: () => (payload === undefined ? undefined : JSON.parse(payload)),
  });
  payloads.set(owned, payload);
  return owned;
}

import { createProcessDiagnostic } from "../compiler/internal/build/createProcessDiagnostic";
import type { ITtscCompilerDiagnostic } from "../structures/ITtscCompilerDiagnostic";
import type { ITtscCompilerResult } from "../structures/ITtscCompilerResult";
import type { ITtscCompilerTransformation } from "../structures/ITtscCompilerTransformation";
import type { TtscBuildResult } from "../structures/internal/TtscBuildResult";
import { serializeCompilerError } from "./serializeCompilerError";

/**
 * The compile producer's actual output and build outcome, before API
 * adaptation. Common: Principled implementation: This input retains output and
 * build outcome as separate producer-owned values. Common: Clear and simple
 * design: Two named fields carry the existing compile adapter boundary without
 * a second output representation. Common: Prohibited implementation shortcuts:
 * The type does not supply native output or certify an authored record as a
 * compiler product. Common: Meaningful documentation: The native sentence
 * distinguishes the producer boundary from API result adaptation.
 */
interface ProjectResult {
  output: Record<string, string>;
  result: TtscBuildResult;
}

/**
 * The transform producer's source records and optional advisory observations.
 * Common: Principled implementation: Optional fields retain the producer's
 * absent-versus-present observations independently of build status. Common:
 * Clear and simple design: One input shape carries source, build and advisory
 * values to the same result adapter. Common: Prohibited implementation
 * shortcuts: The representation does not invent host reads, graph membership or
 * compiler completeness. Common: Meaningful documentation: The native sentence
 * identifies the actual producer-owned fields and optionality.
 */
interface ProjectTransformation {
  dependencies?: Record<string, string[]>;
  dependenciesComplete?: string[];
  graph?: ITtscCompilerTransformation.IReferenceGraph;
  hostInputHashes?: Record<string, string | null>;
  hostInputProofFailures?: Record<string, "observation-unavailable">;
  hostInputRealpaths?: Record<string, string | null>;
  hostInputs?: string[];
  observationsComplete?: false;
  pluginSources?: Record<string, string>;
  result: TtscBuildResult;
  sourceMaps?: Record<string, ITtscCompilerTransformation.ISourceMap>;
  typescript: Record<string, string>;
  volatile?: string[];
}

/**
 * Run the selected compile task once and adapt its returned or thrown outcome.
 *
 * @evidence contracts/common.md#principled-implementation The original task runs once; its output/status/diagnostics or thrown error determine the public result kind.
 * @evidence contracts/common.md#clear-and-simple-design One try/catch joins the task owner with the existing compile and exception adapters.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts No native task, output or error is substituted; caught values retain the existing serialization and classification policy.
 * @evidence contracts/common.md#meaningful-documentation The native sentence states exact invocation and returned/thrown ownership.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation The task owner chooses native files/processes; this boundary chooses only result adaptation and no independent platform policy.
 * @evidence contracts/performance.md#efficient-algorithms Cost includes the arbitrary selected task, diagnostic scan and any process-diagnostic construction or error serialization/classification; the fixed envelope does not bound those costs.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work This adapter coordinates no reusable native producer or cached outcome.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Returned producer references transfer to the caller; task resources and their lifetime remain with the task owner.
 */
export function runProject(task: () => ProjectResult): ITtscCompilerResult {
  try {
    return toCompilerResult(task());
  } catch (error) {
    return {
      error: normalizeError(error),
      kind: classifyException(error),
      type: "exception",
    };
  }
}

/**
 * Run the selected transform task once, preserving its optional observations.
 *
 * @evidence contracts/common.md#principled-implementation Successful and failed build outcomes retain source/advisory values while thrown outcomes use the existing exception policy.
 * @evidence contracts/common.md#clear-and-simple-design One try/catch invokes the selected task and delegates to the transform result adapter.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The adapter neither reconstructs native observations nor replaces the actual task with a result certificate.
 * @evidence contracts/common.md#meaningful-documentation The native sentence distinguishes selected execution from its observation adaptation.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation The task owns its native platform boundaries; this function selects no path, process or filesystem policy.
 * @evidence contracts/performance.md#efficient-algorithms The task cost is delegated in full, followed by diagnostic scanning, fixed optional-field projection and exceptional serialization/classification when needed.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work No completed or in-flight transform is cached by this adapter.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Returned source/advisory references remain caller-owned; the task owns native resource acquisition and retirement.
 */
export function runTransformation(
  task: () => ProjectTransformation,
): ITtscCompilerTransformation {
  try {
    return toCompilerTransformation(task());
  } catch (error) {
    return {
      error: normalizeError(error),
      kind: classifyException(error),
      type: "exception",
    };
  }
}

/**
 * Best-effort classifier for the `kind` field of `IException`. Pattern- matches
 * the real prefixes thrown inside this package:
 *
 * - Plugin: messages from `loadProjectPlugins.ts` / `buildSourcePlugin.ts` start
 *   with `ttsc: plugin "..."` or `ttsc: package "..." declares ...`, and
 *   transform-time spawn failures start with `ttsc.transform:` /
 *   `ttsc.transform.check:`. The Go-toolchain missing envelope also surfaces
 *   here.
 * - Host: everything else under the `ttsc:` umbrella — the bare `ttsc:` strings
 *   from `packageRootDir.ts`, `ttsc: TypeScript-Go executable not found`
 *   (`resolveTsgo.ts`), `ttsc: failed to spawn native compiler host`
 *   (`transformProjectInMemory.ts`), and tsconfig / extended-tsconfig shapes
 *   from `readProjectConfig.ts`.
 * - Anything else falls back to `"unknown"` so embedders always see the field set
 *   per the documented contract.
 *
 * Order matters: plugin patterns must run before the generic `ttsc:` test
 * because every plugin message also starts with `ttsc:`.
 */
/**
 * Classify the observed message using the existing plugin-before-host patterns.
 *
 * @evidence contracts/common.md#principled-implementation Original plugin-prefix precedence and host fallback are retained; unreadable message inspection yields unknown.
 * @evidence contracts/common.md#clear-and-simple-design One guarded message extraction precedes the two existing pattern groups.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Classification is best-effort message policy, not a certificate of exception origin or native process ownership.
 * @evidence contracts/common.md#meaningful-documentation The adjacent native paragraphs describe actual prefix shapes, ordering and unknown fallback.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation Message matching inspects no filesystem, executable or native platform capability.
 * @evidence contracts/performance.md#efficient-algorithms Message inspection can invoke existing Error property behavior; pattern work visits selected message text and extraction failures return unknown. Message size is not bounded here.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Classification coordinates no reusable operation or outcome cache.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Only the returned kind is retained by callers; this operation acquires no resource or registry.
 */
export function classifyException(
  error: unknown,
): "plugin" | "host" | "unknown" {
  let message: string;
  try {
    const description =
      error instanceof Error
        ? error.message
        : typeof error === "string"
          ? error
          : error !== null && typeof error === "object"
            ? Object.getOwnPropertyDescriptor(error, "message")?.value
            : undefined;
    message = typeof description === "string" ? description : "";
  } catch {
    return "unknown";
  }
  if (
    // Match every plugin-origin shape with verb-anchored patterns so a
    // host-path containing the literal token `plugin` (e.g.
    // `TTSC_BINARY=/opt/cache/plugins/ttsc-bin`) does not misclassify
    // as kind="plugin". Each alternative anchors at the start of the
    // message to capture the verb, not anywhere later in the line:
    //
    //   - `ttsc: plugin "..."` / `ttsc: package "..."` — from
    //     loadProjectPlugins.ts
    //   - `ttsc: building plugin "..."` / `ttsc: reading go.mod for
    //     plugin "..."` — from buildSourcePlugin.ts
    //   - `ttsc.transform:` / `ttsc.transform.check:` — from
    //     transformProjectInMemory.ts
    //   - `ttsc-plugin:` — legacy prefix kept for compatibility
    //   - `go toolchain` — the goToolchainNotFoundMessage envelope
    /^ttsc:\s*plugin\b|^ttsc:\s*package\b|^ttsc:\s*building plugin\b|^ttsc:\s*reading go\.mod for plugin\b|^ttsc\.transform[.:]|^ttsc-plugin:|go toolchain/i.test(
      message,
    )
  ) {
    return "plugin";
  }
  if (
    /^ttsc:|tsconfig|extended tsconfig|TypeScript-Go|native compiler host/i.test(
      message,
    )
  ) {
    return "host";
  }
  return "unknown";
}

/**
 * Adapt a compile producer outcome, preserving its output record reference.
 * Common: Principled implementation: Status zero without error diagnostics
 * succeeds; every other result fails and an empty diagnostic list receives the
 * original process diagnostic. Common: Clear and simple design: One
 * status/diagnostic guard constructs success or failure while preserving output
 * identity. Common: Prohibited implementation shortcuts: Warning diagnostics
 * are not converted to errors and nonzero process outcomes are not promoted to
 * success. Common: Meaningful documentation: The native sentence identifies
 * output-reference preservation rather than copied or certified output.
 * Applicability: Native platform boundary: This is result-data policy; the
 * process diagnostic owner formats already reported outcome values.
 * Performance: Computation cost: Diagnostic classification scans until an
 * error; otherwise a fixed envelope retains output/diagnostic references, with
 * delegated process-diagnostic text work on empty failures. Applicability: Work
 * reuse: No producer or previous result is reused by this adapter.
 * Applicability: Resource ownership: Output/diagnostic references transfer
 * through the return value and no independent cache or resource is acquired.
 */
function toCompilerResult(project: ProjectResult): ITtscCompilerResult {
  const { output, result } = project;
  if (result.status === 0 && !hasErrorDiagnostics(result.diagnostics)) {
    return {
      ...(result.diagnostics.length === 0
        ? {}
        : { diagnostics: result.diagnostics }),
      output,
      type: "success",
    };
  }
  return {
    diagnostics:
      result.diagnostics.length === 0
        ? [createProcessDiagnostic(result)]
        : result.diagnostics,
    output,
    type: "failure",
  };
}

/**
 * Adapt source/build outcome and copy optional advisory references only when
 * present.
 *
 * @evidence contracts/common.md#principled-implementation Undefined advisory fields are omitted; present empty/false values and references survive both success and failure, alongside the existing diagnostic decision.
 * @evidence contracts/common.md#clear-and-simple-design One optional-field projection is shared by the two result branches.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The adapter does not manufacture graph, host-read or completeness proof and does not discard it solely because the build failed.
 * @evidence contracts/common.md#meaningful-documentation The native sentence states omission policy and reference ownership.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation Advisory values are passed through without native path normalization or capability inference.
 * @evidence contracts/performance.md#efficient-algorithms Fixed optional-field checks retain references without scanning map text; diagnostic classification and empty-failure formatting have their delegated data costs.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work This adaptation coordinates no reusable compiler/worker or outcome cache.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Returned source/advisory objects remain reachable under caller ownership; this operation owns no process, lease or historical registry.
 */
export function toCompilerTransformation(
  project: ProjectTransformation,
): ITtscCompilerTransformation {
  const {
    dependencies,
    dependenciesComplete,
    graph,
    hostInputHashes,
    hostInputProofFailures,
    hostInputRealpaths,
    hostInputs,
    observationsComplete,
    pluginSources,
    result,
    sourceMaps,
    typescript,
    volatile,
  } = project;
  const advisoryFields = {
    ...(dependencies === undefined ? {} : { dependencies }),
    ...(dependenciesComplete === undefined ? {} : { dependenciesComplete }),
    ...(graph === undefined ? {} : { graph }),
    ...(hostInputHashes === undefined ? {} : { hostInputHashes }),
    ...(hostInputProofFailures === undefined ? {} : { hostInputProofFailures }),
    ...(hostInputRealpaths === undefined ? {} : { hostInputRealpaths }),
    ...(hostInputs === undefined ? {} : { hostInputs }),
    ...(observationsComplete === undefined ? {} : { observationsComplete }),
    ...(pluginSources === undefined ? {} : { pluginSources }),
    ...(sourceMaps === undefined ? {} : { sourceMaps }),
    ...(volatile === undefined ? {} : { volatile }),
  };
  if (result.status === 0 && !hasErrorDiagnostics(result.diagnostics)) {
    return {
      ...(result.diagnostics.length === 0
        ? {}
        : { diagnostics: result.diagnostics }),
      ...advisoryFields,
      type: "success",
      typescript,
    };
  }
  return {
    ...advisoryFields,
    diagnostics:
      result.diagnostics.length === 0
        ? [createProcessDiagnostic(result)]
        : result.diagnostics,
    type: "failure",
    typescript,
  };
}

/**
 * Report whether the supplied diagnostics contain an error category. Common:
 * Principled implementation: Only the literal error category changes this
 * outcome; other diagnostic categories remain advisory. Common: Clear and
 * simple design: A short-circuiting predicate expresses the existing success
 * guard directly. Common: Prohibited implementation shortcuts: Status and
 * message text are not guessed as substitutes for diagnostic category. Common:
 * Meaningful documentation: The native sentence identifies the supplied
 * diagnostic population and category decision. Applicability: Native platform
 * boundary: Category comparison accesses no native platform boundary.
 * Performance: Computation cost: The scan visits at most the supplied
 * diagnostic count and stops at the first error. Applicability: Work reuse:
 * This predicate coordinates no cached or in-flight result. Applicability:
 * Resource ownership: A boolean is returned without retaining diagnostic
 * history or acquiring a resource.
 */
function hasErrorDiagnostics(
  diagnostics: readonly ITtscCompilerDiagnostic[],
): boolean {
  return diagnostics.some((diagnostic) => diagnostic.category === "error");
}

/**
 * Serialize the actual thrown value through the existing compiler error owner.
 *
 * @evidence contracts/common.md#principled-implementation The original serializer receives the exact thrown value rather than a guessed error message.
 * @evidence contracts/common.md#clear-and-simple-design One delegation shares the compiler error representation with synchronous and worker result adapters.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Serialization does not manufacture a native exception or replace the task that threw it.
 * @evidence contracts/common.md#meaningful-documentation The native sentence names the actual value and owning serializer.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation The error representation owner inspects data rather than native platform capability.
 * @evidenceExclude contracts/performance.md#efficient-algorithms The existing serializer owns value traversal, reference tracking and encoded allocation; this adapter adds no independent serialization algorithm or size bound.
