import childProcess from "node:child_process";
import fs from "node:fs";
import path from "node:path";

import { captureProcessOutput } from "../compiler/internal/captureProcessOutput";
import { SidecarEnvironment } from "../compiler/internal/sharedHost/SidecarEnvironment";
import type { PluginContentIdentities } from "../plugin/internal/source/PluginContentIdentities";
import { PluginLoadAnswers } from "../plugin/internal/source/PluginLoadAnswers";
import { E2ETrace } from "./E2ETrace";
import type { IJavaScriptRuntimeCapabilities } from "./IJavaScriptRuntimeCapabilities";
import { OwnedSynchronousProcess } from "./OwnedSynchronousProcess";
import { isSpawnSyncFdExhaustion } from "./isSpawnSyncFdExhaustion";
import { runtimeExecutableIdentity } from "./runtimeExecutableIdentity";
import { spawnSyncWithLowDescriptors } from "./spawnSyncWithLowDescriptors";

/**
 * Probe an interpreter instead of inferring its identity from the host.
 *
 * Successful absolute candidates can be reused only while their actual bytes,
 * lexical link and physical target agree. Preloaded, relative and wrapper
 * candidates are probed anew because those inputs can select mutable behavior.
 * Cache-ineligible candidates do not acquire executable proofs used only by
 * cache lookup and publication.
 *
 * With a record store, the executable identity is proven from metadata and a
 * probe answer recorded for that identity is reused by a later process (#1723);
 * a recorded answer must still name an executable this runtime is.
 *
 * @param runtime The interpreter to probe.
 * @param env Caller environment merged over this process's.
 * @param cwd Working directory of the probe.
 * @param identities Optional record store of the caller's plugin cache.
 * @evidence contracts/common.md#principled-implementation A child reports its own feature availability and executable; byte-aware before/after identity and same-executable proof authorize reuse only for a stable absolute runtime without NODE_OPTIONS preload authority, in process or through an answer recorded under that identity.
 * @evidence contracts/common.md#clear-and-simple-design One probe owner coordinates identity, spawning and parsing; the shared fingerprint helper owns file-content proof and the low-descriptor helper owns the POSIX launch distinction.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Feature availability comes from the actual interpreter rather than its name; descriptor fallback handles a supported kernel constraint and failures produce unsupported capabilities, not fabricated success.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain measured capabilities, reuse restrictions and freshness, with comments separating platform launch and cache permission from tags.
 * @evidence contracts/portability.md#os-neutral-implementation Shared environment merge and lookup apply native name identity to caller precedence and NODE_OPTIONS preload authority, including Windows aliases; Node spawn receives an executable and argv without shell syntax, and only POSIX descriptor exhaustion uses the isolated broker.
 * @evidence contracts/performance.md#efficient-algorithms Environment merge/name handling first decides cache eligibility. Eligible hits prove the executable from a record (three stats and one small read) or read B executable bytes; eligible misses acquire before/after identities around the actual probe. Ineligible calls retain the fresh child without reading executable bytes solely for the forbidden cache. Probe spawning/parsing, a possible descriptor-exhaustion retry and capture-file reads add text/environment/native lookup costs and transient output storage; this adapter sets no explicit byte quota.
 * @evidence contracts/performance.md#reuse-equivalent-work Stable absolute candidates that report their own executable share measured capability results, including false feature flags, within the process and across processes through the record store keyed by the full identity; changed executable bytes, link/target identity, preload options or wrapper identity require another probe, while failed probes without executable identity are not reused.
 * @evidence contracts/performance.md#bound-retention-and-release-resources The synchronous probe owns child completion and fallback captures; finally attempts capture close/removal, whose helper suppresses cleanup failures, so native/file release is unconfirmed on failure. Capability entries retain absolute spellings and path/identity text with no eviction quota; failed identity validation can remove an entry. Returned capability copies transfer to callers.
 */
export function javascriptRuntimeCapabilities(
  runtime: string,
  env: NodeJS.ProcessEnv,
  cwd: string,
  identities?: PluginContentIdentities.Store,
): IJavaScriptRuntimeCapabilities {
  const effectiveEnv = SidecarEnvironment.merge(process.env, env);
  const cacheKey = runtimeCapabilityCacheKey(runtime, effectiveEnv);
  const beforeIdentity =
    cacheKey === undefined
      ? undefined
      : runtimeExecutableIdentity(runtime, identities);
  if (cacheKey !== undefined && beforeIdentity !== undefined) {
    const cached = runtimeCapabilityCache.get(cacheKey);
    if (cached?.identity === beforeIdentity) return { ...cached.capabilities };
    runtimeCapabilityCache.delete(cacheKey);
    // WARNING (#1723): a launch is a new process, so the memo above is empty
    // on every CLI run. The same proven executable answers the same probe; the
    // record store carries that answer across processes.
    const recorded = recordedCapabilities(
      PluginLoadAnswers.read(identities, RUNTIME_CAPABILITIES, [
        cacheKey,
        beforeIdentity,
      ]),
      runtime,
    );
    if (recorded !== undefined) {
      runtimeCapabilityCache.set(cacheKey, {
        capabilities: { ...recorded },
        identity: beforeIdentity,
      });
      return recorded;
    }
  }
  const args = [
    "-e",
    `const Module = require("node:module"); process.stdout.write(JSON.stringify({ bun: typeof globalThis.Bun === "object", executable: process.execPath, registerHooks: typeof Module.registerHooks === "function" }));`,
  ];
  const options = {
    cwd,
    encoding: "utf8" as const,
    env: effectiveEnv,
    timeout: 30_000,
    windowsHide: true,
  };
  let result = E2ETrace.synchronous(
    runtime,
    args,
    options,
    "runtime-capability-probe",
    () =>
      OwnedSynchronousProcess.launch<string>(runtime, args, options) ??
      childProcess.spawnSync(runtime, args, options),
  );
  if (process.platform !== "win32" && isSpawnSyncFdExhaustion(result.error)) {
    const capture = captureProcessOutput();
    try {
      const retried = spawnSyncWithLowDescriptors(runtime, args, options, {
        stderr: capture.stderrPath,
        stdout: capture.stdoutPath,
      });
      const stdout = capture.read("stdout", "utf8") as string;
      const stderr = capture.read("stderr", "utf8") as string;
      result = {
        ...retried,
        output: [null, stdout, stderr],
        stderr,
        stdout,
      };
    } finally {
      capture.dispose();
    }
  }
  let capabilities: IJavaScriptRuntimeCapabilities = {
    bun: false,
    registerHooks: false,
  };
  if (result.status === 0) {
    try {
      const parsed = JSON.parse(
        result.stdout,
      ) as Partial<IJavaScriptRuntimeCapabilities>;
      capabilities = {
        bun: parsed.bun === true,
        ...(typeof parsed.executable === "string" &&
        path.isAbsolute(parsed.executable)
          ? { executable: path.resolve(parsed.executable) }
          : {}),
        registerHooks: parsed.registerHooks === true,
      };
    } catch {
      // An incompatible executable is not a Node runtime candidate.
    }
  }
  // Cache successful absolute candidates only when the child reports that same
  // executable and both its lexical link and physical target retain the same
  // filesystem and actual content identity. Relative/bare commands and wrappers can resolve
  // differently by cwd/PATH/environment, failed probes without an executable
  // identity can become valid later, and NODE_OPTIONS can load mutable user
  // code, so none of those states are memoized. A successful probe can report
  // false for either feature and still be reused under the executable proof.
  // This removes a process spawn from the common path without
  // authorizing a replaced or redirected runtime in a long-lived host.
  const afterIdentity =
    cacheKey === undefined
      ? undefined
      : runtimeExecutableIdentity(runtime, identities);
  if (
    cacheKey !== undefined &&
    capabilities.executable !== undefined &&
    beforeIdentity !== undefined &&
    beforeIdentity === afterIdentity &&
    sameRuntimeExecutable(runtime, capabilities.executable)
  ) {
    runtimeCapabilityCache.set(cacheKey, {
      capabilities: { ...capabilities },
      identity: afterIdentity,
    });
    PluginLoadAnswers.write(
      identities,
      RUNTIME_CAPABILITIES,
      [cacheKey, afterIdentity],
      capabilities,
    );
  }
  return capabilities;
}

/** Answer family of measured runtime capabilities (`PluginLoadAnswers`). */
const RUNTIME_CAPABILITIES = "javascript-runtime-capabilities";

/**
 * A recorded probe answer in the shape the probe produces, still naming an
 * executable this runtime is, or `undefined`.
 */
function recordedCapabilities(
  value: unknown,
  runtime: string,
): IJavaScriptRuntimeCapabilities | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const recorded = value as Partial<IJavaScriptRuntimeCapabilities>;
  if (
    typeof recorded.bun !== "boolean" ||
    typeof recorded.registerHooks !== "boolean" ||
    typeof recorded.executable !== "string" ||
    !path.isAbsolute(recorded.executable) ||
    !sameRuntimeExecutable(runtime, recorded.executable)
  )
    return undefined;
  return {
    bun: recorded.bun,
    executable: recorded.executable,
    registerHooks: recorded.registerHooks,
  };
}

type RuntimeCapabilityCacheEntry = {
  capabilities: IJavaScriptRuntimeCapabilities;
  identity: string;
};

const runtimeCapabilityCache = new Map<string, RuntimeCapabilityCacheEntry>();

/** True when a probe ran the candidate itself rather than a mutable wrapper. */
function sameRuntimeExecutable(candidate: string, executable: string): boolean {
  try {
    const candidateStats = fs.statSync(candidate, { bigint: true });
    const executableStats = fs.statSync(executable, { bigint: true });
    return (
      (candidateStats.ino !== 0n &&
        candidateStats.dev === executableStats.dev &&
        candidateStats.ino === executableStats.ino) ||
      fs.realpathSync.native(candidate) === fs.realpathSync.native(executable)
    );
  } catch {
    return false;
  }
}

/** Stable cache key only for an absolute runtime with no preload authority. */
function runtimeCapabilityCacheKey(
  runtime: string,
  env: NodeJS.ProcessEnv,
): string | undefined {
  if (
    !path.isAbsolute(runtime) ||
    SidecarEnvironment.read(env, "NODE_OPTIONS")?.trim()
  )
    return undefined;
  return path.resolve(runtime);
}

ttsc/src/internal/OwnedNativeProcess.ts:
import {
  type SpawnSyncOptions,
  type SpawnSyncReturns,
  spawn,
} from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { resolveBinary } from "../compiler/internal/resolveBinary";

/**
 * Execute one command under the platform helper's process-tree owner.
 * Cancellation closes the control pipe; completion is accepted only after the
 * helper's joined child and empty-boundary receipt, never merely its exit
 * code.
 *
 * @evidence contracts/common.md#principled-implementation Exact command arguments and environment are sent to the selected native owner; its structurally checked completion receipt supplies tree-shutdown authority before callers release build resources. A missing or invalid proof retains private protocol storage and reports unknown retirement.
 * @evidence contracts/common.md#clear-and-simple-design Node owns asynchronous streams and cancellation while the native helper owns OS containment and wait semantics.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Unsupported helper versions and missing cleanup receipts reject; no ordinary uncontained spawn substitutes for cancellation safety.
 * @evidence contracts/common.md#meaningful-documentation Native prose states the pipe and receipt ownership and the absence of a process-exit-only success path.
 * @evidence contracts/portability.md#os-neutral-implementation The published platform helper resolver selects the executable; exact JSON argv/env avoid a new shell quoting layer, including explicit Windows verbatim command lines.
 * @evidence contracts/performance.md#efficient-algorithms Output accumulation follows the caller's spawn buffer policy, while file-backed descriptor outputs remain streaming. Encoding and receipt serialization scale with actual payload bytes.
 * @evidence contracts/performance.md#reuse-equivalent-work Each command has its own containment lifetime and cannot share a result based on matching arguments.
 * @evidence contracts/performance.md#bound-retention-and-release-resources The completion owner waits for helper close and its tree receipt before removing private protocol storage; stream and abort listeners are removed on settlement. Unknown retirement retains the exact reported private path and rejects; qualified closure or external closure verification is required before reclaiming it.
 */
export namespace OwnedNativeProcess {
  /**
   * Run a command with Node's synchronous-result shape after real async
   * joining. Explicit input bytes and standard output descriptors are
   * supported. Shell, uid/gid, inherited stdin and additional descriptor modes
   * are refused. Cancellation and timeout force termination of the owned native
   * boundary; a custom softer kill signal is therefore refused. TTSC_BINARY
   * retains its helper authority, so an override must implement this protocol
   * version. The optional internal observer receives the actual retirement
   * class even when cancellation or a compiler error rejects the operation.
   * Unknown retirement preserves protocol inputs and does not certify child
   * closure. Rejected receipts retain native lifetime fields as diagnostic
   * causes. Output fields and extra receipt fields are omitted. Diagnostic data
   * never authorizes release.
   *
   * Enabled private tracing may receive a frozen scalar copy of an accepted
   * receipt through the existing retirement observer. The original helper has
   * closed before that copy is made. It contains no command or environment
   * data and cannot grant closure authority. Trace IO can change scheduling.
   *
   * @evidence contracts/common.md#principled-implementation A private request carries exact command/options and a structurally checked native receipt is required after helper close; cancellation returns only after joined and empty-boundary proof.
   * @evidence contracts/common.md#clear-and-simple-design Control stdin is separate from target input, target output streams remain unchanged, and one finally owns listeners and private protocol storage.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Unsupported modes and incompatible helper overrides reject explicitly rather than falling back to an uncontained child or asserting cleanup from helper exit alone.
   * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain supported descriptor/input modes, forced retirement, helper override compatibility and the opt-in frozen receipt observation's scheduling and authority limits; the namespace describes the native ownership split.
   * @evidence contracts/portability.md#os-neutral-implementation The existing native helper resolver owns platform and override precedence; JSON argv/env and explicit Windows verbatim mode preserve the actual command boundary without an added shell layer.
   * @evidence contracts/performance.md#efficient-algorithms Piped output is accumulated up to maxBuffer per stream and file-backed outputs stream through inherited descriptors. Input encoding processes only the supplied view bytes; protocol serialization and receipts scale with their payloads. Enabled tracing with an observer alone copies and freezes nine validated scalar fields without traversing arbitrary receipt payloads.
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Commands can produce external effects and every admitted invocation has its own process boundary and result.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Abort closes the control pipe, then helper close and its native retirement receipt are awaited before private storage is removed. Missing or failed cleanup proof rejects and retains the exact protocol path; a classified failed spawn removes unused storage. The observer transfers classification to the source-resource owner rather than manufacturing a joined result from helper exit; its optional frozen receipt copy lives with this invocation and may transfer to the caller without retaining streams or mutable receipt data.
   */
  export async function run(
    command: string,
    args: readonly string[],
    options: SpawnSyncOptions,
    signal?: AbortSignal,
    observeRetirement?: (
      state: "joined" | "not-started" | "unknown",
      reason?: string,
      observation?: Readonly<{
        /** Original supervising child's PID, retained after its close. */
        helperPid: number | undefined;

        /** Target PID reported by the accepted native receipt. */
        targetPid: number;

        /** Accepted private protocol version. */
        version: number;

        /** Native target completion code, when supplied. */
        status: number | null;

        /** Native target completion signal, when supplied. */
        signal: string | null;

        /** Actual native cancellation classification. */
        cancelled: boolean;

        /** Accepted original-child join field. */
        directChildJoined: boolean;

        /** Accepted native containment-emptiness field. */
        boundaryEmpty: boolean;

        /** Accepted platform reaping mechanism. */
        orphanReaping: string;
      }>,
    ) => void,
  ): Promise<SpawnSyncReturns<string | Buffer>> {
    signal?.throwIfAborted();
    if (options.shell || options.uid !== undefined || options.gid !== undefined)
      throw new Error(
        "ttsc: owned native commands do not support shell, uid or gid overrides",
      );
    if (
      options.killSignal !== undefined &&
      options.killSignal !== "SIGKILL" &&
      options.killSignal !== 9
    )
      throw new Error(
        "ttsc: owned native commands require forced process-tree termination",
      );
    const inputMode = Array.isArray(options.stdio)
      ? options.stdio[0]
      : options.stdio;
    if (
      inputMode === "inherit" ||
      typeof inputMode === "number" ||
      (Array.isArray(options.stdio) && options.stdio.length > 3)
    )
      throw new Error(
        "ttsc: owned native commands require explicit input bytes and standard output descriptors",
      );
    const binary = resolveBinary({ env: options.env });
    if (binary === null)
      throw new Error("ttsc: native process supervisor is unavailable");
    // Convert all potentially throwing caller data before acquiring a process
    // or protocol directory. An invalid encoding must not strand a helper.
    const input = options.input;
    const bytes =
      input === undefined
        ? undefined
        : typeof input === "string"
          ? Buffer.from(
              input,
              options.encoding && options.encoding !== "buffer"
                ? options.encoding
                : "utf8",
            )
          : Buffer.from(
              new Uint8Array(input.buffer, input.byteOffset, input.byteLength),
            );
    const env = Object.fromEntries(
      Object.entries(options.env ?? process.env).filter(
        (entry): entry is [string, string] => entry[1] !== undefined,
      ),
    );
    const payload = `${JSON.stringify({
      version: 1,
      command,
      args: [...args],
      cwd: path.resolve(
        options.cwd === undefined
          ? process.cwd()
          : typeof options.cwd === "string"
            ? options.cwd
            : fileURLToPath(options.cwd),
      ),
      env,
      ...(bytes === undefined ? {} : { inputBase64: bytes.toString("base64") }),
      windowsVerbatimArguments: options.windowsVerbatimArguments === true,
      ...(options.argv0 === undefined ? {} : { argv0: options.argv0 }),
      ...(options.timeout === undefined ? {} : { timeoutMs: options.timeout }),
    })}\n`;
    const directory = fs.mkdtempSync(
      path.join(os.tmpdir(), "ttsc-owned-process-"),
    );
    const resultFile = path.join(directory, "result.json");
    let retirement: "joined" | "not-started" | "unknown" = "not-started";
    let observation: Parameters<NonNullable<typeof observeRetirement>>[2];
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    const limit = options.maxBuffer ?? 1024 * 1024;
    let overflow: Error | undefined;
    let stdoutBytes = 0;
    let stderrBytes = 0;
    const stdio = options.stdio;
    const output = (index: 1 | 2) =>
      Array.isArray(stdio)
        ? (stdio[index] ?? "pipe")
        : stdio === "inherit" || stdio === "ignore"
          ? stdio
          : "pipe";
    const child = (() => {
      try {
        return spawn(binary, ["__source-process", "--result", resultFile], {
          cwd: options.cwd,
          env: options.env ?? process.env,
          windowsHide: true,
          stdio: ["pipe", output(1), output(2)],
        });
      } catch (error) {
        fs.rmSync(directory, { recursive: true, force: true });
        throw error;
      }
    })();
    retirement = "unknown";
    const cancel = () => child.stdin?.end();
    child.stdin?.on("error", () => undefined);
    const collect = (channel: "stdout" | "stderr", chunk: Buffer) => {
      const count =
        channel === "stdout"
          ? (stdoutBytes += chunk.length)
          : (stderrBytes += chunk.length);
      if (count <= limit) (channel === "stdout" ? stdout : stderr).push(chunk);
      else if (overflow === undefined) {
        overflow = Object.assign(
          new Error("ttsc: owned command output exceeded maxBuffer"),
          { code: "ENOBUFS" },
        );
        cancel();
      }
    };
    child.stdout?.on("data", (chunk: Buffer) => collect("stdout", chunk));
    child.stderr?.on("data", (chunk: Buffer) => collect("stderr", chunk));
    signal?.addEventListener("abort", cancel, { once: true });
    let spawnError: Error | undefined;
    const closed = new Promise<void>((resolve) => {
      child.on("error", (error) => {
        spawnError = error;
      });
      child.once("close", () => resolve());
    });
    // An abort after listener installation must not authorize target admission.
    if (signal?.aborted) cancel();
    else {
      child.stdin?.write(payload);
    }
    let originalFailure: unknown;
    let failed = false;
    try {
      await closed;
      if (spawnError !== undefined) {
        // Node's failed spawn has no process owner or admitted target.
        if (child.pid === undefined) retirement = "not-started";
        throw spawnError;
      }
      let receipt: Receipt;
      try {
        receipt = JSON.parse(fs.readFileSync(resultFile, "utf8")) as Receipt;
      } catch (cause) {
        throw new Error(
          "ttsc: native supervisor did not publish a completion receipt",
          { cause },
        );
      }
      if (
        receipt === null ||
        typeof receipt !== "object" ||
        receipt.version !== 1 ||
        !Number.isSafeInteger(receipt.pid) ||
        receipt.pid < 0 ||
        (receipt.status !== null &&
          (!Number.isSafeInteger(receipt.status) || receipt.pid === 0)) ||
        (receipt.signal !== null &&
          (typeof receipt.signal !== "string" ||
            receipt.signal.length === 0)) ||
        typeof receipt.cancelled !== "boolean" ||
        (receipt.error !== undefined &&
          (typeof receipt.error?.code !== "string" ||
            typeof receipt.error?.message !== "string")) ||
        receipt.cleanup?.directChildJoined !== true ||
        receipt.cleanup?.boundaryEmpty !== true ||
        !["owned", "os", "windows-job"].includes(receipt.cleanup.orphanReaping)
      ) {
        // The parsed receipt is untrusted diagnostic data, not closure proof.
        // Project only lifetime fields and never traverse nested payloads.
        const scalar = (value: unknown) =>
          value !== null && typeof value === "object"
            ? { $ttscValue: Array.isArray(value) ? "array" : "object" }
            : value;
        const diagnostic =
          receipt === null ||
          typeof receipt !== "object" ||
          Array.isArray(receipt)
            ? scalar(receipt)
            : {
                version: scalar(receipt.version),
                pid: scalar(receipt.pid),
                status: scalar(receipt.status),
                signal: scalar(receipt.signal),
                cancelled: scalar(receipt.cancelled),
                ...(receipt.error === undefined
                  ? {}
                  : {
                      error:
                        receipt.error !== null &&
                        typeof receipt.error === "object" &&
                        !Array.isArray(receipt.error)
                          ? {
                              code: scalar(receipt.error.code),
                              message: scalar(receipt.error.message),
                            }
                          : scalar(receipt.error),
                    }),
                ...(receipt.cleanup === undefined
                  ? {}
                  : {
                      cleanup:
                        receipt.cleanup !== null &&
                        typeof receipt.cleanup === "object" &&
                        !Array.isArray(receipt.cleanup)
                          ? {
                              directChildJoined: scalar(
                                receipt.cleanup.directChildJoined,
                              ),
                              boundaryEmpty: scalar(
                                receipt.cleanup.boundaryEmpty,
                              ),
                              orphanReaping: scalar(
                                receipt.cleanup.orphanReaping,
                              ),
                            }
                          : scalar(receipt.cleanup),
                    }),
              };
        throw new Error(
          "ttsc: native supervisor did not confirm process-tree retirement",
          { cause: diagnostic },
        );
      }
      retirement = "joined";
      if (observeRetirement !== undefined && process.env.TTSC_E2E_TRACE) {
        // Only already-validated scalar receipt fields cross this private
        // observation boundary. Its allocation cannot replace an outcome.
        try {
          observation = Object.freeze({
            helperPid: child.pid,
            targetPid: receipt.pid,
            version: receipt.version,
            status: receipt.status,
            signal: receipt.signal,
            cancelled: receipt.cancelled,
            directChildJoined: receipt.cleanup.directChildJoined,
            boundaryEmpty: receipt.cleanup.boundaryEmpty,
            orphanReaping: receipt.cleanup.orphanReaping,
          });
        } catch {
          // Missing diagnostics do not change native closure authority.
        }
      }
      signal?.throwIfAborted();
      const encoding = options.encoding;
      const decode = (chunks: Buffer[]) => {
        const bytes = Buffer.concat(chunks);
        return encoding && encoding !== "buffer"
          ? bytes.toString(encoding)
          : bytes;
      };
      const out = child.stdout === null ? null : decode(stdout);
      const err = child.stderr === null ? null : decode(stderr);
      const failure =
        overflow ??
        (receipt.error === undefined
          ? undefined
          : Object.assign(new Error(receipt.error.message), {
              code: receipt.error.code,
            }));
      return {
        pid: receipt.pid,
        status: receipt.status,
        signal: receipt.signal as NodeJS.Signals | null,
        output: [null, out, err],
        stdout: out as string | Buffer,
        stderr: err as string | Buffer,
        ...(failure === undefined ? {} : { error: failure }),
      };
    } catch (error) {
      failed = true;
      originalFailure = error;
      throw error;
    } finally {
      signal?.removeEventListener("abort", cancel);
      child.stdin?.destroy();
      if (observation === undefined)
        observeRetirement?.(
          retirement,
          failed ? String(originalFailure) : undefined,
        );
      else
        observeRetirement?.(
          retirement,
          failed ? String(originalFailure) : undefined,
          observation,
        );
      // A failed proof does not authorize deleting a native reader's protocol
      // inputs. The exact retained path is part of the terminal diagnostic.
      if (retirement === "unknown") {
        throw new Error(
          `ttsc: native retirement is unknown; retained protocol ${directory}`,
          {
            cause: originalFailure,
          },
        );
      }
      try {
        fs.rmSync(directory, { recursive: true, force: true });
      } catch (error) {
        throw failed
          ? new AggregateError(
              [originalFailure, error],
              "ttsc: native protocol cleanup failed",
            )
          : error;
      }
    }
  }
}

interface Receipt {
  version: number;
  pid: number;
  status: number | null;
  signal: string | null;
  error?: { code: string; message: string };
  cancelled: boolean;
  cleanup?: {
    directChildJoined: boolean;
    boundaryEmpty: boolean;
    orphanReaping: string;
  };
}

