import fs from "node:fs";
import path from "node:path";

import type { SafeCacheCleanupTarget } from "./SafeCacheCleanupTarget";
import { SourceNativeRetirement } from "./SourceNativeRetirement";
import { type FilesystemPathIdentityOperations } from "./pathIdentity/FilesystemPathIdentityOperations";
import { createFilesystemPathIdentityContext } from "./pathIdentity/createFilesystemPathIdentityContext";
import { resolveFilesystemPath } from "./pathIdentity/resolveFilesystemPath";

/**
 * Resolve one cache-clean transaction to physical deletion targets.
 *
 * Every target is checked before the caller removes the first one. Existing
 * aliases are pinned to their physical spelling, while a missing suffix keeps
 * the identity of its nearest existing parent. Identity errors other than a
 * genuinely missing path fail closed.
 *
 * Candidates overlapping protected directories are omitted from deletion. This
 * preserves caller-owned caches even when another cleanup selector names their
 * ancestor or descendant; uncertain case or Unicode overlap also preserves a
 * candidate instead of authorizing deletion.
 *
 * Native-retirement guards in selected trees or their enclosing resource roots
 * refuse the entire transaction before deletion. Terminal links retain their
 * unlink-only semantics and do not traverse a guarded destination.
 *
 * The plan contains observed path spellings, not held directory handles or an
 * atomic namespace snapshot. Pinning an ancestor alias does not prevent later
 * replacement of the selected physical parent or terminal entry; callers must
 * preserve that ownership boundary while using the returned plan.
 *
 * @evidence contracts/common.md#principled-implementation Every requested target is physically pinned and validated before return; roots and project-containing directories fail closed, while bidirectional overlap preserves caller-protected directories and unrelated candidates remain eligible.
 * @evidence contracts/common.md#clear-and-simple-design One transaction owns identity proof, terminal-link deletion semantics and protected overlap policy for API and CLI consumers; deletion itself remains with the caller after all candidates are resolved.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Protection follows native identities rather than special cache names; aliases are resolved through supported primitives and unexpected identity errors cannot authorize deletion.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain validation-before-deletion, failure behavior and protected preservation; inline comments describe why ancestors are pinned and terminal links remain links.
 * @evidence contracts/portability.md#os-neutral-implementation The shared native resolver handles physical aliases, volume roots and actual directory case policy; Node lstat identifies terminal links, while unknown missing suffix policy preserves spellings rather than asserting case-variant identity.
 * @evidence contracts/performance.md#efficient-algorithms Resolving the project, P protected paths and C candidates requires path/ancestor observations independently of the overlap loop. Candidate/project checks and at most two comparisons per protected path add O(C(P+1)D) component comparisons for depth D, plus path text and delegated native realpath/stat/case-probe work; selected directory trees are scanned for native guards before the transaction returns; case probes can scan observed directory entries. Context memoization shares equivalent observations within this call; no cross-run index is built for this cleanup set.
 * @evidence contracts/performance.md#reuse-equivalent-work All candidate and protected paths share one identity context, so equivalent ancestor realpath and case queries reuse the same transaction observations; deletion results themselves are not cached across mutable filesystem states.
 * @evidence contracts/performance.md#bound-retention-and-release-resources Context maps retain observed identities, ancestors and case facts for this call, growing with distinct queried paths/ancestors and their text; protected identities use O(P) references and returned targets at most O(C). No directory handle is held; the context becomes reclaimable after return, while the caller owns retained plan strings and later deletion under a preserved namespace boundary.
 */
export function resolveSafeCacheCleanupTargets(
  projectRoot: string,
  cacheDirectories: readonly string[],
  operations: Partial<FilesystemPathIdentityOperations> = {},
  protectedDirectories: readonly string[] = [],
): SafeCacheCleanupTarget[] {
  const identities = createFilesystemPathIdentityContext(operations);
  const lstat = operations.lstat ?? fs.lstatSync;
  const project = identities.resolve(projectRoot);
  const protectedIdentities = protectedDirectories.map((directory) =>
    identities.resolve(directory),
  );
  const targets: SafeCacheCleanupTarget[] = [];
  for (const cacheDirectory of cacheDirectories) {
    const requestedCache = resolveFilesystemPath(cacheDirectory);
    // Fix every mutable alias ancestor before inspecting the terminal entry.
    // All later identity checks and deletion paths use this physical-parent
    // candidate rather than following the original lexical ancestor again.
    // No held handle prevents replacement of that physical namespace itself.
    const pinnedCache = path.join(
      identities.resolve(path.dirname(requestedCache)).path,
      path.basename(requestedCache),
    );
    const cache = identities.resolve(pinnedCache);
    if (
      requestedCache === path.parse(requestedCache).root ||
      cache.path === path.parse(cache.path).root
    ) {
      throw new Error(
        `ttsc: refusing to clean cache directory ${JSON.stringify(requestedCache)} because filesystem roots are never valid cache directories`,
      );
    }
    if (identities.lexicalIsWithin(cache.path, project.path)) {
      throw new Error(
        `ttsc: refusing to clean cache directory ${JSON.stringify(requestedCache)} because it equals or contains project root ${JSON.stringify(project.path)}; choose a dedicated cache directory`,
      );
    }
    if (
      protectedIdentities.some(
        (protectedDirectory) =>
          identities.lexicalIsWithin(protectedDirectory.path, cache.path) ||
          identities.lexicalIsWithin(cache.path, protectedDirectory.path),
      )
    )
      continue;
    const status = lstatIfPresent(pinnedCache, lstat);
    // Recursive rm removes a terminal symlink or junction itself rather than
    // following it. Preserve that behavior while pinning any mutable alias in
    // its ancestors to the physical parent selected by this transaction.
    const deletionPath = status?.isSymbolicLink() ? pinnedCache : cache.path;
    SourceNativeRetirement.assertCleanable(deletionPath);
    targets.push({
      exists: status !== undefined,
      path: deletionPath,
      requestedPath: requestedCache,
    });
  }
  return targets;
}

function lstatIfPresent(
  location: string,
  lstat: NonNullable<FilesystemPathIdentityOperations["lstat"]>,
): fs.Stats | fs.BigIntStats | undefined {
  try {
    return lstat(location);
  } catch (error) {
    if (
      error instanceof Error &&
      "code" in error &&
      (error.code === "ENOENT" || error.code === "ENOTDIR")
    ) {
      return undefined;
    }
    throw error;
  }
}

ttsc/src/internal/restoreCompilerError.t:
/**
 * Restore compiler-error transport while retaining shared and circular data.
 *
 * The serializer supplies a finite data graph with JSON-pointer reference
 * markers. All nodes are allocated before their fields are connected, so
 * forward references and circular causes require no recursive restoration.
 * Literal-object envelopes distinguish source metadata from generated markers;
 * their bodies remain data even when they have a marker's exact field shape.
 * Tagged exceptional values and accessor descriptions remain descriptions; this
 * receiver does not execute accessors or manufacture their values.
 *
 * @evidence contracts/common.md#principled-implementation Allocating the serialized graph before linking its fields preserves shared causes and aggregate members instead of turning reference markers into unrelated errors. Exact marker shapes and identified literal bodies keep user metadata distinct from generated references. The root and Error-shaped causes or aggregate members acquire Error prototypes; ordinary outcome objects retain their data representation.
 * @evidence contracts/common.md#clear-and-simple-design One iterative discovery, allocation and linking sequence shares a source-node map and the serializer's pointer spellings.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Actual reference targets supply error data; messages do not guess ownership or replace unresolved native outcomes. Exceptional-value and accessor tags remain explicit diagnostic data.
 * @evidence contracts/common.md#meaningful-documentation Native prose explains finite serialized inputs, forward/circular references and preserved tagged descriptions.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation Restoration handles structured data only and performs no native filesystem or process operation.
 * @evidence contracts/performance.md#efficient-algorithms Iterative discovery and field linking visit serialized nodes and fields once, with pointer text and property data contributing their actual bytes. The explicit worklist avoids call-stack growth on nested aggregates and cycles.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A source-node map preserves identities within this one received graph; it shares no failure or compiler result across requests.
 * @evidence contracts/performance.md#bound-retention-and-release-resources Maps and worklists belong to this invocation; the caller owns the returned error graph and its shared or circular references. No global error history or native resource is retained.
 */
export function restoreCompilerError(value: unknown): Error {
  if (value === null || typeof value !== "object")
    return new Error(String(value));
  const paths = new Map<string, object>();
  const fields = new Map<object, Record<string, PropertyDescriptor>>();
  const literals = new Map<object, object>();
  const literalBodies = new Set<object>();
  const references = new Map<object, string>();
  const pending = [{ input: value, pointer: "" }];
  while (pending.length !== 0) {
    const { input, pointer } = pending.pop()!;
    paths.set(pointer, input);
    if (fields.has(input)) continue;
    const properties = Object.getOwnPropertyDescriptors(input);
    fields.set(input, properties);
    const body = properties.$ttscProperties?.value;
    const keys = Object.keys(properties);
    if (
      !literalBodies.has(input) &&
      !Array.isArray(input) &&
      keys.length === 2 &&
      properties.$ttscValue?.value === "object" &&
      body !== null &&
      typeof body === "object" &&
      !Array.isArray(body)
    ) {
      literals.set(input, body);
      literalBodies.add(body);
    }
    if (
      !literalBodies.has(input) &&
      !Array.isArray(input) &&
      keys.length === 1 &&
      typeof properties.$ttscReference?.value === "string"
    )
      references.set(input, properties.$ttscReference.value);
    for (const [name, property] of Object.entries(properties)) {
      if (
        !("value" in property) ||
        property.value === null ||
        typeof property.value !== "object"
      )
        continue;
      pending.push({
        input: property.value,
        pointer: `${pointer}/${name.replaceAll("~", "~0").replaceAll("/", "~1")}`,
      });
    }
  }
  const target = (input: object): object => {
    const literal = literals.get(input);
    if (literal !== undefined) return literal;
    if (literalBodies.has(input) || Array.isArray(input)) return input;
    const reference = references.get(input);
    if (reference === undefined) return input;
    const referenced = paths.get(reference);
    return referenced === undefined
      ? input
      : (literals.get(referenced) ?? referenced);
  };
  const errors = new Set<object>();
  const aggregateArrays = new Set<object>();
  const errorNodes = [target(value)];
  while (errorNodes.length !== 0) {
    const error = errorNodes.pop()!;
    if (errors.has(error)) continue;
    errors.add(error);
    const properties = fields.get(error)!;
    const aggregate = properties.errors?.value;
    const members =
      aggregate !== null && typeof aggregate === "object"
        ? target(aggregate)
        : aggregate;
    if (Array.isArray(members) && !aggregateArrays.has(members)) {
      aggregateArrays.add(members);
      for (const [name, descriptor] of Object.entries(fields.get(members)!)) {
        // Array members are canonical indices, not holes or custom metadata.
        const index = Number(name);
        if (
          !Number.isInteger(index) ||
          index < 0 ||
          index >= 0xffffffff ||
          String(index) !== name ||
          !("value" in descriptor)
        )
          continue;
        const member = descriptor.value;
        if (member === null || typeof member !== "object") continue;
        const candidate = target(member);
        const candidateFields = fields.get(candidate);
        if (
          typeof candidateFields?.name?.value === "string" &&
          typeof candidateFields?.message?.value === "string"
        )
          errorNodes.push(candidate);
      }
    }
    const cause = properties.cause;
    if (
      cause &&
      "value" in cause &&
      cause.value !== null &&
      typeof cause.value === "object"
    ) {
      const candidate = target(cause.value);
      const candidateFields = fields.get(candidate);
      if (
        typeof candidateFields?.name?.value === "string" &&
        typeof candidateFields?.message?.value === "string"
      )
        errorNodes.push(candidate);
    }
  }
  const restored = new Map<object, object>();
  for (const [input, properties] of fields) {
    if (target(input) !== input) continue;
    const aggregate = properties.errors?.value;
    const members =
      aggregate !== null && typeof aggregate === "object"
        ? target(aggregate)
        : aggregate;
    restored.set(
      input,
      errors.has(input)
        ? Array.isArray(members)
          ? new AggregateError([], properties.message?.value)
          : new Error(properties.message?.value ?? String(input))
        : Array.isArray(input)
          ? new Array(properties.length?.value)
          : {},
    );
  }
  for (const [input, properties] of fields) {
    if (target(input) !== input) continue;
    const output = restored.get(input)!;
    for (const [name, property] of Object.entries(properties)) {
      if (Array.isArray(output) && name === "length") continue;
      const item = "value" in property ? property.value : undefined;
      Object.defineProperty(
        output,
        name,
        "value" in property
          ? {
              ...property,
              value:
                item !== null && typeof item === "object"
                  ? restored.get(target(item))
                  : item,
            }
          : property,
      );
    }
  }
  return restored.get(target(value)) as Error;
}

ttsc/src/internal/retireLockDirectory.ts:
import crypto from "node:crypto";
import fs from "node:fs";

import { OwnedSynchronousProcess } from "./OwnedSynchronousProcess";
import type { RetireLockDirectoryOperations } from "./RetireLockDirectoryOperations";

/**
 * Free a held lock generation by renaming its directory onto its tombstone, the
 * one operation both build-lock protocols retire a generation with.
 *
 * Windows access or busy refusals can occur while peers read the holder's
 * record inside the held generation. The error alone does not identify the
 * cause or duration. The policy samples a newly created empty sibling rename
 * between the same parents rather than using a time window. A successful probe
 * establishes that this sampled sibling move succeeded. Under the protocol's
 * caller-owned generation premise this permits a retry after `yieldToPeers`. It
 * does not prove that source-specific permissions or attributes allow the held
 * directory to move. Ordinary work has no retry deadline. Once scoped
 * cancellation is observed, cleanup permits one second of further contention:
 * this leaves the request owner's shutdown budget for other releases while
 * allowing transient readers to yield. Expiry reports the last real refusal as
 * the cause of cleanup failure, never successful retirement. An opted-in owner
 * also receives that failure through its scope when a legacy caller catches the
 * thrown exception. Native calls and the caller's yield can exceed that
 * between-attempt grace. When the probe is refused too, the original retirement
 * refusal is thrown; the probe failure does not prove a particular permission
 * or sharing cause.
 *
 * @param source The held generation's directory.
 * @param destination Its tombstone, which a successor's retire can never reuse.
 * @param yieldToPeers Waits once, by the protocol's own polling interval.
 * @param operations Filesystem and platform primitives; the real filesystem and
 *   `process.platform` by default, injectable so the Windows-only probe
 *   branches can be exercised on any host.
 * @returns `true` when the generation was retired; `false` when `source` is
 *   reported missing or `destination` is observed occupied. Those outcomes are
 *   treated as peer progress, without proving which actor changed the paths.
 * @throws When the rename fails for any other reason.
 * @evidence contracts/common.md#principled-implementation Renaming the held generation to its unique tombstone is the ownership transition; reported missing or occupied paths are treated as peer progress. A successful Windows sibling probe permits retry under caller-owned generation assumptions but cannot identify the original refusal's cause or rule out source-specific restrictions. Scoped cancelled cleanup stops retry admission after one second and preserves the last real refusal as failure cause; reporting it to the explicit owner preserves that failure across legacy outcome conversion.
 * @evidence contracts/common.md#clear-and-simple-design One retirement loop delegates missing/occupied classification and native peer-contention probing to private helpers; polling timing remains with the lock protocol caller, and one optional operations argument is the only seam, defaulting to the real filesystem and platform.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Windows retry addresses supported peer reads beneath the held generation rather than overriding filesystem methods; the source-specific restriction uncertainty remains explicit instead of being described as a proved peer cause. The injectable operations are a typed boundary that must report real native results and codes, not a replacement of foreign filesystem methods.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain tombstone ownership, supported contention, probe limits, ordinary unbounded retries and the cancelled-cleanup admission grace; outcome and yield meanings remain separately documented.
 * @evidence contracts/portability.md#os-neutral-implementation Node rename and errno classification carry native behavior; only Windows access/busy refusals invoke the sibling probe, selected by the operations' platform value (the process platform by default), and POSIX unrelated failures propagate.
 * @evidence contracts/performance.md#efficient-algorithms Each attempt performs one retirement rename and at most one sibling probe with a fixed-length random suffix. Path strings scale with source/destination text; native existence, allocation, rename and removal work and the supplied yield callback are delegated costs. Ordinary retries have no cap; cancelled retries check a one-second monotonic grace between native attempts and yields; no explicit directory enumeration occurs unless delegated recursive probe cleanup needs it.
 *
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A rename and its contention observations are mutable ownership effects; replaying a previous result would not retire the current generation.
 *
 * @evidence contracts/performance.md#bound-retention-and-release-resources The operation retires one caller-held generation and attempts to remove each temporary probe; a refused probe removal leaves that empty sibling directory behind without changing the retry decision, ordinary repeated contention can retain the call indefinitely, while scoped cancelled cleanup fails after its between-attempt grace with the last refusal as cause. Native calls/yields are not hard bounded; protocol cleanup owns the retired tombstone.
 */
export function retireLockDirectory(
  source: string,
  destination: string,
  yieldToPeers: () => void,
  operations: RetireLockDirectoryOperations = FILESYSTEM_OPERATIONS,
): boolean {
  let cancelledAt: number | undefined;
  try {
    for (;;) {
      try {
        operations.renameSync(source, destination);
        return true;
      } catch (error) {
        if (isMissingPath(error) || isOccupied(error, destination, operations))
          return false;
        if (!isHeldByPeer(error, source, destination, operations)) throw error;
        if (OwnedSynchronousProcess.cancelled()) {
          cancelledAt ??= performance.now();
          if (performance.now() - cancelledAt >= CANCELLED_CLEANUP_GRACE_MS)
            throw new Error(
              `ttsc: unable to retire lock generation ${source} after ` +
                `${CANCELLED_CLEANUP_GRACE_MS}ms of cancelled cleanup contention`,
              { cause: error },
            );
        }
      }
      yieldToPeers();
    }
  } catch (error) {
    if (OwnedSynchronousProcess.cancelled())
      OwnedSynchronousProcess.reportFailure(error);
    throw error;
  }
}

const CANCELLED_CLEANUP_GRACE_MS = 1_000;

function isMissingPath(error: unknown): boolean {
  const code = (error as NodeJS.ErrnoException).code;
  return code === "ENOENT" || code === "ENOTDIR";
}

/**
 * Whether a failed rename means the destination already exists. Windows reports
 * an occupied directory destination as `EACCES` or `EPERM`, so those count only
 * when the destination is actually present.
 */
function isOccupied(
  error: unknown,
  destination: string,
  operations: RetireLockDirectoryOperations,
): boolean {
  const code = (error as NodeJS.ErrnoException).code;
  if (code === "EEXIST" || code === "ENOTEMPTY") return true;
  return (
    (code === "EACCES" || code === "EPERM") &&
    operations.existsSync(destination)
  );
}

/**
 * Whether this refusal qualifies for retry after a successful sibling probe.
 * The result does not identify a peer or exclude source-specific restrictions.
 */
function isHeldByPeer(
  error: unknown,
  source: string,
  destination: string,
  operations: RetireLockDirectoryOperations,
): boolean {
  if (operations.platform !== "win32") return false;
  const code = (error as NodeJS.ErrnoException).code;
  if (code !== "EPERM" && code !== "EACCES" && code !== "EBUSY") return false;
  if (!operations.existsSync(source)) return false;
  const nonce = crypto.randomBytes(8).toString("hex");
  const probe = `${source}.probe-${nonce}`;
  const moved = `${destination}.probe-${nonce}`;
  try {
    operations.mkdirSync(probe);
  } catch {
    return false;
  }
  try {
    operations.renameSync(probe, moved);
  } catch {
    removeProbe(probe, operations);
    return false;
  }
  removeProbe(moved, operations);
  return true;
}

/**
 * Remove a probe directory without letting its removal decide the retry. The
 * probe records whether its sampled sibling rename succeeded, so a transient
 * refusal to delete the empty directory (an indexer or scanner holding it on
 * Windows) leaves that directory behind rather than turning an eligible retry
 * into a thrown failure.
 */
function removeProbe(
  directory: string,
  operations: RetireLockDirectoryOperations,
): void {
  try {
    operations.rmSync(directory, { force: true, recursive: true });
  } catch {
    // The probe is an empty sibling of the lock; its answer is already known.
  }
}

const FILESYSTEM_OPERATIONS: RetireLockDirectoryOperations = {
  renameSync: fs.renameSync,
  mkdirSync: (location) => fs.mkdirSync(location),
  rmSync: fs.rmSync,
  existsSync: fs.existsSync,
  platform: process.platform,
};

ttsc/src/internal/runHoldingLock.ts:
/**
 * Run the work a held build lock protects, then release the lock without
 * letting the release replace the work's outcome.
 *
 * A release that throws from a `finally` block replaced whatever the work
 * produced: a build that had published its binary failed, and a build that had
 * failed reported the release's error instead of its own. The work's value is
 * returned and its error is thrown as they were. A release that still fails
 * goes to `onReleaseFailure`. This adapter does not establish whether release
 * completed; the caller's lock protocol owns any later abandoned-generation
 * recovery.
 *
 * @param work Synchronous work under the lock. Returning a Promise does not
 *   extend lock ownership until that Promise settles.
 * @param release Frees the lock.
 * @param onReleaseFailure Receives a release's error, which it must not throw.
 * @returns What `work` returned.
 * @throws What `work` threw.
 * @evidence contracts/common.md#principled-implementation Both synchronous success and failure attempt release before preserving the original outcome; the release reporter must not throw, and asynchronous work is outside this lock-lifetime contract.
 * @evidence contracts/common.md#clear-and-simple-design One outcome branch and a shared release-reporting helper expose the ownership transition without wrapping successful results in another protocol.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Real release failures are reported rather than converted into a fabricated build failure or success; no foreign release method is replaced.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain outcome preservation and abandoned-generation recovery; parameter prose makes synchronous ownership and the nonthrowing reporter premise explicit.
 *
 * @evidenceExclude contracts/performance.md#efficient-algorithms This adapter sequences one opaque synchronous work callback and one release; the computation strategy belongs to their owners.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Executing held work and releasing a lock are effectful ownership transitions and cannot be shared by matching callback identities.
 *
 * @evidence contracts/performance.md#bound-retention-and-release-resources The caller transfers a held lock for the synchronous callback lifetime; release is attempted on either outcome, and an unconfirmed release leaves recovery to the caller's lock-generation protocol rather than certifying that ownership ended.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation This adapter preserves opaque callback outcomes and sequences release/reporting without interpreting a native path or error code; the supplied lock callbacks own filesystem identity, platform refusals and recovery.
 */
export function runHoldingLock<T>(
  work: () => T,
  release: () => void,
  onReleaseFailure: (error: unknown) => void,
): T {
  let result: T;
  try {
    result = work();
  } catch (error) {
    releaseReporting(release, onReleaseFailure);
    throw error;
  }
  releaseReporting(release, onReleaseFailure);
  return result;
}

function releaseReporting(
  release: () => void,
  onReleaseFailure: (error: unknown) => void,
): void {
  try {
    release();
  } catch (error) {
    onReleaseFailure(error);
  }
}

ttsc/src/internal/runtimeExecutableIdent:
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { threadId } from "node:worker_threads";

import { PluginContentIdentities } from "../plugin/internal/source/PluginContentIdentities";
import { E2ETrace } from "./E2ETrace";

/**
 * Fingerprint an absolute executable's spelling, target and actual bytes.
 *
 * A changed link, file, or read failure yields no reusable identity. Metadata
 * brackets the streamed read. Concurrent writes that evade every filesystem
 * observation remain outside this snapshot guarantee.
 *
 * With a record store, the bytes of an unchanged executable are proven from its
 * metadata instead of streamed again (`PluginContentIdentities`, #1723): the
 * recorded digest stands only while the physical file's identity, size and both
 * stamps match the record and its modification stamp is separable from a
 * reference the store minted. A plugin load asks for this identity several
 * times, and every launch is a new process, so streaming an 85 MB runtime each
 * time cost about 0.9 s per launch. Without a store, or when that proof is
 * unavailable, the file is streamed as before.
 *
 * @param runtime The executable, absolute.
 * @param identities Optional record store of the caller's plugin cache.
 * @evidence contracts/common.md#principled-implementation The identity joins lexical-link metadata, the selected physical file metadata and the SHA-256 of that file's bytes, streamed under metadata brackets or proven by a record whose separable signature still matches; descriptor and pathname observations must still agree after a read.
 * @evidence contracts/common.md#clear-and-simple-design This one native owner supplies the same identity to runtime capability and plugin caches; the record store owns metadata reuse and a private helper owns the bracketed stream.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Metadata alone never stands for bytes: reuse needs a record written under unchanged separable metadata around an actual read, which a same-tick rewrite or restored timestamps cannot satisfy because change time and the minted reference move.
 * @evidence contracts/common.md#meaningful-documentation Native prose explains absolute-path scope, failure meaning, the record proof and the remaining concurrent-mutation limitation, with separate prose and tags.
 * @evidence contracts/portability.md#os-neutral-implementation Node native realpath and bigint stat preserve link/target identity on supported hosts; absolute paths use native platform semantics, and unreadable or non-regular targets cannot be reused.
 * @evidence contracts/performance.md#efficient-algorithms A proven record costs three stats and one small file read; otherwise a sequential read hashes B bytes with one 64 KiB buffer instead of a complete executable allocation. Native path/realpath/stat observations and serialized metadata add text/lookup costs.
 * @evidence contracts/performance.md#reuse-equivalent-work Processes share an executable digest only through the record store's separable-signature proof; without a store every call streams the file.
 * @evidence contracts/performance.md#bound-retention-and-release-resources One descriptor and one fixed buffer belong to a streamed read; finally attempts closure after read/observation failures as well as success. A close failure returns no identity but cannot confirm native release. Opt-in opened/closed/close-failed observations carry one trace-only call id and actual descriptor, PID/thread and already observed physical identity. Records belong to the single-file collector.
 */
export function runtimeExecutableIdentity(
  runtime: string,
  identities?: PluginContentIdentities.Store,
): string | undefined {
  if (!path.isAbsolute(runtime)) return undefined;
  const startedAt = new Date().toISOString();
  let stage = "lexical-stat";
  let refused: IUnavailable | undefined;
  try {
    const lexical = fs.lstatSync(runtime, { bigint: true });
    stage = "physical-realpath";
    const physicalPath = fs.realpathSync.native(runtime);
    stage = "physical-stat";
    const physical = fs.statSync(physicalPath, { bigint: true });
    if (!physical.isFile())
      return unavailable(runtime, {
        stage,
        reason: "not-regular",
        observed: fileIdentity(physical),
      });
    const read = (): string => {
      const streamed = streamDigest(runtime, physicalPath, physical, lexical, {
        startedAt,
      });
      if (typeof streamed === "string") return streamed;
      refused = streamed;
      throw new Error(streamed.reason);
    };
    const digest =
      identities === undefined
        ? read()
        : PluginContentIdentities.digest(
            identities,
            "executable",
            physicalPath,
            (references) =>
              PluginContentIdentities.fileObservation(references, physicalPath),
            read,
          );
    return [
      physicalPath,
      fileIdentity(lexical),
      fileIdentity(physical),
      digest,
    ].join("\0");
  } catch (error) {
    return unavailable(
      runtime,
      refused ?? {
        stage,
        reason: "filesystem-error",
        observed: error instanceof Error ? error.message : String(error),
      },
    );
  }
}

/** Why an identity could not be formed, at the stage that found it. */
interface IUnavailable {
  stage: string;
  reason: string;
  expected?: string;
  observed?: string;
  observations?: { before: fs.BigIntStats; after: fs.BigIntStats };
}

function unavailable(runtime: string, failure: IUnavailable): undefined {
  E2ETrace.capabilityResolution("runtime-executable-identity-unavailable", {
    runtime,
    stage: failure.stage,
    reason: failure.reason,
    expected: failure.expected,
    observed: failure.observed,
    expectedAtimeNs:
      failure.observations === undefined
        ? undefined
        : String(failure.observations.before.atimeNs),
    observedAtimeNs:
      failure.observations === undefined
        ? undefined
        : String(failure.observations.after.atimeNs),
    expectedBirthtimeNs:
      failure.observations === undefined
        ? undefined
        : String(failure.observations.before.birthtimeNs),
    observedBirthtimeNs:
      failure.observations === undefined
        ? undefined
        : String(failure.observations.after.birthtimeNs),
  });
  return undefined;
}

/**
 * Stream the physical file's bytes between metadata observations of the open
 * descriptor, the physical path and the lexical spelling, returning the digest
 * or what moved. The descriptor is closed in finally; a failed close refuses
 * the identity.
 */
function streamDigest(
  runtime: string,
  physicalPath: string,
  physical: fs.BigIntStats,
  lexical: fs.BigIntStats,
  timing: { startedAt: string },
): string | IUnavailable {
  let stage = "open";
  let descriptor: number | undefined;
  let traceLease: Readonly<Record<string, string | number>> | undefined;
  let result: string | IUnavailable;
  try {
    result = observe();
  } finally {
    if (descriptor !== undefined) {
      try {
        fs.closeSync(descriptor);
        if (traceLease !== undefined)
          E2ETrace.capabilityResolution(
            "runtime-executable-identity-closed",
            traceLease,
          );
      } catch (error) {
        if (traceLease !== undefined)
          E2ETrace.capabilityResolution(
            "runtime-executable-identity-close-failed",
            {
              ...traceLease,
              error: error instanceof Error ? error.message : String(error),
            },
          );
        // A digest whose descriptor could not be closed is refused, as before.
        result = {
          stage: "close",
          reason: "descriptor-close-error",
          observed: error instanceof Error ? error.message : String(error),
        };
      }
    }
  }
  return result;

  function observe(): string | IUnavailable {
    try {
      descriptor = fs.openSync(physicalPath, "r");
      if (process.env.TTSC_E2E_TRACE) {
        traceLease = {
          callId: String(++identityTraceOrdinal),
          runtime,
          physicalPath,
          descriptor,
          pid: process.pid,
          threadId,
          dev: String(physical.dev),
          ino: String(physical.ino),
        };
        E2ETrace.capabilityResolution(
          "runtime-executable-identity-opened",
          traceLease,
        );
      }
      stage = "opened-stat";
      const opened = fs.fstatSync(descriptor, { bigint: true });
      if (fileIdentity(opened) !== fileIdentity(physical))
        return {
          stage,
          reason: "opened-file-changed",
          expected: fileIdentity(physical),
          observed: fileIdentity(opened),
        };
      const hash = crypto.createHash("sha256");
      const buffer = Buffer.allocUnsafe(64 * 1024);
      let remaining = opened.size;
      stage = "read";
      while (remaining > 0n) {
        const requested =
          remaining > BigInt(buffer.length) ? buffer.length : Number(remaining);
        const length = fs.readSync(descriptor, buffer, 0, requested, null);
        if (length === 0)
          return {
            stage,
            reason: "premature-eof",
            expected: String(opened.size),
            observed: String(opened.size - remaining),
          };
        hash.update(buffer.subarray(0, length));
        remaining -= BigInt(length);
      }
      stage = "post-read-opened-stat";
      const afterOpened = fs.fstatSync(descriptor, { bigint: true });
      if (fileIdentity(afterOpened) !== fileIdentity(opened))
        return {
          stage,
          reason: "opened-file-changed-during-read",
          expected: fileIdentity(opened),
          observed: fileIdentity(afterOpened),
          observations: { before: opened, after: afterOpened },
        };
      stage = "post-read-realpath";
      const afterPath = fs.realpathSync.native(runtime);
      if (afterPath !== physicalPath)
        return {
          stage,
          reason: "physical-target-changed",
          expected: physicalPath,
          observed: afterPath,
        };
      stage = "post-read-lexical-stat";
      const afterLexical = fs.lstatSync(runtime, { bigint: true });
      if (fileIdentity(afterLexical) !== fileIdentity(lexical))
        return {
          stage,
          reason: "lexical-file-changed-during-read",
          expected: fileIdentity(lexical),
          observed: fileIdentity(afterLexical),
        };
      stage = "post-read-physical-stat";
      const afterPhysical = fs.statSync(physicalPath, { bigint: true });
      if (fileIdentity(afterPhysical) !== fileIdentity(physical))
        return {
          stage,
          reason: "physical-file-changed-during-read",
          expected: fileIdentity(physical),
          observed: fileIdentity(afterPhysical),
        };
      const digest = hash.digest("hex");
      E2ETrace.capabilityResolution("runtime-executable-identity-observed", {
        runtime,
        physicalPath,
        startedAt: timing.startedAt,
        finishedAt: new Date().toISOString(),
        lexical: fileIdentity(lexical),
        physical: fileIdentity(physical),
        digest,
        openedAtimeNs: String(opened.atimeNs),
        afterOpenedAtimeNs: String(afterOpened.atimeNs),
        openedBirthtimeNs: String(opened.birthtimeNs),
        afterOpenedBirthtimeNs: String(afterOpened.birthtimeNs),
      });
      return digest;
    } catch (error) {
      return {
        stage,
        reason: "filesystem-error",
        observed: error instanceof Error ? error.message : String(error),
      };
    }
  }
}

// Trace-only ordinal distinguishes sequential uses of a reused descriptor.
let identityTraceOrdinal = 0;

/** Bigint metadata distinguishes file replacement and observed writes. */
function fileIdentity(stat: fs.BigIntStats): string {
  return [
    stat.dev,
    stat.ino,
    stat.mode,
    stat.size,
    stat.mtimeNs,
    stat.ctimeNs,
  ].join("\0");
}

ttsc/src/internal/serializeCompilerError:
/**
 * Describe a thrown value without dropping Error causes or aggregate failures.
 *
 * Error name, message and stack are explicit because they are not enumerable.
 * Plain outcome objects and arrays retain enumerable string-keyed data.
 * Repeated objects use a JSON-pointer reference marker, making cycles in a
 * finite observed graph finite without duplicating shared outcome trees. Source
 * objects shaped like reference or literal-object envelopes are escaped under
 * `$ttscProperties`, keeping their data distinct from generated markers. Values
 * JSON cannot express use a tagged description. Accessor descriptors are not
 * invoked to read their values. Reflection can execute Proxy traps and expose
 * changing objects, so arbitrary reflective behavior has no deadline or fixed
 * graph-size guarantee. Failed reflective inspection, such as a revoked Proxy,
 * is marked rather than replacing the compiler's exception. Internal slots of
 * foreign classes are not projected into ordinary data.
 *
 * @evidence contracts/common.md#principled-implementation Explicit Error fields preserve exception meaning while recursively retaining cause, aggregate errors and ordinary outcome data. Pointer markers distinguish repeated references, literal envelopes escape colliding source shapes, and tagged values describe JSON-inexpressible primitives without dropping fields.
 * @evidence contracts/common.md#clear-and-simple-design One traversal owns API and worker failure transport, with private property and scalar helpers; compiler status classification remains separate from serialization.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Available causal data is preserved rather than replaced with only the outer message; literal marker-shaped metadata is escaped rather than prohibited or reinterpreted. Traversal marks accessor descriptors instead of invoking getters and does not patch Error serialization. Proxy reflection may execute traps or fail, with inspection failures explicitly marked rather than inventing outcome data.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs state the retained Error/outcome fields, finite reference representation, exceptional scalars and accessor policy with separate acknowledgments.
 * @evidence contracts/performance.md#efficient-algorithms For a finite observed graph, an explicit stack visits V distinct objects and E reflected owned fields once, with P prototype observations for inherited Error text, scalar/text conversion and pointer spelling costs. O(V+E+P) structural work excludes arbitrary Proxy-trap execution; shared subtrees are not expanded again and traversal does not recurse on the JavaScript call stack. Descriptor collections and pending outputs scale with the observed graph and text.
 *
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Each failure graph belongs to one outcome; sharing an earlier serialization would require immutable graph inputs that arbitrary thrown values do not guarantee.
 *
 * @evidence contracts/performance.md#bound-retention-and-release-resources Seen-object and work-stack state belongs to one traversal and scales with distinct observed objects, fields and pointer text. On completion it becomes reclaimable while the caller owns the returned description; no global exception history is retained. Arbitrary reflective behavior can prevent completion or keep exposing new objects, and this traversal imposes no deadline or population cap.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation serializeCompilerError computes from its arguments only; it opens no file, builds no path and calls no platform or process API.
 */
export function serializeCompilerError(error: unknown): unknown {
  const seen = new WeakMap<object, string>();
  const pending: {
    input: object;
    output: Record<string, unknown> | unknown[];
    pointer: string;
  }[] = [];
  const describe = (value: unknown, pointer: string): unknown => {
    if (value === null || typeof value !== "object")
      return describeScalar(value);
    const previous = seen.get(value);
    if (previous !== undefined) return { $ttscReference: previous };
    seen.set(value, pointer);
    let output: Record<string, unknown> | unknown[];
    try {
      output = Array.isArray(value)
        ? new Array(Object.getOwnPropertyDescriptor(value, "length")!.value)
        : {};
    } catch {
      return { $ttscValue: "uninspectable-object" };
    }
    pending.push({ input: value, output, pointer });
    return output;
  };
  const result = describe(error, "");
  while (pending.length !== 0) {
    const { input, output, pointer } = pending.pop()!;
    let fields: Record<string, PropertyDescriptor>;
    let isError: boolean;
    let destination = output;
    let fieldPointer = pointer;
    try {
      fields = Object.getOwnPropertyDescriptors(input);
      isError = input instanceof Error;
      const keys = Object.keys(fields).filter((key) => fields[key]!.enumerable);
      if (
        !isError &&
        !Array.isArray(input) &&
        ((keys.length === 1 && keys[0] === "$ttscReference") ||
          (keys.length === 2 &&
            keys.includes("$ttscValue") &&
            keys.includes("$ttscProperties")))
      ) {
        destination = {};
        Object.assign(output, {
          $ttscValue: "object",
          $ttscProperties: destination,
        });
        fieldPointer = `${pointer}/$ttscProperties`;
      }
      if (isError) {
        // Built-in names may be inherited; own Error data overrides them below.
        const stack = errorDataField(input as Error, "stack");
        Object.assign(destination, {
          message: errorDataField(input as Error, "message") ?? "",
          name: errorDataField(input as Error, "name") ?? "Error",
          ...(stack === undefined ? {} : { stack }),
        });
      }
    } catch {
      Object.assign(output, { $ttscValue: "uninspectable-object" });
      continue;
    }
    for (const [key, descriptor] of Object.entries(fields)) {
      if (
        !descriptor.enumerable &&
        !(
          isError &&
          ["message", "name", "stack", "cause", "errors"].includes(key)
        )
      )
        continue;
      const value =
        "value" in descriptor
          ? describe(
              descriptor.value,
              `${fieldPointer}/${key.replaceAll("~", "~0").replaceAll("/", "~1")}`,
            )
          : { $ttscValue: "accessor" };
      Object.defineProperty(destination, key, {
        configurable: true,
        enumerable: true,
        value,
        writable: true,
      });
    }
  }
  return result;
}

/** Read inherited Error data without evaluating a user-defined accessor. */
function errorDataField(error: Error, key: string): string | undefined {
  const visited = new WeakSet<object>();
  let current: object | null = error;
  while (current !== null && !visited.has(current)) {
    visited.add(current);
    const descriptor = Object.getOwnPropertyDescriptor(current, key);
    if (descriptor !== undefined)
      return "value" in descriptor && typeof descriptor.value === "string"
        ? descriptor.value
        : undefined;
    current = Object.getPrototypeOf(current) as object | null;
  }
  return undefined;
}

/** Preserve JSON scalars and explicitly describe values outside that domain. */
function describeScalar(value: unknown): unknown {
  if (value === undefined) return { $ttscValue: "undefined" };
  if (typeof value === "bigint")
    return { $ttscValue: "bigint", value: String(value) };
  if (typeof value === "symbol")
    return { $ttscValue: "symbol", value: String(value) };
  if (typeof value === "function") return { $ttscValue: "function" };
  if (typeof value === "number" && !Number.isFinite(value))
    return { $ttscValue: "number", value: String(value) };
  return value;
}

ttsc/src/internal/SourceNativeRetirement:
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

import { E2ETrace } from "./E2ETrace";
import { OwnedSynchronousProcess } from "./OwnedSynchronousProcess";

/**
 * Preserve source-build resources until their native boundary has retired.
 *
 * Guards are published before command admission. Pending and uncertified
 * boundaries protect inputs from cooperating collectors even after their Node
 * owner disappears. Neither PID absence nor elapsed time grants reclamation.
 * Older compiler versions do not implement these guards and cannot safely share
 * quarantined roots. External deletion is outside this protocol.
 *
 * @evidence contracts/common.md#principled-implementation Exact pre-admission guards protect inputs until the original native boundary certifies closure; PID absence and age never grant authority.
 * @evidence contracts/common.md#clear-and-simple-design One protocol owns admission, deferred cleanup and collector checks; native containment remains with the command owner.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Durable pending records remain conservative when unknown diagnostics cannot be published.
 * @evidence contracts/common.md#meaningful-documentation Native prose states cooperative-version limits and the absence of disk-only recovery authority.
 * @evidence contracts/portability.md#os-neutral-implementation Node realpath, lstat and argv-independent JSON paths represent actual filesystem roots; later namespace replacement remains outside the retained-handle premise.
 * @evidence contracts/performance.md#efficient-algorithms Member operations own scans and publication costs; the namespace itself executes no algorithm.
 * @evidence contracts/performance.md#reuse-equivalent-work Guards carry ownership, not reusable compiler results.
 * @evidence contracts/performance.md#bound-retention-and-release-resources Unknown boundaries intentionally retain inputs without an age bound; losing the original closure capability requires operator-confirmed external closure.
 */
export namespace SourceNativeRetirement {
  /**
   * Original task capability retained for qualified recovery. Losing this
   * object leaves durable guards and requires external closure confirmation;
   * loading guard bytes does not manufacture native reclamation authority.
   *
   * @evidence contracts/common.md#principled-implementation Original task identity, resources, admitted boundaries and cleanup callbacks express separate ownership states.
   * @evidence contracts/common.md#clear-and-simple-design Maps index roots and boundary tokens while the FIFO preserves normal finally order.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Disk metadata cannot construct this original task capability or certify process closure.
   * @evidence contracts/common.md#meaningful-documentation Field prose explains original authority and the consequence of losing it.
   * @evidence contracts/portability.md#os-neutral-implementation Resources contain observed physical native roots; command retirement authority is an in-memory capability.
   * @evidence contracts/performance.md#efficient-algorithms This type declares state without executing an algorithm.
   * @evidence contracts/performance.md#reuse-equivalent-work Task identity permits no equivalent-result sharing.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The type acquires no resources itself; begin, settle and recover own their lifetimes.
   */
  export interface Scope {
    /** Identity supplied by the original worker request owner. */
    taskToken: string;

    /** Currently registered physical roots and their retained input paths. */
    resources: Map<string, Resource>;

    /** Original native admission capabilities, never reconstructed from disk. */
    boundaries: Map<string, Boundary>;

    /** Original cleanup callbacks, in normal finally-unwinding order. */
    deferred: Array<() => void>;

    /**
     * Optional task-local publication primitives for an explicit filesystem
     * boundary oracle. Omitted tasks use Node's original synchronous APIs.
     * Implementations must preserve exclusive-open and real descriptor
     * meaning.
     */
    guardFileOperations?: Pick<
      typeof fs,
      "openSync" | "writeFileSync" | "closeSync" | "renameSync" | "rmSync"
    >;
  }

  /**
   * Allocate an empty task capability without acquiring a filesystem guard.
   *
   * @evidence contracts/common.md#principled-implementation A nonempty task token distinguishes the original admission owner and starts with no native commands.
   * @evidence contracts/common.md#clear-and-simple-design Two maps and one FIFO separate registration, boundary state and deferred cleanup.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Allocation grants no native closure certificate from PID or elapsed time.
   * @evidence contracts/common.md#meaningful-documentation Native prose identifies allocation without filesystem acquisition.
   * @evidence contracts/portability.md#os-neutral-implementation Allocation handles opaque identity and collections without native operations.
   * @evidence contracts/performance.md#efficient-algorithms One object and three empty collections take constant initial space.
   * @evidence contracts/performance.md#reuse-equivalent-work Each task receives distinct mutable ownership state rather than a shared result.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The caller owns the returned capability; no filesystem or process handle is acquired.
   */
  export function createScope(taskToken: string): Scope {
    if (taskToken.length === 0)
      throw new Error("ttsc: empty native task identity");
    return {
      taskToken,
      resources: new Map(),
      boundaries: new Map(),
      deferred: [],
    };
  }

  /**
   * Install one synchronous task; promises do not extend its lexical lifetime.
   *
   * @evidence contracts/common.md#principled-implementation Finally restores the predecessor even when task work throws.
   * @evidence contracts/common.md#clear-and-simple-design One lexical saved reference supports nested synchronous scopes.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts An asynchronously returned value cannot extend this synchronous authority implicitly.
   * @evidence contracts/common.md#meaningful-documentation Native prose states the synchronous lifetime and promise limitation.
   * @evidence contracts/portability.md#os-neutral-implementation Scope sequencing has no native path or process representation.
   * @evidence contracts/performance.md#efficient-algorithms One reference save and restore surround delegated callback cost.
   * @evidence contracts/performance.md#reuse-equivalent-work Every effectful callback runs independently; this operation caches no answer.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Restoration releases the global reference while the original caller retains its task capability.
   */
  export function run<T>(scope: Scope, task: () => T): T {
    const previous = current;
    current = scope;
    try {
      return task();
    } finally {
      current = previous;
    }
  }

  /**
   * Register inputs before their first native command. Additional paths merge
   * with the same held generation; conflicting generation authority is refused.
   * Ordinary synchronous callers acquire no new protocol state.
   *
   * @evidence contracts/common.md#principled-implementation Physical root identity and generation/nonce consistency bind additional paths to the same held resource.
   * @evidence contracts/common.md#clear-and-simple-design A root-indexed map merges paths while retaining one generation capability.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Registration is opt-in and cannot silently substitute a conflicting generation.
   * @evidence contracts/common.md#meaningful-documentation Native prose explains registration timing, merging and ordinary-call behavior.
   * @evidence contracts/portability.md#os-neutral-implementation Native realpath resolves existing root aliases; retained path spellings use Node path resolution.
   * @evidence contracts/performance.md#efficient-algorithms Merging scans existing and incoming path strings once through a Set; map lookup uses the physical root key.
   * @evidence contracts/performance.md#reuse-equivalent-work Repeated registration shares the same root entry only when supplied generation authority agrees.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Task resource entries persist until safe forget or scope reclamation; native guards snapshot registrations at admission.
   */
  export function register(resource: {
    /** Existing physical root where cooperating cleanup observes guards. */
    fenceRoot: string;

    /** Exact inputs retained and disclosed in terminal diagnostics. */
    retainedPaths: readonly string[];

    /** Held source-key or shared-cache lease generation, when applicable. */
    generation?: string;

    /** Original source-key task completion capability, when applicable. */
    completionNonce?: string;
  }): void {
    if (current === undefined) return;
    const root = physicalRoot(resource.fenceRoot);
    const previous = current.resources.get(root);
    if (
      previous !== undefined &&
      ((resource.generation !== undefined &&
        previous.generation !== undefined &&
        resource.generation !== previous.generation) ||
        (resource.completionNonce !== undefined &&
          previous.completionNonce !== undefined &&
          resource.completionNonce !== previous.completionNonce))
    )
      throw new Error(
        `ttsc: conflicting native resource generation at ${root}`,
      );
    current.resources.set(root, {
      fenceRoot: root,
      retainedPaths: [
        ...new Set([
          ...(previous?.retainedPaths ?? []),
          ...resource.retainedPaths.map((entry) => path.resolve(entry)),
        ]),
      ],
      generation: resource.generation ?? previous?.generation,
      completionNonce: resource.completionNonce ?? previous?.completionNonce,
    });
  }

  /**
   * Register an explicitly selected shared Go cache only in an owned task.
   * Ordinary synchronous consumers retain their existing directory behavior.
   * This adds lifetime protection, without claiming eviction ownership or
   * restricting independent builders that share the cache.
   *
   * @evidence contracts/common.md#principled-implementation Scoped native work creates or resolves the selected Go root before registration so its eventual guard protects the same physical input directory.
   * @evidence contracts/common.md#clear-and-simple-design One helper confines scoped-only directory materialization and registration; ordinary unmanaged callbacks keep their prior path.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Lifetime guard metadata does not convert a user cache into an evictable compiler-owned cache or serialize independent builds.
   * @evidence contracts/common.md#meaningful-documentation Native prose distinguishes lifetime protection, eviction ownership and unchanged ordinary synchronous behavior.
   * @evidence contracts/portability.md#os-neutral-implementation Node recursive mkdir and delegated native realpath preserve existing physical aliases without choosing case policy from an OS name.
   * @evidence contracts/performance.md#efficient-algorithms One directory creation observation and delegated root registration scale with path depth and retained path text.
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Shared cache ownership permits concurrent builds but authorizes no compiler-result reuse in this helper.
   * @evidence contracts/performance.md#bound-retention-and-release-resources No process or persistent handle is acquired; the scope owns the root entry and each admitted boundary owns its guard until certified retirement.
   */
  export function registerSharedRoot(root: string): void {
    if (current === undefined) return;
    fs.mkdirSync(root, { recursive: true });
    register({ fenceRoot: root, retainedPaths: [root] });
  }

  /**
   * Forget a safely released registration, never another generation's inputs.
   *
   * @evidence contracts/common.md#principled-implementation Safe tasks remove only the matching registered generation.
   * @evidence contracts/common.md#clear-and-simple-design The current scope and one physical root lookup keep ownership local.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Unresolved native ownership prevents forgetting instead of treating cleanup as complete.
   * @evidence contracts/common.md#meaningful-documentation Native prose states safe release and exact-generation exclusion.
   * @evidence contracts/portability.md#os-neutral-implementation Native realpath supplies the same physical root spelling used at registration.
   * @evidence contracts/performance.md#efficient-algorithms One physical resolution and map lookup perform the removal.
   * @evidence contracts/performance.md#reuse-equivalent-work Removing ownership state does not reuse a computed build result.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Safe forgetting drops the scope entry; admitted boundaries retain their original resource snapshots.
   */
  export function forget(fenceRoot: string, generation?: string): void {
    if (current === undefined || !canRelease()) return;
    const root = physicalRoot(fenceRoot);
    const resource = current.resources.get(root);
    if (
      resource !== undefined &&
      (generation === undefined || resource.generation === generation)
    )
      current.resources.delete(root);
  }

  /**
   * Publish every input guard before the native owner may admit a command.
   * Partial publication failure admits no native work and rolls back only this
   * boundary's guards. A failed rollback remains a visible protected record. An
   * unresolved earlier command closes further admission in the same task.
   * Exclusive open registers ownership before any write or close can fail.
   * Failed close/rollback preserves original errors and exact paths for the
   * task owner even if a legacy resolver converts the result to unavailable.
   *
   * @evidence contracts/common.md#principled-implementation All registered guards are written before command admission; publication failure rolls back only files whose exclusive open actually succeeded, including partial writes; close/rollback errors remain original aggregate members.
   * @evidence contracts/common.md#clear-and-simple-design One boundary snapshots registered resources and tracks its exact guard paths.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Publication refusal admits no command; rollback failure stays visible rather than claiming clean release.
   * @evidence contracts/common.md#meaningful-documentation Native prose explains publication ordering and partial-failure effects.
   * @evidence contracts/portability.md#os-neutral-implementation Native directory validation rejects guard links; an actual exclusive descriptor establishes creation ownership before writing, while EEXIST cannot grant deletion authority.
   * @evidence contracts/performance.md#efficient-algorithms For R registered roots, publication writes R records whose bytes scale with retained path text.
   * @evidence contracts/performance.md#reuse-equivalent-work Fresh boundary tokens prohibit accidental reuse of an effectful admission.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Each boundary owns one guard per root from exclusive open until certified settlement or successful pre-admission rollback; failed close/rollback is reported across legacy catches, and unknown descriptor closure is never claimed or blindly retried.
   */
  export function begin(boundaryToken: string): void {
    if (current === undefined) return;
    if (!canRelease())
      throw new Error(
        "ttsc: native admission is closed while an earlier boundary has unresolved retirement",
      );
    if (boundaryToken.length === 0 || current.boundaries.has(boundaryToken))
      throw new Error("ttsc: native boundary identity was empty or reused");
    const boundary: Boundary = {
      token: boundaryToken,
      state: "not-started",
      resources: [...current.resources.values()],
      files: [],
      candidates: new Set(),
    };
    current.boundaries.set(boundaryToken, boundary);
    try {
      for (const resource of boundary.resources) {
        const directory = guardDirectory(resource.fenceRoot, true)!;
        const file = path.join(
          directory,
          `${digest(current.taskToken)}-${digest(boundaryToken)}.json`,
        );
        writeGuard(
          file,
          current.taskToken,
          boundary,
          resource,
          "pending",
          true,
        );
      }
      boundary.state = "pending";
    } catch (error) {
      const failures: unknown[] = [error];
      const operations = current.guardFileOperations ?? fs;
      const retained: string[] = [];
      const owned = [...boundary.files];
      for (const file of boundary.files) {
        try {
          operations.rmSync(file, { force: true });
        } catch (failure) {
          failures.push(failure);
          retained.push(file);
        }
      }
      boundary.files = retained;
      const failure = new AggregateError(
        failures,
        `ttsc: native guard publication failed before admission; created guards: ${JSON.stringify(owned)}; retained guards: ${JSON.stringify(retained)}; retained paths: ${JSON.stringify(boundary.resources.flatMap((resource) => resource.retainedPaths))}`,
      );
      if (
        failures.length > 1 ||
        (error instanceof GuardPublicationError && error.cleanupFailed)
      )
        OwnedSynchronousProcess.reportFailure(failure);
      throw failure;
    }
  }

  /**
   * Accept the original boundary owner's classified outcome. A certified
   * terminal outcome is immutable, so a surrounding catch cannot turn a joined
   * command back into unknown. Unknown remains protected if diagnostic writes
   * fail; the pre-admission pending guard already protects its inputs.
   * Candidate close/removal failures retain their original errors and reach the
   * owned task even when later resolver code catches the thrown outcome.
   * Successful removal relinquishes that pathname immediately; only failed
   * removals retain retry authority, and all roots are attempted before
   * failure.
   *
   * @evidence contracts/common.md#principled-implementation Only the original boundary accepts a classified result; safe certificates cannot become unknown through a surrounding catch.
   * @evidence contracts/common.md#clear-and-simple-design The state transition and exact guard-file list centralize completion and unknown publication.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts An unknown diagnostic write failure retains the pre-admission guard instead of inferring native closure.
   * @evidence contracts/common.md#meaningful-documentation Native prose states immutable safe outcomes and failure-safe unknown protection.
   * @evidence contracts/portability.md#os-neutral-implementation Node exclusive temporary writes and rename publish metadata; native I/O refusal is propagated.
   * @evidence contracts/performance.md#efficient-algorithms Unknown publication visits registered guard files and serialized path bytes; certified cleanup scans each still-owned guard and failed candidate once before aggregating refusals.
   * @evidence contracts/performance.md#reuse-equivalent-work Repeated identical safe outcomes retry cleanup, while conflicting certificates are rejected.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Joined or never-started outcomes relinquish each successfully removed guard or candidate pathname and retain only failed removals for retry; original cleanup failures reach the owned task across legacy catches. Unknown retains guards and failed owned candidates until qualified recovery.
   */
  export function settle(
    boundaryToken: string,
    retirement: "joined" | "not-started" | "unknown",
    reason?: string,
  ): void {
    if (current === undefined) return;
    const boundary = current.boundaries.get(boundaryToken);
    if (boundary === undefined)
      throw new Error("ttsc: native outcome has no admitted boundary");
    if (
      (boundary.state === "joined" || boundary.state === "not-started") &&
      retirement === "unknown"
    )
      return;
    if (
      (boundary.state === "joined" || boundary.state === "not-started") &&
      retirement !== boundary.state
    )
      throw new Error(
        "ttsc: certified native retirement outcome cannot change",
      );
    if (retirement === "unknown") {
      boundary.state = "unknown";
      boundary.reason =
        reason ?? "native process-tree retirement was not confirmed";
      const failures: unknown[] = [];
      for (let index = 0; index < boundary.resources.length; index++) {
        try {
          writeGuard(
            boundary.files[index]!,
            current.taskToken,
            boundary,
            boundary.resources[index]!,
            "unknown",
          );
        } catch (error) {
          failures.push(error);
        }
      }
      if (failures.length !== 0) {
        const failure = new AggregateError(failures, diagnostic(boundary));
        if (
          failures.some(
            (error) =>
              error instanceof GuardPublicationError && error.cleanupFailed,
          )
        )
          OwnedSynchronousProcess.reportFailure(failure);
        throw failure;
      }
      return;
    }
    boundary.state = retirement;
    const failures: unknown[] = [];
    const retained: string[] = [];
    const retainedCandidates = new Set<string>();
    const operations = current.guardFileOperations ?? fs;
    for (const file of [...boundary.files, ...boundary.candidates]) {
      try {
        operations.rmSync(file, { force: true });
      } catch (error) {
        failures.push(error);
        if (boundary.candidates.has(file)) retainedCandidates.add(file);
        else retained.push(file);
      }
    }
    boundary.files = retained;
    boundary.candidates = retainedCandidates;
    if (failures.length !== 0) {
      const failure = new AggregateError(
        failures,
        `ttsc: certified native guard cleanup failed; retained guards: ${JSON.stringify([...retained, ...retainedCandidates])}; retained paths: ${JSON.stringify(boundary.resources.flatMap((resource) => resource.retainedPaths))}`,
      );
      OwnedSynchronousProcess.reportFailure(failure);
      throw failure;
    }
  }

  /**
   * Run safe cleanup now or retain its original capability after unknown
   * retirement. Deferred callbacks are not treated as completed cleanup. A
   * cleanup refusal is recorded for the task owner before it is rethrown, so a
   * surrounding discovery catch cannot turn resource loss into success.
   *
   * @evidence contracts/common.md#principled-implementation Cleanup executes only when all admitted boundaries certify safety; otherwise its original callback is retained. An immediate refusal remains the same thrown error and is recorded in the asynchronous task owner's failure ledger.
   * @evidence contracts/common.md#clear-and-simple-design One predicate chooses immediate execution or FIFO deferral.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Deferral is never reported as completed cleanup.
   * @evidence contracts/common.md#meaningful-documentation Native prose distinguishes retained authority from successful release.
   * @evidence contracts/portability.md#os-neutral-implementation The callback owns native details; this operation sequences opaque cleanup capabilities.
   * @evidence contracts/performance.md#efficient-algorithms One safety scan over task boundaries precedes constant-time append or delegated cleanup.
   * @evidence contracts/performance.md#reuse-equivalent-work Effectful cleanup callbacks are not deduplicated by matching return values.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Deferred callbacks remain with the original scope until qualified recovery succeeds; unknown has no age-based eviction.
   */
  export function release(cleanup: () => void): void {
    if (current !== undefined && !canRelease()) current.deferred.push(cleanup);
    else {
      try {
        cleanup();
      } catch (error) {
        OwnedSynchronousProcess.reportFailure(error);
        throw error;
      }
    }
  }

  /**
   * Release one destructible resource using its observed registration identity.
   *
   * Capture the original scope, physical key and registration while the root
   * still exists. Cleanup can then remove that root without another realpath.
   * Only successful cleanup drops the exact captured registration; a failed
   * cleanup or a replacement registration remains owned. Unknown boundaries
   * defer the same callback and identity through the original release protocol.
   *
   * The optional task failure distinguishes an earlier thrown undefined from
   * no earlier failure. It is combined with a cleanup refusal, never rethrown
   * after successful cleanup or deferred recovery. Ordinary unscoped callers
   * perform cleanup without observing or inventing a registration.
   *
   * Enabled private tracing observes the original callback's execution, not
   * its deferral. Scalar own error properties are read without invoking
   * getters; reflection or sink failures leave the original outcome intact.
   * Synchronous trace writes can change scheduling and prove only that run.
   *
   * @evidence contracts/common.md#principled-implementation Physical identity and the exact resource object are captured before destruction; only successful cleanup removes that identical registration from the original scope, while failure and replacement retain ownership.
   * @evidence contracts/common.md#clear-and-simple-design One operation combines destructive cleanup with registration release, using the existing release/recover protocol instead of making each caller order physical lookup around removal.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A missing scoped root fails its real observation without guessing an identity or weakening forget; ordinary unscoped calls acquire no protocol state, and original task/cleanup errors remain separate aggregate members when both fail.
   * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain capture timing, replacement and failure retention, unknown deferral, thrown undefined, successful recovery and passive trace limits; they do not claim an atomic namespace or retained directory handle.
   * @evidence contracts/portability.md#os-neutral-implementation Native realpath observes aliases before destruction and the captured map key avoids resolving a removed path; later namespace replacement remains outside the caller's ownership premise.
   * @evidence contracts/performance.md#efficient-algorithms Scoped capture performs one native physical lookup and map observation before the existing boundary safety scan; cleanup costs are delegated and the final identity comparison/map removal does not enumerate resources. Enabled tracing alone allocates an observer, projects five error properties and visits the scope's B boundaries, with synchronous encoding and IO proportional to their recorded text.
   * @evidence contracts/performance.md#reuse-equivalent-work The captured object proves only this release's original registration, never reusable compiler results; a reentrant replacement is retained rather than treated as equivalent ownership.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Failed cleanup retains its registration; unknown boundaries retain the original callback through FIFO recovery, whose failed callback remains queued. Immediate cleanup failure follows release's reporting contract without creating a new automatic retry, and successful cleanup drops only its original entry. An enabled observer shares that callback's lifetime; bounded trace storage has no resource-release authority.
   */
  export function releaseResource(
    fenceRoot: string,
    cleanup: () => void,
    taskFailure?: { error: unknown },
  ): void {
    const scope = current;
    const failure = (error: unknown): unknown =>
      taskFailure === undefined
        ? error
        : new AggregateError(
            [taskFailure.error, error],
            "ttsc: task and resource cleanup failed",
            { cause: taskFailure.error },
          );
    let root: string | undefined;
    try {
      root = scope === undefined ? undefined : physicalRoot(fenceRoot);
    } catch (error) {
      const combined = failure(error);
      OwnedSynchronousProcess.reportFailure(combined);
      throw combined;
    }
    const resource = root === undefined ? undefined : scope!.resources.get(root);
    const observe = !process.env.TTSC_E2E_TRACE
      ? undefined
      : (phase: string, error?: unknown): void => {
          try {
            const detail: Record<string, string | number | boolean | null | undefined> = {};
            if (error !== null && (typeof error === "object" || typeof error === "function"))
              for (const field of ["code", "errno", "syscall", "path", "dest"]) {
                const descriptor = Object.getOwnPropertyDescriptor(error, field);
                const value: unknown = descriptor?.value;
                if (typeof value === "string" || typeof value === "number")
                  detail[field] = value;
              }
            E2ETrace.capabilityResolution(phase, {
              taskToken: scope?.taskToken,
              resourceRoot: root ?? fenceRoot,
              ...detail,
            });
            if (phase === "source-resource-cleanup-started" && scope !== undefined)
              for (const [boundary, state] of scope.boundaries)
                E2ETrace.capabilityResolution("source-resource-cleanup-boundary", {
                  taskToken: scope.taskToken,
                  resourceRoot: root,
                  boundary,
                  retirement: state.state,
                });
          } catch {
            // Diagnostic reflection and IO cannot replace original cleanup.
          }
        };
    release(() => {
      observe?.("source-resource-cleanup-started");
      try {
        cleanup();
      } catch (error) {
        observe?.("source-resource-cleanup-threw", error);
        throw failure(error);
      }
      observe?.("source-resource-cleanup-returned");
      if (
        scope !== undefined &&
        root !== undefined &&
        scope.resources.get(root) === resource
      )
        scope.resources.delete(root);
    });
  }

  /**
   * Observe the installed task's native closure authority without throwing.
   *
   * @evidence contracts/common.md#principled-implementation Every boundary must be joined or never started before cleanup is safe.
   * @evidence contracts/common.md#clear-and-simple-design One task-local predicate serves every release consumer.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts No PID, clock or unavailable plugin result supplies closure proof.
   * @evidence contracts/common.md#meaningful-documentation Native prose identifies a nonthrowing authority observation.
   * @evidence contracts/portability.md#os-neutral-implementation The predicate inspects discriminants without native operations.
   * @evidence contracts/performance.md#efficient-algorithms The scan stops at the first unresolved boundary and takes at most the task boundary count.
   * @evidence contracts/performance.md#reuse-equivalent-work Mutable boundary state is inspected anew, not cached.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Observation allocates transient iteration state and acquires no resource.
   */
  export function canRelease(): boolean {
    if (current === undefined) return true;
    for (const boundary of current.boundaries.values())
      if (boundary.state === "unknown" || boundary.state === "pending")
        return false;
    return true;
  }

  /**
   * Retry deferred cleanup only with the original task and boundary capability.
   * The caller must supply actual qualified native closure, not a timer or PID
   * observation. No disk-only recovery capability is created by this API.
   *
   * @evidence contracts/common.md#principled-implementation Only the original scope and exact boundary token can apply qualified closure and retry original cleanup. Failed callbacks remain at the FIFO head, preserve their original thrown error and report it to the current asynchronous task owner before propagation.
   * @evidence contracts/common.md#clear-and-simple-design Certified settlement precedes FIFO cleanup, and a throwing callback remains at the head for retry.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Timers and PID observations cannot manufacture recovery authority; losing it leaves terminal quarantine.
   * @evidence contracts/common.md#meaningful-documentation Native prose states caller proof requirements and excludes disk-only recovery.
   * @evidence contracts/portability.md#os-neutral-implementation Settlement and callbacks own native filesystem effects; this coordinator preserves their actual failures.
   * @evidence contracts/performance.md#efficient-algorithms Settlement scans every still-owned guard and candidate before reporting cleanup failures; deferred callbacks run in FIFO order until the first callback failure.
   * @evidence contracts/performance.md#reuse-equivalent-work A previously certified identical outcome can retry failed cleanup without rerunning successful callbacks.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Successful callbacks are removed once; failures retain the original capability for another qualified retry.
   */
  export function recover(
    scope: Scope,
    boundaryToken: string,
    retirement: "joined" | "not-started",
  ): void {
    run(scope, () => {
      const boundary = scope.boundaries.get(boundaryToken);
      if (
        boundary === undefined ||
        (boundary.state !== "unknown" && boundary.state !== retirement)
      )
        throw new Error(
          "ttsc: recovery does not identify an unresolved native boundary",
        );
      settle(boundaryToken, retirement);
      if (!canRelease()) return;
      while (scope.deferred.length !== 0) {
        const cleanup = scope.deferred[0]!;
        try {
          cleanup();
        } catch (error) {
          OwnedSynchronousProcess.reportFailure(error);
          throw error;
        }
        scope.deferred.shift();
      }
    });
  }

  /**
   * Pending, malformed and unknown guards all prohibit collector reclamation.
   * An exact generation query ignores valid guards for different generations.
   *
   * @evidence contracts/common.md#principled-implementation Any pending, unknown or malformed guard prevents reclamation.
   * @evidence contracts/common.md#clear-and-simple-design One shared reader defines conservative protection for all collectors.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Invalid metadata is protected rather than interpreted as absence.
   * @evidence contracts/common.md#meaningful-documentation Native prose names the protected states and collector purpose.
   * @evidence contracts/portability.md#os-neutral-implementation Guard reading validates native directory identity and rejects links.
   * @evidence contracts/performance.md#efficient-algorithms Reading costs the guard-entry count and total metadata bytes; no PID queries are needed.
   * @evidence contracts/performance.md#reuse-equivalent-work Mutable guard directories are observed for each reclamation decision.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The observation holds no persistent handle and acquires no ownership.
   */
  export function isProtected(fenceRoot: string, generation?: string): boolean {
    const generations = protectedGenerations(fenceRoot);
    return (
      generations === undefined ||
      (generation === undefined
        ? generations.size !== 0
        : generations.has(generation))
    );
  }

  /**
   * Snapshot protected generations for one cooperative collector pass.
   * Undefined protects every generation because metadata is malformed or an
   * unleased shared input has no narrower generation. An empty set protects
   * none. Eviction must still recheck root protection before deleting objects.
   *
   * @evidence contracts/common.md#principled-implementation Valid guards select their exact generations; malformed or unleased records conservatively protect all generations rather than authorizing deletion.
   * @evidence contracts/common.md#clear-and-simple-design A set-or-universal result separates one metadata scan from the collector's per-record membership checks.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The snapshot supplies no native closure proof and cannot replace the final root guard check before object deletion.
   * @evidence contracts/common.md#meaningful-documentation Native prose specifies universal, empty and exact-generation meanings and the snapshot's deletion limitation.
   * @evidence contracts/portability.md#os-neutral-implementation The shared native guard reader validates directory identity and JSON records before generations enter the set.
   * @evidence contracts/performance.md#efficient-algorithms One scan costs guard count and metadata bytes; subsequent record membership avoids rescanning G guards for every one of L lease records.
   * @evidence contracts/performance.md#reuse-equivalent-work One collector pass shares this observed guard snapshot; later passes and final object-eviction admission make fresh native observations.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The returned set retains at most one token per observed guarded generation and holds no native handle; the collector owns this transient snapshot.
   */
  export function protectedGenerations(
    fenceRoot: string,
  ): ReadonlySet<string> | undefined {
    const generations = new Set<string>();
    for (const guard of readGuards(fenceRoot)) {
      if (guard.record?.generation === undefined) return undefined;
      generations.add(guard.record.generation);
    }
    return generations;
  }

  /**
   * Refuse unknown or malformed exclusive-key ownership. Pending guards remain
   * non-admitting wait states; callers must separately avoid acquisition and
   * binary adoption while isProtected remains true.
   *
   * @evidence contracts/common.md#principled-implementation Unknown or malformed exclusive-key ownership refuses admission; pending guards permit only the existing bounded waiter, whose acquisition and binary adoption remain blocked separately.
   * @evidence contracts/common.md#clear-and-simple-design Admission policy is separate from shared-cache collector protection.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Shared Go cache builds do not invoke this exclusive-key check; their separate leases remain concurrent.
   * @evidence contracts/common.md#meaningful-documentation Native prose identifies exclusive admission and its quarantine diagnostic.
   * @evidence contracts/portability.md#os-neutral-implementation Guard paths and retained native paths are reported using Node filesystem spellings.
   * @evidence contracts/performance.md#efficient-algorithms A guard-directory scan and metadata reads precede the first refusal.
   * @evidence contracts/performance.md#reuse-equivalent-work Fresh admission rechecks mutable metadata rather than reusing a prior availability observation.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The check acquires no ownership and leaves retained guards untouched.
   */
  export function assertAvailable(fenceRoot: string): void {
    for (const guard of readGuards(fenceRoot)) {
      if (guard.record?.state === "pending") continue;
      throw new Error(
        `ttsc: source resource is quarantined: ${guard.file}; ${guard.record?.reason ?? "native retirement metadata is unreadable or invalid"}; retained paths: ${JSON.stringify(guard.record?.retainedPaths ?? [fenceRoot])}; qualified native closure or operator-confirmed external closure is required`,
      );
    }
  }

  /**
   * Explain retained input ownership in a bounded wait's failure diagnostic.
   * This reports observed guard bytes and grants no process-closure authority.
   *
   * @evidence contracts/common.md#principled-implementation The first observed guard supplies its state, original reason and exact retained paths without inferring lifetime from PID or elapsed time.
   * @evidence contracts/common.md#clear-and-simple-design One optional diagnostic lets bounded waiters preserve the same metadata interpretation as collector and admission checks.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Pending diagnostic publication does not manufacture a safe outcome or make a timeout reclaim inputs.
   * @evidence contracts/common.md#meaningful-documentation Native prose states the reporting purpose and explicitly excludes closure authority.
   * @evidence contracts/portability.md#os-neutral-implementation The shared native reader validates guard directories; JSON retains actual path spellings in the diagnostic.
   * @evidence contracts/performance.md#efficient-algorithms One guard scan and path-byte formatting occur on diagnostic demand, outside successful waiter polls.
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Mutable guard diagnostics are observed anew at the failure boundary rather than cached across transitions.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The returned string holds no process or directory capability; guard and input retention remain unchanged.
   */
  export function describeProtection(fenceRoot: string): string | undefined {
    const guard = readGuards(fenceRoot)[0];
    if (guard === undefined) return undefined;
    return `native input ownership ${guard.record?.state ?? "invalid"} at ${guard.file}: ${guard.record?.reason ?? "native closure remains unconfirmed"}; retained paths: ${JSON.stringify(guard.record?.retainedPaths ?? [fenceRoot])}`;
  }

  /**
   * Refuse ownership completion or stealing while any native guard remains.
   *
   * @evidence contracts/common.md#principled-implementation Any relevant guard prohibits completion or stealing; exact differing generations do not block their independent lease release.
   * @evidence contracts/common.md#clear-and-simple-design One generation filter serves key retirement and shared Go record cleanup.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Malformed metadata cannot authorize generation-based bypass.
   * @evidence contracts/common.md#meaningful-documentation Native prose describes completion and stealing refusal.
   * @evidence contracts/portability.md#os-neutral-implementation The shared reader validates native guard directories and preserves I/O failures.
   * @evidence contracts/performance.md#efficient-algorithms The check scans guard entries and metadata until a relevant protection is found.
   * @evidence contracts/performance.md#reuse-equivalent-work Reclamation authority is observed anew rather than cached across filesystem mutations.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Refusal leaves the original resources and guards owned; the check holds no persistent handle.
   */
  export function assertReleasable(
    fenceRoot: string,
    generation?: string,
  ): void {
    for (const guard of readGuards(fenceRoot)) {
      if (
        generation !== undefined &&
        guard.record?.generation !== undefined &&
        guard.record.generation !== generation
      )
        continue;
      throw new Error(
        `ttsc: native input ownership remains protected at ${guard.file}; retained paths: ${JSON.stringify(guard.record?.retainedPaths ?? [fenceRoot])}`,
      );
    }
  }

  /**
   * Refuse recursive clean when a selected physical tree or its ancestors
   * contain a guard. Terminal links are not followed. Scans acquire no held
   * directory identity; callers retain the existing deletion-race premise.
   *
   * @evidence contracts/common.md#principled-implementation A whole-tree and ancestor check prevents recursive deletion of guarded inputs while terminal links remain unlinkable.
   * @evidence contracts/common.md#clear-and-simple-design An iterative directory stack and ancestor walk separate descendant guards from enclosing ownership.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Links are not traversed and unknown guards cannot be treated as safe deletion targets.
   * @evidence contracts/common.md#meaningful-documentation Native prose states terminal-link behavior and the existing deletion-race limitation.
   * @evidence contracts/portability.md#os-neutral-implementation Node lstat distinguishes actual terminal links; callers supply physically pinned ancestor paths.
   * @evidence contracts/performance.md#efficient-algorithms The scan costs visited directories and guard metadata bytes; full traversal is necessary because guards may exist in any selected descendant.
   * @evidence contracts/performance.md#reuse-equivalent-work Each clean transaction observes mutable guards; no cross-clean index supplies stale authority.
   * @evidence contracts/performance.md#bound-retention-and-release-resources Only path strings and a directory stack are retained during the call; no held directory identity prevents later replacement.
   */
  export function assertCleanable(target: string): void {
    const resolved = path.resolve(target);
    let terminalLink = false;
    try {
      terminalLink = fs.lstatSync(resolved).isSymbolicLink();
    } catch (error) {
      if (!missing(error)) throw error;
    }
    let ancestor = terminalLink ? path.dirname(resolved) : resolved;
    for (;;) {
      assertReleasable(ancestor);
      const parent = path.dirname(ancestor);
      if (parent === ancestor) break;
      ancestor = parent;
    }
    const pending = terminalLink ? [] : [resolved];
    while (pending.length !== 0) {
      const directory = pending.pop()!;
      let stats: fs.Stats;
      try {
        stats = fs.lstatSync(directory);
      } catch (error) {
        if (missing(error)) continue;
        throw error;
      }
      if (!stats.isDirectory() || stats.isSymbolicLink()) continue;
      assertReleasable(directory);
      for (const entry of fs.readdirSync(directory, { withFileTypes: true }))
        if (
          entry.isDirectory() &&
          !entry.isSymbolicLink() &&
          entry.name !== GUARD_DIRECTORY
        )
          pending.push(path.join(directory, entry.name));
    }
  }
}

/**
 * A registered physical input root and its optional exact source/lease
 * generation.
 *
 * Optional generation and nonce preserve existing owner authority while path
 * lists explain retained inputs. One resource combines its root, diagnostic
 * input paths and exact generation identity. A root entry never equates PID
 * identity with native closure. Field comments identify ownership and
 * diagnostic purpose. Native paths are strings whose physical root was resolved
 * at registration. This type executes no algorithm. The type grants no
 * equivalent-result reuse. Runtime scope and boundary owners govern the
 * represented resource lifetime.
 */
interface Resource {
  /** Observed physical directory holding the guard. */
  fenceRoot: string;

  /** Exact input spellings disclosed by the original owner. */
  retainedPaths: string[];

  /** Held key or Go lease generation, absent for unleased shared roots. */
  generation?: string;

  /** Original key completion capability, absent for Go roots. */
  completionNonce?: string;
}

/**
 * One original command admission and its exact input-guard publication set.
 *
 * State separates unresolved admission from qualified joined or never-started
 * closure. One boundary stores its token, immutable snapshot and owned guard
 * paths. Unknown is represented explicitly instead of converted to successful
 * cleanup. Native prose identifies per-command ownership and publication scope.
 * File strings address native guard entries; classification comes from the
 * native owner. This type declares state without scanning or publishing. A
 * boundary identity cannot be reused for another admission. The task owner
 * retains this record and its input snapshot until qualified completion or
 * terminal quarantine.
 */
interface Boundary {
  /** Original command admission token. */
  token: string;

  /** Explicit closure classification; unresolved states prohibit cleanup. */
  state: "pending" | "joined" | "not-started" | "unknown";

  /** Native owner diagnosis when closure is unknown. */
  reason?: string;

  /** Resource snapshot taken before native command admission. */
  resources: Resource[];

  /** Exclusively created guard entries still owned, including partial writes. */
  files: string[];

  /** Exclusively created update candidates whose removal has not succeeded. */
  candidates: Set<string>;
}

/**
 * Cooperating-version metadata that preserves input ownership without granting
 * recovery authority.
 *
 * Version, exact task/boundary identity and pending/unknown states distinguish
 * the publication contract. One JSON record carries diagnostic paths and
 * optional exact generation identity. Neither process identity nor a timestamp
 * can authorize reclamation from these bytes. Native prose explains cooperation
 * and the lack of recovery authority. Native path strings preserve diagnostic
 * spellings; guard directory identity is validated separately. This type
 * executes no metadata reads or scans. Guard identity does not imply
 * compiler-result equivalence. Publication and qualified settlement own record
 * acquisition and deletion; unknown records have no age expiry.
 */
interface GuardRecord {
  /** Cooperative JSON protocol revision. */
  version: 1;

  /** Original request identity; this string alone grants no recovery. */
  taskToken: string;

  /** Exact command admission identity. */
  boundaryToken: string;

  /** Both persisted states prohibit reclamation. */
  state: "pending" | "unknown";

  /** Original native-owner refusal, when diagnostic publication succeeded. */
  reason?: string;

  /** Exact retained input paths for terminal diagnosis. */
  retainedPaths: string[];

  /** Held key/lease generation, absent for unleased shared inputs. */
  generation?: string;

  /** Original source-key completion identity, absent for Go roots. */
  completionNonce?: string;
}

/**
 * Encode an opaque identity into a fixed safe guard filename component.
 *
 * SHA-256 hex encoding avoids path separators in arbitrary task tokens. One
 * standard hash operation owns filename encoding. No consumer or expected
 * result is special-cased. Native prose states the filename purpose rather than
 * a security certificate. Hex output is a filename component on supported Node
 * filesystems. Hashing costs token bytes and produces fixed-size output.
 * Repeated hashing is local identity encoding; no effectful work is cached. The
 * temporary hash object holds no persistent resource.
 */
function digest(token: string): string {
  return crypto.createHash("sha256").update(token).digest("hex");
}

/**
 * Recognize only filesystem absence codes accepted by conservative guard
 * lookup.
 *
 * ENOENT and ENOTDIR denote absent path components; other errors must remain
 * visible. One structural code predicate supports unknown error values.
 * Permission and malformed metadata errors cannot be mistaken for absence.
 * Native prose names the limited absence interpretation. Node native error
 * codes express absence without OS-name branching. A fixed set of property/code
 * checks takes constant work. Each actual error is classified independently.
 * The predicate retains no handles or historical error registry.
 */
function missing(error: unknown): boolean {
  return (
    error !== null &&
    typeof error === "object" &&
    "code" in error &&
    (error.code === "ENOENT" || error.code === "ENOTDIR")
  );
}

/**
 * Resolve an existing native root to the physical spelling used by its
 * registration.
 *
 * Native realpath observes actual filesystem aliases before map indexing. One
 * Node filesystem primitive owns canonical spelling. Lexical path normalization
 * alone is not treated as physical identity. Native prose explains the
 * existing-root premise. realpath.native resolves physical identity without
 * assuming a platform case rule. Native ancestor resolution and path text drive
 * cost. Mutable native identity is resolved per registration or lookup. The
 * operation holds no directory handle and cannot prevent later namespace
 * replacement.
 */
function physicalRoot(root: string): string {
  return fs.realpathSync.native(path.resolve(root));
}

/**
 * Validate or create the ordinary native directory holding one root's guards.
 *
 * Lstat rejects links and resolved-parent identity keeps metadata under the
 * selected physical root. One helper centralizes directory creation and
 * boundary validation. Only absence may omit lookup; unsafe aliases and I/O
 * failures do not authorize deletion. Native prose explains guard containment
 * and lookup/create behavior. Native realpath and lstat inspect actual links
 * and parent identity on supported filesystems. Directory creation and metadata
 * resolution scale with ancestor depth and path text. Native observations are
 * refreshed because namespace identity can change. No directory handle is
 * retained; the existing namespace ownership premise remains necessary.
 */
function guardDirectory(root: string, create: boolean): string | undefined {
  const directory = path.join(root, GUARD_DIRECTORY);
  if (create) fs.mkdirSync(directory, { recursive: true });
  let stats: fs.Stats;
  try {
    stats = fs.lstatSync(directory);
  } catch (error) {
    if (!create && missing(error)) return undefined;
    throw error;
  }
  if (
    !stats.isDirectory() ||
    stats.isSymbolicLink() ||
    path.dirname(fs.realpathSync.native(directory)) !== physicalRoot(root)
  )
    throw new Error(
      `ttsc: unsafe native retirement guard directory: ${directory}`,
    );
  return directory;
}

/**
 * Publish one boundary's metadata with exclusive initial creation or atomic
 * replacement.
 *
 * Exclusive open owns the actual descriptor and registers an initial file
 * before writing; a failed open never permits pathname deletion. Later updates
 * own a unique candidate until successful rename transfers it to the guard. One
 * serializer and descriptor-based publication path preserve task, boundary and
 * resource identity; a private aggregate distinguishes write errors from
 * ownership cleanup failures. Failed unknown replacement leaves the previous
 * guard conservative rather than authorizing release. Native prose
 * distinguishes initial admission publication from later diagnostics. Node
 * exclusive writes and rename expose real filesystem refusal; no cross-platform
 * shell syntax is used. Serialization and writes scale with token and retained
 * path bytes. Effectful publications run anew for each native boundary
 * transition. Close is attempted once after writing and its failure is never
 * treated as closure. Initial rollback belongs to begin; update candidates
 * enter the owned set after exclusive open and leave it only on successful
 * rename or removal. Failed candidate removal retains exact authority for
 * qualified recovery. Write, close, rename and removal failures remain original
 * aggregate members; cleanup failures are reported across legacy catches.
 */
function writeGuard(
  file: string,
  taskToken: string,
  boundary: Boundary,
  resource: Resource,
  state: GuardRecord["state"],
  initial = false,
): void {
  const bytes = JSON.stringify({
    version: 1,
    taskToken,
    boundaryToken: boundary.token,
    state,
    reason: boundary.reason,
    ...resource,
  });
  const operations = current?.guardFileOperations ?? fs;
  const candidate = initial
    ? file
    : `${file}.${crypto.randomBytes(16).toString("hex")}.tmp`;
  // Open is the ownership transition. An EEXIST refusal must never cause
  // deletion of the pathname this boundary did not create.
  const descriptor = operations.openSync(candidate, "wx");
  if (initial) boundary.files.push(file);
  else boundary.candidates.add(candidate);
  const failures: unknown[] = [];
  let cleanupFailed = false;
  let published = false;
  try {
    operations.writeFileSync(descriptor, bytes);
  } catch (error) {
    failures.push(error);
  }
  try {
    operations.closeSync(descriptor);
  } catch (error) {
    failures.push(error);
    cleanupFailed = true;
  }
  if (!initial) {
    if (failures.length === 0) {
      try {
        operations.renameSync(candidate, file);
        published = true;
        boundary.candidates.delete(candidate);
      } catch (error) {
        failures.push(error);
      }
    }
    if (!published) {
      try {
        operations.rmSync(candidate, { force: true });
        boundary.candidates.delete(candidate);
      } catch (error) {
        failures.push(error);
        cleanupFailed = true;
      }
    }
  }
  if (failures.length !== 0)
    throw new GuardPublicationError(
      failures,
      `ttsc: native guard file publication failed at ${candidate}; retained paths: ${JSON.stringify(resource.retainedPaths)}`,
      cleanupFailed,
    );
}

/**
 * Original publication errors plus the distinction between failed writing and
 * failed ownership cleanup. Only cleanup failures need an additional report
 * across legacy unavailable conversion; no native process was admitted merely
 * by creating a guard. The array preserves original error references, and the
 * caller supplies exact paths in the message. This private classification
 * acquires no resources and cannot authorize recovery or cached result reuse.
 */
class GuardPublicationError extends AggregateError {
  /** Whether a real close or owned-candidate removal refused cleanup. */
  readonly cleanupFailed: boolean;

  constructor(errors: unknown[], message: string, cleanupFailed: boolean) {
    super(errors, message);
    this.cleanupFailed = cleanupFailed;
  }
}

/**
 * Observe all root guards conservatively, treating invalid entries as
 * protected.
 *
 * Version, token-derived filename, states and field shapes validate the
 * cooperative JSON protocol. A single directory map serves admission,
 * collectors and clean. Unexpected entries or parse failures do not become
 * empty ownership. Native prose identifies conservative parsing and
 * missing-directory behavior. Native directory validation rejects aliased
 * metadata roots; entry types and actual JSON bytes are observed. Reading costs
 * guard count and total metadata bytes, including validation hashing. Mutable
 * guards are reread for each ownership decision. Only transient entry/JSON/path
 * data are retained; this reader grants no recovery capability.
 */
function readGuards(
  root: string,
): Array<{ file: string; record?: GuardRecord }> {
  const directory = guardDirectory(root, false);
  if (directory === undefined) return [];
  return fs.readdirSync(directory, { withFileTypes: true }).map((entry) => {
    const file = path.join(directory, entry.name);
    if (!entry.isFile() || entry.isSymbolicLink()) return { file };
    try {
      const record = JSON.parse(
        fs.readFileSync(file, "utf8"),
      ) as Partial<GuardRecord> | null;
      if (
        record === null ||
        record.version !== 1 ||
        typeof record.taskToken !== "string" ||
        record.taskToken.length === 0 ||
        typeof record.boundaryToken !== "string" ||
        record.boundaryToken.length === 0 ||
        entry.name !==
          `${digest(record.taskToken)}-${digest(record.boundaryToken)}.json` ||
        (record.reason !== undefined && typeof record.reason !== "string") ||
        (record.state !== "pending" && record.state !== "unknown") ||
        !Array.isArray(record.retainedPaths) ||
        !record.retainedPaths.every((entry) => typeof entry === "string") ||
        (record.generation !== undefined &&
          typeof record.generation !== "string") ||
        (record.completionNonce !== undefined &&
          typeof record.completionNonce !== "string")
      )
        return { file };
      return { file, record: record as GuardRecord };
    } catch {
      return { file };
    }
  });
}

/**
 * Describe unknown retirement with its boundary and exact retained input paths.
 *
 * The original boundary snapshot supplies paths without guessing a process
 * lifetime. One error message states reason, retained paths and required
 * qualified recovery. An error message does not certify closure or successful
 * cleanup. Native prose identifies diagnostic purpose. JSON encoding preserves
 * native path strings in the diagnostic. Formatting scans retained paths and
 * their text bytes. Diagnostics reflect the current boundary reason, without
 * caching a previous failure. The returned string owns no native handle or
 * cleanup authority.
 */
function diagnostic(boundary: Boundary): string {
  return `ttsc: native retirement is unknown for ${boundary.token}: ${boundary.reason}; retained paths: ${JSON.stringify(boundary.resources.flatMap((resource) => resource.retainedPaths))}; qualified native closure or operator-confirmed external closure is required`;
}

const GUARD_DIRECTORY = ".ttsc-native-retirements";
let current: SourceNativeRetirement.Scope | undefined;

