   */
  export function select(
    resolution: {
      manifest: string;
      projectContext: string | null;
      plugins: readonly {
        binary: string;
        capabilities: Record<string, boolean>;
      }[];
    },
    capability: string,
  ): ITtscCapabilityPlugin[] {
    return resolution.plugins
      .filter(
        (plugin) =>
          plugin.binary !== "" && plugin.capabilities[capability] === true,
