import { createRequire } from "node:module";
import path from "node:path";

import type { ITtscParsedProjectConfig } from "../../../structures/internal/ITtscParsedProjectConfig";
import { PluginPackageResolution } from "./PluginPackageResolution";
import { moduleResolutionBaseSelects } from "./moduleResolutionBaseSelects";

/**
 * Return config ancestry and package-discovery manifest inputs, including
 * missing nearer candidates that could redirect the selected package later.
 *
 * @evidence contracts/common.md#principled-implementation Config ancestry, lexical selection and missing config candidates influence selection; automatic discovery additionally observes nearest manifest and dependency search candidates through the selecting root. The project reader separately states whether these config observations are complete.
 * @evidence contracts/common.md#clear-and-simple-design The collector obtains package resolution from its owner and assembles universal loader inputs, leaving source Program dependencies to the native reference graph.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Missing candidates are real future selection inputs; farther unconsulted roots are not added as compensating guesses, and explicit plugin lists can avoid automatic discovery.
 * @evidence contracts/common.md#meaningful-documentation Native JSDoc identifies ancestry and missing discovery candidates; the private helper explains the selected-root stopping condition, with paragraph/tag separation following the documentation skill.
 * @evidence contracts/portability.md#os-neutral-implementation Native resolve/dirname/join and Node createRequire search paths construct OS-neutral host inputs; package-name slash splitting is package-specifier grammar, not filesystem parsing.
 * @evidence contracts/performance.md#efficient-algorithms Config paths are natively normalized and indexed; discovery additionally walks nearest-manifest ancestors, reads/parses manifest bytes and resolves each direct dependency through Node search roots and physical candidate checks. Candidate generation/query work can repeat before Set deduplication. Final sorting costs depend on unique input count and path-text comparisons; native metadata, path/topology and manifest/name bytes remain part of the cost.
 * @evidence contracts/performance.md#reuse-equivalent-work The operation assembles one shared universal input population for the load; identical candidate paths are retained once by the Set, while current filesystem resolution is not cached here.
 *
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The Set and returned array belong to this call, with no cross-call retention or acquired open resource.
 */
export function collectProjectHostInputs(
  project: ITtscParsedProjectConfig,
  includePluginDiscovery: boolean = true,
): string[] {
  const inputs = new Set<string>(
    [...project.configPaths, ...(project.configInputs ?? [])].map((file) =>
      path.resolve(file),
    ),
  );
  if (!includePluginDiscovery) return [...inputs].sort();
  const manifestCandidates =
    PluginPackageResolution.collectNearestPackageJsonCandidates(project.root);
  for (const candidate of manifestCandidates) inputs.add(candidate);
  const manifest = manifestCandidates.find(
    PluginPackageResolution.existingFile,
  );
  if (manifest !== undefined) {
    const projectManifest =
      PluginPackageResolution.readPackageManifest(manifest);
    if (projectManifest !== undefined) {
      const projectRoot = path.dirname(manifest);
      for (const dependency of PluginPackageResolution.directDependencyNames(
        projectManifest,
      )) {
        const dependencyManifest =
          PluginPackageResolution.resolveDependencyPackageJson(
            dependency,
            projectRoot,
          );
        for (const candidate of collectDependencyManifestCandidates(
          dependency,
          manifest,
          dependencyManifest,
        )) {
          inputs.add(candidate);
        }
        if (dependencyManifest !== undefined) {
          inputs.add(path.resolve(dependencyManifest));
        }
      }
    }
  }
  return [...inputs].sort();
}

/**
 * Record package manifests whose later appearance can redirect discovery: the
 * manifest of each search root's package directory, through the root that
 * selects the manifest discovery read (`moduleResolutionBaseSelects`), or every
 * root when none was found.
 */
function collectDependencyManifestCandidates(
  packageName: string,
  parentFile: string,
  selectedManifest: string | undefined,
): string[] {
  const out: string[] = [];
  for (const searchPath of createRequire(parentFile).resolve.paths(
    packageName,
  ) ?? []) {
    const packageDirectory = path.join(searchPath, ...packageName.split("/"));
    out.push(path.join(packageDirectory, "package.json"));
    if (moduleResolutionBaseSelects(packageDirectory, selectedManifest, []))
      break;
  }
  return out;
}

ttsc/src/plugin/internal/load/composePlu:
import type { ITtscPlugin } from "../../../structures/ITtscPlugin";
import type { ITtscProjectPluginConfig } from "../../../structures/ITtscProjectPluginConfig";
import type { ProjectPluginEntries } from "./ProjectPluginEntries";

/**
 * Resolve descriptor composition from the original ordered plugin records.
 *
 * One-hop redirects inherit source, contributors and host capabilities from
 * their aggregate without cascading through another redirected descriptor.
 * Conflicting aggregates, reciprocal cycles and target-owned contributors are
 * rejected before any Go producer is built. Input records are not mutated.
 *
 * @evidence contracts/common.md#principled-implementation Uses original descriptor identities for every alias edge, detects reciprocal cycles and conflicting owners, and copies only the selected aggregate host fields; nontransitive composition cannot read a previously redirected answer.
 * @evidence contracts/common.md#clear-and-simple-design Pure composition owns redirects while descriptor evaluation and native compilation remain in loadProjectPlugins; the private matcher compares only exact declared name or transform specifier.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts No plugin-name exception or guessed source identity permits a redirect; incompatible target contributors and ambiguous aggregate owners fail with their existing diagnostics.
 * @evidence contracts/common.md#meaningful-documentation Native prose states one-hop inheritance, original-record lookup, nonmutation and rejection before native build; inline comments explain contributor and capability ownership.
 * @evidence contracts/performance.md#efficient-algorithms For n plugins, a aggregates and at most k aliases per aggregate, initial wrapper construction/filtering costs O(n), including the no-aggregate path's returned copy. Validation scans all aliases, reciprocal-cycle checks perform O(a squared times k) alias comparisons and redirect selection performs O(n times a times k) comparisons. Trimming and string equality additionally depend on alias/name/specifier lengths, and redirected record spreads copy their enumerable fields. Direct scans preserve original-record one-hop selection; the implementation imposes no population bound and does not claim constant-cost string comparisons.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Composition uses this invocation's original descriptors and entry aliases; it owns no completed-answer cache or cross-request sharing.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Initial wrappers for all plugins, the selected aggregate array, matching-reference arrays and redirected shallow records are invocation-local or returned to the caller; shared contributor/capability objects remain borrowed descriptor values. No history or live handle is acquired.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation This body compares declared names and transform specifiers as exact aliases and transfers source/contributor/capability values without resolving a path, opening a file or launching a process. Native source identity and building remain loader responsibilities.
 */
export function composePluginSources(
  entries: readonly ProjectPluginEntries.ProjectPluginEntry[],
  plugins: readonly ITtscPlugin[],
): ITtscPlugin[] {
  const aggregates = plugins
    .map((plugin, index) => ({ index, plugin }))
    .filter(({ plugin }) => Array.isArray(plugin.composes));
  if (aggregates.length === 0) {
    return [...plugins];
  }
  for (const { plugin } of aggregates) {
    for (const target of plugin.composes!) {
      if (typeof target !== "string" || target.trim() === "") {
        throw new Error(
          `ttsc: plugin "${plugin.name}" has an invalid "composes" target; ` +
            `targets must be non-empty plugin names or transform specifiers`,
        );
      }
    }
  }
  // Composition is intentionally one hop only: A.composes=[B] sends B to A's
  // binary, but if B.composes=[C] then C uses B's original source and does NOT
  // cascade to A. Detect cycles (A.composes=[B] && B.composes=[A]) and throw,
  // otherwise the silent reswap below would mis-route both plugins.
  for (const { index: i, plugin: a } of aggregates) {
    for (const { index: j, plugin: b } of aggregates) {
      if (i === j) continue;
      const aTransform = entries[i]?.config.transform;
      const bTransform = entries[j]?.config.transform;
      const aComposesB = a.composes!.some((alias) =>
        matchesPluginAlias(alias, b, bTransform),
      );
      const bComposesA = b.composes!.some((alias) =>
        matchesPluginAlias(alias, a, aTransform),
      );
      if (aComposesB && bComposesA) {
        throw new Error(
          `ttsc: plugin composes cycle detected between "${a.name}" and "${b.name}"; ` +
            `each plugin lists the other in its "composes" array — composition is one hop only, not transitive`,
        );
      }
    }
  }
  return plugins.map((plugin, index) => {
    const transform = entries[index]?.config.transform;
    const matchingAggregates = aggregates.filter(
      ({ index: aggregateIndex, plugin: aggregatePlugin }) =>
        aggregateIndex !== index &&
        aggregatePlugin.composes!.some((alias) =>
          matchesPluginAlias(alias, plugin, transform),
        ),
    );
    if (matchingAggregates.length > 1) {
      throw new Error(
        `ttsc: plugin "${plugin.name}" is composed by multiple aggregate plugins; ` +
          `each plugin entry can be redirected to only one aggregate native host`,
      );
    }
    const aggregate = matchingAggregates[0];
    if (aggregate === undefined) {
      return plugin;
    }
    // A composed plugin's source is rerouted to the aggregate's binary,
    // so its own `contributors` would link into a different host than
    // it was authored against. The "one binary" guarantee in the
    // protocol doc holds only when the composed plugin defers entirely
    // to the aggregate; reject early instead of silently producing two
    // diverging binaries.
    if (plugin.contributors && plugin.contributors.length > 0) {
      throw new Error(
        `ttsc: plugin "${plugin.name}" is composed by "${aggregate.plugin.name}" but declares its own "contributors"; ` +
          `move the contributors onto the aggregate plugin or drop the composes redirect`,
      );
    }
    return {
      ...plugin,
      source: aggregate.plugin.source,
      contributors: aggregate.plugin.contributors,
      // The composed plugin's runtime BINARY is the aggregate's binary,
      // so the CLI surface (which flags the sidecar parses) is the
      // aggregate's. Inherit `capabilities` from the aggregate so a
      // capability the aggregate declares — e.g. threadingArgs — does
      // not get silently dropped just because the composed entry's own
      // descriptor omitted it. An absent aggregate declaration is also its
      // own CLI contract; a redirected library cannot certify the new host.
      capabilities: aggregate.plugin.capabilities,
    };
  });
}

function matchesPluginAlias(
  alias: string,
  plugin: ITtscPlugin,
  transform: ITtscProjectPluginConfig["transform"],
): boolean {
  return (
    alias === plugin.name ||
    (typeof transform === "string" && alias === transform)
  );
}

