import { spawn } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { Worker } from "node:worker_threads";

import { E2ETrace } from "../../../internal/E2ETrace";
import { OwnedSynchronousProcess } from "../../../internal/OwnedSynchronousProcess";
import { SourceNativeRetirement } from "../../../internal/SourceNativeRetirement";
import { SourceBuildCacheLayout } from "./SourceBuildCacheLayout";

/**
 * Coordination between Go builds that use ttsc's own Go object cache and the
 * opportunistic pruning of that cache.
 *
 * Coordinated build and admitted maintenance attempts publish records in
 * private cache directories and attempt heartbeat startup. Pruning skips the
 * cohort a live build may still read, and an abandoned record expires after a
 * grace period (one hour for builds, one minute for maintenance). Byte-read
 * failure still permits age-based expiry when metadata is readable; unknown age
 * or failed clock-skew repair defers pruning conservatively. This is
 * opportunistic coordination rather than an absolute proof that every abandoned
 * record can be reclaimed.
 *
 * Scoped native boundaries add independent guards: their exact build leases
 * survive age/PID-based collection until qualified closure. Shared cache guards
 * prevent eviction and clean without serializing independent builders.
 * Maintenance freshness remains separate so an old maintenance record cannot
 * block concurrent builds indefinitely under an unrelated native guard.
 *
 * Age-based expiry for unguarded records assumes a running task can keep its
 * heartbeat fresh. A prolonged suspension or failed heartbeat after startup can
 * outlast the grace; elapsed time alone does not prove that its Go process has
 * ended.
 *
 * @evidence contracts/common.md#principled-implementation Exact scoped native guards supersede build-lease expiry until certified closure while shared Go admission remains concurrent. Published completion and refreshed mtimes implement task policy: build grace is one hour and maintenance grace one minute. Unknown metadata age defers pruning, while unreadable bytes can still expire by observed age; grace expiry is not process-absence proof after heartbeat failure.
 * @evidence contracts/common.md#clear-and-simple-design Root validation, task publication and collection form one coordination boundary used by builders and maintenance.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Time windows are documented coordination policy; worker/process alternatives address actual synchronous-build and native spawn constraints rather than known fixtures.
 * @evidence contracts/common.md#meaningful-documentation Native prose explains lease purpose and conservative unreadable/clock-skew limits; function and member comments describe release and startup outcomes.
 * @evidence contracts/portability.md#os-neutral-implementation Native filesystem metadata and Node worker/process APIs provide the boundary without assuming an OS's case policy.
 *
 * @evidenceExclude contracts/performance.md#efficient-algorithms The namespace groups member-owned processing strategies and performs no scan itself.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Namespace membership establishes no computed-result identity.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Actual records and workers are owned by create/finish operations rather than the namespace declaration.
 */
export namespace GoBuildCacheCoordination {
  /** Directory of the cache holding one record per running Go build. */
  export const GO_BUILD_CACHE_LEASE_DIR = ".ttsc-build-leases";

  /** Directory of the cache holding one record per running maintenance pass. */
  export const GO_BUILD_CACHE_MAINTENANCE_DIR = ".ttsc-maintenance";

  const GO_BUILD_CACHE_COORDINATION_STALE_MS = 60 * 60 * 1000;

  const GO_BUILD_CACHE_MAINTENANCE_STALE_MS = 60 * 1000;

  const GO_BUILD_CACHE_COORDINATION_CLOCK_SKEW_MS = 5 * 60 * 1000;

  const GO_BUILD_CACHE_COORDINATION_HEARTBEAT_MS = 5_000;

  /**
   * Create the owned Go cache and return its observed physical directory
   * spelling.
   *
   * The leaf may be user-controlled inside `node_modules/.cache`; accepting a
   * symlink or junction there would let LRU deletion escape into an arbitrary
   * two-hex directory. Returning the canonical spelling also keeps the build,
   * leases, and maintenance address that spelling if an ancestor alias moves.
   * These sequential observations do not retain a directory handle or prevent
   * later physical-path replacement.
   *
   * @evidence contracts/common.md#principled-implementation lstat rejects aliased leaves and physical parent validation confines the returned Go root to its resolved parent before deletion or builds use it.
   * @evidence contracts/common.md#clear-and-simple-design Validation returns one physical spelling or throws, so consumers do not carry partially safe paths.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Native filesystem facts establish ownership boundaries, not guessed cache names or foreign API mutation.
   * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain project-controlled leaf risk, ancestor-alias spelling resolution and the absence of a retained directory handle.
   * @evidence contracts/portability.md#os-neutral-implementation Native realpath/lstat preserve actual identity; no Windows-name check supplies volume case semantics.
   * @evidence contracts/performance.md#efficient-algorithms Fixed metadata calls validate the leaf; path resolution and recursive creation scale with ancestor depth.
   *
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Mutable aliases are checked per operation rather than cached without an invalidation witness.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Validation opens no persistent handle and owns no cache entries.
   */
  export function canonicalGoBuildCacheRoot(root: string): string {
    fs.mkdirSync(root, { recursive: true });
    const physicalParent = fs.realpathSync.native(path.dirname(root));
    const stats = fs.lstatSync(root);
    if (!stats.isDirectory() || stats.isSymbolicLink()) {
      throw new Error(`ttsc: unsafe Go build cache root: ${root}`);
    }
    const physicalRoot = fs.realpathSync.native(root);
    if (path.dirname(physicalRoot) !== physicalParent) {
      throw new Error(`ttsc: Go build cache root escaped its parent: ${root}`);
    }
    return physicalRoot;
  }

  /**
   * One published build or maintenance record, owned by this process.
   *
   * @evidence contracts/common.md#principled-implementation Record identity and lifecycle callbacks represent the same owned task; completion cannot be mistaken for another task's lease.
   * @evidence contracts/common.md#clear-and-simple-design The interface exposes only its published path, startup and terminal release.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The callbacks are explicit ownership operations, not mutation of external worker APIs.
   * @evidence contracts/common.md#meaningful-documentation Member prose explains terminal completion, startup failure and synchronous-build purpose with blank-separated fields.
   * @evidence contracts/portability.md#os-neutral-implementation The path denotes a native coordination file while callbacks hide worker versus process startup differences.
   *
   * @evidenceExclude contracts/performance.md#efficient-algorithms This interface declares an ownership capability and chooses no algorithm.
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work The interface is not a computed-result coordinator.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Actual acquisition and release are performed by the factory and callbacks, not this type declaration.
   */
  export interface GoBuildCacheCoordinationRecord {
    /** Path of the record file. */
    file: string;

    /**
     * Request heartbeat shutdown, attempt to mark the record complete, then
     * attempt deletion. Synchronous finish does not join shutdown; an explicit
     * worker scope tracks actual exit/close and termination failures for its
     * asynchronous owner to join. Ordinary failures may leave a task or file. A
     * successful completion write prevents a failed delete from leaving the
     * task active; if both writes and deletion fail, stale-timeout handling
     * remains the collector's fallback.
     *
     * @evidence contracts/common.md#principled-implementation The terminal callback requests refresher shutdown and attempts complete-state publication before removal; only successful publication records completion if deletion fails, and actual termination remains tracked for an opted-in asynchronous owner rather than joined by this synchronous callback.
     * @evidence contracts/common.md#clear-and-simple-design Release is one idempotent operation and prevents later heartbeat restart.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts Completion persistence addresses a real failed-unlink state rather than simulating successful cleanup.
     * @evidence contracts/common.md#meaningful-documentation Native prose states ordering and its failure consequence, separated from tags.
     * @evidence contracts/portability.md#os-neutral-implementation Native worker termination and file removal failures are encapsulated by the owning callback.
     * @evidence contracts/performance.md#efficient-algorithms Release performs task-control and guard metadata checks before atomic record cleanup, without scanning cache object contents; costs include stored path and host/PID metadata bytes and native filesystem resolution.
     *
     * @evidenceExclude contracts/performance.md#reuse-equivalent-work This callback closes one owned task, not a reusable computation.
     *
     * @evidence contracts/performance.md#bound-retention-and-release-resources Finish requests worker termination or child kill, then attempts completion publication/removal only when native closure permits it; unresolved boundaries retain the exact lease and original cleanup callback until qualified recovery. Opted-in scope owners join tracked exit/close and receive termination failures; ordinary synchronous callers do not join. Failed removal is marked complete only if publication succeeds; otherwise age/uncertainty policy may retain the record, and terminal state prevents another cleanup attempt through this capability.
     */
    finish: () => void;

    /**
     * Keep the record fresh from a background refresher while this thread
     * blocks in a synchronous build. Successful startup is reused; failed
     * startup can be attempted again. Returns `false` when no mechanism could
     * initialize during readiness checks (the record then relies on age
     * policy). Repeated calls reuse the startup-acknowledged capability without
     * proving the refresher is still healthy. Finished records cannot be
     * restarted. Explicit worker scopes keep attempted refreshers referenced
     * until actual exit/close is joined by their asynchronous owner; ordinary
     * callers retain the unreferenced synchronous behavior.
     *
     * @evidence contracts/common.md#principled-implementation Initialization acknowledgement is required before the callback reports an independently refreshing task; a completed record has no restart capability.
     * @evidence contracts/common.md#clear-and-simple-design Lazy initialization stores one acknowledged refresher capability per unfinished record, separately from terminal finish state.
     * @evidence contracts/common.md#prohibited-implementation-shortcuts Worker and low-descriptor child paths support actual runtime capability differences, not fixture-specific outcomes.
     * @evidence contracts/common.md#meaningful-documentation Native prose names synchronous-build purpose, acknowledged-capability reuse, retryable initialization failure and terminal-state behavior.
     * @evidence contracts/portability.md#os-neutral-implementation Node workers or the current Node executable provide native background work without shell command quoting.
     * @evidence contracts/performance.md#efficient-algorithms Repeated starts reuse the stored startup-acknowledged capability. First startup attempts a worker and, if unavailable, a Node child; timed readiness waits have a grace per mechanism, while construction/native file observations add their own duration. Child script/argument bytes and readiness-path checks contribute to startup cost.
     *
     * @evidenceExclude contracts/performance.md#reuse-equivalent-work Reusing a heartbeat capability is lifecycle ownership, not equivalent build-result reuse.
     *
     * @evidence contracts/performance.md#bound-retention-and-release-resources One successful refresher capability is stored per record; failed worker termination may overlap child fallback. Startup/finish track actual worker exit, termination requests and child close for an opted-in owner to join; ordinary synchronous callers do not join, and ready-file deletion is best-effort. A later failed refresher is not recreated by repeating start; record expiry follows the declared freshness policy.
     */
    startHeartbeat: () => boolean;
  }

  /**
   * Publish an `active` record for this process in the coordination directory
   * `directoryName` of the cache at `root`.
   *
   * @evidence contracts/common.md#principled-implementation A random process-qualified record distinguishes concurrent tasks, atomic metadata publishes active/complete states and terminal finish prevents restart.
   * @evidence contracts/common.md#clear-and-simple-design Returned callbacks close over exactly one record, heartbeat and terminal flag rather than a global task registry.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Random uniqueness and completion-before-unlink address real concurrent publication and cleanup failures; no consumer identity is privileged.
   * @evidence contracts/common.md#meaningful-documentation Native type/member comments describe ownership and release semantics while the factory identifies the publication location.
   * @evidence contracts/portability.md#os-neutral-implementation Native path, hostname and atomic entry publication identify the local task without assuming PID meaning on another host.
   * @evidence contracts/performance.md#efficient-algorithms Publication validates native coordination paths and atomically writes one host/PID/status record, with path/JSON-byte costs. Startup is lazy and shares the stored capability; it includes worker construction or child launch/readiness observations rather than just record writes.
   *
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work A task lease is not a cached build answer; producer identity and lock sharing belong to the build owner.
   *
   * @evidence contracts/performance.md#bound-retention-and-release-resources The caller receives one record and lazy refresher capability and must call finish after its synchronous task. Termination and actual exit/close are tracked for opted-in owners to join after synchronous work; ordinary callers request termination without joining. Failed startup can overlap fallback; scoped unknown native closure retains the exact lease without age expiry, while unguarded failed completion/removal follows age/uncertainty policy. This factory imposes no cross-task population bound.
   */
  export function createGoBuildCacheCoordinationRecord(
    root: string,
    directoryName: string,
  ): GoBuildCacheCoordinationRecord {
    const directory = goBuildCacheCoordinationDirectory(
      root,
      directoryName,
      true,
    )!;
    const record = path.join(
      directory,
      `${process.pid}-${crypto.randomBytes(16).toString("hex")}.json`,
    );
    const metadata = {
      directoryName,
      hostname: os.hostname(),
      pid: process.pid,
      startedAt: Date.now(),
    };
    writeGoBuildCacheCoordinationRecord(record, metadata, "active");
    if (directoryName === GO_BUILD_CACHE_LEASE_DIR)
      SourceNativeRetirement.register({
        fenceRoot: root,
        retainedPaths: [root, record],
        generation: path.basename(record),
      });
    let heartbeat: GoBuildCacheHeartbeat | undefined;
    let finished = false;
    return {
      file: record,
      finish: () => {
        if (finished) return;
        finished = true;
        try {
          heartbeat?.stop();
        } catch (error) {
          trackGoBuildCacheRetirement(Promise.reject(error));
          // Native termination failure must not skip completion publication.
        }
        heartbeat = undefined;
        SourceNativeRetirement.release(() => {
          SourceNativeRetirement.assertReleasable(root, path.basename(record));
          // A failed unlink must not leave a completed task looking active until
          // its stale timeout. Persist completion first; collectors discard it.
          try {
            writeGoBuildCacheCoordinationRecord(record, metadata, "complete");
          } catch {}
          try {
            fs.rmSync(record, { force: true });
          } catch {}
          SourceNativeRetirement.forget(root, path.basename(record));
        });
      },
      startHeartbeat: () => {
        if (finished) return false;
        heartbeat ??= startGoBuildCacheHeartbeat(record);
        return heartbeat !== undefined;
      },
    };
  }

  /** Publish a complete coordination state through the shared atomic writer. */
  function writeGoBuildCacheCoordinationRecord(
    file: string,
    metadata: {
      directoryName: string;
      hostname: string;
      pid: number;
      startedAt: number;
    },
    status: "active" | "complete",
  ): void {
    SourceBuildCacheLayout.replaceCacheMetadataFile(
      file,
      `${JSON.stringify({ ...metadata, status, version: 1 })}\n`,
    );
  }

  /** The sole release capability for one background refresher. */
  interface GoBuildCacheHeartbeat {
    /** Request termination; opted-in owners keep closure referenced and joined. */
    stop: () => void;
  }

  /**
   * Refresh one synchronous task independently of the blocked parent thread.
   *
   * Initialization is acknowledged before success. Later inaccessible record
   * writes can still stop freshness, so collection retains its conservative
   * grace and uncertainty policy rather than claiming perfect liveness.
   */
  function startGoBuildCacheHeartbeat(
    file: string,
  ): GoBuildCacheHeartbeat | undefined {
    const control = new SharedArrayBuffer(4);
    const state = new Int32Array(control);
    try {
      const worker = new Worker(
        [
          'const fs = process.getBuiltinModule("node:fs");',
          'const { workerData } = process.getBuiltinModule("node:worker_threads");',
          "const state = new Int32Array(workerData.control);",
          "Atomics.store(state, 0, 1);",
          "Atomics.notify(state, 0);",
          "for (;;) {",
          "  const result = Atomics.wait(state, 0, 1, workerData.interval);",
          '  if (result !== "timed-out" || Atomics.load(state, 0) !== 1) break;',
          "  try {",
          "    const now = new Date();",
          "    fs.utimesSync(workerData.file, now, now);",
          "  } catch {}",
          "}",
        ].join("\n"),
        {
          eval: true,
          workerData: {
            control,
            file,
            interval: GO_BUILD_CACHE_COORDINATION_HEARTBEAT_MS,
          },
        },
      );
      const owned = OwnedSynchronousProcess.track(
        new Promise<void>((resolve) => worker.once("exit", () => resolve())),
      );
      worker.on("error", () => {
        Atomics.store(state, 0, 2);
        Atomics.notify(state, 0);
      });
      if (!owned) worker.unref();
      Atomics.wait(state, 0, 0, GO_BUILD_CACHE_COORDINATION_HEARTBEAT_MS);
      if (Atomics.load(state, 0) === 1) {
        return {
          stop: () => {
            Atomics.store(state, 0, 2);
            Atomics.notify(state, 0);
            retireGoBuildCacheWorker(worker);
          },
        };
      }
      Atomics.store(state, 0, 2);
      Atomics.notify(state, 0);
      retireGoBuildCacheWorker(worker);
    } catch {}

    // Node's permission model can deny Worker construction while still allowing
    // the child process required for `go build`. The fallback inherits only the
    // low standard descriptors and checks its parent PID. An IPC channel would
    // allocate another high descriptor and recreate Darwin's spawn EBADF limit.
    const ready = `${file}.heartbeat-${crypto.randomBytes(16).toString("hex")}`;
    let heartbeatChild: ReturnType<typeof spawn> | undefined;
    try {
      const heartbeatArgs = [
        "-e",
        [
          'const fs = require("node:fs");',
          "const file = process.argv[1];",
          "const interval = Number(process.argv[2]);",
          "const parent = Number(process.argv[3]);",
          "const ready = process.argv[4];",
          "const timer = setInterval(() => {",
          "  try { process.kill(parent, 0); } catch { clearInterval(timer); process.exit(0); }",
          "  try {",
          '    if (JSON.parse(fs.readFileSync(file, "utf8")).status === "complete") {',
          "      clearInterval(timer); process.exit(0);",
          "    }",
          "    const now = new Date();",
          "    fs.utimesSync(file, now, now);",
          '  } catch (error) { if (error.code === "ENOENT") { clearInterval(timer); process.exit(0); } }',
          "}, interval);",
          'try { fs.writeFileSync(ready, "ready", { flag: "wx" }); }',
          "catch { clearInterval(timer); process.exit(1); }",
        ].join("\n"),
        file,
        String(GO_BUILD_CACHE_COORDINATION_HEARTBEAT_MS),
        String(process.pid),
        ready,
      ];
      const trace = E2ETrace.begin(
        process.execPath,
        heartbeatArgs,
        {},
        "go-cache-heartbeat",
      );
      const child = spawn(process.execPath, heartbeatArgs, {
        stdio: [0, 1, 2],
        windowsHide: true,
      });
      const owned = OwnedSynchronousProcess.track(
        new Promise<void>((resolve) => child.once("close", () => resolve())),
      );
      heartbeatChild = child;
      E2ETrace.asynchronous(trace, child);
      trackGoBuildCacheRetirement(
        new Promise<void>((resolve, reject) => {
          // Capture this promise while the lexical scope is installed: these
          // events run after the synchronous callback restores its scope.
          child.on("error", (error) => {
            // A failed spawn can fall back to unavailable. A launched child's
            // control failure must reach its owner even if it later closes.
            if (child.pid !== undefined) reject(error);
          });
          child.once("close", () => resolve());
        }),
      );
      if (!owned) child.unref();
      if (child.pid === undefined) return undefined;
      const deadline =
        performance.now() + GO_BUILD_CACHE_COORDINATION_HEARTBEAT_MS;
      while (!fs.existsSync(ready)) {
        if (performance.now() >= deadline) {
          retireGoBuildCacheChild(child);
          return undefined;
        }
        Atomics.wait(state, 0, Atomics.load(state, 0), 10);
      }
      return {
        stop: () => {
          retireGoBuildCacheChild(child);
        },
      };
    } catch {
      try {
        if (heartbeatChild !== undefined)
          retireGoBuildCacheChild(heartbeatChild);
      } catch (error) {
        trackGoBuildCacheRetirement(Promise.reject(error));
      }
      return undefined;
    } finally {
      try {
        fs.rmSync(ready, { force: true });
      } catch {}
    }
  }

  /** Preserve scoped retirement failures without unhandled ordinary rejections. */
  function trackGoBuildCacheRetirement(retirement: Promise<unknown>): void {
    OwnedSynchronousProcess.track(retirement);
    void retirement.catch(() => undefined);
  }

  /** Track a real worker termination request, including synchronous refusal. */
  function retireGoBuildCacheWorker(worker: Worker): void {
    try {
      trackGoBuildCacheRetirement(worker.terminate());
    } catch (error) {
      trackGoBuildCacheRetirement(Promise.reject(error));
    }
  }

  /** A kill request never replaces the independently tracked child close. */
  function retireGoBuildCacheChild(child: ReturnType<typeof spawn>): void {
    try {
      child.kill();
    } catch (error) {
      trackGoBuildCacheRetirement(Promise.reject(error));
      throw error;
    }
  }

  /**
   * The live records of one coordination directory at `now`. Completed and
   * age-policy-stale records have deletion attempted; inaccessible metadata is
   * retained when its age cannot be established safely. Exact native-guarded
   * build generations are retained independently of status and age. Maintenance
   * records retain their ordinary freshness policy so unrelated guards cannot
   * block independent shared-cache builds indefinitely.
   *
   * @evidence contracts/common.md#principled-implementation Exact native-guarded build generations override status and age; for unguarded records complete status overrides age, and stale ordinary records have removal attempted. Unknown metadata age or far-future clock observations preserve possible work, while unreadable content alone does not prevent age-based expiry.
   * @evidence contracts/common.md#clear-and-simple-design One snapshot feeds a liveness helper and best-effort removal, returning only the protected paths.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts PID lifetime is not substituted for task lifetime; actual task status and heartbeat age drive selection.
   * @evidence contracts/common.md#meaningful-documentation Native prose distinguishes completed/stale reclamation from inaccessible metadata retention.
   * @evidence contracts/portability.md#os-neutral-implementation Native Dirents select ordinary files and sequential lstat/realpath checks validate the coordination directory's observed spelling; no directory handle prevents later replacement.
   * @evidence contracts/performance.md#efficient-algorithms One native-guard snapshot and generation Set membership avoid repeating a guard scan for each lease; one coordination listing and per-selected-record JSON/mtime reads scale with guard and record counts, path strings and metadata bytes, with arrays retaining entry/path text. Future-clock rebasing can add atomic metadata writes, and stale/complete cleanup adds native removals; directory validation adds native resolution without scanning unrelated cache payloads.
   *
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Liveness is time-sensitive and filesystem-mutating collection is not memoized.
   *
   * @evidence contracts/performance.md#bound-retention-and-release-resources Unguarded completed and stale records are reclaimed; exact native guards retain build records until qualified closure without age expiry. Unknown metadata or failed deletion can also retain records beyond ordinary grace.
   */
  export function collectLiveGoBuildCacheCoordinationRecords(
    root: string,
    directoryName: string,
    now: number,
  ): string[] {
    const directory = goBuildCacheCoordinationDirectory(
      root,
      directoryName,
      false,
    );
    if (directory === undefined) return [];
    let records: fs.Dirent[];
    try {
      records = fs.readdirSync(directory, { withFileTypes: true });
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw error;
    }
    const live: string[] = [];
    const protectedGenerations =
      directoryName === GO_BUILD_CACHE_LEASE_DIR
        ? SourceNativeRetirement.protectedGenerations(root)
        : new Set<string>();
    for (const record of records) {
      if (!record.isFile()) {
        continue;
      }
      const file = path.join(directory, record.name);
      const protectedNativeInputs =
        protectedGenerations === undefined ||
        protectedGenerations.has(record.name);
      if (
        protectedNativeInputs ||
        goBuildCacheCoordinationRecordIsLive(file, directoryName, now)
      ) {
        live.push(file);
        continue;
      }
      try {
        fs.rmSync(file, { force: true });
      } catch {}
    }
    return live;
  }

  /**
   * Resolve one private coordination directory without following a project-
   * supplied symlink or junction outside the owned Go cache.
   */
  function goBuildCacheCoordinationDirectory(
    root: string,
    directoryName: string,
    create: boolean,
  ): string | undefined {
    if (create) fs.mkdirSync(root, { recursive: true });
    const directory = path.join(root, directoryName);
    if (create) {
      try {
        fs.mkdirSync(directory);
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      }
    }
    let stats: fs.Stats;
    try {
      stats = fs.lstatSync(directory);
    } catch (error) {
      if (!create && (error as NodeJS.ErrnoException).code === "ENOENT") {
        return undefined;
      }
      throw error;
    }
    if (!stats.isDirectory() || stats.isSymbolicLink()) {
      throw new Error(
        `ttsc: unsafe Go build cache coordination directory: ${directory}`,
      );
    }
    const physicalRoot = fs.realpathSync.native(root);
    const physicalDirectory = fs.realpathSync.native(directory);
    if (path.dirname(physicalDirectory) !== physicalRoot) {
      throw new Error(
        `ttsc: Go build cache coordination directory escaped its root: ${directory}`,
      );
    }
    return physicalDirectory;
  }

  /** Classify task freshness without deleting under uncertain native state. */
  function goBuildCacheCoordinationRecordIsLive(
    file: string,
    directoryName: string,
    now: number,
  ): boolean {
    let contents: string | undefined;
    try {
      contents = fs.readFileSync(file, "utf8");
      const parsed = JSON.parse(contents) as Record<string, unknown>;
      if (parsed.status === "complete") return false;
      // Parse valid records for forward compatibility, but do not equate a PID's
      // lifetime with one task. A failed unlink can leave a record owned by a
      // still-running Vite process, while a dead Node parent can leave its
      // spawnSync Go child alive. The heartbeat/grace below models the task.
      void parsed;
    } catch {}
    try {
      const age = now - fs.statSync(file).mtimeMs;
      if (age < -GO_BUILD_CACHE_COORDINATION_CLOCK_SKEW_MS) {
        // A restored cache can carry a far-future timestamp, but the same state
        // also occurs when the system clock moves backward during a real build.
        // Rebase the record and grant one ordinary grace period; an active
        // heartbeat keeps refreshing it, while an orphan then expires normally.
        // Treat a failed rebase as live too: the safe failure mode is to defer
        // opportunistic maintenance, never to delete under a possibly live Go.
        // Replace the directory entry rather than changing its inode in place.
        // A restored or user-modified cache can contain a hard-linked record;
        // utimesSync(file) would then mutate metadata outside the owned cache.
        if (contents !== undefined) {
          try {
            SourceBuildCacheLayout.replaceCacheMetadataFile(file, contents);
          } catch {}
        }
        return true;
      }
      const staleMs =
        directoryName === GO_BUILD_CACHE_MAINTENANCE_DIR
          ? GO_BUILD_CACHE_MAINTENANCE_STALE_MS
          : GO_BUILD_CACHE_COORDINATION_STALE_MS;
      return age <= staleMs;
    } catch (error) {
      return (error as NodeJS.ErrnoException).code !== "ENOENT";
    }
  }
}

ttsc/src/plugin/internal/source/GoEnviro:
import crypto from "node:crypto";

import { SidecarEnvironment } from "../../../compiler/internal/sharedHost/SidecarEnvironment";
import { GoSourceInputs } from "./GoSourceInputs";
import { PluginBuildEnvironmentWitness } from "./PluginBuildEnvironmentWitness";
import type { PluginContentIdentities } from "./PluginContentIdentities";
import { PluginLoadAnswers } from "./PluginLoadAnswers";
import { spawnGoTool } from "./spawnGoTool";

/**
 * Acquire current Go values together with their environment-file evidence.
 * Build digests and syntax readers share this owner; a file-location hint is
 * never a retained positive environment verdict (#1516, #1712).
 *
 * @evidence contracts/common.md#principled-implementation The acquisition pairs actual Go output with native pre-read file evidence; callers retain their own completeness and reuse policy.
 * @evidence contracts/common.md#clear-and-simple-design One namespace owns environment-file discovery and native acquisition for build and manifest clients.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts No handwritten default GOENV path or process-permanent environment success replaces native Go.
 * @evidence contracts/common.md#meaningful-documentation Prose distinguishes observation from a discovery hint and identifies both consumers.
 * @evidenceExclude contracts/portability.md#os-neutral-implementation The read member owns native observation and execution.
 * @evidenceExclude contracts/performance.md#efficient-algorithms The read member owns acquisition and identity costs.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work The read member owns hint sharing; no result cache is exposed.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The read member describes the private hint map and delegated native lifetime.
 */
export namespace GoEnvironmentReading {
  /**
   * The Go environment file each Go tool and environment was last seen to name,
   * which lets a reading witness that file before `go env` reads it.
   */
  const goEnvironmentFiles = new Map<string, string | null>();

  /**
   * Answer family that carries the same location hint across processes, so a
   * new process does not run `go env` once merely to learn it (#1722). A wrong
   * or stale hint only costs the existing rediscovery run.
   */
  const ENVIRONMENT_FILE_HINT = "go-environment-file";

  /**
   * What chooses the file's location: `GOENV`, else `os.UserConfigDir()`
   * (`%AppData%`, `$XDG_CONFIG_HOME`, `$HOME`, Plan 9's `$home`). The hint
   * across processes is keyed by these alone, because a launch rarely repeats
   * every unrelated variable, such as a per-run trace path, and a hint that
   * misses costs the rediscovery run on every launch.
   */
  const LOCATION_VARIABLES = [
    "GOENV",
    "APPDATA",
    "XDG_CONFIG_HOME",
    "HOME",
    "home",
  ] as const;

  /**
   * Run `go env -json` for the requested keys and `GOENV`, the file `go env -w`
   * writes, witnessing that file before the run reads it.
   *
   * The file decides the reading without being part of it, so only its metadata
   * is kept, and it must be taken before the read: metadata taken after would
   * describe an edit that landed between the two, and a reading of the old
   * content would pass as proven. Which file `go env` reads is known only from
   * its answer, so the file this Go tool and environment named last is
   * witnessed first, and a reading that names another is taken again with that
   * one witnessed. A file that keeps moving between runs leaves the reading
   * unwitnessable, so a kept reading or a build keyed on it never holds.
   *
   * The location hint also comes from the record store when one is supplied, so
   * a new process witnesses the right file on its first run instead of running
   * `go env` once only to learn the name.
   *
   * @param identities Optional record store carrying the hint across processes.
   * @returns The parsed object, or `undefined` when native acquisition or JSON
   *   object decoding failed.
   * @evidence contracts/common.md#principled-implementation Actual Go supplies values and the environment-file path; pre-read metadata and bounded rediscovery preserve the earliest file witness instead of attaching a later state to an earlier read.
   * @evidence contracts/common.md#clear-and-simple-design One acquisition serves build hashing and manifest syntax qualification; callers choose keys and own interpretation and cache admission.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts A remembered file name is only a discovery hint. Every call executes Go, and unresolved movement marks its witness unproven rather than lending a historical positive verdict.
   * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain why file discovery can repeat and distinguish unavailable acquisition from current authority.
   * @evidence contracts/portability.md#os-neutral-implementation Go reports its actual environment-file location; native path metadata and the existing Go process owner supply observation and execution semantics.
   * @evidence contracts/performance.md#efficient-algorithms Hashing the complete tool/environment identity and up to three native Go queries process full name/value/output bytes. Requested keys contribute argument bytes; file discovery uses metadata rather than an SDK walk.
   * @evidence contracts/performance.md#reuse-equivalent-work Only file-location discovery hints are shared: in process across equal selected-tool/environment identities, and through the record store across equal selected tools and location variables, since the reading verifies any hint against the file Go reports. Current Go values and file authority are reacquired for every call.
   * @evidence contracts/performance.md#bound-retention-and-release-resources The module retains one file-location hint per historical tool/environment identity, without eviction, but no positive reading or native handle; persisted hints belong to the single-file collector. Command capture/retirement belongs to spawnGoTool and the caller owns the transferred witness.
   */
  export function read(
    goBinary: string,
    cwd: string,
    env: NodeJS.ProcessEnv,
    keys: readonly string[],
    witness: PluginBuildEnvironmentWitness.Record | undefined,
    identities?: PluginContentIdentities.Store,
  ): Record<string, unknown> | undefined {
    const memo = crypto.createHash("sha256").update(goBinary);
    for (const [key, value] of Object.entries(env).sort(([left], [right]) =>
      left < right ? -1 : left > right ? 1 : 0,
    )) {
      if (value !== undefined)
        memo.update(`\0${key.length}:${key}${value.length}:${value}`);
    }
    const memoKey = memo.digest("hex");
    let named = goEnvironmentFiles.get(memoKey);
    if (named === undefined) {
      const hinted = PluginLoadAnswers.read(
        identities,
        ENVIRONMENT_FILE_HINT,
        hintKey(goBinary, env),
      );
      if (hinted === null || typeof hinted === "string") named = hinted;
    }
    const remembered = named;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      if (named !== undefined && named !== null)
        PluginBuildEnvironmentWitness.add(witness, named);
      const result = spawnGoTool(goBinary, ["env", "-json", ...keys, "GOENV"], {
        cwd,
        encoding: "utf8",
        env: GoSourceInputs.goBuildEnv(goBinary, undefined, env),
        windowsHide: true,
      });
      if (result.error !== undefined || result.status !== 0) return undefined;
      let parsed: Record<string, unknown>;
      try {
        const decoded: unknown = JSON.parse(result.stdout);
        if (
          decoded === null ||
          typeof decoded !== "object" ||
          Array.isArray(decoded)
        )
          return undefined;
        parsed = decoded as Record<string, unknown>;
      } catch {
        return undefined;
      }
      const reported =
        typeof parsed.GOENV === "string" &&
        parsed.GOENV !== "" &&
        parsed.GOENV !== "off"
          ? parsed.GOENV
          : null;
      if (reported === named) {
        goEnvironmentFiles.set(memoKey, named);
        if (named !== remembered)
          PluginLoadAnswers.write(
            identities,
            ENVIRONMENT_FILE_HINT,
            hintKey(goBinary, env),
            named,
          );
        return parsed;
      }
      if (named !== undefined && named !== null) witness?.delete(named);
      named = reported;
      goEnvironmentFiles.set(memoKey, named);
      // No file to witness: the reading depends on none.
      if (named === null || witness === undefined) {
        if (named !== remembered)
          PluginLoadAnswers.write(
            identities,
            ENVIRONMENT_FILE_HINT,
            hintKey(goBinary, env),
            named,
          );
        return parsed;
      }
    }
    if (named !== undefined && named !== null)
      PluginBuildEnvironmentWitness.refuse(witness, named);
    return undefined;
  }

  // A wrong hint is safe: the reading compares it with the `GOENV` Go reports
  // and runs again with the reported file witnessed.
  function hintKey(goBinary: string, env: NodeJS.ProcessEnv): unknown {
    return [
      goBinary,
      LOCATION_VARIABLES.map(
        (name) => SidecarEnvironment.read(env, name) ?? null,
      ),
    ];
  }
}

ttsc/src/plugin/internal/source/GoSource:
import fs from "node:fs";
import path from "node:path";

/**
 * What of a Go source plugin, and of its toolchain, the build and the cache key
 * both see.
 *
 * The source walk and the cache key must agree on which files count, or an
 * irrelevant file would bust the cached binary (or a relevant one would not),
 * and the build must run with the same toolchain environment the key hashed.
 *
 * Membership is ttsc's declared snapshot naming policy, not Go dependency
 * discovery. Excluded entries are neither copied nor hashed, even when Go could
 * embed them in the original package. File-backed plugin data must use names
 * and directories included by this policy. Generated workspace files belong to
 * the scratch build; the caller's excluded workspace bytes are not preserved.
 *
 * @evidence contracts/common.md#principled-implementation One policy defines the selected source snapshot and fixed artifact flags so hashing, copying and observers agree on its population; name exclusions do not establish which files a raw Go package could consume.
 * @evidence contracts/common.md#clear-and-simple-design Source-name predicates and invocation-environment construction are centralized for consumers instead of copying their policies across loaders and watchers.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The declared naming exclusions apply uniformly to source consumers, including deliberately embedded data with matching names; GOWORK and managed GOCACHE express the scratch build protocol rather than fixture-specific exceptions.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs distinguish the snapshot naming policy from Go input discovery and describe excluded data and workspace ownership; invocation and artifact-flag prose explains their separate build responsibilities.
 * @evidence contracts/portability.md#os-neutral-implementation Native roots use Node path APIs; the same configured sidecar-name exclusions apply across platforms without deriving filesystem capabilities from the running OS.
 *
 * @evidenceExclude contracts/performance.md#efficient-algorithms The namespace groups input policies; each function owns its environment or membership processing.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Fixed policies are not retained computation; this namespace owns no runtime memo.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Policy collections have fixed population and do not own external resources.
 */
export namespace GoSourceInputs {
  /**
   * Artifact flags shared by native compilation and its environment identity.
   *
   * Go's trimpath removes disposable materialization paths from object keys and
   * debug information. Runtime source locations identify module files; source
   * diagnostics and embedded file contents still come from the snapshot.
   */
  export const BUILD_FLAGS: readonly string[] = Object.freeze(["-trimpath"]);

  /**
   * Names of directories excluded below a plugin source root: a nested
   * `node_modules`, a repository's `.git`, and ttsc's own `.ttsc`. An observer
   * outside this package, such as `ttscserver`'s native host, is handed this
   * list rather than a copy of it.
   */
  export const PRUNED_SOURCE_DIRECTORY_NAMES: readonly string[] = [
    "node_modules",
    ".git",
    ".ttsc",
  ];

  const PRUNE_DIRS = new Set(PRUNED_SOURCE_DIRECTORY_NAMES);

  const GENERATED_WORKSPACE_FILES = new Set(["go.work", "go.work.sum"]);

  /**
   * The environment of a `go` invocation: `GOWORK=auto`, ttsc's own `GOCACHE`
   * when a cache root is given, and `GOROOT` inferred from the binary's
   * location when the copied environment's value is absent or empty. Build
   * callers supply the managed cache; metadata callers retain their ambient
   * GOCACHE.
   *
   * @evidence contracts/common.md#principled-implementation A copied environment receives explicit workspace/cache settings and an inferred SDK root only when its existing GOROOT value is absent or empty; nonempty caller values remain unchanged.
   * @evidence contracts/common.md#clear-and-simple-design One constructor serves build and metadata invocations; omitting the cache root intentionally keeps read-only probes separate from owned-cache writes.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The caller's environment is preserved rather than mutating process globals, and documented Go variables express supported invocation policy.
   * @evidence contracts/common.md#meaningful-documentation Native prose states override precedence and why only actual builds receive managed GOCACHE; tags have separate presentation.
   * @evidence contracts/portability.md#os-neutral-implementation Native SDK inference delegates to path APIs, and Go's environment variables carry process configuration across supported operating systems.
   * @evidence contracts/performance.md#efficient-algorithms Environment enumeration copies E property references and processes key names; values are not deep-copied. SDK inference also performs native path-text construction and an existence query, whose filesystem/path costs are not bounded by E alone.
   *
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Each invocation needs its effective environment copy; no retained computation is coordinated here.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Only a call-local environment object is created.
   */
  export function goBuildEnv(
    goBinary: string,
    goBuildCacheRoot?: string,
    effectiveEnv: NodeJS.ProcessEnv = process.env,
  ): NodeJS.ProcessEnv {
    const env = { ...effectiveEnv };
    env.GOWORK = "auto";
    // Only the actual `go build` needs ttsc's GOCACHE; read-only metadata spawns
    // (`go mod edit`, `go env`, `go version`) call goBuildEnv with no cache root
    // and inherit ambient GOCACHE rather than receiving the managed build
    // cache here. This constructor does not certify child-side effects.
    if (goBuildCacheRoot) {
      env.GOCACHE = goBuildCacheRoot;
    }
    const goRoot = inferGoRoot(goBinary);
    if (goRoot && !env.GOROOT) {
      env.GOROOT = goRoot;
    }
    return env;
  }

  /**
   * Infer an SDK root for an absolute binary path inside `<root>/bin` when
   * `<root>/src/runtime` exists. The binary basename and runtime entry kind are
   * not validated here; `null` means this layout check did not match.
   *
   * @evidence contracts/common.md#principled-implementation An absolute binary path under bin and an existing src/runtime path establish this layout inference; the selected compiler's actual identity belongs to its resolution/probing owner, and other layouts leave the caller's environment unchanged.
   * @evidence contracts/common.md#clear-and-simple-design Small early returns expose each required layout condition without a speculative toolchain-discovery abstraction.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Layout recognition uses the SDK's real structure, not a particular user's install path or expected test directory.
   * @evidence contracts/common.md#meaningful-documentation Native prose documents the recognized layout and null meaning rather than merely repeating the return type.
   * @evidence contracts/portability.md#os-neutral-implementation Node absolute/dirname/join operations use native path syntax; the Go SDK's bin and src/runtime components are distribution-defined names.
   *
   * @evidence contracts/performance.md#efficient-algorithms A fixed sequence of native absolute/dirname/basename/join operations and one existence query checks the layout without enumerating a source tree. Path text and native lookup still contribute cost; fixed operation count is not a constant-byte filesystem bound.
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Existence is checked for the current invocation rather than memoized independently of SDK changes.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The function retains no state or native handle.
   */
  export function inferGoRoot(goBinary: string): string | null {
    if (!path.isAbsolute(goBinary)) return null;
    const binDir = path.dirname(goBinary);
    if (path.basename(binDir) !== "bin") return null;
    const goRoot = path.dirname(binDir);
    return fs.existsSync(path.join(goRoot, "src", "runtime")) ? goRoot : null;
  }

  /**
   * Whether a directory is excluded from the source snapshot: `node_modules`,
   * `.git`, and `.ttsc`. Membership is by name, even for caller-owned data.
   *
   * @evidence contracts/common.md#principled-implementation Exact membership in the shared directory-name set makes every source consumer use the same snapshot omission rule.
   * @evidence contracts/common.md#clear-and-simple-design One predicate exposes policy without requiring walkers to duplicate its set.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts These are declared subtree exclusions, not a test of whether every matching directory is owned by a package manager, repository or cache.
   * @evidence contracts/common.md#meaningful-documentation Native prose names the omitted directory categories, with a blank line before tags.
   *
   * @evidenceExclude contracts/portability.md#os-neutral-implementation This name-membership predicate performs no native lookup or path interpretation.
   *
   * @evidence contracts/performance.md#efficient-algorithms A prebuilt three-name set avoids rebuilding policy per directory; lookup still compares/hashes the supplied name under native JavaScript string/Set behavior and does not inspect directory content.
   *
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Static policy lookup does not coordinate a completed or in-flight computation.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources The fixed module policy has constant population and owns no external resource.
   */
  export function shouldPruneDirectory(name: string): boolean {
    return PRUNE_DIRS.has(name);
  }

  /**
   * Names of files excluded from the snapshot: workspace files and names
   * commonly used for operating-system sidecars. Excluding them avoids key
   * changes on unrelated workspace or file-browser writes, but also excludes
   * caller-authored data with those names. An observer that runs outside this
   * package, such as `ttscserver`'s native host, is handed this list rather
   * than a copy of it.
   */
  export const OMITTED_SOURCE_FILE_NAMES: readonly string[] = [
    ...GENERATED_WORKSPACE_FILES,
    ".DS_Store",
    "Thumbs.db",
  ];

  /**
   * File suffixes excluded from the snapshot: archive names commonly produced
   * by `npm pack`, and backup names ending in `~`. These suffixes remain
   * excluded when the files hold deliberately authored plugin data.
   */
  export const OMITTED_SOURCE_FILE_SUFFIXES: readonly string[] = [
    ".tgz",
    ".tar.gz",
    "~",
  ];

  /**
   * Whether a file name is excluded from the source snapshot
   * (`OMITTED_SOURCE_FILE_NAMES`, `OMITTED_SOURCE_FILE_SUFFIXES`).
   *
   * @evidence contracts/common.md#principled-implementation Exact names and defined suffixes decide snapshot omission consistently for source digests, copies and observers, independently of Go embed directives.
   * @evidence contracts/common.md#clear-and-simple-design Shared name/suffix lists keep the complete file-exclusion policy visible to external observers and this predicate.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts The published name policy applies without inspecting file contents or treating matching embedded data as an exception; it does not claim all excluded files are irrelevant to Go.
   * @evidence contracts/common.md#meaningful-documentation Native prose points to the documented categories rather than inventing an additional omission policy.
   *
   * @evidenceExclude contracts/portability.md#os-neutral-implementation This string predicate does not interpret native path identity or access the filesystem.
   *
   * @evidence contracts/performance.md#efficient-algorithms The policy lists have fixed size; suffix comparison costs at most their total fixed suffix lengths, without traversing file contents.
   *
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work Static policy lookup does not share runtime computation across requests.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources Only fixed policy constants are referenced.
   */
  export function shouldOmitSourceFile(name: string): boolean {
    return (
      OMITTED_SOURCE_FILE_NAMES.includes(name) ||
      OMITTED_SOURCE_FILE_SUFFIXES.some((suffix) => name.endsWith(suffix))
    );
  }
}

