        goBinary,
        opts.pluginName,
        env,
        opts.readers,
        opts.identities,
      );
      SourcePluginWorkspace.writeGoWork(
        scratch,
        SourcePluginWorkspace.findTtscOverlayDirs(),
        goBinary,
        opts.pluginName,
        env,
        reader,
      );
