    inputs: readonly { source: string; label: string }[],
    env: NodeJS.ProcessEnv,
    readers = new Map<string, SourcePluginWorkspace.GoModReader>(),
    identities?: PluginContentIdentities.Store,
    readings?: SelectionReadings,
  ): Package[] {
