      new Array(inputs.length);
    for (const group of groups.values()) {
      const first = inputs[group[0]!.index]!;
      const observations = inspect({
        source: first.source,
        pluginName: first.label,
        env,
        readers,
        identities,
        readings,
        proposal: !group[0]!.ownModule,
        packages: group.map(({ entry }) => ({ entry })),
      });
