import fs from "node:fs";
import path from "node:path";

import { CachePrunePolicy } from "./CachePrunePolicy";
import type { IPluginCachePruneOptions } from "./IPluginCachePruneOptions";
import { SourceBuildCacheLayout } from "./SourceBuildCacheLayout";

/**
 * Opportunistically bound a part of the cache root whose entries are single
 * files: the descriptor evaluations under `descriptors/`, the capability
 * answers under `capabilities/`, the plugin content identities under
 * `identities/`, the plugin-load answers under `answers/`, and the lowered
 * orphan sources under `ttsx-orphan/`.
 *
 * The policy is the plugin cache's (`CachePrunePolicy`). An entry's last use is
 * its modification time: a write sets it, and every hit records a use by
 * setting it again (`recordCacheFileUse`), improving its recent-use priority
 * under the collection policy rather than pinning it indefinitely. A writer
 * publishes an entry by renaming a finished staging file over it, so removing
 * an entry can only make a reader miss and compute the answer again, never read
 * a partial one; a staging file a crashed writer left behind is an entry nobody
 * uses, and ages out like one.
 *
 * A part absent or nonordinary at admission is left alone. A pass that gets
 * beyond the interval gate attempts marker publication after eviction; physical
 * path validation does not retain a directory handle against concurrent root
 * replacement. Failures are swallowed, since a collection must never fail the
 * launch that triggered it.
 *
 * @evidence contracts/common.md#principled-implementation Ordinary-root validation selects physical spelling for the pass, subject to that path retaining its identity during later lookups. Age and oldest-first size eviction operate on atomically published answer files, whose deletion means a cache miss rather than a partial answer; no directory handle freezes the root against concurrent replacement.
 * @evidence contracts/common.md#clear-and-simple-design Admission, age eviction, fresh accounting and size eviction are separate phases, followed by one retry marker publication.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Layout-independent file metadata drives reclamation; failures are tolerated because cache availability is optional, not hidden to fabricate a computed answer.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain payloads, hit-touch metadata, atomic publication and failure behavior under the documentation guidance.
 * @evidence contracts/portability.md#os-neutral-implementation lstat rejects aliased root leaves at admission, and later paths use the observed physical root instead of the original ancestor alias. Native per-file removal handles sharing restrictions without shell assumptions; physical spelling is not an ongoing object-identity pin.
 * @evidence contracts/performance.md#efficient-algorithms Two metadata scans and optional numeric timestamp sorting cost O(entries log entries), with temporary metadata and filename/path text scaling with admitted entries. Root validation and native metadata operations add path work, and interval-marker reading/encoding costs its text bytes; cached answer payload bytes are not read.
 *
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Answer equivalence is established by owning readers and producer keys, not eviction.
 *
 * @evidence contracts/performance.md#bound-retention-and-release-resources Thirty-day age and 2 GiB-triggered LRU target historical state; all entries used within the protection window and failed deletions can exceed the budget until later retry.
 */
export function pruneCacheFileRoot(
  root: string,
  options: Omit<IPluginCachePruneOptions, "protectedEntries"> = {},
): void {
  try {
    const stats = fs.lstatSync(root);
    if (!stats.isDirectory() || stats.isSymbolicLink()) return;
    root = SourceBuildCacheLayout.canonicalPluginCacheRoot(root);
    const marker = path.join(root, CachePrunePolicy.GC_MARKER_FILE);
    const now = options.now ?? Date.now();
    const lastRun = SourceBuildCacheLayout.readTimestamp(marker);
    if (
      options.force !== true &&
      lastRun !== null &&
      lastRun <= now &&
      now - lastRun < CachePrunePolicy.GC_INTERVAL_MS
    )
      return;
    const maxBytes = options.maxBytes ?? CachePrunePolicy.MAX_BYTES;
    const protectedAgeMs =
      options.protectedAgeMs ?? CachePrunePolicy.PROTECTED_AGE_MS;
    const targetBytes = options.targetBytes ?? CachePrunePolicy.TARGET_BYTES;
    for (const entry of collectEntries(root))
      if (now - entry.lastUsedAt > CachePrunePolicy.ENTRY_MAX_AGE_MS)
        removeEntry(entry.file);
    const remaining = collectEntries(root);
    let total = remaining.reduce((sum, entry) => sum + entry.size, 0);
    if (total > maxBytes) {
      for (const entry of remaining.sort(
        (a, b) => a.lastUsedAt - b.lastUsedAt,
      )) {
        if (total <= targetBytes) break;
        if (now - entry.lastUsedAt <= protectedAgeMs) continue;
        if (removeEntry(entry.file)) total -= entry.size;
      }
    }
    SourceBuildCacheLayout.replaceCacheMetadataFile(
      marker,
      `${
        total > maxBytes
          ? now - CachePrunePolicy.GC_INTERVAL_MS + protectedAgeMs
          : now
      }\n`,
    );
  } catch {
    // Collection is opportunistic; the launch proceeds when it fails.
  }
}

/** One ordinary cache file's eviction metadata from this pass. */
interface ICacheFileEntry {
  /** Ordinary file path under the physical answer-cache root. */
  file: string;

  /** Last-use modification timestamp in milliseconds. */
  lastUsedAt: number;

  /** Snapshot byte size. */
  size: number;
}

/** Snapshot ordinary files, excluding the collector's own interval marker. */
function collectEntries(root: string): ICacheFileEntry[] {
  const entries: ICacheFileEntry[] = [];
  let dirents: fs.Dirent[];
  try {
    dirents = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return entries;
  }
  for (const dirent of dirents) {
    if (!dirent.isFile() || dirent.name === CachePrunePolicy.GC_MARKER_FILE)
      continue;
    const file = path.join(root, dirent.name);
    try {
      const stats = fs.lstatSync(file);
      if (!stats.isFile()) continue;
      entries.push({ file, lastUsedAt: stats.mtimeMs, size: stats.size });
    } catch {
      // Removed or replaced since the listing: not an entry this pass sees.
    }
  }
  return entries;
}

/** Attempt one payload deletion and report whether the path remains absent. */
function removeEntry(file: string): boolean {
  try {
    fs.rmSync(file, { force: true });
    return !fs.existsSync(file);
  } catch {
    // Windows may refuse while another process holds the file open.
    return false;
  }
}

ttsc/src/plugin/internal/source/pruneGoB:
import fs from "node:fs";
import path from "node:path";

import { SourceNativeRetirement } from "../../../internal/SourceNativeRetirement";
import { GoBuildCacheCoordination } from "./GoBuildCacheCoordination";
import type { IGoBuildCachePruneOptions } from "./IGoBuildCachePruneOptions";
import { SourceBuildCacheLayout } from "./SourceBuildCacheLayout";

/**
 * Attempt byte-policy eviction of selected ordinary Go cache files.
 *
 * A maintenance intent blocks new build leases. If any existing lease remains,
 * maintenance yields without object eviction; coordination metadata can still
 * change. A later invocation may retry after normal admission checks. Only
 * ordinary files immediately inside Go's two-hex buckets enter accounting;
 * nested executable-cache directories, other kinds, coordination metadata and
 * Go's trim marker are outside this byte policy. Missing observations or failed
 * removals can leave actual storage above its thresholds without a hard bound.
 *
 * Pending, unknown or malformed native guards skip eviction regardless of lease
 * heartbeat age. Shared-cache admission remains independent of this deletion
 * protection. Older versions do not cooperate with native guards.
 *
 * @evidence contracts/common.md#principled-implementation A published maintenance intent precedes the live-lease check, so builders and deletion coordinate over the same owned physical root before object eviction.
 * @evidence contracts/common.md#clear-and-simple-design Admission, lease exclusion, eviction and marker publication occur in order; finally invokes intent finish, whose completion/removal remain best-effort.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Go bucket spelling follows its object-cache layout; missing heartbeat startup yields instead of assuming exclusion.
 * @evidence contracts/common.md#meaningful-documentation Native paragraphs explain lease exclusion and which populations are outside the byte policy; inline prose explains delayed over-budget retry.
 * @evidence contracts/portability.md#os-neutral-implementation Observed ordinary-root spelling, native Dirents and per-file removals avoid shell operations and OS-default identity assumptions; sequential metadata checks do not pin later pathnames.
 * @evidence contracts/performance.md#efficient-algorithms Listing includes root/bucket entries and their names; selected-file native stats and two O(N log N) numeric sorts account for N observed files without reading payload bytes. Arrays/Sets retain path text and metadata. Root validation, marker bytes, lease-record scans and heartbeat startup add delegated native/JSON costs; inaccessible observations can undercount rather than certify total disk usage.
 *
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work Go establishes object equivalence; maintenance chooses eviction rather than reusable computation identity.
 *
 * @evidence contracts/performance.md#bound-retention-and-release-resources Default 8 GiB triggers removal toward 6 GiB of accounted files, with a target-sized metadata-recent reserve. Live/unknown leases, missing observations, excluded kinds and failed deletion prevent a hard disk bound. Finally calls intent finish; ordinary synchronous callers do not join refresher termination, while opted-in owners join tracked exit/close and receive failures. Native guards can retain inputs without an age bound; record cleanup can fail; marker pacing requires another invocation and does not schedule maintenance itself.
 */
export function pruneGoBuildCacheRoot(
  root: string,
  options: IGoBuildCachePruneOptions = {},
): void {
  let intent:
    | GoBuildCacheCoordination.GoBuildCacheCoordinationRecord
    | undefined;
  try {
    const cacheRoot = GoBuildCacheCoordination.canonicalGoBuildCacheRoot(root);
    if (SourceNativeRetirement.isProtected(cacheRoot)) return;
    const marker = path.join(cacheRoot, GO_BUILD_CACHE_GC_MARKER_FILE);
    const now = options.now ?? Date.now();
    const lastRun = SourceBuildCacheLayout.readTimestamp(marker);
    if (
      options.force !== true &&
      lastRun !== null &&
      lastRun <= now &&
      now - lastRun < GO_BUILD_CACHE_GC_INTERVAL_MS
    ) {
      return;
    }

    intent = GoBuildCacheCoordination.createGoBuildCacheCoordinationRecord(
      cacheRoot,
      GoBuildCacheCoordination.GO_BUILD_CACHE_MAINTENANCE_DIR,
    );
    if (!intent.startHeartbeat()) {
      // Maintenance is opportunistic. Without an independent heartbeat a
      // synchronous scan could look abandoned while it is still deleting, so
      // yield instead of weakening the build/maintenance exclusion.
      return;
    }
    if (
      GoBuildCacheCoordination.collectLiveGoBuildCacheCoordinationRecords(
        cacheRoot,
        GoBuildCacheCoordination.GO_BUILD_CACHE_LEASE_DIR,
        now,
      ).length !== 0
    ) {
      return;
    }

    if (SourceNativeRetirement.isProtected(cacheRoot)) return;
    const remainingBytes = pruneGoBuildCacheEntries(cacheRoot, {
      maxBytes: options.maxBytes ?? GO_BUILD_CACHE_MAX_BYTES,
      now,
      protectedAgeMs: options.protectedAgeMs ?? GO_BUILD_CACHE_PROTECTED_AGE_MS,
      targetBytes: options.targetBytes ?? GO_BUILD_CACHE_TARGET_BYTES,
    });
    // If recent protection or a transient delete failure left the cache above
    // the ceiling, retry after the protection window instead of suppressing
    // every maintenance attempt for a full day.
    const maxBytes = options.maxBytes ?? GO_BUILD_CACHE_MAX_BYTES;
    const protectedAgeMs =
      options.protectedAgeMs ?? GO_BUILD_CACHE_PROTECTED_AGE_MS;
    const markerTimestamp =
      remainingBytes > maxBytes
        ? now - GO_BUILD_CACHE_GC_INTERVAL_MS + protectedAgeMs
        : now;
    SourceBuildCacheLayout.replaceCacheMetadataFile(
      marker,
      `${markerTimestamp}\n`,
    );
  } catch {
    // Go-cache GC is opportunistic; builds still proceed when it fails.
  } finally {
    intent?.finish();
  }
}

// Go's own object-cache trim is age-based and has no size ceiling. The default
// ttsc-owned cache therefore triggers collection above 8 GiB and trims toward
// 6 GiB of selected ordinary files. A target-sized newest cohort eligible by
// observed mtime (including the declared one-hour access granularity allowance)
// is reserved; this is not proof of actual recent use or a hard storage ceiling.
const GO_BUILD_CACHE_GC_INTERVAL_MS = 24 * 60 * 60 * 1000;

const GO_BUILD_CACHE_MAX_BYTES = 8 * 1024 * 1024 * 1024;

const GO_BUILD_CACHE_TARGET_BYTES = 6 * 1024 * 1024 * 1024;

const GO_BUILD_CACHE_PROTECTED_AGE_MS = 60 * 60 * 1000;

const GO_BUILD_CACHE_GC_MARKER_FILE = ".ttsc-gc";

// Go amortizes cache-hit mtime writes over one hour. An object used inside
// ttsc's one-hour protection window may therefore still carry an mtime almost
// one additional hour old.
const GO_BUILD_CACHE_ACCESS_MTIME_GRANULARITY_MS = 60 * 60 * 1000;

/** Snapshot metadata for one ordinary Go object selected by this pass. */
interface GoBuildCacheObject {
  /** Physical object path beneath the selected cache root. */
  file: string;

  /** Native last-use modification timestamp, in milliseconds. */
  lastUsedAt: number;

  /** Snapshot byte size used for eviction accounting. */
  size: number;
}

/** Prune oldest objects toward the byte target while reserving a recent cohort. */
function pruneGoBuildCacheEntries(
  root: string,
  options: {
    maxBytes: number;
    now: number;
    protectedAgeMs: number;
    targetBytes: number;
  },
): number {
  const entries = collectGoBuildCacheObjects(root);
  let total = entries.reduce((sum, entry) => sum + entry.size, 0);
  if (total <= options.maxBytes) {
    return total;
  }
  // Protect the newest recent objects only up to one target-sized cohort
  // reserve. Protecting every object younger than an hour would let repeated
  // 2.9 GiB cold builds grow without bound during that hour.
  const protectedFiles = new Set<string>();
  let protectedBytes = 0;
  for (const entry of [...entries].sort(
    (a, b) => b.lastUsedAt - a.lastUsedAt,
  )) {
    if (
      options.now - entry.lastUsedAt >
      options.protectedAgeMs + GO_BUILD_CACHE_ACCESS_MTIME_GRANULARITY_MS
    ) {
      continue;
    }
    if (protectedBytes >= options.targetBytes) {
      break;
    }
    if (protectedBytes + entry.size > options.targetBytes) {
      break;
    }
    protectedFiles.add(entry.file);
    protectedBytes += entry.size;
  }
  for (const entry of entries.sort((a, b) => a.lastUsedAt - b.lastUsedAt)) {
    if (total <= options.targetBytes) {
      return total;
    }
    if (protectedFiles.has(entry.file)) {
      continue;
    }
    try {
      fs.rmSync(entry.file, { force: true });
      total -= entry.size;
    } catch {
      // A concurrent antivirus/indexer can transiently hold a file on Windows.
    }
  }
  return total;
}

/** Snapshot ordinary files in Go's two-hex object buckets. */
function collectGoBuildCacheObjects(root: string): GoBuildCacheObject[] {
  const output: GoBuildCacheObject[] = [];
  let buckets: fs.Dirent[];
  try {
    buckets = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return output;
  }
  for (const bucket of buckets) {
    if (!bucket.isDirectory() || !/^[0-9a-f]{2}$/.test(bucket.name)) {
      continue;
    }
    const directory = path.join(root, bucket.name);
    let files: fs.Dirent[];
    try {
      files = fs.readdirSync(directory, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const file of files) {
      if (!file.isFile()) {
        continue;
      }
      const absolute = path.join(directory, file.name);
      try {
        const stats = fs.statSync(absolute);
        output.push({
          file: absolute,
          lastUsedAt: stats.mtimeMs,
          size: stats.size,
        });
      } catch {}
    }
  }
  return output;
}

