/**
 * Separate lexical and physical identities for one selected project.
 *
 * The resolver attempts realpath for the physical fields. If that operation
 * fails, it retains the selected absolute spelling; the field names alone do
 * not certify filesystem identity.
 *
 * @evidence contracts/common.md#principled-implementation Invocation and logical spellings remain separate from the resolver's physical-path selections because symlink selection and compiler ownership can differ; realpath failure preserves the selected absolute spelling rather than certifying it, and explicit overrides remain distinguishable from defaults.
 * @evidence contracts/common.md#clear-and-simple-design Named identity fields make each path's role available to plugin contexts without overloading one project root for selection, loading and caller overrides.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Lexical paths are not discarded and later recreated with platform guesses; caller-declared origins stay explicit rather than being inferred from generated wrapper locations.
 * @evidence contracts/common.md#meaningful-documentation Native comments explain canonicalization and the origin of each identity; blank member lines and prose/tag separation follow the documentation skill.
 * @evidence contracts/portability.md#os-neutral-implementation Native lexical selections and physical-path results retain their separate roles, including the realpath-failure fallback; the type requires neither manual separator splitting nor blanket lowercasing, and physical equality remains a filesystem owner's responsibility.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 */
export interface ITtscProjectIdentity {
  /** Absolute invocation working directory, without realpath resolution. */
  invocationCwd: string;

  /** Selected absolute config spelling, before realpath resolution. */
  logicalConfigPath: string;

  /** Directory containing the caller-selected config spelling. */
  logicalProjectRoot: string;

  /** Config path after attempted realpath; selected spelling on failure. */
  physicalConfigPath: string;

  /** Selected root after attempted realpath; selected spelling on failure. */
  physicalProjectRoot: string;

  /** Caller project-root override resolved from invocation cwd, when present. */
  explicitProjectRoot?: string;

  /** Caller-declared plugin-config discovery origin, when present. */
  pluginConfigOrigin?: string;
}

/**
 * Normalized local filesystem dependencies published by project rules.
 *
 * @evidence contracts/common.md#principled-implementation Exact paths, glob populations and selection-reload inputs have distinct roles; declared spellings accompany physical identities so link retargeting remains observable instead of being lost during normalization.
 * @evidence contracts/common.md#clear-and-simple-design One snapshot exposes normalized comparison inputs and optional pre-normalization watch inputs, keeping filesystem publication separate from watcher installation.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Missing exact paths remain meaningful candidates; consumers do not replace them with a fabricated present-file list or compensate for lost symlink spellings.
 * @evidence contracts/common.md#meaningful-documentation Native comments explain missing paths, slash glob vocabulary, reload scope and why declared spellings are retained; paragraph, member and tag spacing follow the documentation skill.
 * @evidence contracts/portability.md#os-neutral-implementation Native exact paths and forward-slash glob patterns are distinct vocabularies. Normalization uses observed realpath prefixes and filesystem case policy, preserving unresolved spelling when evidence is unavailable. Retained pre-identity spellings let consumers consider link/junction replacement attention; the value itself certifies neither complete alias resolution nor installed watcher behavior.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 */
export interface ITtscProjectInputSnapshot {
  /** Exact absolute paths, retained even while missing. */
  files: readonly string[];

  /** Absolute glob patterns using forward-slash separators. */
  globs: readonly string[];

  /** Exact paths whose change invalidates plugin/execution selection. */
  reloadFiles?: readonly string[];

  /** Directories whose immediate topology changes execution selection. */
  reloadDirectories?: readonly string[];

  /** Selected root identity, with unresolved spelling where proof is absent. */
  root: string;

  /**
   * The spellings the contributors published, before identity normalization.
   *
   * Successful realpath observations can replace a link spelling with its
   * target; missing or unavailable suffixes retain unresolved spelling. The
   * merger retains absolute lexical spellings when they differ from normalized
   * identity lists, so watcher consumers can consider both target changes and
   * replacement attention at a declared link. These lists do not install or
   * certify watcher delivery by themselves.
   */
  declared?: {
    /** Original exact-path spellings, including absent candidates. */
    files: readonly string[];

    /** Original glob spellings before physical-identity normalization. */
    globs: readonly string[];

    /** Original exact inputs that alter execution selection. */
    reloadFiles?: readonly string[];

    /** Original directory inputs that alter execution selection. */
    reloadDirectories?: readonly string[];
  };
}

/**
 * Inputs for locating the tsconfig/jsconfig that owns an invocation.
 *
 * @evidence contracts/common.md#principled-implementation Optional explicit config, source file and cwd preserve the locator's alternative selection bases; an independent project-root override supports generated configs without changing their selected identity.
 * @evidence contracts/common.md#clear-and-simple-design This input record states selection hints only, leaving discovery and physical identity derivation with the project locator.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Explicit overrides are supported caller inputs rather than special cases for temporary fixture paths or known consumers.
