ttsc/src/structures/internal/TtscBuildOp:
import type { TtscCommonOptions } from "./TtscCommonOptions";

/**
 * Internal options for a TypeScript-Go project build.
 *
 * @evidence contracts/common.md#principled-implementation Optional emit distinguishes requested emission, analysis and project-defined selection; forwarded compiler flags retain their documented precedence, while fix/format request host commands separately from emission selection.
 * @evidence contracts/common.md#clear-and-simple-design Shared process/project options are inherited once, while this record adds only project-build controls rather than unrelated single-file path policy.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Overrides are declared host controls; the launcher owns command restrictions and mutation-command emission suppression, while API callers supply their own selection rather than relying on fixture-specific behavior.
 * @evidence contracts/common.md#meaningful-documentation Native JSDoc spells out emit selection and forwarded-option precedence, source-rewrite command effects, launcher restrictions and verbosity ownership; paragraphs, member and tag spacing follow the documentation skill.
 * @evidence contracts/portability.md#os-neutral-implementation Config and output-directory overrides are native path values interpreted by the build owner from cwd, while inherited environment and passthrough argv remain structured; this type does not embed POSIX shell or separator assumptions.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 */
export interface TtscBuildOptions extends TtscCommonOptions {
  /** Config file or containing directory, absolute or resolved from `cwd`. */
  tsconfig?: string;

  /**
   * Emit override for the current call.
   *
   * - `true`: request emission despite the project's `noEmit` setting.
   * - `false`: select the analysis/check lane.
   * - `undefined`: use the project's `noEmit` selection.
   *
   * Forwarded compiler options follow these compiler defaults and can override
   * them. Emission still depends on successful checks and producer behavior.
   */
  emit?: boolean;

  /**
   * Request the fix command from configured check-stage hosts. A host may
   * reject unsupported commands. Source files may be rewritten. The launcher
   * also sets `emit: false`; API callers select emission separately.
   */
  fix?: boolean;

  /**
   * Request the format command from configured check-stage hosts. Source files
   * may be rewritten, and a host may reject unsupported commands. With `emit:
   * false`, the dispatcher adds no later type-check or transform pass. The
   * launcher sets that emit selection for `ttsc format` and rejects watch mode,
   * single-file mode, or an explicit enabled `--emit`.
   */
  format?: boolean;

  /** Per-call output-directory request, absolute or resolved from `cwd`. */
  outDir?: string;

  /**
   * Request native quiet/verbose presentation; `false` also adds ttsc's direct
   * build summary. The launcher defaults to `true`; omitted SDK values leave
   * native verbosity modifiers unset.
   */
  quiet?: boolean;
}

ttsc/src/structures/internal/TtscBuildRe:
import type { ITtscCompilerDiagnostic } from "../ITtscCompilerDiagnostic";
import type { ITtscCompilerTransformation } from "../ITtscCompilerTransformation";

/**
 * Internal result captured from TypeScript-Go or native plugin sidecars.
 *
 * @evidence contracts/common.md#principled-implementation Exit status, actual normal completion, diagnostics, streams, check-generation witnesses and optional emitted-source provenance remain separate. Absent provenance, an unknown output's empty source list and a complete empty output map differ; null input witnesses record absence while missing keys establish no reusable proof.
 * @evidence contracts/common.md#clear-and-simple-design One result record carries process facts and separately requested emitted-file/provenance data without making display-text parsing responsible for source ownership.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Streams derive from actual host output, though failure normalization can move stdout into stderr and phase composition can concatenate them. Numeric status remains separate from normal-completion proof; neither diagnostic text nor normalization invents successful execution or source ownership.
 * @evidence contracts/common.md#meaningful-documentation Native comments state status versus actual completion, emitted-list availability, generation ownership, null versus missing witnesses and unknown/ambiguous provenance states; member and tag separation follow the documentation skill.
 * @evidence contracts/portability.md#os-neutral-implementation Provenance distinguishes actual absolute native output spelling from physical source identity captured by the producer or stable external observations; neither path is case-folded or reconstructed from a URL, and each producer owns its resolution premise.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 */
export interface TtscBuildResult {
  /** Compiler-time graph of the same check generation, when transported. */
  graph?: ITtscCompilerTransformation.IReferenceGraph;
  /** Structured compiler/plugin diagnostics, supplied or parsed from output. */
  diagnostics: ITtscCompilerDiagnostic[];

  /** Files written by the build when emitted-file listing was requested. */
  emittedFiles?: string[];

  /**
   * Emitter provenance for actual written JavaScript outputs. Keys are absolute
   * native output spellings; values retain contributing physical source paths.
   * Native producers capture those identities in the compile generation. The
   * external compiler adapter instead requires matching pre/post source
   * selection, effective options, physical identities and contents, including
   * the selected executable. It cannot detect a concurrent change restored
   * between observations.
   *
   * Multiple sources are ambiguous for single-file routing, and an empty list
   * means the producer could not establish full ownership under its premise.
   *
   * Absent means unavailable or an older producer. A present empty map means a
   * supported producer reported no eligible written JavaScript output.
   * Consumers must not infer source ownership from emitted filenames in either
   * unknown state. Provenance does not by itself establish overall build
   * success.
   */
  emittedSources?: Record<string, readonly string[]>;

  /**
   * Actual proof-refusal reasons for reported output paths. Diagnostic context
   * alone establishes no source ownership and does not replace compiler
   * errors.
   */
  emittedSourceProofFailures?: Readonly<Record<string, string>>;

  /** Native inputs declared or observed by the contributing check generations. */
  hostInputs?: string[];

  /**
   * Generation-captured SHA-256 witnesses, keyed by declared native input. Null
   * records observed absence; a missing key supplies no reusable proof.
   */
  hostInputHashes?: Record<string, string | null>;

  /**
   * Generation-captured physical paths, or null for observed absence. Missing
   * keys preserve unavailable or conflicting proof without a later realpath.
   */
  hostInputRealpaths?: Record<string, string | null>;

  /** A contributing producer explicitly reported incomplete observations. */
  observationsComplete?: false;

  /**
   * Actual spawn completion fact before null-status coercion. True requires a
   * present native exit status and no terminating signal; absence proves no
   * completion premise for generation-owned metadata.
   */
  processCompletedNormally?: boolean;

  /** Process-style exit status. `0` means success. */
  status: number;

  /** Host stdout text after any failure normalization or phase composition. */
  stdout: string;

  /** Host stderr text after any failure normalization or phase composition. */
  stderr: string;
}

ttsc/src/structures/internal/TtscCommonO:
import type { ITtscProjectPluginConfig } from "../ITtscProjectPluginConfig";

/**
 * Internal options shared by the CLI build, single-file emit, and runtime
 * paths.
 *
 * @evidence contracts/common.md#principled-implementation Optional overrides preserve default resolution and distinguish disabled plugins from an explicit replacement list; passthrough tokens retain the native compiler's own option parser authority.
 * @evidence contracts/common.md#clear-and-simple-design The shared record contains cross-path project/process policy once; build and single-file options extend it with their own operation-specific controls.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Native binary/env injection is a supported embedding boundary; compiler options remain tokens rather than hardcoded approximations of the entire native schema.
 * @evidence contracts/common.md#meaningful-documentation Native comments explain option ownership, config discovery origins, threading and plugin override states; paragraphs, member and tag spacing follow the documentation skill.
 * @evidence contracts/portability.md#os-neutral-implementation Native path inputs and Node environment data stay separate from passthrough argv tokens, enabling OS-neutral spawn/path handling without shell quoting assumptions or platform-specific executable names in this representation.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 */
export interface TtscCommonOptions {
  /**
   * Explicit TypeScript-Go executable.
   *
   * A nonempty override must be an existing absolute path. It bypasses
   * package-based resolution; the native spawn owns execution failures.
   */
  binary?: string;

  /** Working directory for config discovery and relative file paths. */
  cwd?: string;

  /**
   * Selected project root, resolved from `cwd` independently of config
   * location.
   */
  projectRoot?: string;

  /**
   * Directory that anchors plugin config-file discovery and relative
   * `configFile` resolution (forwarded to plugin processes as
   * `TTSC_PLUGIN_CONFIG_DIR`). Set by build integrations that compile through a
   * generated tsconfig outside the project; when omitted, plugins anchor at the
   * tsconfig's own directory.
   */
  pluginConfigDir?: string;

  /** Environment variables merged over `process.env` for child processes. */
  env?: NodeJS.ProcessEnv;

  /** Explicit root directory for compiled source-plugin cache artifacts. */
  cacheDir?: string;

  /** Request nonpretty compiler output unless passthrough controls `--pretty`. */
  structuredDiagnostics?: boolean;

  /**
   * Run TypeScript-Go single-threaded — one checker, serial parse/check/emit.
   * Mirrors `tsgo --singleThreaded`. Useful for deterministic debugging and CI
   * repro.
   */
  singleThreaded?: boolean;

  /**
   * Requested checker pool size, mirroring `tsgo --checkers`; `singleThreaded`
   * takes precedence. Check hosts receive this only when they declare support.
   * The source-plugin driver clamps its serial transform Program to one
   * checker; direct TypeScript-Go execution otherwise owns its default and pool
   * policy.
   */
  checkers?: number;

  /**
   * Compiler-option tokens retaining their boundaries and order. Direct tsgo
   * execution forwards them; native hosts receive a JSON compiler-option
   * payload with timing flags omitted because host timing has its own channel.
   * tsgo owns option parsing, including flags without a first-class ttsc option
   * such as `--strict`, `--target es2020` and `--listFiles`. Internal output
   * isolation can append destination overrides after these tokens.
   */
  passthrough?: readonly string[];

  /**
   * Validated visible CLI project assignments at their original positions in
   * passthrough. Only the launcher supplies this metadata; explicit compiler
   * instances retain their resolvedProject authority instead.
   */
  compilerProjectSelections?: readonly {
    passthroughIndex: number;
    value: string;
  }[];

  /**
   * Retained native compiler argument base when project selection redirects
   * the Program to a different root. Absent retains the selected project root.
   * Response frames and relative native options use this base; plugin/rule
   * context and config-relative paths retain their separate project authority.
   */
  compilerArgsCwd?: string;

  /**
   * Override project plugin loading for this invocation.
   *
   * - `false`: disable project plugin loading and dependency discovery.
   * - Array: use these entries instead of config and dependency discovery.
   * - `undefined`: use the project config entries and discover plugins from
   *   direct dependencies.
   */
  plugins?: readonly ITtscProjectPluginConfig[] | false;
}

ttsc/src/structures/ITtscCompilerTransfo:
import type { ITtscCompilerDiagnostic } from "./ITtscCompilerDiagnostic";

/**
 * Result of a TypeScript source-to-source transformation operation.
 *
 * Unlike {@link ITtscCompilerResult}, this contract is not an emit contract: the
 * `typescript` map carries producer-reported source text rather than compiler
 * emit artifacts. The builtin producer returns loaded non-declaration source
 * files' text, including JavaScript inputs when admitted by the program; source
 * maps are separate advisory payloads, not entries in that text map.
 *
 * @evidence contracts/common.md#principled-implementation The discriminated union separates completed source transformation from failure and host exception; its producer-reported source text map is distinct from emit output.
 * @evidence contracts/common.md#clear-and-simple-design Named result variants share advisory dependency types but retain outcome-specific requirements, allowing callers to narrow by type.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Source text and optional invalidation metadata describe actual producer outputs; the contract does not substitute emitted JavaScript for transformed TypeScript.
 * @evidence contracts/common.md#meaningful-documentation Native JSDoc distinguishes transformation from emit, then explains result and advisory-data semantics on their declarations; paragraphs, member spacing and tag separation follow the documentation skill.
 * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
 * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
 * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
 * @evidence contracts/portability.md#os-neutral-implementation Result variants carry producer-coordinate source keys, native input paths and filesystem observations through their shared advisory types without rebasing or inferring platform capabilities. The discriminant does not itself certify physical identity, freshness or a universal source-map URL interpretation; those boundaries are documented on the selected variant and metadata type.
 */
export type ITtscCompilerTransformation =
  | ITtscCompilerTransformation.ISuccess
  | ITtscCompilerTransformation.IFailure
  | ITtscCompilerTransformation.IException;

export namespace ITtscCompilerTransformation {
  /**
   * Host-owned reference graph of the transformed program, mirroring the
   * envelope's optional `graph` section.
   *
   * The graph reports the loaded compiler program's resolved references, global
   * contributors, configuration ancestry and resolver observations. Bundler
   * adapters normally select the reachability closure of {@link edges} together
   * with {@link globals} and {@link configs}; an admitted complete dependency
   * declaration can narrow that graph selection. Resolver inputs, host inputs
   * and plugin source inputs remain separate invalidation lanes. The graph
   * alone does not certify every plugin's output dependencies or that the
   * reported filesystem state is still current.
   *
   * Keys and values follow the same convention as {@link ISuccess.typescript}:
   * project-relative slash paths, falling back to absolute slash paths outside
   * the project root.
   *
   * @evidence contracts/common.md#principled-implementation Direct reference edges, universal globals/configs and resolver predicates preserve different input influences; consumers derive reachability and replay only the observed filesystem predicates.
   * @evidence contracts/common.md#clear-and-simple-design The graph separates realized references from candidate observations and proof failures so adapters can invalidate conservatively without attributing compiler reads to plugins.
   * @evidence contracts/common.md#prohibited-implementation-shortcuts Missing or failed proofs remain refusals to reuse; neither an empty candidate map nor a guessed platform case policy fabricates compiler evidence.
   * @evidence contracts/common.md#meaningful-documentation Native JSDoc explains path vocabulary, global influence, optional legacy fields and the compiler-owned case policy; documented members and distinct paragraphs follow the documentation skill.
   * @evidenceExclude contracts/performance.md#bound-retention-and-release-resources A type declaration acquires and holds no runtime resource.
   * @evidenceExclude contracts/performance.md#efficient-algorithms A type declaration chooses no processing strategy.
   * @evidenceExclude contracts/performance.md#reuse-equivalent-work A type declaration computes nothing, so there is no work to share.
   * @evidence contracts/portability.md#os-neutral-implementation Graph keys use the producer's cwd-relative slash spelling with absolute slash paths for outside-root or cross-volume inputs; this protocol spelling is distinct from reported native realpaths carried by inputRealpaths and observations, which can retain lexical fallback on native VFS errors. The reported compiler case policy governs compiler membership comparisons rather than an OS-name assumption; absent policy or proof does not establish native filesystem capabilities.
   */
  export interface IReferenceGraph {
    /**
     * Direct resolved references per file: imports, re-exports, `///
     * <reference>` targets, and type reference directives — type-only edges
     * included. Direct edges only; consumers compute transitive reachability
     * themselves.
     */
    edges: Record<string, string[]>;

    /**
     * Files contributing to the global scope (ambient declaration files, script
     * files, global augmentations, `typeRoots` entries). A change to any of
     * them can affect every file in the program.
     */
    globals: string[];

    /** The project tsconfig followed by its `extends` ancestry. */
    configs: string[];

    /**
     * Exact lexical filesystem inputs consulted by TypeScript-Go's module,
     * type-reference, and triple-slash path resolution, keyed by source file.
     * Hosts watch and prove these paths in addition to realized graph members.
     *
     * The native producer omits an empty candidate map. Absence describes no
     * reported source-owned candidates; it does not certify that resolution
     * consulted no filesystem input, including universal resolution inputs.
     */
    candidates?: Record<string, string[]>;

    /**
     * Automatic type discovery and resolution inputs that affect every source,
     * including effective type-root directory membership.
     */
    resolutionInputs?: string[];

    /**
     * Filesystem predicates recorded during construction and resolver replay
     * for this graph. Each property is independent: `fileExists: false` and
     * `directoryExists: true` describe one stable directory and do not
     * conflict. Consumers re-run only the predicates present in an entry, so a
     * failed file candidate is never reinterpreted as generic path absence.
     */
    inputObservations?: Record<string, IInputObservation>;

    /**
