import { TypeGuardError } from "../TypeGuardError";

/**
 * Report an assertion failure.
 *
 * When `exceptionable` is true it throws the error that `factory` makes, or a
 * TypeGuardError when `factory` is not a function; otherwise it returns false
 * so a union probe can try the next branch.
 *
 * @evidence contracts/common.md#principled-implementation When the call is exceptionable it throws an error built by the caller's factory if one is a function, and a TypeGuardError otherwise, and when it is not exceptionable it returns false so a union probe can try another branch without throwing. The factory is tested for callability because a pointwise call such as `rows.map(assertUser)` passes the element index in that position, which a bare truthiness test would call.
 * @evidence contracts/common.md#clear-and-simple-design One function with a boolean guard and one factory branch.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A non-callable argument falls back to the default error and is not retried or wrapped; the comment explains that a create-time factory overridden by the argument cannot be recovered here.
 * @evidence contracts/common.md#meaningful-documentation The doc states the two outcomes and the factory rule; the inline comment records the pointwise hand-off failure.
 */
export const _assertGuard = (
  exceptionable: boolean,
  props: TypeGuardError.IProps,
  factory?: (props: TypeGuardError.IProps) => Error,
): false => {
  if (exceptionable === true) {
    // `factory` arrives from the generated function's second parameter, which
    // a pointwise hand-off fills with something that is not a factory at all:
    // `rows.map(assertUser)` passes the element index. A truthiness test then
    // called a number and reported `factory is not a function`, hiding the
    // real assertion failure — and only for indices other than 0. Require a
    // callable, and fall back to TypeGuardError for everything else.
    //
    // A create-time factory is the default of that same parameter, so a
    // non-callable argument has already overridden it by the time this runs
    // and cannot be recovered here. TypeGuardError still names the property
    // that failed, which `factory is not a function` never did.
    if (typeof factory === "function") throw factory(props);
    throw new TypeGuardError(props);
  }
  return false;
};

typia/src/internal/_coerceLlmArguments.t:
import { ILlmSchema } from "@typia/interface";
import { LlmJson } from "@typia/utils";

/**
 * Coerce already parsed LLM arguments to the types of the parameters schema.
 *
 * The result is not validated; the type argument is the caller's assertion.
 *
 * @evidence contracts/common.md#principled-implementation The function delegates to the utilities' schema-directed coercion, which converts double-stringified values to the types that the parameters schema declares, and casts the result to the caller's type because coercion does not validate it.
 * @evidence contracts/common.md#clear-and-simple-design A one-line adapter so the emitted code depends on one internal name and the utility package remains the owner of the algorithm.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts There is no second coercion implementation to drift from the utility's.
 * @evidence contracts/common.md#meaningful-documentation The doc states that no validation is performed and that the type argument is the caller's assertion.
 */
export const _coerceLlmArguments = <T>(
  value: unknown,
  parameters: ILlmSchema.IParameters,
): T => LlmJson.coerce(value, parameters);

import { ILlmEvaluation, IValidation } from "@typia/interface";

import { _accessExpressionAsString } from "./_accessExpressionAsString";

/**
 * Compile-time plan of `typia.llm.evaluation<T>()`, one entry per decision leaf
 * of `T`.
 *
 * @internal
 */
export type _ILlmEvaluationPlan =
  | _ILlmEvaluationPlan.IBoolean
  | _ILlmEvaluationPlan.IChoice
  | _ILlmEvaluationPlan.IScore
  | _ILlmEvaluationPlan.ISet;

/** @internal */
export namespace _ILlmEvaluationPlan {
  interface IBase {
    /** Property names from the root of `T` to the leaf. */
    path: string[];
    instructions: string;
  }
  export interface IBoolean extends IBase {
    kind: "boolean";
    threshold: number;
  }
  export interface IChoice extends IBase {
    kind: "choice";
    options: IMember<string>[];
  }
  export interface IScore extends IBase {
    kind: "score";
    /** Sorted in ascending value order; level `i` is `levels[i]`. */
    levels: IMember<number>[];
  }
  export interface ISet extends IBase {
    kind: "set";
    members: ISetMember[];
  }
  export interface IMember<Value extends string | number> {
    value: Value;
    description?: string;
    /** Acceptance minimum of the member, when it has one. */
    minimum?: number;
  }
  export interface ISetMember {
    value: string;
    description?: string;
    threshold: number;
  }
}

/**
 * Creates the `ILlmEvaluation` of `typia.llm.evaluation<T>()` from its plan.
 *
 * Both the question map and the decoder derive their keys from here, so the
 * readable path encoding has a single owner.
 *
 * @internal
 */
export const _createLlmEvaluation = <T>(
  plan: _ILlmEvaluationPlan[],
  decimals: number = 2,
): ILlmEvaluation<T> => {
  const questions: Record<string, ILlmEvaluation.IQuestion> = {};
  for (const leaf of plan) {
    if (leaf.kind === "set")
      for (const member of leaf.members)
        assign(questions, key([...leaf.path, member.value]), {
          type: "boolean",
          instructions: setInstructions(leaf, member),
        });
    else assign(questions, key(leaf.path), question(leaf));
  }
  return {
    questions,
    config: { decimals },
    decode: (answers: unknown): IValidation<T> =>
      decode(plan, answers, decimals),
  };
};

/* -----------------------------------------------------------
  QUESTIONS
----------------------------------------------------------- */
/**
 * Encodes a property path as a question key, like `refund.requested`.
 *
 * Every segment after the first uses typia's accessor notation, so the key is
 * the validation path without its `$input` root. The first segment is quoted
 * when it is not an identifier, and always when it is `__proto__`, so no key
 * can collide with another or reach an object's prototype.
 */
const key = (path: string[]): string => {
  const head: string = path[0]!;
  const postfix: string = _accessExpressionAsString(head);
  const first: string =
    head === "__proto__"
      ? `[${JSON.stringify(head)}]`
      : postfix.startsWith(".")
        ? head
        : postfix;
  return first + path.slice(1).map(_accessExpressionAsString).join("");
};

const question = (
  leaf:
    | _ILlmEvaluationPlan.IBoolean
    | _ILlmEvaluationPlan.IChoice
    | _ILlmEvaluationPlan.IScore,
): ILlmEvaluation.IQuestion => {
  if (leaf.kind === "boolean")
    return { type: "boolean", instructions: leaf.instructions };
  else if (leaf.kind === "choice") {
    const criteria: Record<string, string | null> = {};
    for (const option of leaf.options)
      assign(criteria, option.value, option.description ?? null);
    return { type: "choice", instructions: leaf.instructions, criteria };
  }
  return {
    type: "score",
    instructions: leaf.instructions,
    // the transform rejects fewer than two levels
    criteria: leaf.levels.map(
      (level) => level.description ?? String(level.value),
    ) as [string, string, ...string[]],
  };
};

const setInstructions = (
  leaf: _ILlmEvaluationPlan.ISet,
  member: _ILlmEvaluationPlan.ISetMember,
): string =>
  [
    leaf.instructions,
    "",
    `Does the option ${JSON.stringify(member.value)} apply?`,
    ...(member.description !== undefined ? [member.description] : []),
  ].join("\n");

/* -----------------------------------------------------------
  VALIDATION
----------------------------------------------------------- */
const decode = <T>(
  plan: _ILlmEvaluationPlan[],
  answers: unknown,
  decimals: number,
): IValidation<T> => {
  // half a unit in the last decimal place per rounded value
  const precision: IPrecision = {
    probability: 0.5 * 10 ** -decimals,
    score: 0.5 * 10 ** -decimals,
  };
  const map: Record<string, unknown> | null = object(answers);
  if (map === null)
    return {
      success: false,
      data: answers,
      errors: [
        {
          path: "$input",
          expected: "Record<string, ILlmEvaluation answer>",
          value: answers,
        },
      ],
    };

  const errors: IValidation.IError[] = [];
  const expected: Set<string> = new Set();
  const output: Record<string, unknown> = {};
  const read = (id: string): unknown => {
    expected.add(id);
    try {
      return Object.prototype.hasOwnProperty.call(map, id)
        ? map[id]
        : undefined;
    } catch {
      // The decision reader reports the inaccessible answer on its own path.
      return undefined;
    }
  };

  for (const leaf of plan) {
    const path: string = accessor(leaf.path);
    if (leaf.kind === "set") {
      const values: string[] = [];
      for (const member of leaf.members) {
        const memberPath: string = [
          path,
          _accessExpressionAsString(member.value),
        ].join("");
        const answer: unknown = read(key([...leaf.path, member.value]));
        const probability: number | null = inspect(
          memberPath,
          answer,
          errors,
          () => booleanProbability(answer, memberPath, errors),
        );
        if (probability !== null && probability >= member.threshold)
          values.push(member.value);
      }
      place(output, leaf.path, values);
      continue;
    }
    const answer: unknown = read(key(leaf.path));
    if (leaf.kind === "boolean") {
      const probability: number | null = inspect(path, answer, errors, () =>
        booleanProbability(answer, path, errors),
      );
      if (probability !== null)
        place(output, leaf.path, probability >= leaf.threshold);
    } else if (leaf.kind === "choice") {
      const value: string | null = inspect(path, answer, errors, () =>
        choice(leaf, answer, path, errors, precision),
      );
      if (value !== null) place(output, leaf.path, value);
    } else {
      const value: number | null = inspect(path, answer, errors, () =>
        score(leaf, answer, path, errors, precision),
      );
      if (value !== null) place(output, leaf.path, value);
    }
  }
  let received: string[];
  try {
    received = Object.keys(map);
  } catch {
    errors.push({
      path: "$input",
      expected: "readable evaluation answer map",
      value: answers,
      description: "Evaluation answer keys could not be inspected.",
    });
    received = [];
  }
  for (const id of received)
    if (expected.has(id) === false)
      try {
        errors.push({
          path: `$input${_accessExpressionAsString(id)}`,
          expected: "undefined",
          value: map[id],
          description: "The answer does not belong to any question.",
        });
      } catch {
        errors.push({
          path: `$input${_accessExpressionAsString(id)}`,
          expected: "readable evaluation answer",
          value: undefined,
          description: "The extra answer could not be inspected.",
        });
      }
  return errors.length === 0
    ? { success: true, data: output as T }
    : { success: false, data: answers, errors };
};

/** Contain exceptions from getters and proxies at the decision path. */
const inspect = <T>(
  path: string,
  answer: unknown,
  errors: IValidation.IError[],
  read: () => T,
): T | null => {
  try {
    return read();
  } catch {
    errors.push({
      path,
      expected: "readable evaluation answer",
      value: answer,
      description: "The answer could not be inspected.",
    });
    return null;
  }
};

const booleanProbability = (
  answer: unknown,
  path: string,
  errors: IValidation.IError[],
): number | null => {
  const record: Record<string, unknown> | null = object(answer);
  const type: unknown = record?.type;
  const probability: unknown =
    record === null
      ? undefined
      : type === "boolean"
        ? record.probability
        : type === "noul"
          ? record.noul
          : undefined;
  if (isProbability(probability)) return probability;
  errors.push({
    path,
    expected:
      '{ type: "boolean"; probability: number } | { type: "noul"; noul: number }',
    value: answer,
    description:
      record === null
        ? "Missing boolean answer."
        : type !== "boolean" && type !== "noul"
          ? `Answer type must be "boolean" or "noul", but got ${label(type)}.`
          : "Boolean answer needs a probability in [0, 1].",
  });
  return null;
};

const choice = (
  leaf: _ILlmEvaluationPlan.IChoice,
  answer: unknown,
  path: string,
  errors: IValidation.IError[],
  precision: IPrecision,
): string | null => {
  const expected: string = `{ type: "choice"; choice: ${leaf.options
    .map((option) => JSON.stringify(option.value))
    .join(" | ")}; probabilities?: Record<string, number> }`;
  const record: Record<string, unknown> | null = object(answer);
  const type: unknown = record?.type;
  const selected: unknown = type === "choice" ? record?.choice : undefined;
  const option: _ILlmEvaluationPlan.IMember<string> | undefined =
    record !== null && type === "choice"
      ? leaf.options.find((o) => o.value === selected)
      : undefined;
  if (record === null || option === undefined) {
    errors.push({
      path,
      expected,
      value: answer,
      description:
        record === null
          ? "Missing choice answer."
          : type !== "choice"
            ? `Answer type must be "choice", but got ${label(type)}.`
            : "Choice answer must select one of the declared options.",
    });
    return null;
  }
  const probabilities: Record<string, number> | null | undefined = distribution(
    record.probabilities,
    leaf.options.map((o) => o.value),
    precision.probability,
  );
  if (probabilities === null) {
    errors.push({
      path,
      expected,
      value: answer,
      description:
        "Choice probabilities must contain every declared option exactly once, use numbers in [0, 1], and sum to 1.",
    });
    return null;
  }
  if (probabilities !== undefined) {
    const selected: number = own(probabilities, option.value)!;
    if (
      Object.values(probabilities).some(
        (probability) => probability > selected + PROBABILITY_TOLERANCE,
      )
    ) {
      errors.push({
        path,
        expected,
        value: answer,
        description:
          "Choice answer must select an option with maximum probability.",
      });
      return null;
    }
  }
  return accept(
    option,
    option.value,
    own(probabilities, option.value),
    path,
    answer,
    expected,
    errors,
  )
    ? option.value
    : null;
};

const score = (
  leaf: _ILlmEvaluationPlan.IScore,
  answer: unknown,
  path: string,
  errors: IValidation.IError[],
  precision: IPrecision,
): number | null => {
  const last: number = leaf.levels.length - 1;
  const expected: string = `{ type: "score"; score: number; probabilities?: Record<string, number> }`;
  const record: Record<string, unknown> | null = object(answer);
  const type: unknown = record?.type;
  const scored: unknown = type === "score" ? record?.score : undefined;
  if (
    record === null ||
    type !== "score" ||
    typeof scored !== "number" ||
    Number.isFinite(scored) === false ||
    scored < 0 ||
    scored > last
  ) {
    errors.push({
      path,
      expected,
      value: answer,
      description:
        record === null
          ? "Missing score answer."
          : type !== "score"
            ? `Answer type must be "score", but got ${label(type)}.`
            : `Score answer needs a score in [0, ${last}].`,
    });
    return null;
  }
  const probabilities: Record<string, number> | null | undefined = distribution(
    record.probabilities,
    leaf.levels.map((_, i) => String(i)),
    precision.probability,
  );
  if (probabilities === null) {
    errors.push({
      path,
      expected,
      value: answer,
      description:
        "Score probabilities must contain every level index exactly once, use numbers in [0, 1], and sum to 1.",
    });
    return null;
  }
  if (probabilities !== undefined) {
    const mean: number = leaf.levels.reduce(
      (total, _, index) => total + index * own(probabilities, String(index))!,
      0,
    );
    const meanRoundingError: number = leaf.levels.reduce(
      (total, _, index) => total + index * precision.probability,
      0,
    );
    if (
      Math.abs(mean - scored) >
      PROBABILITY_TOLERANCE + meanRoundingError + precision.score
    ) {
      errors.push({
        path,
        expected,
        value: answer,
        description:
          "Score must equal the probability-weighted mean of its distribution.",
      });
      return null;
    }
  }

  // the most probable level when a distribution exists, where a tie resolves
  // to the lower level; otherwise the level nearest to the fractional score,
  // where a half rounds up
  let index: number = Math.round(scored);
  if (probabilities !== undefined && Object.keys(probabilities).length !== 0) {
    index = -1;
    leaf.levels.forEach((_, i) => {
      const p: number | undefined = own(probabilities, String(i));
      if (
        p !== undefined &&
        (index === -1 || p > own(probabilities, String(index))!)
      )
        index = i;
    });
  }
  const level: _ILlmEvaluationPlan.IMember<number> = leaf.levels[index]!;
  return accept(
    level,
    level.value,
    own(probabilities, String(index)),
    path,
    answer,
    expected,
    errors,
  )
    ? level.value
    : null;
};

/** Enforces the acceptance minimum of the selected member, if any. */
const accept = (
  member: { minimum?: number },
  value: string | number,
  probability: number | undefined,
  path: string,
  answer: unknown,
  expected: string,
  errors: IValidation.IError[],
): boolean => {
  if (member.minimum === undefined) return true;
  if (probability === undefined) {
    errors.push({
      path,
      expected,
      value: answer,
      description: `${JSON.stringify(value)} requires probability >= ${member.minimum}, but the answer has no probability for it.`,
    });
    return false;
  }
  if (probability < member.minimum) {
    errors.push({
      path,
      expected,
      value: answer,
      description: `${JSON.stringify(value)} has probability ${probability} < ${member.minimum}.`,
    });
    return false;
  }
  return true;
};

/**
 * Reads optional `probabilities`: `undefined` when absent, `null` when
 * malformed.
 */
const distribution = (
  input: unknown,
  keys: string[],
  roundingError: number,
): Record<string, number> | null | undefined => {
  if (input === undefined) return undefined;
  const record: Record<string, unknown> | null = object(input);
  if (record === null) return null;
  if (Object.keys(record).length !== keys.length) return null;
  const output: Record<string, number> = {};
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(record, key) === false)
      return null;
    const probability: unknown = record[key];
    if (isProbability(probability) === false) return null;
    assign(output, key, probability);
  }
  if (
    Math.abs(
      Object.values(output).reduce((sum, probability) => sum + probability, 0) -
        1,
    ) >
    PROBABILITY_TOLERANCE + keys.length * roundingError
  )
    return null;
  return output;
};

/** AI SDK's absolute tolerance for probability sums and derived values. */
const PROBABILITY_TOLERANCE = 1e-6;

interface IPrecision {
  probability: number;
  score: number;
}

/* -----------------------------------------------------------
  HELPERS
----------------------------------------------------------- */
/**
 * Renders an untrusted answer `type` for a message; unlike `JSON.stringify`, it
 * never throws on a bigint or circular value.
 */
const label = (value: unknown): string =>
  typeof value === "string" ? JSON.stringify(value) : typeof value;

const accessor = (path: string[]): string =>
  "$input" + path.map(_accessExpressionAsString).join("");

/** Match AI SDK's JSON-record boundary, including null-prototype dictionaries. */
const object = (input: unknown): Record<string, unknown> | null => {
  if (typeof input !== "object" || input === null) return null;
  try {
    if (Array.isArray(input)) return null;
    const prototype: object | null = Object.getPrototypeOf(input);
    return prototype === Object.prototype || prototype === null
      ? (input as Record<string, unknown>)
      : null;
  } catch {
    // A revoked or trapping proxy is not a usable answer record.
    return null;
  }
};

/**
 * Reads an own probability, so an option named like an `Object.prototype`
 * member (`constructor`, `toString`, ...) never inherits a value.
 */
const own = (
  probabilities: Record<string, number> | undefined,
  key: string,
): number | undefined =>
  probabilities !== undefined &&
  Object.prototype.hasOwnProperty.call(probabilities, key)
    ? probabilities[key]
    : undefined;

const isProbability = (value: unknown): value is number =>
  typeof value === "number" &&
  Number.isFinite(value) &&
  value >= 0 &&
  value <= 1;

/** Writes the leaf value, creating the intermediate objects of its path. */
const place = (
  output: Record<string, unknown>,
  path: string[],
  value: unknown,
): void => {
  let target: Record<string, unknown> = output;
  path.slice(0, -1).forEach((name) => {
    if (Object.prototype.hasOwnProperty.call(target, name) === false)
      assign(target, name, {});
    target = target[name] as Record<string, unknown>;
  });
  assign(target, path[path.length - 1]!, value);
};

/** Own-property assignment that cannot reach the prototype via `__proto__`. */
const assign = (
  target: Record<string, unknown>,
  name: string,
  value: unknown,
): void => {
  if (name === "__proto__")
    Object.defineProperty(target, name, {
      value,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  else target[name] = value;
};

typia/src/internal/_createStandardSchema:
import { IValidation, StandardSchemaV1 } from "@typia/interface";

/**
 * Make a validator satisfy the Standard Schema contract.
 *
 * The same function is returned with a `~standard` property whose `validate`
 * runs it and maps its errors to issues with key-segment paths. Error paths
 * must use the generated `$input` grammar; validator or path-parsing exceptions
 * propagate rather than becoming Standard Schema issues.
 *
 * @evidence contracts/common.md#principled-implementation The validator function is extended with a `~standard` property that satisfies the Standard Schema contract: version 1, vendor `typia`, and a validate function that runs the original validator and maps its errors to issues whose path is parsed from typia's `$input` notation into key segments. Success returns the data as the value. The function is modified in place with Object.assign, so the returned value is the same callable.
 * @evidence contracts/common.md#clear-and-simple-design One factory and a path parser written as a small state machine for start, property, string key and number key; the value formatter is separate.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The contract members are declared by the specification and are filled from the validator's own results, with no case keyed on a consumer. The parser expects generated `$input` paths and throws for an invalid prefix or unfinished segment; validator and conversion exceptions propagate. The fixed version/vendor fields are contract constants.
 * @evidence contracts/common.md#meaningful-documentation The doc states the added property, the issue mapping and that the returned function is the same object.
 */
export const _createStandardSchema = <T>(
  fn: (input: unknown) => IValidation<T>,
): ((input: unknown) => IValidation<T>) & StandardSchemaV1<T, T> =>
  Object.assign(fn, {
    "~standard": {
      version: 1,
      vendor: "typia",
      validate: (input: unknown): StandardSchemaV1.Result<T> => {
        const result = fn(input);
        if (result.success) {
          return {
            value: result.data,
          } satisfies StandardSchemaV1.SuccessResult<T>;
        } else {
          return {
            issues: result.errors.map((error) => ({
              message: `expected ${error.expected}, got ${formatValue(error.value)}`,
              path: typiaPathToStandardSchemaPath(error.path),
            })),
          } satisfies StandardSchemaV1.FailureResult;
        }
      },
    },
  } satisfies StandardSchemaV1<T, T>);

const formatValue = (value: unknown): string => {
  if (typeof value === "object") {
    if (value === null) return "null";
    try {
      if (Array.isArray(value)) return "[object Array]";
    } catch {
      // A revoked proxy can throw even for Array.isArray().
    }
    return "[object Object]";
  }
  if (typeof value === "function") return "[function]";
  return String(value);
};

enum PathParserState {
  // Start of a new segment
  // When the parser is in this state,
  // the pointer must point `.` or `[` or equal to length of the path
  Start,
  // Parsing a property key (`.hoge`)
  Property,
  // Parsing a string key (`["fuga"]`)
  StringKey,
  // Parsing a number key (`[42]`)
  NumberKey,
}

const typiaPathToStandardSchemaPath = (
  path: string,
): ReadonlyArray<StandardSchemaV1.PathSegment> => {
  if (!path.startsWith("$input")) {
    throw new Error(`Invalid path: ${JSON.stringify(path)}`);
  }

  const segments: StandardSchemaV1.PathSegment[] = [];
  let currentSegment = "";
  let state: PathParserState = PathParserState.Start;
  let index = "$input".length - 1;
  while (index < path.length - 1) {
    index++;
    const char = path[index];

    if (state === PathParserState.Property) {
      if (char === "." || char === "[") {
        // End of property
        segments.push({
          key: currentSegment,
        });
        state = PathParserState.Start;
      } else if (index === path.length - 1) {
        // End of path
        currentSegment += char;
        segments.push({
          key: currentSegment,
        });
        index++;
        state = PathParserState.Start;
      } else {
        currentSegment += char;
      }
    } else if (state === PathParserState.StringKey) {
      if (char === '"') {
        // End of string key
        segments.push({
          key: JSON.parse(currentSegment + char),
        });
        // Skip `"` and `]`
        index += 2;
        state = PathParserState.Start;
      } else if (char === "\\") {
        // Skip the next character from parsing
        currentSegment += path[index];
        index++;
        currentSegment += path[index];
      } else {
        currentSegment += char;
      }
    } else if (state === PathParserState.NumberKey) {
      if (char === "]") {
        // End of number key
        segments.push({
          key: Number.parseInt(currentSegment),
        });
        index++;
        state = PathParserState.Start;
      } else {
        currentSegment += char;
      }
    }

    if (state === PathParserState.Start && index < path.length - 1) {
      const newChar = path[index];
      currentSegment = "";
      if (newChar === "[") {
        if (path[index + 1] === '"') {
          // Start of string key
          // NOTE: Typia uses JSON.stringify for this kind of keys, so `'` will not used as a string delimiter
          state = PathParserState.StringKey;
          index++;
          currentSegment = '"';
        } else {
          // Start of number key
          state = PathParserState.NumberKey;
        }
      } else if (newChar === ".") {
        // Start of property
        state = PathParserState.Property;
      } else {
        throw new Error("Unreachable: pointer points invalid character");
      }
    }
  }

  if (state !== PathParserState.Start) {
    throw new Error(`Failed to parse path: ${JSON.stringify(path)}`);
  }

  return segments;
};

typia/src/internal/_decimal.ts:
/**
 * A decimal number, `coefficient * 10 ** exponent`.
 *
 * @evidence contracts/common.md#principled-implementation A decimal number is the pair of an integer coefficient and a power-of-ten exponent, `coefficient * 10^exponent`, which represents a printed number exactly where a double cannot.
 * @evidence contracts/common.md#clear-and-simple-design Two fields.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A data record.
 * @evidence contracts/common.md#meaningful-documentation A comment states the representation.
 */
export interface _IDecimal {
  /** Signed integer digits of the decimal representation. */
  coefficient: bigint;

  /** Power of ten applied to the coefficient. */
  exponent: number;
}

/**
 * An exact quotient of two big integers.
 *
 * @evidence contracts/common.md#principled-implementation An exact quotient is a numerator and a denominator of big integers, so divisibility can be tested by remainder.
 * @evidence contracts/common.md#clear-and-simple-design Two fields.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A data record.
 * @evidence contracts/common.md#meaningful-documentation A comment states the representation.
 */
export interface _IDecimalRatio {
  /** Exact dividend after aligning the decimal exponents. */
  numerator: bigint;

  /** Exact nonzero divisor after aligning the decimal exponents. */
  denominator: bigint;
}

/**
 * Read a number as the decimal that its shortest string shows.
 *
 * @returns The decimal, or `null` for a non-finite number
 *
 * @evidence contracts/common.md#principled-implementation The shortest decimal string of the number, which is what JavaScript prints, is split into digits and an exponent: the mantissa digits form the coefficient, the sign is applied and the exponent is the printed exponent minus the number of decimals. Non-finite numbers return null.
 * @evidence contracts/common.md#clear-and-simple-design One function using string operations and BigInt.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The decimal reading is the documented semantics for `multipleOf` and not a tolerance fix.
 * @evidence contracts/common.md#meaningful-documentation A comment states the reading of a number as its printed decimal and the null case.
 */
export const _decimalDecompose = (value: number): _IDecimal | null => {
  if (Number.isFinite(value) === false) return null;
  const [mantissa = "0", exponentText = "0"] = value.toString().split("e");
  const negative: boolean = mantissa.startsWith("-");
  const unsigned: string = negative ? mantissa.slice(1) : mantissa;
  const point: number = unsigned.indexOf(".");
  const decimals: number = point === -1 ? 0 : unsigned.length - point - 1;
  const digits: bigint = BigInt(unsigned.replace(".", ""));
  return {
    coefficient: negative ? -digits : digits,
    exponent: Number(exponentText) - decimals,
  };
};

/**
 * Divide a number by a decimal exactly.
 *
 * @returns The ratio, or `null` for a non-finite value or a zero divisor
 *
 * @evidence contracts/common.md#principled-implementation The dividend is decomposed and the exponents are aligned by multiplying the numerator or the denominator by a power of ten, giving an exact ratio; a zero divisor or a non-finite value returns null.
 * @evidence contracts/common.md#clear-and-simple-design One function over the decomposition and the power helper.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The result is exact and no rounding is used.
 * @evidence contracts/common.md#meaningful-documentation A comment states the ratio and the null cases.
 */
export const _decimalDivide = (
  value: number,
  divisor: _IDecimal,
): _IDecimalRatio | null => {
  const dividend: _IDecimal | null = _decimalDecompose(value);
  if (dividend === null || divisor.coefficient === BigInt(0)) return null;
  const exponent: number = dividend.exponent - divisor.exponent;
  return exponent >= 0
    ? {
        numerator: dividend.coefficient * _decimalPower(exponent),
        denominator: divisor.coefficient,
      }
    : {
        numerator: dividend.coefficient,
        denominator: divisor.coefficient * _decimalPower(-exponent),
      };
};

/**
 * Find the smallest positive integer whose multiples are the integers that are
 * multiples of a decimal.
 *
 * @returns The step, or `null` for a non-finite or non-positive value
 *
 * @evidence contracts/common.md#principled-implementation For an integer value to be a multiple of a decimal step `c * 10^e`, the step is the integer itself when the exponent is not negative and otherwise the coefficient divided by its gcd with 10^-e; non-finite and non-positive steps return null.
 * @evidence contracts/common.md#clear-and-simple-design One function reusing the decomposition, the power and the gcd helper.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The result follows from the arithmetic.
 * @evidence contracts/common.md#meaningful-documentation A comment states the three cases.
 */
export const _decimalIntegerStep = (value: number): _IDecimal | null => {
  const decimal: _IDecimal | null = _decimalDecompose(value);
  if (decimal === null || decimal.coefficient <= BigInt(0)) return null;
  if (decimal.exponent >= 0)
    return {
      coefficient: decimal.coefficient * _decimalPower(decimal.exponent),
      exponent: 0,
    };

  const denominator: bigint = _decimalPower(-decimal.exponent);
  return {
    coefficient:
      decimal.coefficient / _decimalGcd(decimal.coefficient, denominator),
    exponent: 0,
  };
};

/**
 * Convert a decimal to the nearest number.
 *
 * @evidence contracts/common.md#principled-implementation The decimal is formatted as `coefficient e exponent` text and parsed by Number, which returns the nearest double, so the conversion is exact whenever the decimal is representable and otherwise rounds to the nearest.
 * @evidence contracts/common.md#clear-and-simple-design One expression.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Rounding is stated and callers verify the result where validity matters, as the random multiple helper does.
 * @evidence contracts/common.md#meaningful-documentation A comment states the nearest-double conversion.
 */
export const _decimalToNumber = (value: _IDecimal): number =>
  Number(`${value.coefficient}e${value.exponent}`);

/**
 * Compute ten to a non-negative integer power exactly.
 *
 * @evidence contracts/common.md#principled-implementation Ten to a non-negative integer power is computed with big integers, so it is exact for any exponent.
 * @evidence contracts/common.md#clear-and-simple-design One expression.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A general helper.
 * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
 */
export const _decimalPower = (exponent: number): bigint =>
  BigInt(10) ** BigInt(exponent);

/**
 * Compute the greatest common divisor of two big integers.
 *
 * @evidence contracts/common.md#principled-implementation Euclid's remainder iteration accepts the signed integers and returns the absolute final divisor. The absolute remainder decreases on each nonterminal step, so it terminates; two zeros return zero.
 * @evidence contracts/common.md#clear-and-simple-design One loop.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts A recognized algorithm.
 * @evidence contracts/common.md#meaningful-documentation A one-line comment states what it returns.
 */
export const _decimalGcd = (x: bigint, y: bigint): bigint => {
  while (y !== BigInt(0)) [x, y] = [y, x % y];
  return x < BigInt(0) ? -x : x;
};

