/**
 * Checks four-digit year, month and day syntax and Gregorian month length.
 *
 * The numeric year is used directly, including year zero; Date parsing and its
 * local-time normalization do not determine validity.
 *
 * @evidence contracts/common.md#principled-implementation Captured ranges establish month and positive day bounds before indexing the month-length table. The divisible-by-400 or divisible-by-4-but-not-100 rule adds the February leap day, so syntactically valid impossible dates fail.
 * @evidence contracts/common.md#clear-and-simple-design The private syntax expression and month-length table separate lexical ranges from the one calendar calculation that syntax cannot establish.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The table and divisibility rules represent the calendar uniformly; no dates or consumers receive special outcomes.
 * @evidence contracts/common.md#meaningful-documentation The doc states the four-digit year, month and day syntax and the Gregorian month length, that year zero is accepted and that Date parsing does not decide validity.
 */
export const _isFormatDate = (str: string): boolean => {
  const match: RegExpExecArray | null = PATTERN.exec(str);
  if (match === null) return false;
  const year: number = Number(match[1]);
  const month: number = Number(match[2]);
  const day: number = Number(match[3]);
  const maximum: number =
    DAYS[month - 1]! +
    (month === 2 && (year % 400 === 0 || (year % 4 === 0 && year % 100 !== 0))
      ? 1
      : 0);
  return day <= maximum;
};

const PATTERN = /^([0-9]{4})-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$/;
const DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31] as const;

typia/src/internal/_isFormatDateTime.ts:
import { _isFormatDate } from "./_isFormatDate";

/**
 * Checks timestamp syntax, calendar dates and possible UTC leap-second
 * position.
 *
 * An explicit Z or numeric offset is required. A second of 60 is permitted only
 * at a UTC June or December month-end boundary; this does not consult a
 * historical leap-second announcement table.
 *
 * @evidence contracts/common.md#principled-implementation The syntax expression bounds clock and offset fields and delegates the date to the calendar predicate. UTC setters preserve literal years, and offset subtraction determines whether a potential leap second occupies the permitted month-end minute.
 * @evidence contracts/common.md#clear-and-simple-design Ordinary seconds finish after syntax/calendar validation; only the leap-second branch constructs the UTC instant needed for the boundary decision.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts UTC conversion and the potential leap-second boundary are uniform rules. The implementation neither relies on local timezone nor special-cases fixture dates; historical announcements are outside this check.
 * @evidence contracts/common.md#meaningful-documentation The doc states that an offset is required, when a second of 60 is allowed and that no leap-second announcement table is consulted.
 */
export const _isFormatDateTime = (str: string): boolean => {
  const match: RegExpExecArray | null = PATTERN.exec(str);
  if (match === null || _isFormatDate(match[1]!) === false) return false;
  if (match[7] !== "60") return true;

  const instant: Date = new Date(0);
  instant.setUTCFullYear(
    Number(match[2]),
    Number(match[3]) - 1,
    Number(match[4]),
  );
  instant.setUTCHours(Number(match[5]), Number(match[6]), 0, 0);
  const offset: number =
    match[8] === undefined
      ? 0
      : (match[8] === "+" ? 1 : -1) *
        (Number(match[9]) * 60 + Number(match[10]));
  instant.setUTCMinutes(instant.getUTCMinutes() - offset);
  return (
    instant.getUTCHours() === 23 &&
    instant.getUTCMinutes() === 59 &&
    ((instant.getUTCMonth() === 5 && instant.getUTCDate() === 30) ||
      (instant.getUTCMonth() === 11 && instant.getUTCDate() === 31))
  );
};

const PATTERN =
  /^(([0-9]{4})-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01]))[Tt]((?:[01][0-9]|2[0-3])):([0-5][0-9]):([0-5][0-9]|60)(?:\.[0-9]+)?(?:[Zz]|([+-])((?:[01][0-9]|2[0-3])):([0-5][0-9]))$/;

/**
 * Checks the internationalized hostname spelling of the `idn-hostname` format.
 *
 * Accepts the hostname structure with label characters extended to the code
 * units from U+00A1 to U+FFFF. It checks characters and lengths only: IDNA
 * mapping, Punycode and the contextual and bidirectional rules are not applied.
 * Surrogate pairs are accepted as two label code units, so astral characters
 * consume two units of the label and hostname length limits.
 *
 * @evidence contracts/common.md#principled-implementation The ASCII hostname structure is reused with the label class widened to code units from U+00A1 to U+FFFF, so every valid hostname is also a valid IDN hostname as the comment records. Without the `u` flag, both units of a surrogate pair match separately and consume two units of the length limits; this also admits unpaired surrogates. IDNA mapping, Punycode and contextual and bidirectional rules are not applied, so this spelling check is an approximation rather than IDNA validation.
 * @evidence contracts/common.md#clear-and-simple-design One predicate and one private pattern, identical to the copy in @typia/utils.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The widening is a stated approximation of IDNA, not a fixture accommodation.
 * @evidence contracts/common.md#meaningful-documentation The doc states the character range and the checks that are absent.
 */
export const _isFormatIdnHostname = (str: string): boolean => PATTERN.test(str);

// The ASCII `hostname` structure with the label character class extended by the
// non-ASCII range: every valid host name is a valid IDN host name, so this must
// accept a single label, a one-to-63-character label in any position, and a
// name up to 253 characters, exactly as `_isFormatHostname` does (issue #2317).
const PATTERN =
  /^(?=.{1,253}\.?$)[a-z0-9\u00a1-\uffff](?:[a-z0-9\u00a1-\uffff-]{0,61}[a-z0-9\u00a1-\uffff])?(?:\.[a-z0-9\u00a1-\uffff](?:[a-z0-9\u00a1-\uffff-]{0,61}[a-z0-9\u00a1-\uffff])?)*\.?$/i;

typia/src/internal/_isFormatIriReference:
/**
 * Checks the `iri-reference` format at the character level.
 *
 * Rejects control characters, DEL and C1 controls, lone surrogates, space and
 * the characters `"<>\^`{|}`, and any `%`that is not followed by two
 * hexadecimal digits. A colon before the first`/`, `?`or`#` must end a valid
 * scheme. Authority, port and path structure are not parsed.
 *
 * @evidence contracts/common.md#principled-implementation Characters that no IRI may contain (controls, space, lone surrogates and a few ASCII delimiters) and malformed percent escapes are rejected, and a colon before the first path delimiter must be the end of a valid scheme, which separates `a:b` from the relative `./a:b`. Authority, port and path structure are not parsed, so the predicate is a character and scheme check and not full grammar validation.
 * @evidence contracts/common.md#clear-and-simple-design One predicate with three private patterns, identical to the copy in @typia/utils.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The forbidden set comes from the IRI grammar and not from examples.
 * @evidence contracts/common.md#meaningful-documentation The doc states what is rejected and what is not parsed.
 */
export const _isFormatIriReference = (str: string): boolean => {
  if (FORBIDDEN.test(str) || INVALID_PERCENT.test(str)) return false;
  const colon: number = str.indexOf(":");
  const boundary: number = str.search(/[/?#]/u);
  return (
    colon === -1 || (boundary !== -1 && boundary < colon) || SCHEME.test(str)
  );
};

const FORBIDDEN = /[\u0000-\u0020\u007f-\u009f\ud800-\udfff"<>\\^`{|}]/u;
const INVALID_PERCENT = /%(?![0-9A-Fa-f]{2})/u;
const SCHEME = /^[A-Za-z][A-Za-z0-9+.-]*:/u;

typia/src/internal/_isFormatRegex.ts:
/**
 * Checks whether the runtime accepts a regular expression source without flags.
 *
 * Construction validates syntax; the resulting expression is never executed
 * against a value and is not retained.
 *
 * @evidence contracts/common.md#principled-implementation RegExp construction is the syntax authority of the runtime. Only successful construction returns true; syntax exceptions are converted to false.
 * @evidence contracts/common.md#clear-and-simple-design A single construction/exception boundary avoids maintaining a second regular expression grammar.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Native RegExp construction is the required syntax check and is not replaced or patched. No source receives an exceptional verdict.
 * @evidence contracts/common.md#meaningful-documentation The doc states that the source is tested by construction without flags, and that the expression is neither executed against a value nor retained.
 */
export const _isFormatRegex = (str: string): boolean => {
  try {
    new RegExp(str);
    return true;
  } catch {
    return false;
  }
};

typia/src/internal/_isFormatTime.ts:
/**
 * Checks an offset-qualified clock and possible UTC leap-second minute.
 *
 * There is no calendar date to verify. A second of 60 requires the supplied
 * clock and offset to map to 23:59 UTC, with negative offsets normalized into
 * the day.
 *
 * @evidence contracts/common.md#principled-implementation The expression bounds clock and offset fields. Offset subtraction and a nonnegative modulo of 1440 minutes identify the final UTC minute without pretending a date is present.
 * @evidence contracts/common.md#clear-and-simple-design Ordinary seconds use the syntax result; the extra arithmetic is confined to the leap-second branch and needs no Date allocation.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Clock ranges and day wrapping apply to all inputs; no local-time conversion or fixture-specific leap-second allowance is used.
 * @evidence contracts/common.md#meaningful-documentation The doc states that an offset is required, that there is no date to verify and how a second of 60 maps to 23:59 UTC with negative offsets normalized into the day.
 */
export const _isFormatTime = (str: string): boolean => {
  const match: RegExpExecArray | null = PATTERN.exec(str);
  if (match === null) return false;
  if (match[3] !== "60") return true;

  // RFC 3339 admits `:60` only where a leap second is inserted, which is
  // always 23:59:60 UTC. `date-time` decides that from the instant it can
  // build; a clock carries no date, so it shifts itself by its own offset and
  // asks the same question, wrapping the result back into the day.
  const offset: number =
    match[4] === undefined
      ? 0
      : (match[4] === "+" ? 1 : -1) *
        (Number(match[5]) * 60 + Number(match[6]));
  const minutes: number = Number(match[1]) * 60 + Number(match[2]) - offset;
  return ((minutes % DAY) + DAY) % DAY === DAY - 1;
};

const PATTERN =
  /^([01][0-9]|2[0-3]):([0-5][0-9]):([0-5][0-9]|60)(?:\.[0-9]+)?(?:[Zz]|([+-])((?:[01][0-9]|2[0-3])):([0-5][0-9]))$/;
const DAY = 24 * 60;

typia/src/internal/_isFormatUri.ts:
/**
 * Checks the RFC 3986 URI spelling of the `uri` format.
 *
 * Requires a scheme, then accepts the hierarchical forms with an optional
 * authority, an IPv4, IPv6 or future-version address literal or a registered
 * name, a path, a query and a fragment, ignoring case. A string with neither
 * `/` nor `:` is rejected first, because a URI always has a scheme separator.
 * The accepted subset requires a nonempty hierarchical part after the scheme;
 * scheme-only forms such as `urn:` are not accepted.
 *
 * @evidence contracts/common.md#principled-implementation The expression checks URI syntax with a scheme, authority and path alternatives, optional user information, address literal or registered host name, port, query and fragment, ignoring case. It requires a nonempty hierarchical part after the scheme, unlike RFC 3986's path-empty alternative. The cheap slash-or-colon guard is implied by the scheme. The IPv4 octet alternative also accepts leading zeros; these accepted syntax rules are not a complete RFC grammar implementation.
 * @evidence contracts/common.md#clear-and-simple-design One predicate with two private patterns, identical to the copy in @typia/utils; the long expression is the grammar and is not factored.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The same documented URI subset applies to every input. The preliminary guard is implied by the scheme separator and therefore does not impose a different result.
 * @evidence contracts/common.md#meaningful-documentation The doc states the structure and the guard.
 */
export const _isFormatUri = (str: string): boolean =>
  NOT_URI_FRAGMENT.test(str) && URI.test(str);

const NOT_URI_FRAGMENT = /\/|:/;
const URI =
  /^(?:[a-z][a-z0-9+\-.]*:)(?:\/?\/(?:(?:[a-z0-9\-._~!$&'()*+,;=:]|%[0-9a-f]{2})*@)?(?:\[(?:(?:(?:(?:[0-9a-f]{1,4}:){6}|::(?:[0-9a-f]{1,4}:){5}|(?:[0-9a-f]{1,4})?::(?:[0-9a-f]{1,4}:){4}|(?:(?:[0-9a-f]{1,4}:){0,1}[0-9a-f]{1,4})?::(?:[0-9a-f]{1,4}:){3}|(?:(?:[0-9a-f]{1,4}:){0,2}[0-9a-f]{1,4})?::(?:[0-9a-f]{1,4}:){2}|(?:(?:[0-9a-f]{1,4}:){0,3}[0-9a-f]{1,4})?::[0-9a-f]{1,4}:|(?:(?:[0-9a-f]{1,4}:){0,4}[0-9a-f]{1,4})?::)(?:[0-9a-f]{1,4}:[0-9a-f]{1,4}|(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?))|(?:(?:[0-9a-f]{1,4}:){0,5}[0-9a-f]{1,4})?::[0-9a-f]{1,4}|(?:(?:[0-9a-f]{1,4}:){0,6}[0-9a-f]{1,4})?::)|[Vv][0-9a-f]+\.[a-z0-9\-._~!$&'()*+,;=:]+)\]|(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)|(?:[a-z0-9\-._~!$&'()*+,;=]|%[0-9a-f]{2})*)(?::\d*)?(?:\/(?:[a-z0-9\-._~!$&'()*+,;=:@]|%[0-9a-f]{2})*)*|\/(?:(?:[a-z0-9\-._~!$&'()*+,;=:@]|%[0-9a-f]{2})+(?:\/(?:[a-z0-9\-._~!$&'()*+,;=:@]|%[0-9a-f]{2})*)*)?|(?:[a-z0-9\-._~!$&'()*+,;=:@]|%[0-9a-f]{2})+(?:\/(?:[a-z0-9\-._~!$&'()*+,;=:@]|%[0-9a-f]{2})*)*)(?:\?(?:[a-z0-9\-._~!$&'()*+,;=:@/?]|%[0-9a-f]{2})*)?(?:#(?:[a-z0-9\-._~!$&'()*+,;=:@/?]|%[0-9a-f]{2})*)?$/i;

typia/src/internal/_isMultipleOf.ts:
import { _decimalDecompose, _decimalDivide } from "./_decimal";

/**
 * Test whether a number is a multiple of a divisor, reading both as decimals.
 *
 * `0.3` is a multiple of `0.1`. A non-finite number or a divisor that is not
 * positive gives false.
 *
 * @evidence contracts/common.md#principled-implementation Both numbers are read as the decimals they print as and the ratio of the dividend to the divisor is tested exactly with big integers, so `0.3` is a multiple of `0.1`; a non-finite value or a non-positive divisor is false.
 * @evidence contracts/common.md#clear-and-simple-design One predicate over the shared decimal helpers, which the random multiple generator also uses.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The decimal reading is the tag's documented meaning.
 * @evidence contracts/common.md#meaningful-documentation A comment states the decimal reading and the false cases.
 */
export const _isMultipleOf = (value: number, multipleOf: number): boolean => {
  const divisor = _decimalDecompose(multipleOf);
  if (divisor === null || divisor.coefficient <= BigInt(0)) return false;
  const ratio = _decimalDivide(value, divisor);
  return ratio !== null && ratio.numerator % ratio.denominator === BigInt(0);
};

typia/src/internal/_isTypeFloat.ts:
/**
 * Test whether a number is within the 32-bit float range; fractions are
 * allowed.
 *
 * @evidence contracts/common.md#principled-implementation A value is a 32-bit float when it is within the single-precision range, which the two bounds express; fractions are allowed and NaN and the infinities fail the comparison. The bound literal is the decimal text of the maximum, so values that only round to it are accepted.
 * @evidence contracts/common.md#clear-and-simple-design One expression and two constants.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The bounds are the format's.
 * @evidence contracts/common.md#meaningful-documentation A comment states the range and that fractions are allowed.
 */
export const _isTypeFloat = (value: number): boolean =>
  MINIMUM <= value && value <= MAXIMUM;

const MINIMUM = -3.4028235e38;
const MAXIMUM = 3.4028235e38;

