typia/src/internal/_isUniqueItems.ts:
/**
 * Checks that no two elements of an array are equal.
 *
 * Primitives are compared with strict equality, so two `NaN` values are not
 * duplicates. Objects, arrays, maps, sets, dates, regular expressions, boxed
 * primitives, buffers and typed arrays are compared structurally, with cycles
 * tolerated. Native categories must match on both sides; ordinary class
 * instances retain comparison by enumerable structure. Every pair is compared,
 * so the work grows quadratically with the number of elements. Blob comparison
 * uses size and MIME type; File adds name and last-modified time. Their payload
 * bytes are not read.
 *
 * @evidence contracts/common.md#principled-implementation Native categories are checked on both sides, distinguishing files from blobs and native values from ordinary objects. Every pair of elements is compared with a structural equality that is strict for primitives, handles arrays, sets, maps, boxed primitives, dates, expressions, files, blobs and binary buffers and compares plain objects by own enumerable keys, with a pair table so cycles end. Sets and maps are matched without regard to order. The pairwise scan costs quadratic time in the number of elements, which is stated in the doc.
 * @evidence contracts/common.md#clear-and-simple-design One predicate over a private equality builder and a bytes helper, identical to the copy in @typia/utils.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Equality rules are the documented ones and no element is special-cased.
 * @evidence contracts/common.md#meaningful-documentation The doc states the equality rules, the cycle tolerance and the quadratic cost.
 */
export const _isUniqueItems = (elements: any[]): boolean => {
  for (let i = 0; i < elements.length; i++)
    for (let j = i + 1; j < elements.length; j++)
      if (equals(new WeakMap())(elements[i], elements[j])) return false;
  return true;
};

const equals = (visited: WeakMap<object, WeakMap<object, boolean>>) => {
  const next = (a: any, b: any): boolean => {
    if (a === b) return true;
    if (
      a === null ||
      b === null ||
      typeof a !== "object" ||
      typeof b !== "object"
    )
      return false;

    const previous: boolean | undefined = visited.get(a)?.get(b);
    if (previous !== undefined) return previous;
    const pairs: WeakMap<object, boolean> =
      visited.get(a) ?? new WeakMap<object, boolean>();
    visited.set(a, pairs);
    pairs.set(b, true);

    const result: boolean = compare(a, b);
    pairs.set(b, result);
    return result;
  };

  const compare = (a: object, b: object): boolean => {
    if (kind(a) !== kind(b)) return false;
    if (Array.isArray(a)) {
      if (!Array.isArray(b) || a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        const aHas: boolean = Object.hasOwn(a, i);
        if (aHas !== Object.hasOwn(b, i) || (aHas && !next(a[i], b[i])))
          return false;
      }
      return true;
    }
    if (Array.isArray(b)) return false;

    if (a instanceof Set) {
      if (!(b instanceof Set) || a.size !== b.size) return false;
      const unmatched: any[] = [...b];
      for (const value of a) {
        const index: number = unmatched.findIndex((candidate) =>
          next(value, candidate),
        );
        if (index === -1) return false;
        unmatched.splice(index, 1);
      }
      return true;
    }
    if (a instanceof Map) {
      if (!(b instanceof Map) || a.size !== b.size) return false;
      const unmatched: [any, any][] = [...b];
      for (const [key, value] of a) {
        const index: number = unmatched.findIndex(
          ([candidateKey, candidateValue]) =>
            next(key, candidateKey) && next(value, candidateValue),
        );
        if (index === -1) return false;
        unmatched.splice(index, 1);
      }
      return true;
    }

    if (a instanceof Boolean)
      return b instanceof Boolean && a.valueOf() === b.valueOf();
    if (Object.prototype.toString.call(a) === "[object BigInt]")
      return (
        Object.prototype.toString.call(b) === "[object BigInt]" &&
        a.valueOf() === b.valueOf()
      );
    if (Object.prototype.toString.call(a) === "[object Symbol]")
      return (
        Object.prototype.toString.call(b) === "[object Symbol]" &&
        a.valueOf() === b.valueOf()
      );
    if (a instanceof Number)
      return b instanceof Number && a.valueOf() === b.valueOf();
    if (a instanceof String)
      return b instanceof String && a.valueOf() === b.valueOf();
    if (a instanceof Date)
      return b instanceof Date && a.getTime() === b.getTime();
    if (a instanceof RegExp)
      return (
        b instanceof RegExp && a.source === b.source && a.flags === b.flags
      );

    if (typeof File !== "undefined" && a instanceof File)
      return (
        b instanceof File &&
        a.name === b.name &&
        a.size === b.size &&
        a.type === b.type &&
        a.lastModified === b.lastModified
      );
    if (typeof Blob !== "undefined" && a instanceof Blob)
      return b instanceof Blob && a.size === b.size && a.type === b.type;

    if (a instanceof DataView) {
      if (!(b instanceof DataView) || a.byteLength !== b.byteLength)
        return false;
      return bytes(a.buffer, a.byteOffset, a.byteLength).every(
        (value, index) =>
          value === bytes(b.buffer, b.byteOffset, b.byteLength)[index],
      );
    }
    if (ArrayBuffer.isView(a)) {
      if (
        !ArrayBuffer.isView(b) ||
        b instanceof DataView ||
        Object.getPrototypeOf(a) !== Object.getPrototypeOf(b) ||
        a.byteLength !== b.byteLength
      )
        return false;
      const x: Uint8Array = bytes(a.buffer, a.byteOffset, a.byteLength);
      const y: Uint8Array = bytes(b.buffer, b.byteOffset, b.byteLength);
      return x.every((value, index) => value === y[index]);
    }
    if (a instanceof ArrayBuffer)
      return (
        b instanceof ArrayBuffer &&
        a.byteLength === b.byteLength &&
        bytes(a).every((value, index) => value === bytes(b)[index])
      );
    if (
      typeof SharedArrayBuffer !== "undefined" &&
      a instanceof SharedArrayBuffer
    )
      return (
        b instanceof SharedArrayBuffer &&
        a.byteLength === b.byteLength &&
        bytes(a).every((value, index) => value === bytes(b)[index])
      );

    const keys: PropertyKey[] = Reflect.ownKeys(a).filter((key) =>
      Object.prototype.propertyIsEnumerable.call(a, key),
    );
    return (
      keys.length ===
        Reflect.ownKeys(b).filter((key) =>
          Object.prototype.propertyIsEnumerable.call(b, key),
        ).length &&
      keys.every(
        (key) =>
          Object.prototype.propertyIsEnumerable.call(b, key) &&
          next((a as any)[key], (b as any)[key]),
      )
    );
  };
  return next;
};

const bytes = (
  buffer: ArrayBufferLike,
  byteOffset: number = 0,
  byteLength: number = buffer.byteLength,
): Uint8Array => new Uint8Array(buffer, byteOffset, byteLength);

/**
 * Keeps native categories separate while ordinary class instances stay
 * structural.
 */
const kind = (value: object): string => {
  if (Array.isArray(value)) return "Array";
  if (value instanceof Set) return "Set";
  if (value instanceof Map) return "Map";
  if (value instanceof Boolean) return "Boolean";
  if (value instanceof Number) return "Number";
  if (value instanceof String) return "String";
  const tag: string = Object.prototype.toString.call(value);
  if (tag === "[object BigInt]" || tag === "[object Symbol]") return tag;
  if (value instanceof Date) return "Date";
  if (value instanceof RegExp) return "RegExp";
  if (typeof File !== "undefined" && value instanceof File) return "File";
  if (typeof Blob !== "undefined" && value instanceof Blob) return "Blob";
  if (value instanceof DataView) return "DataView";
  if (ArrayBuffer.isView(value)) return "TypedArray";
  if (value instanceof ArrayBuffer) return "ArrayBuffer";
  if (
    typeof SharedArrayBuffer !== "undefined" &&
    value instanceof SharedArrayBuffer
  )
    return "SharedArrayBuffer";
  return "Object";
};

typia/src/internal/_jsonStringifyArray.t:
/**
 * Serializes the elements of an array the way ECMAScript `JSON.stringify` does.
 *
 * `SerializeJSONArray` walks index `0` to `LengthOfArrayLike(value) - 1` and
 * writes `null` wherever the element serializes to `undefined`. Neither
 * `Array.prototype.map` nor `Array.prototype.join` reproduces that:
 *
 * - `map` never visits a hole and leaves one behind, and `join` renders a hole as
 *   empty text, so a sparse array joined into malformed text such as `[,1]`. A
 *   hole exists at runtime whatever the element type declares, so this is not
 *   an `any` concern.
 * - `join` renders a mapped `undefined` as empty text too, which is what an `any`
 *   or `unknown` element holding a function, a symbol, or a `toJSON` that
 *   returns nothing serializes to.
 *
 * The length is converted with `ToLength` and read once, which is both what
 * `JSON.stringify` does and what `Array.prototype.every` - the traversal
 * typia's own array checkers emit - does, so the checker and the serializer
 * walk one index range rather than two that merely usually coincide.
 *
 * @param elements Array being serialized.
 * @param mapper Serializer of one element, emitted by the transform.
 *
 * @returns Comma separated element text, without the enclosing brackets.
 *
 * @internal
 */
export const _jsonStringifyArray = <T>(
  elements: ArrayLike<T>,
  mapper: (elem: T, index: number) => string,
): string => {
  const length: number = Math.min(
    Math.max(Math.trunc(elements.length) || 0, 0),
    Number.MAX_SAFE_INTEGER,
  );
  let output: string = "";
  for (let i: number = 0; i < length; ++i) {
    const elem: T | undefined = elements[i];
    // A hole and an explicit `undefined` are answered without calling the
    // mapper, because the mapper is the element type's own serializer and a
    // typed one has no answer for a missing value. Everything else is answered
    // from the mapper's *result*: an element that is present but serializes to
    // nothing — a function, a symbol, or a `toJSON` returning nothing in an
    // `any` slot — is `null` in an array position, exactly as
    // SerializeJSONArray specifies, and testing the input instead would let its
    // text become the literal `undefined`.
    const text: string | undefined =
      elem === undefined ? undefined : mapper(elem, i);
    output += (i === 0 ? "" : ",") + (text === undefined ? "null" : text);
  }
  return output;
};

typia/src/internal/_jsonStringifyRest.ts:
/**
 * Turn a stringified bracketed body into a comma-led continuation.
 *
 * The surrounding brackets are removed; an empty body, which is two characters,
 * gives the empty string.
 *
 * @evidence contracts/common.md#principled-implementation The argument is the stringified tail of an array or object body, that is brackets around zero or more elements, and the function turns it into a comma-led continuation by stripping the brackets, with an empty body (two characters) giving the empty string, so a fixed prefix of tuple elements can be followed by the rest elements.
 * @evidence contracts/common.md#clear-and-simple-design One expression over one string.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts It relies on the caller's bracketed input and does not parse it.
 * @evidence contracts/common.md#meaningful-documentation A comment states the expected input and the empty case.
 */
export const _jsonStringifyRest = (str: string): string => {
  return str.length === 2 ? "" : "," + str.substring(1, str.length - 1);
};

/**
 * Serialize a string as a JSON string literal.
 *
 * A string with no control character, surrogate, quote or backslash is wrapped
 * in quotes, and quotes and backslashes are escaped by copying slices; any
 * control character or surrogate falls back to `JSON.stringify`, so the result
 * equals `JSON.stringify(str)` for every input.
 *
 * In the past, name of `typia` was `typescript-json`, and supported JSON
 * serialization by wrapping `fast-json-stringify. `typescript-json`was a helper
 * library of`fast-json-stringify`, which can skip manual JSON schema definition
 * just by putting pure TypeScript type.
 *
 * This `$string` function is a part of `fast-json-stringify` at that time, and
 * still being used in `typia` for the string serialization.
 *
 * @reference https://github.com/fastify/fast-json-stringify/blob/master/lib/serializer.js
 *
 * @blog https://dev.to/samchon/good-bye-typescript-is-ancestor-of-typia-20000x-faster-validator-49fi
 *
 * @evidence contracts/common.md#principled-implementation The common case is a string without control characters, quotes, backslashes or surrogates, which is wrapped in quotes without a pass through the general serializer; quotes and backslashes are escaped by copying slices, and any control character or surrogate falls back to `JSON.stringify`, which handles every remaining escape and lone-surrogate rule, so the result equals `JSON.stringify(str)` for all input.
 * @evidence contracts/common.md#clear-and-simple-design One function with a single scan and one fallback.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The fast path is a speed-up with the same result and falls back for every character that needs more than escaping a quote or backslash; it is adapted from fast-json-stringify, as the comment records.
 * @evidence contracts/common.md#meaningful-documentation The doc states what the function produces, the origin and the reference of the helper; the equality with `JSON.stringify` is argued in the principle answer.
 */
export const _jsonStringifyString = (str: string): string => {
  const len = str.length;
  let result = "";
  let last = -1;
  let point = 255;

  // eslint-disable-next-line
  for (var i = 0; i < len; i++) {
    point = str.charCodeAt(i);
    if (point < 32) {
      return JSON.stringify(str);
    }
    if (point >= 0xd800 && point <= 0xdfff) {
      // The current character is a surrogate.
      return JSON.stringify(str);
    }
    if (
      point === 0x22 || // '"'
      point === 0x5c // '\'
    ) {
      last === -1 && (last = 0);
      result += str.slice(last, i) + "\\";
      last = i;
    }
  }

  return (
    (last === -1 && '"' + str + '"') || '"' + result + str.slice(last) + '"'
  );
};

typia/src/internal/_llmApplicationFinali:
import { IJsonParseResult, ILlmApplication } from "@typia/interface";
import { LlmJson, LlmSchemaConverter } from "@typia/utils";

/**
 * Complete an emitted LLM application at runtime.
 *
 * Each function gets `parse` and `coerce` bound to its parameters schema and a
 * validator that a custom hook can replace. The schema configuration is the one
 * the emitted application declares. The returned application shares schemas
 * with the primitive; keep them unchanged while using the bound operations.
 *
 * @evidence contracts/common.md#principled-implementation The emitted application, which has the schemas and the declared configuration, is completed at runtime: each function gains parse and coerce bound to its parameter schema and a validator that a custom hook can replace, and the configuration is the emitted one with the hook. The schema configuration is taken from the emitted application because that is where the generic was resolved, so a strict build reports strict.
 * @evidence contracts/common.md#clear-and-simple-design One function that spreads the primitive application and maps its functions, using the utility package for parsing and coercion.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Parsing and coercion are delegated to the utilities and the hook is the supported customization point.
 * @evidence contracts/common.md#meaningful-documentation A comment states the completion and the source of the configuration.
 */
export const _llmApplicationFinalize = <Class extends object = any>(
  app: ILlmApplication.__IPrimitive<Class>,
  config?: Partial<Pick<ILlmApplication.IConfig, "validate">>,
): ILlmApplication<Class> => ({
  ...app,
  config: {
    // The schema configuration comes from the emitted application, which is
    // where the `Config` generic was resolved. Rebuilding it from the
    // converter's defaults reported `strict: false` for a strict build, and
    // `@typia/mcp` then inverted a strict output schema without strict, which
    // drops every constraint it carries as a description tag (issue #2293).
    ...LlmSchemaConverter.getConfig(app.config),
    validate: config?.validate ?? null,
  },
  functions: app.functions.map((func) => ({
    ...func,
    parse: (input: string): IJsonParseResult<unknown> =>
      LlmJson.parse(input, func.parameters),
    coerce: (input: unknown): unknown => LlmJson.coerce(input, func.parameters),
    validate: config?.validate?.[func.name] ?? func.validate,
  })),
});

