import type { OpenApi } from "@typia/interface";

import { _isUniqueItems } from "./_isUniqueItems";
import { _randomInteger } from "./_randomInteger";

const DEFAULT_MIN_ITEMS = 1;
const DEFAULT_RANGE = 5;
const DEFAULT_RECURSIVE_RANGE = 2;

/**
 * Consecutive duplicates that end a unique draw once its floor is satisfied.
 *
 * For independent uniform draws with one unseen value among four, sixty-four
 * misses in a row have probability `0.75 ** 64`. This stopping rule does not
 * prove domain exhaustion. Below the floor it is disabled, but the total
 * attempt budget can still end before a reachable minimum is observed.
 */
const STALE_LIMIT = 64;

/**
 * Generate a random array from an array schema.
 *
 * The length is drawn between the bounds, with a default minimum of one, or
 * zero on a recursive cycle. For a unique array the count is a preference above
 * the minimum: drawing stops at the total attempt budget or, after reaching the
 * minimum, a run of duplicates. A result below the minimum throws even when
 * enough distinct values exist but were not observed within that budget.
 *
 * The optional source supplies draws in [0, 1); it defaults to the platform
 * source resolved when this helper is called. Nested draws use the same
 * source.
 *
 * @evidence contracts/common.md#principled-implementation The length is drawn between the schema's bounds with a default minimum of one, or zero on a recursive cycle so graph-shaped data ends, and elements come from the supplied callback. Unique generation stops at the requested count, count * 100 + 1000 total attempts, or sixty-four consecutive duplicates after the minimum is met. These bounded observations do not prove domain exhaustion; a result below the minimum throws even if the callback could produce more distinct values. A returned result always meets the minimum, while the chosen count is a preference above it.
 * @evidence contracts/common.md#clear-and-simple-design One function with a plain branch and a unique branch; defaults are module constants.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The unique branch accepts a result shorter than the preferred count when it meets the minimum. Failure means the minimum was not observed within the finite attempt budget, rather than proving it unreachable; no callback domain is inferred from repeated duplicates.
 * @evidence contracts/common.md#meaningful-documentation The doc states the length rule, the unique-draw budget and the stale limit, and the module comments explain the reasoning.
 */
export const _randomArray = <T>(
  props: Omit<OpenApi.IJsonSchema.IArray, "items"> & {
    element: (index: number, count: number) => T;
    recursive?: boolean;
  },
  source: () => number = Math.random,
) => {
  const defaultMinimum: number =
    props.recursive === true ? 0 : DEFAULT_MIN_ITEMS;
  const minimum: number =
    props.minItems ??
    Math.min(props.maxItems ?? defaultMinimum, defaultMinimum);
  const count: number = _randomInteger(
    {
      type: "integer",
      minimum,
      maximum:
        props.maxItems ??
        minimum +
          (props.recursive === true ? DEFAULT_RECURSIVE_RANGE : DEFAULT_RANGE),
    },
    source,
  );
  if (props.uniqueItems !== true)
    return new Array(count).fill(null).map((_, i) => props.element(i, count));
  // How many distinct values the element can take is not knowable from here --
  // `element` is a closure over whatever the transform emitted, from `boolean`
  // to a recursive object -- so the count above is a preference, not a
  // contract. Stop at the bounded attempt budget or duplicate-run limit, then
  // keep what was reached if it meets the minimum. Neither limit proves that
  // the callback's domain has nothing new left.
  //
  // Failing on that budget instead is what made `Array<boolean> &
  // UniqueItems` throw on two draws in three: `[true, false]` satisfies the
  // declaration at every count, and a count of five is unreachable for a
  // domain of two however many times it is redrawn. Only a result below the
  // floor is a real failure, which is still the honest outcome for a window
  // like `MinItems<3>` over a domain of two.
  //
  // Below the floor the whole budget is available, though a rare or biased
  // callback can still miss enough distinct values before it ends. Above the
  // floor further attempts only increase length, so `STALE_LIMIT` consecutive
  // duplicates end that search early. This bounds repeated work for nested
  // small-domain unique arrays without claiming the domain is exhausted.
  const elements: T[] = [];
  const maximumAttempts: number = count * 100 + 1000;
  let stale: number = 0;
  for (
    let attempts = 0;
    elements.length !== count && attempts !== maximumAttempts;
    attempts++
  ) {
    const candidate: T = props.element(elements.length, count);
    if (elements.every((element) => _isUniqueItems([element, candidate]))) {
      elements.push(candidate);
      stale = 0;
    } else if (elements.length >= minimum && ++stale === STALE_LIMIT) break;
  }
  if (elements.length < minimum)
    throw new Error(
      "Unable to generate enough unique items; the element domain may be too small.",
    );
  return elements;
};

typia/src/internal/_randomBigint.ts:
import { OpenApi } from "@typia/interface";

import { _decimalIntegerStep } from "./_decimal";

/**
 * Generates a random `bigint` satisfying an integer schema.
 *
 * The schema carries its bounds and step as numbers, but the value is a
 * `bigint`, so the draw runs on integers. Drawing through doubles rounded every
 * value past 2^53, and it checked `multipleOf` against a double's shortest
 * decimal text rather than the integer `BigInt` makes of it, so `random`
 * returned values the validator rejects, or gave up on a range that holds one
 * (#2457). An integral bound or step is read as the integer the double holds,
 * which is the integer the validator compares with.
 *
 * @evidence contracts/common.md#principled-implementation Bounds and step are read as the integers their doubles hold, an exclusive bound is moved to the next inclusive integer, and the draw is made on bigints so no precision is lost past 2^53; a multiple of the step is chosen by dividing the range by the step, drawing a quotient and multiplying back. The draw scales one 53-bit sample, so a range wider than 2^53 values is sampled at most that many distinct points.
 * @evidence contracts/common.md#clear-and-simple-design One function with small private helpers for the bound, the step, the rounding divisions and the draw.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts Errors for empty or infinite ranges are explicit, and the step is the integer the validator compares with.
 * @evidence contracts/common.md#meaningful-documentation The doc explains why the draw is not done through doubles and cites the issue.
 */
export const _randomBigint = (schema: OpenApi.IJsonSchema.IInteger): bigint => {
  const lower: bigint | null = boundary(
    schema.minimum,
    schema.exclusiveMinimum,
    "lower",
  );
  const upper: bigint | null = boundary(
    schema.maximum,
    schema.exclusiveMaximum,
    "upper",
  );
  const minimum: bigint =
    lower ?? (upper === null ? BigInt(0) : upper - BigInt(100));
  const maximum: bigint =
    upper ?? (lower === null ? BigInt(100) : lower + BigInt(100));
  if (minimum > maximum)
    throw new Error("Minimum value is greater than maximum value.");
  if (schema.multipleOf === undefined) return between(minimum, maximum);

  const step: bigint | null = integerStep(schema.multipleOf);
  if (step === null || step <= BigInt(0))
    throw new Error("The multipleOf value must be a positive finite number.");
  const first: bigint = ceilDivide(minimum, step);
  const last: bigint = floorDivide(maximum, step);
  if (first > last)
    throw new Error("The range does not contain a multipleOf value.");
  return between(first, last) * step;
};

/**
 * Reads one side's inclusive integer bound.
 *
 * `-Infinity` below or `Infinity` above excludes no integer, so it is no bound
 * at all; `Infinity` below or `-Infinity` above excludes every integer.
 */
const boundary = (
  inclusive: number | undefined,
  exclusive: number | undefined,
  side: "lower" | "upper",
): bigint | null => {
  const candidates: bigint[] = [];
  for (const [value, open] of [
    [inclusive, false],
    [exclusive, true],
  ] as const) {
    if (value === undefined) continue;
    if (Number.isFinite(value) === false) {
      if (value === (side === "lower" ? -Infinity : Infinity)) continue;
      throw new Error("Numeric range has no finite value.");
    }
    candidates.push(
      side === "lower"
        ? open
          ? BigInt(Math.floor(value)) + BigInt(1)
          : BigInt(Math.ceil(value))
        : open
          ? BigInt(Math.ceil(value)) - BigInt(1)
          : BigInt(Math.floor(value)),
    );
  }
  if (candidates.length === 0) return null;
  return candidates.reduce((x, y) =>
    side === "lower" ? (x > y ? x : y) : x < y ? x : y,
  );
};

/**
 * The smallest positive integer a `multipleOf` divides.
 *
 * An integral step is the integer its double holds; a fractional one, such as
 * `1.5`, steps by its smallest integer multiple (`3`).
 */
const integerStep = (multipleOf: number): bigint | null => {
  if (Number.isFinite(multipleOf) === false) return null;
  if (Number.isInteger(multipleOf)) return BigInt(multipleOf);
  return _decimalIntegerStep(multipleOf)?.coefficient ?? null;
};

const ceilDivide = (x: bigint, y: bigint): bigint => {
  const quotient: bigint = x / y;
  return x % y > BigInt(0) ? quotient + BigInt(1) : quotient;
};

const floorDivide = (x: bigint, y: bigint): bigint => {
  const quotient: bigint = x / y;
  return x % y < BigInt(0) ? quotient - BigInt(1) : quotient;
};

/** Draws an integer in `[minimum, maximum]`, scaling one 53-bit sample. */
const between = (minimum: bigint, maximum: bigint): bigint => {
  const scale: bigint = BigInt(1) << BigInt(53);
  const sample: bigint = BigInt(
    Math.min(
      Number(scale - BigInt(1)),
      Math.floor(Math.max(0, Math.random()) * Number(scale)),
    ),
  );
  return minimum + ((maximum - minimum + BigInt(1)) * sample) / scale;
};

typia/src/internal/_randomFormatByte.ts:
import { _randomInteger } from "./_randomInteger";
import {
  _ILengthProps,
  _RANDOM_LENGTH_ERROR,
  _randomLengthPick,
  _randomLengthWindow,
} from "./_randomStringLength";
import { __randomBase64 } from "./private/__randomComposition";

/**
 * Generate a Base64 string for the `byte` format at a length the bounds allow.
 *
 * @evidence contracts/common.md#principled-implementation Base64 lengths are multiples of four, so an unconstrained draw spends four to twelve groups, and a constrained one raises the window floor to the first multiple of four it contains and steps by four; an empty window throws. Each character is from the alphabet that the validator allows, so no encoding step is needed and no padding is produced.
 * @evidence contracts/common.md#clear-and-simple-design One function over the shared length window and Base64 helpers.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The length rule is the format's.
 * @evidence contracts/common.md#meaningful-documentation An inline comment explains the grouping.
 */
export const _randomFormatByte = (props?: _ILengthProps): string => {
  // Base64 encodes three bytes as four characters, so a valid length is always
  // a multiple of four; an unconstrained draw spends between four and twelve
  // groups, and a constrained one raises the window to the first multiple it
  // contains and steps by four from there.
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return __randomBase64(
      4 *
        _randomInteger({
          type: "integer",
          minimum: DEFAULT_GROUP_MIN,
          maximum: DEFAULT_GROUP_MAX,
        }),
    );
  const window = _randomLengthWindow(props, { minimum: 0, spread: 16 });
  const low: number = Math.ceil(window.low / 4) * 4;
  if (low > window.high) throw new Error(_RANDOM_LENGTH_ERROR);
  const length: number =
    low +
    4 *
      _randomLengthPick({
        low: 0,
        high: Math.floor((window.high - low) / 4),
      });
  return __randomBase64(length);
};

const DEFAULT_GROUP_MIN = 4;
const DEFAULT_GROUP_MAX = 12;

