import { _ILengthProps, _randomFormatLength } from "./_randomStringLength";
import { __IEpochProps, __randomEpoch } from "./private/__randomEpoch";

/**
 * Generate a `YYYY-MM-DD` date within the epoch bounds. Custom bounds must
 * describe valid Date instants with four-digit ISO years; expanded-year ISO
 * text is outside this fixed-width generator's contract.
 *
 * @evidence contracts/common.md#principled-implementation With valid Date bounds in the four-digit ISO-year range, a date is the first ten characters of a random instant's ISO text; the fixed-length wrapper checks it against the length bounds and throws when no draw fits. Custom out-of-range instants and expanded ISO years are not normalized here.
 * @evidence contracts/common.md#clear-and-simple-design One expression over the epoch drawer and the fixed-length wrapper.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The instant bounds are handled by the shared epoch drawer.
 * @evidence contracts/common.md#meaningful-documentation The doc states that the date is the date part of a random instant within the epoch bounds.
 */
export const _randomFormatDate = (props?: __IEpochProps & _ILengthProps) =>
  _randomFormatLength(props, () =>
    new Date(__randomEpoch(props)).toISOString().substring(0, 10),
  );

typia/src/internal/_randomFormatDatetime:
import {
  _ILengthProps,
  _RANDOM_LENGTH_ERROR,
  _randomLengthPick,
  _randomLengthWindow,
} from "./_randomStringLength";
import { __randomDigits } from "./private/__randomComposition";
import { __IEpochProps, __randomEpoch } from "./private/__randomEpoch";

/**
 * Generate an RFC 3339 date-time with a `Z` offset at a length the bounds
 * allow. Custom epoch bounds must stay within valid Date instants with
 * four-digit ISO years, which the fixed-width second-precision prefix assumes.
 *
 * @evidence contracts/common.md#principled-implementation Within valid Date bounds with four-digit ISO years, an unconstrained draw is a random instant in ISO text; a constrained one keeps the fixed-width second-precision prefix and chooses either a `Z` suffix or a fraction of the digits needed, avoiding length21 and throwing when the window holds no valid length. Custom expanded-year bounds are outside this fixed-width contract.
 * @evidence contracts/common.md#clear-and-simple-design One function over the length window and digit helpers.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The length rules are those of RFC 3339 timestamps with a `Z` offset.
 * @evidence contracts/common.md#meaningful-documentation The inline comments explain the length arithmetic.
 */
export const _randomFormatDatetime = (
  props?: __IEpochProps & _ILengthProps,
) => {
  const instant = (): string => new Date(__randomEpoch(props)).toISOString();
  if (props?.minLength === undefined && props?.maxLength === undefined)
    return instant();
  // `YYYY-MM-DDTHH:MM:SS` plus `Z` is the shortest instant, and a fractional
  // second grows it one digit at a time. Because that fraction needs both a dot
  // and at least one digit, 21 is the single length between the two forms that
  // no instant can have.
  const window = _randomLengthWindow(props, {
    minimum: SECONDS + 1,
    spread: 8,
  });
  let length: number = _randomLengthPick(window);
  if (length === SECONDS + 2)
    length = window.high >= SECONDS + 3 ? SECONDS + 3 : SECONDS + 1;
  if (length < window.low || length > window.high)
    throw new Error(_RANDOM_LENGTH_ERROR);
  const base: string = instant().substring(0, SECONDS);
  return length === SECONDS + 1
    ? `${base}Z`
    : `${base}.${__randomDigits(length - SECONDS - 2)}Z`;
};

const SECONDS = "0000-00-00T00:00:00".length;

typia/src/internal/_randomFormatDuration:
import { _randomInteger } from "./_randomInteger";
import {
  _ILengthProps,
  _randomLengthPick,
  _randomLengthWindow,
} from "./_randomStringLength";
import { __randomNumeric } from "./private/__randomComposition";

/**
 * Generate an ISO 8601 duration at a length the bounds allow.
 *
 * @evidence contracts/common.md#principled-implementation An unconstrained draw composes years, months and days and hours, minutes and seconds with zero parts omitted, and falls back to `PT0S`; a constrained one writes a single year designator with the digit count that fits, since an integer has no maximum digits, so any length from three upward is reachable.
 * @evidence contracts/common.md#clear-and-simple-design One function with two branches and a small composer.
 * @evidence contracts/common.md#prohibited-implementation-shortcuts The length rule follows the grammar and no length is redrawn blindly.
 * @evidence contracts/common.md#meaningful-documentation An inline comment explains the single designator.
 */
export const _randomFormatDuration = (props?: _ILengthProps): string => {
  if (props?.minLength === undefined && props?.maxLength === undefined) {
    const period: string = durate([
      ["Y", random(0, 100)],
      ["M", random(0, 12)],
      ["D", random(0, 31)],
    ]);
    const time: string = durate([
      ["H", random(0, 24)],
      ["M", random(0, 60)],
      ["S", random(0, 60)],
    ]);
    if (period.length + time.length === 0) return "PT0S";
    return `P${period}${time.length ? "T" : ""}${time}`;
  }
  // A single designator carries an unbounded digit count, so `P<n>Y` expresses
  // every length from three upward and `P1Y` is the shortest duration there is.
  const length: number = _randomLengthPick(
    _randomLengthWindow(props, { minimum: MINIMUM, spread: 6 }),
  );
  return `P${__randomNumeric(length - MINIMUM + 1)}Y`;
};

const MINIMUM = "P1Y".length;

const durate = (elements: [string, number][]) =>
  elements
    .filter(([_unit, value]) => value !== 0)
    .map(([unit, value]) => `${value}${unit}`)
    .join("");
const random = (minimum: number, maximum: number) =>
  _randomInteger({
    type: "integer",
    minimum,
    maximum,
  });

