    ? ""
    : `/${_randomString({
        type: "string",
        minLength: length - 1,
        maxLength: length - 1,
      })}`;
};

const PREFIX = "/components/schemas/";

const random = () =>
  _randomString({ type: "string", minLength: 10, maxLength: 10 });

